        he_vac = dbo.f_getSumaConceptoPromedio(CONVERT(DATE, @fechaingreso), CONVERT(DATE, @ceasedate), @cia, @person, @extras, periodo),
        bono_vac = dbo.f_getSumaConceptoPromedio(CONVERT(DATE, @fechaingreso), CONVERT(DATE, @ceasedate), @cia, @person, @bono, periodo),
        comision_vac = dbo.f_getSumaConceptoPromedio(CONVERT(DATE, @fechaingreso), CONVERT(DATE, @ceasedate), @cia, @person, @comision, periodo),
        feriado_vac = dbo.f_getSumaConceptoPromedio(CONVERT(DATE, @fechaingreso), CONVERT(DATE, @ceasedate), @cia, @person, @feriado, periodo),
        faltas_vac =
            dbo.f_getSumaConceptoPromedioVAC(
                CASE
                    WHEN DATEDIFF(YEAR, @fechaingreso, @ceasedate) <= 1 THEN CONVERT(DATE, @fechaingreso)
                    ELSE CONVERT(DATE, CONVERT(VARCHAR(4), YEAR(@ceasedate) - 1) + RIGHT(CONVERT(VARCHAR(8), @fechaingreso, 112), 4))
                END,
                CONVERT(DATE, @ceasedate), @cia, @person, @faltas, periodo)
            + dbo.f_getSumaConceptoPromedioVAC(
                CASE
                    WHEN DATEDIFF(YEAR, @fechaingreso, @ceasedate) <= 1 THEN CONVERT(DATE, @fechaingreso)
                    ELSE CONVERT(DATE, CONVERT(VARCHAR(4), YEAR(@ceasedate) - 1) + RIGHT(CONVERT(VARCHAR(8), @fechaingreso, 112), 4))
                END,
                CONVERT(DATE, @ceasedate), @cia, @person, @lsg, periodo)
            + dbo.f_getSumaConceptoPromedioVAC(
                CASE
                    WHEN DATEDIFF(YEAR, @fechaingreso, @ceasedate) <= 1 THEN CONVERT(DATE, @fechaingreso)
                    ELSE CONVERT(DATE, CONVERT(VARCHAR(4), YEAR(@ceasedate) - 1) + RIGHT(CONVERT(VARCHAR(8), @fechaingreso, 112), 4))
                END,
                CONVERT(DATE, @ceasedate), @cia, @person, @susp, periodo);

    SELECT
        LEFT(periodo, 4) + '-' + SUBSTRING(periodo, 5, 2) AS periodo_fmt,
        he_vac,
        bono_vac,
        feriado_vac,
        comision_vac,
        faltas_vac,
        he_cts,
        bono_cts,
        feriado_cts,
        comision_cts,
        faltas_cts,
        he_gra,
        bono_gra,
        feriado_gra,
        comision_gra,
        faltas_gra,
        CASE
            WHEN @ceasedate >= CONVERT(DATETIME, LEFT(@period, 4) + '0501')
             AND @ceasedate <= CONVERT(DATETIME, LEFT(@period, 4) + '1031') THEN
                CASE
                    WHEN CONVERT(DATE, @fechaingreso) >= CONVERT(DATE, LEFT(@period, 4) + '0501')
                     AND CONVERT(DATE, @fechaingreso) <= CONVERT(DATE, LEFT(@period, 4) + '1031')
                        THEN dbo.f_getMesesDividir(CONVERT(DATE, @fechaingreso), CONVERT(DATE, @ceasedate))
                    ELSE dbo.f_getMesesDividir(CONVERT(DATE, LEFT(@period, 4) + '0501'), CONVERT(DATE, @ceasedate))
                END
            ELSE
                CASE
                    WHEN @ceasedate > CONVERT(DATETIME, LEFT(@period, 4) + '1031') THEN
                        CASE
                            WHEN CONVERT(DATE, @fechaingreso) > CONVERT(DATETIME, LEFT(@period, 4) + '1031')
                                THEN dbo.f_getMesesDividir(CONVERT(DATE, @fechaingreso), CONVERT(DATE, @ceasedate))
                            ELSE dbo.f_getMesesDividir(CONVERT(DATE, LEFT(@period, 4) + '1101'), CONVERT(DATE, @ceasedate))
                        END
                    ELSE
                        CASE
                            WHEN CONVERT(DATE, @fechaingreso) > CONVERT(DATETIME, CONVERT(CHAR(4), CONVERT(INT, LEFT(@period, 4)) - 1) + '1031')
                                THEN dbo.f_getMesesDividir(CONVERT(DATE, @fechaingreso), CONVERT(DATE, @ceasedate))
                            ELSE dbo.f_getMesesDividir(CONVERT(DATE, CONVERT(CHAR(4), CONVERT(INT, LEFT(@period, 4)) - 1) + '1101'), CONVERT(DATE, @ceasedate))
                        END
                END
        END AS ctsCant,
        CASE
            WHEN MONTH(@ceasedate) < 7 THEN
                CASE
                    WHEN CONVERT(DATE, @fechaingreso) > CONVERT(DATE, LEFT(@period, 4) + '0101')
                        THEN dbo.f_getMesesDividir(CONVERT(DATE, @fechaingreso), CONVERT(DATE, @ceasedate))
                    ELSE dbo.f_getMesesDividir(CONVERT(DATE, LEFT(@period, 4) + '0101'), CONVERT(DATE, @ceasedate))
                END
            ELSE
                CASE
                    WHEN CONVERT(DATE, @fechaingreso) > CONVERT(DATE, LEFT(@period, 4) + '0701')
                        THEN dbo.f_getMesesDividir(CONVERT(DATE, @fechaingreso), CONVERT(DATE, @ceasedate))
                    ELSE dbo.f_getMesesDividir(CONVERT(DATE, LEFT(@period, 4) + '0701'), CONVERT(DATE, @ceasedate))
                END
        END AS gratiCant,
        SY_Person.Name,
        CONVERT(VARCHAR(20), @ceasedate, 103) AS fechacese,
        CONVERT(VARCHAR(20), @fechaingreso, 103) AS fechaingreso,
        dbo.f_getMesesDividir(CONVERT(DATE, @fechaingreso), CONVERT(DATE, @ceasedate)) AS vaccant
    FROM #temp_reporte
        INNER JOIN SY_Person
            ON #temp_reporte.person = SY_Person.Person;
END
GO



-- ============================================================================
-- [015/282] f_count_medical_rest_days_web.sql
-- ============================================================================

/*
    Cuenta días con descanso médico (PDT) en un rango sumando tramos recortados.
    Si hay tramos superpuestos el mismo día puede contarse más de una vez (caso raro).
    Usado por sp_pr_saldovacaciones_web.
*/
CREATE OR ALTER FUNCTION [dbo].[f_count_medical_rest_days_web]
(
    @company       CHAR(4),
    @person        VARCHAR(20),
    @pdt           VARCHAR(2),
    @range_start   DATETIME,
    @range_end     DATETIME,
    @inclusive_end BIT
)
RETURNS INT
AS
BEGIN
    DECLARE @eff_end DATETIME;
    DECLARE @result INT = 0;

    IF @range_start IS NULL OR @range_end IS NULL
        RETURN 0;

    SET @range_start = CAST(@range_start AS DATE);
    SET @range_end = CAST(@range_end AS DATE);

    IF @inclusive_end = 0
        SET @eff_end = DATEADD(DAY, -1, @range_end);
    ELSE
        SET @eff_end = @range_end;

    IF @eff_end < @range_start
        RETURN 0;

    SELECT @result = ISNULL(SUM(
        CASE
            WHEN bounds.rs <= bounds.re THEN DATEDIFF(DAY, bounds.rs, bounds.re) + 1
            ELSE 0
        END
    ), 0)
    FROM PR_EmployeeMedicalRest emr
        INNER JOIN PR_MedicalRestType mrt
            ON emr.MedicalRestType = mrt.MedicalRestType
           AND mrt.PDT = @pdt
        CROSS APPLY (
            SELECT
                CASE
                    WHEN CAST(emr.DateBegin AS DATE) > @range_start THEN CAST(emr.DateBegin AS DATE)
                    ELSE @range_start
                END AS rs,
                CASE
                    WHEN CAST(emr.DateEnd AS DATE) < @eff_end THEN CAST(emr.DateEnd AS DATE)
                    ELSE @eff_end
                END AS re
        ) bounds
    WHERE emr.Person = @person
      AND emr.Company = @company
      AND CAST(emr.DateBegin AS DATE) <= @eff_end
      AND CAST(emr.DateEnd AS DATE) >= @range_start;

    RETURN ISNULL(@result, 0);
END
GO



-- ============================================================================
-- [016/282] f_getPromedioGrati.sql
-- ============================================================================

/*
    Promedio Grati: promedio de un concepto en un proceso y rango de periodos.
    Igual que Promedio Vac, pero el periodo inicial depende del periodo en proceso:
      - Enero a Julio  -> inicio Enero del mismo año
      - Agosto a Diciembre -> inicio Julio del mismo año
*/
CREATE OR ALTER FUNCTION [dbo].[f_getPromedioGrati](
    @cia           VARCHAR(20),
    @person        VARCHAR(20),
    @payrolltype   VARCHAR(20),
    @process       VARCHAR(20),
    @period        VARCHAR(20),
    @period_end    VARCHAR(20),
    @concept       VARCHAR(20),
    @valor_minimo  NUMERIC(19, 4),
    @divisor       NUMERIC(19, 4) = NULL,
    @fechaingreso  DATETIME = NULL
)
RETURNS NUMERIC(19, 4)
AS
BEGIN
    DECLARE @period_begin  VARCHAR(20);
    DECLARE @mes_periodo   INT;
    DECLARE @inicio_yyyymm CHAR(6);

    IF @period IS NULL OR @period_end IS NULL
        RETURN 0;

    SET @mes_periodo = CONVERT(INT, SUBSTRING(@period, 5, 2));

    SET @inicio_yyyymm = CASE
        WHEN @mes_periodo BETWEEN 1 AND 7 THEN LEFT(@period, 4) + '01'
        ELSE LEFT(@period, 4) + '07'
    END;

    SELECT @period_begin = MIN(p.PRPeriod)
    FROM PR_Period p (NOLOCK)
    WHERE p.Company = @cia
      AND p.PayRollType = @payrolltype
      AND LEFT(p.PRPeriod, 6) >= @inicio_yyyymm;

    IF @period_begin IS NULL
        RETURN 0;

    RETURN dbo.f_getPromedioVac(
        @cia,
        @person,
        @payrolltype,
        @process,
        @period_begin,
        @period_end,
        @concept,
        @valor_minimo,
        @divisor,
        @fechaingreso
    );
END
GO



-- ============================================================================
-- [017/282] f_getPromedioVac.sql
-- ============================================================================

/*
    Promedio Vac: promedio de un concepto en un proceso y rango de periodos.
    Suma los importes de cada mes del rango completo.
    Divide entre @divisor si > 0; si no, entre meses del rango desde ingreso/reingreso.
    Si menos de @valor_minimo meses tienen importe > 0, devuelve 0.
*/
CREATE OR ALTER FUNCTION [dbo].[f_getPromedioVac](
    @cia           VARCHAR(20),
    @person        VARCHAR(20),
    @payrolltype   VARCHAR(20),
    @process       VARCHAR(20),
    @period_begin  VARCHAR(20),
    @period_end    VARCHAR(20),
    @concept       VARCHAR(20),
    @valor_minimo  NUMERIC(19, 4),
    @divisor       NUMERIC(19, 4) = NULL,
    @fechaingreso  DATETIME = NULL
)
RETURNS NUMERIC(19, 4)
AS
BEGIN
    DECLARE @suma            NUMERIC(19, 4);
    DECLARE @meses_positivos INT;
    DECLARE @meses_divisor   INT;
    DECLARE @hire_yyyymm     CHAR(6);

    IF ISNULL(LTRIM(RTRIM(@concept)), '') = ''
        RETURN 0;

    IF @period_begin IS NULL OR @period_end IS NULL
        RETURN 0;

    SELECT
        @suma = SUM(ISNULL(epc.importe, 0)),
        @meses_positivos = SUM(CASE WHEN ISNULL(epc.importe, 0) > 0 THEN 1 ELSE 0 END)
    FROM PR_Period p (NOLOCK)
        LEFT JOIN (
            SELECT
                e.PRPeriod,
                ISNULL(e.ConceptValueLo, e.ConceptValue) AS importe
            FROM PR_EmployeePayRollConcept e (NOLOCK)
            WHERE e.Company = @cia
              AND e.PayRollType = @payrolltype
              AND e.Person = @person
              AND e.ProcessType = @process
              AND e.Concept = @concept
        ) epc ON epc.PRPeriod = p.PRPeriod
    WHERE p.Company = @cia
      AND p.PayRollType = @payrolltype
      AND p.PRPeriod BETWEEN @period_begin AND @period_end;

    IF ISNULL(@meses_positivos, 0) < ISNULL(@valor_minimo, 0)
        RETURN 0;

    IF ISNULL(@divisor, 0) > 0
    BEGIN
        SET @meses_divisor = CONVERT(INT, @divisor);
    END
    ELSE
    BEGIN
        IF @fechaingreso IS NOT NULL
            SET @hire_yyyymm = LEFT(CONVERT(VARCHAR(8), CONVERT(DATE, @fechaingreso), 112), 6);
        ELSE
            SET @hire_yyyymm = NULL;

        SELECT @meses_divisor = COUNT(*)
        FROM PR_Period p (NOLOCK)
        WHERE p.Company = @cia
          AND p.PayRollType = @payrolltype
          AND p.PRPeriod BETWEEN @period_begin AND @period_end
          AND (
                @hire_yyyymm IS NULL
                OR LEFT(p.PRPeriod, 6) >= @hire_yyyymm
              );
    END

    IF ISNULL(@meses_divisor, 0) = 0
        RETURN 0;

    RETURN ISNULL(@suma, 0) / @meses_divisor;
END
GO



-- ============================================================================
-- [018/282] f_getSuma5ta_web.sql
-- ============================================================================

/*
    Suma conceptos configurados en PR_Configura5ta para seguimiento de 5ta.
    Usado por: sp_pr_5ta_trabajador_web
*/
CREATE OR ALTER FUNCTION [dbo].[f_getSuma5ta_web]
(
    @cia         VARCHAR(4),
    @person      VARCHAR(20),
    @period      VARCHAR(20),
    @payrolltype VARCHAR(20),
    @type        CHAR(2)
)
RETURNS NUMERIC(19, 4)
AS
BEGIN
    DECLARE @resultado NUMERIC(19, 4);

    SET @resultado = ISNULL((
        SELECT SUM(
            ISNULL(E.ConceptValueLo, E.ConceptValue)
            * CASE WHEN P.applysum = 'P' THEN 1 ELSE -1 END
        )
        FROM PR_EmployeePayRollConcept E
            INNER JOIN PR_Mapping M
                ON E.Company = M.Company AND M.Company = @cia
            INNER JOIN PR_Configura5ta P
                ON E.Concept = P.concept
               AND E.Company = @cia
               AND E.Person = @person
               AND E.PRPeriod = @period
               AND E.PayRollType = @payrolltype
               AND E.ProcessType = P.processtype
               AND P.plame = '14'
               AND P.type = @type
    ), 0);

    RETURN @resultado;
END
GO



-- ============================================================================
-- [019/282] f_getSumaConceptosCTS.sql
-- ============================================================================

/*
    SC_CTS: suma de un concepto en un proceso desde el inicio del ciclo de provisión CTS
    hasta @period_end. El ciclo depende del periodo en proceso (@period):
      - Mayo a Octubre  -> inicio Mayo del mismo año
      - Noviembre a Abril -> inicio Noviembre (año anterior si ene-abr)
    Si @period_end es anterior al periodo de inicio del ciclo, devuelve 0.
    Respeta fecha de ingreso/reingreso: no suma periodos anteriores al mes de alta.
*/
CREATE OR ALTER FUNCTION [dbo].[f_getSumaConceptosCTS](
    @cia           VARCHAR(20),
    @person        VARCHAR(20),
    @payrolltype   VARCHAR(20),
    @process       VARCHAR(20),
    @period        VARCHAR(20),
    @period_end    VARCHAR(20),
    @concept       VARCHAR(20)
)
RETURNS NUMERIC(19, 4)
AS
BEGIN
    DECLARE @period_begin     VARCHAR(20);
    DECLARE @inicio_ciclo_cts DATE;
    DECLARE @inicio_yyyymm    CHAR(6);
    DECLARE @mes_periodo      INT;
    DECLARE @order_ini        INT;
    DECLARE @order_fin        INT;
    DECLARE @fechaingreso     DATETIME;
    DECLARE @hire_yyyymm      CHAR(6);
    DECLARE @period_hire      VARCHAR(20);
    DECLARE @order_hire       INT;

    IF ISNULL(LTRIM(RTRIM(@concept)), '') = ''
        RETURN 0;

    IF @period IS NULL OR @period_end IS NULL
        RETURN 0;

    SET @mes_periodo = CONVERT(INT, SUBSTRING(@period, 5, 2));

    SET @inicio_ciclo_cts = CASE
        WHEN @mes_periodo BETWEEN 5 AND 10 THEN CONVERT(DATE, LEFT(@period, 4) + '0501')
        WHEN @mes_periodo BETWEEN 11 AND 12 THEN CONVERT(DATE, LEFT(@period, 4) + '1101')
        ELSE CONVERT(DATE, CONVERT(CHAR(4), CONVERT(INT, LEFT(@period, 4)) - 1) + '1101')
    END;

    SET @inicio_yyyymm = LEFT(CONVERT(VARCHAR(8), @inicio_ciclo_cts, 112), 6);

    SELECT @period_begin = MIN(p.PRPeriod)
    FROM PR_Period p (NOLOCK)
    WHERE p.Company = @cia
      AND p.PayRollType = @payrolltype
      AND LEFT(p.PRPeriod, 6) >= @inicio_yyyymm;

    IF @period_begin IS NULL
        RETURN 0;

    SELECT @order_ini = PeriodOrder
    FROM PR_Period (NOLOCK)
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND PRPeriod = @period_begin;

    SELECT @fechaingreso = ISNULL(e.ReEntryDate, e.EntryDate)
    FROM PR_Employee e (NOLOCK)
    WHERE e.Company = @cia
      AND e.Person = @person;

    IF @fechaingreso IS NOT NULL
    BEGIN
        SET @hire_yyyymm = LEFT(CONVERT(VARCHAR(8), CONVERT(DATE, @fechaingreso), 112), 6);

        SELECT @period_hire = MIN(p.PRPeriod)
        FROM PR_Period p (NOLOCK)
        WHERE p.Company = @cia
          AND p.PayRollType = @payrolltype
          AND LEFT(p.PRPeriod, 6) >= @hire_yyyymm;

        IF @period_hire IS NOT NULL
        BEGIN
            SELECT @order_hire = PeriodOrder
            FROM PR_Period (NOLOCK)
            WHERE Company = @cia
              AND PayRollType = @payrolltype
              AND PRPeriod = @period_hire;

            IF ISNULL(@order_hire, 0) > ISNULL(@order_ini, 0)
            BEGIN
                SET @period_begin = @period_hire;
                SET @order_ini = @order_hire;
            END
        END
    END

    SELECT @order_fin = PeriodOrder
    FROM PR_Period (NOLOCK)
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND PRPeriod = @period_end;

    IF ISNULL(@order_fin, 0) < ISNULL(@order_ini, 0)
        RETURN 0;

    RETURN dbo.f_getSumaConceptosProceso(
        @cia, @person, @payrolltype, @process,
        @period_begin, @period_end, @concept
    );
END
GO



-- ============================================================================
-- [020/282] f_getSumaConceptosGrati.sql
-- ============================================================================

/*
    SC_GRATI: suma de un concepto en un proceso desde el inicio del ciclo de gratificación
    hasta @period_end. El ciclo depende del periodo en proceso (@period):
      - Enero a Junio  -> inicio Enero del mismo año
      - Julio a Diciembre -> inicio Julio del mismo año
    Si @period_end es anterior al periodo de inicio del ciclo, devuelve 0.
*/
CREATE OR ALTER FUNCTION [dbo].[f_getSumaConceptosGrati](
    @cia           VARCHAR(20),
    @person        VARCHAR(20),
    @payrolltype   VARCHAR(20),
    @process       VARCHAR(20),
    @period        VARCHAR(20),
    @period_end    VARCHAR(20),
    @concept       VARCHAR(20)
)
RETURNS NUMERIC(19, 4)
AS
BEGIN
    DECLARE @period_begin       VARCHAR(20);
    DECLARE @inicio_ciclo_grati DATE;
    DECLARE @inicio_yyyymm      CHAR(6);
    DECLARE @mes_periodo        INT;
    DECLARE @order_ini          INT;
    DECLARE @order_fin          INT;

    IF ISNULL(LTRIM(RTRIM(@concept)), '') = ''
        RETURN 0;

    IF @period IS NULL OR @period_end IS NULL
        RETURN 0;

    SET @mes_periodo = CONVERT(INT, SUBSTRING(@period, 5, 2));

    SET @inicio_ciclo_grati = CASE
        WHEN @mes_periodo BETWEEN 1 AND 6 THEN CONVERT(DATE, LEFT(@period, 4) + '0101')
        ELSE CONVERT(DATE, LEFT(@period, 4) + '0701')
    END;

    SET @inicio_yyyymm = LEFT(CONVERT(VARCHAR(8), @inicio_ciclo_grati, 112), 6);

    SELECT @period_begin = MIN(p.PRPeriod)
    FROM PR_Period p (NOLOCK)
    WHERE p.Company = @cia
      AND p.PayRollType = @payrolltype
      AND LEFT(p.PRPeriod, 6) >= @inicio_yyyymm;

    IF @period_begin IS NULL
        RETURN 0;

    SELECT @order_ini = PeriodOrder
    FROM PR_Period (NOLOCK)
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND PRPeriod = @period_begin;

    SELECT @order_fin = PeriodOrder
    FROM PR_Period (NOLOCK)
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND PRPeriod = @period_end;

    IF ISNULL(@order_fin, 0) < ISNULL(@order_ini, 0)
        RETURN 0;

    RETURN dbo.f_getSumaConceptosProceso(
        @cia, @person, @payrolltype, @process,
        @period_begin, @period_end, @concept
    );
END
GO



-- ============================================================================
-- [021/282] f_getSumaConceptosIngreso.sql
-- ============================================================================

/*
    SCIngreso: suma de un concepto en un proceso desde el periodo de ingreso/reingreso
    hasta @period_end. Si @period_end es anterior al periodo de ingreso, devuelve 0.
*/
CREATE OR ALTER FUNCTION [dbo].[f_getSumaConceptosIngreso](
    @cia           VARCHAR(20),
    @person        VARCHAR(20),
    @payrolltype   VARCHAR(20),
    @process       VARCHAR(20),
    @period_end    VARCHAR(20),
    @concept       VARCHAR(20),
    @fechaingreso  DATETIME
)
RETURNS NUMERIC(19, 4)
AS
BEGIN
    DECLARE @period_begin VARCHAR(20);
    DECLARE @hire_yyyymm  CHAR(6);
    DECLARE @order_ini    INT;
    DECLARE @order_fin    INT;

    IF ISNULL(LTRIM(RTRIM(@concept)), '') = ''
        RETURN 0;

    IF @period_end IS NULL OR @fechaingreso IS NULL
        RETURN 0;

    SET @hire_yyyymm = LEFT(CONVERT(VARCHAR(8), CONVERT(DATE, @fechaingreso), 112), 6);

    SELECT @period_begin = MIN(p.PRPeriod)
    FROM PR_Period p (NOLOCK)
    WHERE p.Company = @cia
      AND p.PayRollType = @payrolltype
      AND LEFT(p.PRPeriod, 6) >= @hire_yyyymm;

    IF @period_begin IS NULL
        RETURN 0;

    SELECT @order_ini = PeriodOrder
    FROM PR_Period (NOLOCK)
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND PRPeriod = @period_begin;

    SELECT @order_fin = PeriodOrder
    FROM PR_Period (NOLOCK)
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND PRPeriod = @period_end;

    IF ISNULL(@order_fin, 0) < ISNULL(@order_ini, 0)
        RETURN 0;

    RETURN dbo.f_getSumaConceptosProceso(
        @cia, @person, @payrolltype, @process,
        @period_begin, @period_end, @concept
    );
END
GO



-- ============================================================================
-- [022/282] f_getSumaConceptosProceso.sql
-- ============================================================================

/*
    Suma valores de uno o varios conceptos en un rango de periodos y proceso.
    @conceptlist: IDs separados por | (pipe). Si vacío, devuelve 0.
*/
CREATE OR ALTER FUNCTION [dbo].[f_getSumaConceptosProceso](
    @cia           VARCHAR(20),
    @person        VARCHAR(20),
    @payrolltype   VARCHAR(20),
    @process       VARCHAR(20),
    @period_begin  VARCHAR(20),
    @period_end    VARCHAR(20),
    @conceptlist   VARCHAR(500)
)
RETURNS NUMERIC(19, 4)
AS
BEGIN
    DECLARE @result NUMERIC(19, 4);
    DECLARE @xml XML;

    IF ISNULL(LTRIM(RTRIM(@conceptlist)), '') = ''
        RETURN 0;

    IF @period_begin IS NULL OR @period_end IS NULL
        RETURN 0;

    SET @xml = CAST(
        '<i>' + REPLACE(REPLACE(LTRIM(RTRIM(@conceptlist)), '&', '&amp;'), '|', '</i><i>') + '</i>' AS XML
    );

    SELECT @result = SUM(ISNULL(epc.ConceptValueLo, epc.ConceptValue))
    FROM PR_EmployeePayRollConcept epc (NOLOCK)
        INNER JOIN (
            SELECT LTRIM(RTRIM(T.c.value('.', 'VARCHAR(20)'))) AS Concept
            FROM @xml.nodes('/i') AS T(c)
            WHERE LTRIM(RTRIM(T.c.value('.', 'VARCHAR(20)'))) <> ''
        ) c ON epc.Concept = c.Concept
    WHERE epc.Company = @cia
      AND epc.PayRollType = @payrolltype
      AND epc.Person = @person
      AND epc.PRPeriod BETWEEN @period_begin AND @period_end
      AND epc.ProcessType = @process;

    RETURN ISNULL(@result, 0);
END
GO



-- ============================================================================
-- [023/282] f_map_conceptlist_cia.sql
-- ============================================================================

/*
    Mapea ConceptList (IDs de PR_Concept separados por |) de @cia_origen a @cia_destino
    usando FormulaCode como clave común entre empresas.
*/
CREATE OR ALTER FUNCTION [dbo].[f_map_conceptlist_cia]
(
    @conceptlist VARCHAR(500),
    @cia_origen  VARCHAR(4),
    @cia_destino VARCHAR(4)
)
RETURNS VARCHAR(500)
AS
BEGIN
    DECLARE @result VARCHAR(500) = '';
    DECLARE @work VARCHAR(500);
    DECLARE @pos INT;
    DECLARE @piece VARCHAR(50);
    DECLARE @fc VARCHAR(50);
    DECLARE @dest_concept VARCHAR(20);

    SET @conceptlist = NULLIF(LTRIM(RTRIM(ISNULL(@conceptlist, ''))), '');
    IF @conceptlist IS NULL
        RETURN NULL;

    SET @work = @conceptlist + '|';

    WHILE LEN(@work) > 0
    BEGIN
        SET @pos = CHARINDEX('|', @work);
        IF @pos = 0
            BREAK;

        SET @piece = LTRIM(RTRIM(LEFT(@work, @pos - 1)));
        SET @work = SUBSTRING(@work, @pos + 1, LEN(@work));

        IF @piece <> ''
        BEGIN
            SET @fc = NULL;
            SET @dest_concept = NULL;

            SELECT @fc = LTRIM(RTRIM(ISNULL(FormulaCode, '')))
            FROM PR_Concept (NOLOCK)
            WHERE Company = @cia_origen
              AND Concept = @piece;

            IF @fc IS NOT NULL AND @fc <> ''
            BEGIN
                SELECT @dest_concept = Concept
                FROM PR_Concept (NOLOCK)
                WHERE Company = @cia_destino
                  AND LTRIM(RTRIM(ISNULL(FormulaCode, ''))) = @fc;

                IF @dest_concept IS NOT NULL AND LTRIM(RTRIM(@dest_concept)) <> ''
                BEGIN
                    IF @result <> ''
                        SET @result = @result + '|';
                    SET @result = @result + @dest_concept;
                END
            END
        END
    END

    RETURN NULLIF(@result, '');
END
GO



-- ============================================================================
-- [024/282] listar_conceptos_faltantes_sb03_liquidacion.sql
-- ============================================================================

/*
    Conceptos de BGT (fórmulas LIQUIDACIÓN) que NO existen en SB03
    con el mismo FormulaCode — bloquean sp_pr_replicar_formula_cia.

    Ejecutar en: hm_aci
*/
SET NOCOUNT ON;

SELECT
    c.Concept              AS concept_bgt,
    c.FormulaCode          AS formulacode,
    c.Description          AS descripcion_bgt,
    fh.FormulaHeader       AS formulaheader_bgt,
    fh.Description         AS formula_descripcion,
    pt.ShortName           AS proceso,
    pr.ShortName           AS planilla
FROM PR_FormulaHeader fh
INNER JOIN PR_ProcessType pt
    ON fh.Proccestype = pt.ProcessType
INNER JOIN PR_PayRollType pr
    ON fh.Payrolltype = pr.PayRollType
INNER JOIN PR_Concept c
    ON c.Company = fh.Company
   AND c.FormulaCode = fh.formulacode
WHERE fh.Company = 'BGT'
  AND pt.ShortName = 'LIQUIDACION'
  AND NOT EXISTS (
        SELECT 1
        FROM PR_Concept s
        WHERE s.Company = 'SB03'
          AND s.FormulaCode = fh.formulacode
  )
ORDER BY
    c.FormulaCode,
    fh.FormulaHeader;

-- Resumen
SELECT COUNT(*) AS total_conceptos_faltantes
FROM (
    SELECT DISTINCT fh.formulacode
    FROM PR_FormulaHeader fh
    INNER JOIN PR_ProcessType pt
        ON fh.Proccestype = pt.ProcessType
    WHERE fh.Company = 'BGT'
      AND pt.ShortName = 'LIQUIDACION'
      AND NOT EXISTS (
            SELECT 1
            FROM PR_Concept s
            WHERE s.Company = 'SB03'
              AND s.FormulaCode = fh.formulacode
      )
) x;

GO


-- ============================================================================
-- [025/282] queries_depurar_conceptos_auxiliares.sql
-- ============================================================================

/*
    Consultas de referencia — depuración conceptos AUXILIARES por compañía.

    Recomendado: usar el SP sp_pr_depurar_conceptos_auxiliares_web (modos RESUMEN,
    NO_USADOS, G1, G2, G3, G4, DETALLE).

    Este archivo documenta la lógica por grupo para ejecutar manualmente en SSMS.
    Cambie @company según la empresa destino (BGT, SB01, SB02, ...).
*/
DECLARE @company VARCHAR(4) = 'BGT';

/* =============================================================================
   MAESTRO — conceptos tipo Auxiliares (ShortName = 'X')
   ============================================================================= */
SELECT
    c.Company,
    c.Concept AS concept_id,
    LTRIM(RTRIM(c.FormulaCode)) AS formulacode,
    LTRIM(RTRIM(c.Description)) AS nombre_concepto,
    LTRIM(RTRIM(c.Status)) AS status
FROM PR_Concept c
    INNER JOIN PR_ConceptType ct
        ON ct.ConceptType = c.ConceptType
       AND ct.Company = c.Company
WHERE c.Company = @company
  AND LTRIM(RTRIM(ct.ShortName)) = 'X'
ORDER BY c.FormulaCode, c.Description;

GO

DECLARE @company VARCHAR(4) = 'BGT';

/* =============================================================================
   GRUPO 1 — AUX usados en fórmulas (cabecera, condición, detalle, ConceptList)
   ============================================================================= */
SELECT DISTINCT
    c.Company,
    c.Concept AS concept_id,
    LTRIM(RTRIM(c.FormulaCode)) AS formulacode,
    LTRIM(RTRIM(c.Description)) AS nombre_concepto
FROM (
    SELECT fh.Company, fh.Concept AS concept_id
    FROM PR_FormulaHeader fh
    WHERE fh.Company = @company
      AND fh.Concept IS NOT NULL AND LTRIM(RTRIM(fh.Concept)) <> ''

    UNION

    SELECT fh.Company, fh.ConceptCond
    FROM PR_FormulaHeader fh
    WHERE fh.Company = @company
      AND fh.ConceptCond IS NOT NULL AND LTRIM(RTRIM(fh.ConceptCond)) <> ''

    UNION

    SELECT fh.Company, fd.Concept
    FROM PR_FormulaHeader fh
    INNER JOIN PR_FormulaDetail fd ON fd.FormulaHeader = fh.FormulaHeader
    WHERE fh.Company = @company
      AND fd.Concept IS NOT NULL AND LTRIM(RTRIM(fd.Concept)) <> ''

    UNION

    SELECT fh.Company, s.concept_id
    FROM PR_FormulaHeader fh
    INNER JOIN PR_FormulaDetail fd ON fd.FormulaHeader = fh.FormulaHeader
    CROSS APPLY (
        SELECT LTRIM(RTRIM(
            SUBSTRING(
                fd.ConceptList,
                n.number,
                CHARINDEX('|', fd.ConceptList + '|', n.number) - n.number
            )
        )) AS concept_id
        FROM master..spt_values n
        WHERE n.type = 'P'
          AND n.number BETWEEN 1 AND LEN(ISNULL(fd.ConceptList, ''))
          AND SUBSTRING('|' + fd.ConceptList, n.number, 1) = '|'
    ) s
    WHERE fh.Company = @company
      AND fd.ConceptList IS NOT NULL
      AND LTRIM(RTRIM(fd.ConceptList)) <> ''
      AND LTRIM(RTRIM(s.concept_id)) <> ''
) u
    INNER JOIN PR_Concept c
        ON c.Concept = u.concept_id AND c.Company = u.Company
    INNER JOIN PR_ConceptType ct
        ON ct.ConceptType = c.ConceptType AND ct.Company = c.Company
WHERE LTRIM(RTRIM(ct.ShortName)) = 'X'
ORDER BY formulacode;

GO

DECLARE @company VARCHAR(4) = 'BGT';

/* =============================================================================
   GRUPO 2 — AUX en asignación (PR_EmployeeConcept)
   ============================================================================= */
SELECT DISTINCT
    c.Company,
    c.Concept AS concept_id,
    LTRIM(RTRIM(c.FormulaCode)) AS formulacode,
    LTRIM(RTRIM(c.Description)) AS nombre_concepto
FROM PR_EmployeeConcept ec
    INNER JOIN PR_Concept c
        ON c.Concept = ec.Concept AND c.Company = ec.Company
    INNER JOIN PR_ConceptType ct
        ON ct.ConceptType = c.ConceptType AND ct.Company = c.Company
WHERE ec.Company = @company
  AND LTRIM(RTRIM(ct.ShortName)) = 'X'
ORDER BY formulacode;

GO

DECLARE @company VARCHAR(4) = 'BGT';

/* =============================================================================
   GRUPO 3 — AUX calculados (PR_EmployeePayRollConcept)
   ============================================================================= */
SELECT DISTINCT
    c.Company,
    c.Concept AS concept_id,
    LTRIM(RTRIM(c.FormulaCode)) AS formulacode,
    LTRIM(RTRIM(c.Description)) AS nombre_concepto
FROM PR_EmployeePayRollConcept epc
    INNER JOIN PR_Concept c
        ON c.Concept = epc.Concept AND c.Company = epc.Company
    INNER JOIN PR_ConceptType ct
        ON ct.ConceptType = c.ConceptType AND ct.Company = c.Company
WHERE epc.Company = @company
  AND LTRIM(RTRIM(ct.ShortName)) = 'X'
ORDER BY formulacode;

GO

/* =============================================================================
   GRUPO 4 — Nemónicos literales en SP de cálculo
   (usar sp_pr_extraer_nemonicos_literal_sp_web por cada SP o el SP principal)
   ============================================================================= */
EXEC dbo.sp_pr_extraer_nemonicos_literal_sp_web
    @procedure_name = 'sp_pr_calcular_finmes_persona';

EXEC dbo.sp_pr_extraer_nemonicos_literal_sp_web
    @procedure_name = 'sp_pr_calcular_liquidacion_persona';

EXEC dbo.sp_pr_extraer_nemonicos_literal_sp_web
    @procedure_name = 'sp_pr_calcular_gratificacion_persona';

EXEC dbo.sp_pr_extraer_nemonicos_literal_sp_web
    @procedure_name = 'sp_pr_calcular_provcts_persona';

EXEC dbo.sp_pr_extraer_nemonicos_literal_sp_web
    @procedure_name = 'sp_pr_calcular_provgrati_persona';

EXEC dbo.sp_pr_extraer_nemonicos_literal_sp_web
    @procedure_name = 'sp_pr_calcular_provvac_persona';

GO

DECLARE @company VARCHAR(4) = 'BGT';

/* =============================================================================
   SP PRINCIPAL — resumen y listas (recomendado)
   ============================================================================= */
EXEC dbo.sp_pr_depurar_conceptos_auxiliares_web
    @company = @company,
    @modo = 'RESUMEN';

EXEC dbo.sp_pr_depurar_conceptos_auxiliares_web
    @company = @company,
    @modo = 'NO_USADOS';

EXEC dbo.sp_pr_depurar_conceptos_auxiliares_web
    @company = @company,
    @modo = 'DETALLE';

GO



-- ============================================================================
-- [026/282] query_cmp_rem_basica_junio_calc_vs_julio_asig.sql
-- ============================================================================

/*
    hm_aci / BGT / EMPLEADOS / MENSUAL
    Compara REM_BASICA calculada en JUNIO 2026 vs asignación permanente vigente en JULIO 2026.

    Solo trabajadores activos (PR_Employee.Status = 'N') con importe en AMBOS periodos
    (cálculo junio + asignación permanente julio).

    Columnas:
      DNI, NOMBRE, IMPORTE_JUNIO_CALCULADO, IMPORTE_JULIO_ASIGNACION
      DIFERENCIA, FLAG (IGUAL | DIFERENTE)
*/
SET NOCOUNT ON;

DECLARE @cia          VARCHAR(10)  = 'BGT';
DECLARE @payrolltype  VARCHAR(20)  = 'LIMABGT 000000000005';  -- EMPLEADOS
DECLARE @processtype  VARCHAR(20)  = 'BGT 000000000002';      -- MENSUAL
DECLARE @period_jun   VARCHAR(10)  = '20260606';
DECLARE @period_jul   VARCHAR(10)  = '20260707';

;WITH activos AS (
    SELECT e.Person
    FROM PR_Employee e (NOLOCK)
    WHERE e.Company = @cia
      AND e.PayRollType = @payrolltype
      AND LTRIM(RTRIM(ISNULL(e.Status, ''))) = 'N'
),
calc_jun AS (
    SELECT
        epc.Person,
        CAST(SUM(ISNULL(epc.ConceptValueLo, epc.ConceptValue)) AS DECIMAL(18, 4)) AS importe_junio
    FROM PR_EmployeePayRollConcept epc (NOLOCK)
    INNER JOIN PR_Concept c (NOLOCK)
        ON c.Company = epc.Company
       AND c.Concept = epc.Concept
    INNER JOIN activos a
        ON a.Person = epc.Person
    WHERE epc.Company = @cia
      AND epc.PayRollType = @payrolltype
      AND epc.ProcessType = @processtype
      AND epc.PRPeriod = @period_jun
      AND UPPER(LTRIM(RTRIM(ISNULL(c.FormulaCode, '')))) = 'REM_BASICA'
    GROUP BY epc.Person
),
asig_jul AS (
    /* Permanente vigente en julio: inicio <= julio y (sin fin o fin >= julio) */
    SELECT
        ec.Person,
        CAST(SUM(ISNULL(ec.ConceptValue, 0)) AS DECIMAL(18, 4)) AS importe_julio_asig
    FROM PR_EmployeeConcept ec (NOLOCK)
    INNER JOIN PR_Concept c (NOLOCK)
        ON c.Company = ec.Company
       AND c.Concept = ec.Concept
    INNER JOIN activos a
        ON a.Person = ec.Person
    WHERE ec.Company = @cia
      AND ec.PayRollType = @payrolltype
      AND UPPER(LTRIM(RTRIM(ISNULL(c.FormulaCode, '')))) = 'REM_BASICA'
      AND UPPER(LTRIM(RTRIM(ISNULL(ec.FlagFrecuencyType, '')))) = 'P'
      AND ec.PRPeriodStart <= @period_jul
      AND (
            ec.PRPeriodEnd IS NULL
         OR LTRIM(RTRIM(ec.PRPeriodEnd)) = ''
         OR ec.PRPeriodEnd >= @period_jul
          )
    GROUP BY ec.Person
)
SELECT
    LTRIM(RTRIM(j.Person)) AS DNI,
    LTRIM(RTRIM(
        ISNULL(sp.LastName1, '') + ' ' +
        ISNULL(sp.LastName2, '') + ' ' +
        ISNULL(sp.Name1, '') + ' ' +
        ISNULL(sp.Name2, '')
    )) AS NOMBRE,
    j.importe_junio AS IMPORTE_JUNIO_CALCULADO,
    a.importe_julio_asig AS IMPORTE_JULIO_ASIGNACION,
    CAST(a.importe_julio_asig - j.importe_junio AS DECIMAL(18, 4)) AS DIFERENCIA,
    CASE
        WHEN j.importe_junio = a.importe_julio_asig THEN 'IGUAL'
        ELSE 'DIFERENTE'
    END AS FLAG
FROM calc_jun j
INNER JOIN asig_jul a
    ON a.Person = j.Person
LEFT JOIN SY_Person sp (NOLOCK)
    ON sp.Person = j.Person
-- WHERE j.importe_junio <> a.importe_julio_asig   -- descomentar solo diferencias
ORDER BY
    CASE WHEN j.importe_junio = a.importe_julio_asig THEN 1 ELSE 0 END,
    NOMBRE,
    DNI;
GO



-- ============================================================================
-- [027/282] sp_ac_alvisoft_parte1.sql
-- ============================================================================

/*
    Cabecera TXT Alvisoft (registro tipo 0000).
    Optimizado para web: no modifica empleados; solo genera la cabecera.

    Usado por: POST /api/asientos/interfaz/generar-archivo
*/
CREATE OR ALTER PROCEDURE [dbo].[SP_AC_ALVISOFT_PARTE1]
    @Voucher VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        REPLICATE('0', 7 - LEN('1')) + '1' AS nroregistro1,
        '0000' AS tiporegistro1,
        '00' AS subtiporegistro1,
        '01' AS versiontiporegistro1,
        (SELECT CODECITY FROM SY_Company WHERE Company = AC_Voucher.Company) AS compania
    FROM AC_Voucher
    WHERE Voucher = @Voucher;
END

GO


-- ============================================================================
-- [028/282] sp_ac_eliminar_centro_costo_web.sql
-- ============================================================================

/*
    Maestro Centros de Costo — eliminación de AC_CostCenter.
    Usado por: POST /api/centros-costo/eliminar
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_ac_eliminar_centro_costo_web]
    @company    VARCHAR(4),
    @costcenter VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @costcenter = LTRIM(RTRIM(ISNULL(@costcenter, '')));

    IF NOT EXISTS (
        SELECT 1
        FROM AC_CostCenter (NOLOCK)
        WHERE Company = @company
          AND CostCenter = @costcenter
    )
    BEGIN
        RAISERROR('No se encontró el centro de costo.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM PR_Employee (NOLOCK)
        WHERE CostCenter = @costcenter
    )
    BEGIN
        RAISERROR('No se puede eliminar: el centro de costo está asignado a trabajadores.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM PR_EmployeePayroll (NOLOCK)
        WHERE CostCenter = @costcenter
    )
    BEGIN
        RAISERROR('No se puede eliminar: el centro de costo está referenciado en planillas.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM AC_CostCenterDistribution (NOLOCK)
        WHERE CostCenter = @costcenter
    )
    BEGIN
        RAISERROR('No se puede eliminar: el centro de costo tiene distribución contable.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM AC_CostCenter (NOLOCK)
        WHERE Company = @company
          AND CostCenter <> @costcenter
          AND (ParentLevel1 = @costcenter OR ParentLevel2 = @costcenter)
    )
    BEGIN
        RAISERROR('No se puede eliminar: el centro de costo es padre de otros centros.', 16, 1);
        RETURN;
    END;

    BEGIN TRY
        DELETE FROM AC_CostCenter
        WHERE Company = @company
          AND CostCenter = @costcenter;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 547
            RAISERROR('No se puede eliminar: el centro de costo tiene movimientos o configuraciones relacionadas.', 16, 1);
        ELSE
        BEGIN
            DECLARE @error VARCHAR(4000) = ERROR_MESSAGE();
            RAISERROR('%s', 16, 1, @error);
        END;
        RETURN;
    END CATCH;

    SELECT
        @costcenter AS costcenter,
        'Centro de costo eliminado correctamente.' AS mensaje;
END
GO



-- ============================================================================
-- [029/282] sp_ac_eliminar_cuenta_contable_web.sql
-- ============================================================================

/*
    Maestro Cuentas Contables — eliminación de AC_Account.
    Usado por: POST /api/asientos/cuentas-contables/eliminar
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_ac_eliminar_cuenta_contable_web]
    @company VARCHAR(4),
    @account VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @account = LTRIM(RTRIM(ISNULL(@account, '')));

    IF NOT EXISTS (
        SELECT 1
        FROM AC_Account (NOLOCK)
        WHERE Company = @company
          AND Account = @account
    )
    BEGIN
        RAISERROR('No se encontró la cuenta contable.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM PR_AccountProfileDetail (NOLOCK)
        WHERE Company = @company
          AND (DebitAccount = @account OR CreditAccount = @account)
    )
    BEGIN
        RAISERROR('No se puede eliminar: la cuenta está asignada a conceptos contables.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM AC_Account (NOLOCK)
        WHERE Company = @company
          AND Account <> @account
          AND (InflationAccount = @account OR AccountAssociated = @account)
    )
    BEGIN
        RAISERROR('No se puede eliminar: la cuenta está asociada a otra cuenta contable.', 16, 1);
        RETURN;
    END;

    BEGIN TRY
        DELETE FROM AC_Account
        WHERE Company = @company
          AND Account = @account;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 547
            RAISERROR('No se puede eliminar: la cuenta tiene movimientos o configuraciones relacionadas.', 16, 1);
        ELSE
        BEGIN
            DECLARE @error VARCHAR(4000) = ERROR_MESSAGE();
            RAISERROR('%s', 16, 1, @error);
        END;
        RETURN;
    END CATCH;

    SELECT
        @account AS account,
        'Cuenta contable eliminada correctamente.' AS mensaje;
END
GO



-- ============================================================================
-- [030/282] sp_ac_guardar_centro_costo_web.sql
-- ============================================================================

/*
    Maestro Centros de Costo — alta / edición de AC_CostCenter.
    El ID CostCenter se genera desde SY_ObjectSecuence, objeto ACCOSTCENTER.

    Defaults en alta:
      Name              = Description (truncado a 50)
      CCCode            = Abbrev
      CCLevel           = 1
      FlagDistribution  = 'N'
      Status            = 'A'
      ReplicationUnit   = 'LIMA'
      XLastUser/XLastDate = auditoría

    Usado por: POST /api/centros-costo/guardar

    En alta (modo I): tras grabar en la compañía origen, replica el centro
    en las demás empresas activas donde aún no exista el mismo Abbrev.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_ac_guardar_centro_costo_web]
    @modo         CHAR(1),
    @company      VARCHAR(4),
    @costcenter   VARCHAR(20) = NULL,
    @abbrev       VARCHAR(20),
    @description  VARCHAR(255),
    @xlastuser    VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @costcenter_nuevo VARCHAR(20);
    DECLARE @name VARCHAR(50);
    DECLARE @tabla_id TABLE (id_generado VARCHAR(20));
    DECLARE @cia_dest VARCHAR(4);
    DECLARE @costcenter_dest VARCHAR(20);
    DECLARE @max_seq NUMERIC(18, 0);
    DECLARE @replicadas INT = 0;

    SET @modo = UPPER(LTRIM(RTRIM(ISNULL(@modo, ''))));
    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @costcenter = NULLIF(LTRIM(RTRIM(ISNULL(@costcenter, ''))), '');
    SET @abbrev = LTRIM(RTRIM(ISNULL(@abbrev, '')));
    SET @description = LTRIM(RTRIM(ISNULL(@description, '')));
    SET @xlastuser = NULLIF(LTRIM(RTRIM(ISNULL(@xlastuser, ''))), '');
    SET @name = LEFT(@description, 50);

    IF @modo NOT IN ('I', 'U')
    BEGIN
        RAISERROR('Modo de operación inválido.', 16, 1);
        RETURN;
    END;

    IF @company = ''
    BEGIN
        RAISERROR('Indique la compañía.', 16, 1);
        RETURN;
    END;

    IF @abbrev = '' OR @description = ''
    BEGIN
        RAISERROR('Indique la abreviatura y la descripción del centro de costo.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM AC_CostCenter (NOLOCK)
        WHERE Company = @company
          AND LTRIM(RTRIM(ISNULL(Abbrev, ''))) = @abbrev
          AND (@modo = 'I' OR CostCenter <> @costcenter)
    )
    BEGIN
        RAISERROR('Ya existe un centro de costo con la misma abreviatura.', 16, 1);
        RETURN;
    END;

    IF @modo = 'I'
    BEGIN
        INSERT INTO @tabla_id (id_generado)
        EXEC dbo.sp_pr_genera_correlativo_web
            @cia = @company,
            @object = 'ACCOSTCENTER',
            @xlastuser = @xlastuser;

        SELECT @costcenter_nuevo = id_generado FROM @tabla_id;

        IF NULLIF(LTRIM(RTRIM(ISNULL(@costcenter_nuevo, ''))), '') IS NULL
        BEGIN
            RAISERROR('No se pudo generar el correlativo del centro de costo.', 16, 1);
            RETURN;
        END;

        INSERT INTO AC_CostCenter (
            CostCenter, Company, Name, Description, Abbrev,
            Status, CCCode, CCLevel, FlagDistribution,
            ReplicationUnit, XLastUser, XLastDate
        )
        VALUES (
            @costcenter_nuevo, @company, @name, @description, @abbrev,
            'A', @abbrev, 1, 'N',
            'LIMA', @xlastuser, GETDATE()
        );

        /* Replica a otras empresas activas si no tienen la misma abreviatura. */
        DECLARE empresas CURSOR LOCAL FAST_FORWARD FOR
            SELECT LTRIM(RTRIM(Company))
            FROM SY_Company (NOLOCK)
            WHERE LTRIM(RTRIM(Company)) <> @company
              AND ISNULL(status, 'A') = 'A';

        OPEN empresas;
        FETCH NEXT FROM empresas INTO @cia_dest;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            IF NOT EXISTS (
                SELECT 1
                FROM AC_CostCenter (NOLOCK)
                WHERE Company = @cia_dest
                  AND LTRIM(RTRIM(ISNULL(Abbrev, ''))) = @abbrev
            )
            AND EXISTS (
                SELECT 1
                FROM SY_ObjectSecuence (NOLOCK)
                WHERE Company = @cia_dest
                  AND Object = 'ACCOSTCENTER'
                  AND ReplicationUnit = 'LIMA'
            )
            BEGIN
                SELECT @max_seq = MAX(
                    CASE
                        WHEN ISNUMERIC(RIGHT(LTRIM(RTRIM(CostCenter)), 12)) = 1
                        THEN CAST(RIGHT(LTRIM(RTRIM(CostCenter)), 12) AS BIGINT)
                        ELSE NULL
                    END
                )
                FROM AC_CostCenter (NOLOCK)
                WHERE Company = @cia_dest;

                IF @max_seq IS NOT NULL
                BEGIN
                    UPDATE SY_ObjectSecuence
                    SET Secuence = @max_seq
                    WHERE Company = @cia_dest
                      AND Object = 'ACCOSTCENTER'
                      AND ReplicationUnit = 'LIMA'
                      AND Secuence < @max_seq;
                END;

                DELETE FROM @tabla_id;

                INSERT INTO @tabla_id (id_generado)
                EXEC dbo.sp_pr_genera_correlativo_web
                    @cia = @cia_dest,
                    @object = 'ACCOSTCENTER',
                    @xlastuser = @xlastuser;

                SELECT @costcenter_dest = id_generado FROM @tabla_id;

                IF NULLIF(LTRIM(RTRIM(ISNULL(@costcenter_dest, ''))), '') IS NOT NULL
                   AND NOT EXISTS (
                        SELECT 1 FROM AC_CostCenter (NOLOCK) WHERE CostCenter = @costcenter_dest
                   )
                BEGIN
                    INSERT INTO AC_CostCenter (
                        CostCenter, Company, Name, Description, Abbrev,
                        Status, CCCode, CCLevel, FlagDistribution,
                        ReplicationUnit, XLastUser, XLastDate
                    )
                    VALUES (
                        @costcenter_dest, @cia_dest, @name, @description, @abbrev,
                        'A', @abbrev, 1, 'N',
                        'LIMA', @xlastuser, GETDATE()
                    );
                    SET @replicadas = @replicadas + 1;
                END;
            END;

            FETCH NEXT FROM empresas INTO @cia_dest;
        END;

        CLOSE empresas;
        DEALLOCATE empresas;

        SELECT
            @costcenter_nuevo AS costcenter,
            CASE
                WHEN @replicadas > 0 THEN
                    'Centro de costo registrado correctamente. Replicado en '
                    + CAST(@replicadas AS VARCHAR(10))
                    + CASE WHEN @replicadas = 1 THEN ' empresa.' ELSE ' empresas.' END
                ELSE
                    'Centro de costo registrado correctamente.'
            END AS mensaje;
        RETURN;
    END;

    IF @costcenter IS NULL OR NOT EXISTS (
        SELECT 1
        FROM AC_CostCenter (NOLOCK)
        WHERE Company = @company
          AND CostCenter = @costcenter
    )
    BEGIN
        RAISERROR('No se encontró el centro de costo a actualizar.', 16, 1);
        RETURN;
    END;

    UPDATE AC_CostCenter
    SET Abbrev = @abbrev,
        Description = @description,
        Name = @name,
        CCCode = @abbrev,
        XLastUser = @xlastuser,
        XLastDate = GETDATE()
    WHERE Company = @company
      AND CostCenter = @costcenter;

    SELECT
        @costcenter AS costcenter,
        'Centro de costo actualizado correctamente.' AS mensaje;
END
GO



-- ============================================================================
-- [031/282] sp_ac_guardar_cuenta_contable_web.sql
-- ============================================================================

/*
    Maestro Cuentas Contables — alta / edición de AC_Account.
    El ID Account se genera desde SY_ObjectSecuence, objeto ACACCOUNT.
    Usado por: POST /api/asientos/cuentas-contables/guardar

    En alta (modo I): tras grabar en la compañía origen, replica la cuenta
    en las demás empresas activas donde aún no exista el mismo Code.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_ac_guardar_cuenta_contable_web]
    @modo      CHAR(1),
    @company   VARCHAR(4),
    @account   VARCHAR(20) = NULL,
    @code      VARCHAR(255),
    @name      VARCHAR(255),
    @xlastuser VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @account_nuevo VARCHAR(20);
    DECLARE @tabla_id TABLE (id_generado VARCHAR(20));
    DECLARE @cia_dest VARCHAR(4);
    DECLARE @account_dest VARCHAR(20);
    DECLARE @max_seq NUMERIC(18, 0);
    DECLARE @replicadas INT = 0;

    SET @modo = UPPER(LTRIM(RTRIM(ISNULL(@modo, ''))));
    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @account = NULLIF(LTRIM(RTRIM(ISNULL(@account, ''))), '');
    SET @code = LTRIM(RTRIM(ISNULL(@code, '')));
    SET @name = LTRIM(RTRIM(ISNULL(@name, '')));
    SET @xlastuser = NULLIF(LTRIM(RTRIM(ISNULL(@xlastuser, ''))), '');

    IF @modo NOT IN ('I', 'U')
    BEGIN
        RAISERROR('Modo de operación inválido.', 16, 1);
        RETURN;
    END;

    IF @company = ''
    BEGIN
        RAISERROR('Indique la compañía.', 16, 1);
        RETURN;
    END;

    IF @code = '' OR @name = ''
    BEGIN
        RAISERROR('Indique el código y nombre de la cuenta contable.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM AC_Account (NOLOCK)
        WHERE Company = @company
          AND LTRIM(RTRIM(ISNULL(Code, ''))) = @code
          AND (@modo = 'I' OR Account <> @account)
    )
    BEGIN
        RAISERROR('Ya existe una cuenta contable con el mismo código.', 16, 1);
        RETURN;
    END;

    IF @modo = 'I'
    BEGIN
        INSERT INTO @tabla_id (id_generado)
        EXEC dbo.sp_pr_genera_correlativo_web
            @cia = @company,
            @object = 'ACACCOUNT',
            @xlastuser = @xlastuser;

        SELECT @account_nuevo = id_generado FROM @tabla_id;

        IF NULLIF(LTRIM(RTRIM(ISNULL(@account_nuevo, ''))), '') IS NULL
        BEGIN
            RAISERROR('No se pudo generar el correlativo de la cuenta contable.', 16, 1);
            RETURN;
        END;

        INSERT INTO AC_Account (
            Account, Company, Code, Name, Description,
            ACCurrency, Status, XLastUser, XLastDate
        )
        VALUES (
            @account_nuevo, @company, @code, @name, @name,
            'LO', 'A', @xlastuser, GETDATE()
        );

        /* Replica a otras empresas activas si no tienen el mismo código. */
        DECLARE empresas CURSOR LOCAL FAST_FORWARD FOR
            SELECT LTRIM(RTRIM(Company))
            FROM SY_Company (NOLOCK)
            WHERE LTRIM(RTRIM(Company)) <> @company
              AND ISNULL(status, 'A') = 'A';

        OPEN empresas;
        FETCH NEXT FROM empresas INTO @cia_dest;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            IF NOT EXISTS (
                SELECT 1
                FROM AC_Account (NOLOCK)
                WHERE Company = @cia_dest
                  AND LTRIM(RTRIM(ISNULL(Code, ''))) = @code
            )
            AND EXISTS (
                SELECT 1
                FROM SY_ObjectSecuence (NOLOCK)
                WHERE Company = @cia_dest
                  AND Object = 'ACACCOUNT'
                  AND ReplicationUnit = 'LIMA'
            )
            BEGIN
                /* Asegura correlativo >= máximo ID existente en la compañía destino. */
                SELECT @max_seq = MAX(
                    CASE
                        WHEN ISNUMERIC(RIGHT(LTRIM(RTRIM(Account)), 12)) = 1
                        THEN CAST(RIGHT(LTRIM(RTRIM(Account)), 12) AS BIGINT)
                        ELSE NULL
                    END
                )
                FROM AC_Account (NOLOCK)
                WHERE Company = @cia_dest;

                IF @max_seq IS NOT NULL
                BEGIN
                    UPDATE SY_ObjectSecuence
                    SET Secuence = @max_seq
                    WHERE Company = @cia_dest
                      AND Object = 'ACACCOUNT'
                      AND ReplicationUnit = 'LIMA'
                      AND Secuence < @max_seq;
                END;

                DELETE FROM @tabla_id;

                INSERT INTO @tabla_id (id_generado)
                EXEC dbo.sp_pr_genera_correlativo_web
                    @cia = @cia_dest,
                    @object = 'ACACCOUNT',
                    @xlastuser = @xlastuser;

                SELECT @account_dest = id_generado FROM @tabla_id;

                IF NULLIF(LTRIM(RTRIM(ISNULL(@account_dest, ''))), '') IS NOT NULL
                   AND NOT EXISTS (
                        SELECT 1 FROM AC_Account (NOLOCK) WHERE Account = @account_dest
                   )
                BEGIN
                    INSERT INTO AC_Account (
                        Account, Company, Code, Name, Description,
                        ACCurrency, Status, XLastUser, XLastDate
                    )
                    VALUES (
                        @account_dest, @cia_dest, @code, @name, @name,
                        'LO', 'A', @xlastuser, GETDATE()
                    );
                    SET @replicadas = @replicadas + 1;
                END;
            END;

            FETCH NEXT FROM empresas INTO @cia_dest;
        END;

        CLOSE empresas;
        DEALLOCATE empresas;

        SELECT
            @account_nuevo AS account,
            CASE
                WHEN @replicadas > 0 THEN
                    'Cuenta contable registrada correctamente. Replicada en '
                    + CAST(@replicadas AS VARCHAR(10))
                    + CASE WHEN @replicadas = 1 THEN ' empresa.' ELSE ' empresas.' END
                ELSE
                    'Cuenta contable registrada correctamente.'
            END AS mensaje;
        RETURN;
    END;

    IF @account IS NULL OR NOT EXISTS (
        SELECT 1
        FROM AC_Account (NOLOCK)
        WHERE Company = @company
          AND Account = @account
    )
    BEGIN
        RAISERROR('No se encontró la cuenta contable a actualizar.', 16, 1);
        RETURN;
    END;

    UPDATE AC_Account
    SET Code = @code,
        Name = @name,
        Description = @name,
        XLastUser = @xlastuser,
        XLastDate = GETDATE()
    WHERE Company = @company
      AND Account = @account;

    SELECT
        @account AS account,
        'Cuenta contable actualizada correctamente.' AS mensaje;
END
GO



-- ============================================================================
-- [032/282] sp_ac_listar_centros_costo_web.sql
-- ============================================================================

/*
    Maestro Centros de Costo — listado AC_CostCenter por compañía.
    Usado por: POST /api/centros-costo/listado
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_ac_listar_centros_costo_web]
    @company  VARCHAR(4),
    @busqueda VARCHAR(255) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @busqueda = NULLIF(LTRIM(RTRIM(ISNULL(@busqueda, ''))), '');

    SELECT
        A.CostCenter AS costcenter,
        LTRIM(RTRIM(ISNULL(A.Abbrev, ''))) AS abbrev,
        LTRIM(RTRIM(ISNULL(A.Description, ''))) AS description
    FROM AC_CostCenter A (NOLOCK)
    WHERE A.Company = @company
      AND (
            @busqueda IS NULL
         OR A.Abbrev LIKE '%' + @busqueda + '%'
         OR A.Description LIKE '%' + @busqueda + '%'
         OR A.Name LIKE '%' + @busqueda + '%'
         OR A.CCCode LIKE '%' + @busqueda + '%'
      )
    ORDER BY A.Abbrev, A.Description;
END
GO



-- ============================================================================
-- [033/282] sp_ac_listar_cuentas_contables_web.sql
-- ============================================================================

/*
    Maestro Cuentas Contables — listado AC_Account por compañía.
    Usado por: POST /api/asientos/cuentas-contables/listado
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_ac_listar_cuentas_contables_web]
    @company  VARCHAR(4),
    @busqueda VARCHAR(255) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @busqueda = NULLIF(LTRIM(RTRIM(ISNULL(@busqueda, ''))), '');

    SELECT
        A.Account AS account,
        LTRIM(RTRIM(ISNULL(A.Code, ''))) AS code,
        LTRIM(RTRIM(ISNULL(A.Name, ''))) AS name
    FROM AC_Account A (NOLOCK)
    WHERE A.Company = @company
      AND (
            @busqueda IS NULL
         OR A.Code LIKE '%' + @busqueda + '%'
         OR A.Name LIKE '%' + @busqueda + '%'
      )
    ORDER BY A.Code, A.Name;
END
GO



-- ============================================================================
-- [034/282] sp_pr_5ta_trabajador_web.sql
-- ============================================================================

/*
    Seguimiento de cálculo de 5ta categoría por trabajador.
    Usado por: POST /get_calculo_quinta_trabajador

    Parámetros:
      @company     — compañía
      @payrolltype — tipo de planilla
      @process     — tipo de proceso
      @period      — periodo (yyyymmdd)
      @person      — código trabajador
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_5ta_trabajador_web]
    @company     VARCHAR(4),
    @payrolltype VARCHAR(20),
    @process     VARCHAR(20),
    @period      VARCHAR(20),
    @person      VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    SET @process = LTRIM(RTRIM(ISNULL(@process, '')));
    SET @period = LTRIM(RTRIM(ISNULL(@period, '')));
    SET @person = LTRIM(RTRIM(ISNULL(@person, '')));

    SELECT DISTINCT
        CASE
            WHEN sy_person.lastname1 IS NULL THEN ''
            ELSE sy_person.lastname1
        END + ' ' +
        CASE
            WHEN sy_person.lastname2 IS NULL THEN ''
            ELSE sy_person.lastname2
        END + ' ' +
        CASE
            WHEN sy_person.name1 IS NULL THEN ''
            ELSE sy_person.name1
        END + ' ' +
        CASE
            WHEN sy_person.name2 IS NULL THEN ''
            ELSE sy_person.name2
        END AS name,
        (
            SELECT description
            FROM sy_persondocumenttype (NOLOCK)
            WHERE sy_persondocumenttype.PersonDocumentType = sy_person.employeedocumenttype
        ) + ':' AS documenttype,
        sy_person.documentnumber,
        (SELECT 12 - CONVERT(INT, SUBSTRING(@period, 5, 2))) AS meses_pendientes,
        (
            SELECT ParameterNumberValue * 7
            FROM PR_Parameter
            WHERE shortname = 'UIT' + SUBSTRING(@period, 1, 4)
              AND PR_Parameter.Company = @company
        ) AS uit,
        (
            SELECT ParameterNumberValue
            FROM PR_Parameter
            WHERE shortname = 'UIT' + SUBSTRING(@period, 1, 4)
              AND PR_Parameter.Company = @company
        ) AS par_uit,
        pr_employeepayroll.person,
        pr_employeepayroll.company,
        pr_employeepayroll.processtype,
        pr_employeepayroll.payrolltype,
        pr_position.description AS cargo,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND SUBSTRING(PRPERIOD, 1, 6) = LEFT(@period, 6)
              AND pr_concept.formulacode = 'PROYECCION_RENTA'
              AND PERSON = pr_employee.person
        ) AS proy_ingresos,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND SUBSTRING(PRPERIOD, 1, 6) = LEFT(@period, 6)
              AND pr_concept.formulacode = 'REM_ACUM_OTRA_EM'
              AND PERSON = pr_employee.person
        ) AS rem_otra_empresa,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND SUBSTRING(PRPERIOD, 1, 6) = LEFT(@period, 6)
              AND pr_concept.formulacode = 'PROY_GRATI_JULIO'
              AND PERSON = pr_employee.person
        ) AS grati_julio,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND SUBSTRING(PRPERIOD, 1, 6) = LEFT(@period, 6)
              AND pr_concept.formulacode = 'PROY_GRATI_DICIEMBRE'
              AND PERSON = pr_employee.person
        ) AS grati_dic,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND SUBSTRING(PRPERIOD, 1, 6) = LEFT(@period, 6)
              AND pr_concept.formulacode = 'REM_ACUMULADA'
              AND PERSON = pr_employee.person
        ) AS rem_acumulada,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND SUBSTRING(PRPERIOD, 1, 6) = LEFT(@period, 6)
              AND pr_concept.formulacode = 'TOTAL_REM_IMP_RENTA'
              AND PERSON = pr_employee.person
        ) AS ingresos_5ta,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND SUBSTRING(PRPERIOD, 1, 6) = LEFT(@period, 6)
              AND pr_concept.formulacode = 'TOTAL5TAQUINCENA'
              AND PERSON = pr_employee.person
        ) AS otros_ingresos_5ta,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND SUBSTRING(PRPERIOD, 1, 6) = LEFT(@period, 6)
              AND pr_concept.formulacode = 'RET_5TA_ACUMULADA'
              AND PERSON = pr_employee.person
        ) AS ret_anteriores,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND SUBSTRING(PRPERIOD, 1, 6) = LEFT(@period, 6)
              AND pr_concept.formulacode = 'RENTA_ACUM_OTRA_EMP'
              AND PERSON = pr_employee.person
        ) AS ret_otra_empresa,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND SUBSTRING(PRPERIOD, 1, 6) = LEFT(@period, 6)
              AND pr_concept.formulacode = 'MESES'
              AND PERSON = pr_employee.person
        ) AS meses,
        CASE WHEN 1 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0101', @payrolltype, 'IN') END AS ingreso01,
        CASE WHEN 2 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0202', @payrolltype, 'IN') END AS ingreso02,
        CASE WHEN 3 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0303', @payrolltype, 'IN') END AS ingreso03,
        CASE WHEN 4 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0404', @payrolltype, 'IN') END AS ingreso04,
        CASE WHEN 5 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0505', @payrolltype, 'IN') END AS ingreso05,
        CASE WHEN 6 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0606', @payrolltype, 'IN') END AS ingreso06,
        CASE WHEN 7 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0707', @payrolltype, 'IN') END AS ingreso07,
        CASE WHEN 8 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0808', @payrolltype, 'IN') END AS ingreso08,
        CASE WHEN 9 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0909', @payrolltype, 'IN') END AS ingreso09,
        CASE WHEN 10 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1010', @payrolltype, 'IN') END AS ingreso10,
        CASE WHEN 11 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1111', @payrolltype, 'IN') END AS ingreso11,
        CASE WHEN 12 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1212', @payrolltype, 'IN') END AS ingreso12,
        CASE WHEN 1 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0101', @payrolltype, 'LI') END AS descuento01,
        CASE WHEN 2 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0202', @payrolltype, 'LI') END AS descuento02,
        CASE WHEN 3 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0303', @payrolltype, 'LI') END AS descuento03,
        CASE WHEN 4 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0404', @payrolltype, 'LI') END AS descuento04,
        CASE WHEN 5 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0505', @payrolltype, 'LI') END AS descuento05,
        CASE WHEN 6 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0606', @payrolltype, 'LI') END AS descuento06,
        CASE WHEN 7 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0707', @payrolltype, 'LI') END AS descuento07,
        CASE WHEN 8 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0808', @payrolltype, 'LI') END AS descuento08,
        CASE WHEN 9 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0909', @payrolltype, 'LI') END AS descuento09,
        CASE WHEN 10 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1010', @payrolltype, 'LI') END AS descuento10,
        CASE WHEN 11 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1111', @payrolltype, 'LI') END AS descuento11,
        CASE WHEN 12 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1212', @payrolltype, 'LI') END AS descuento12,
        CASE WHEN 1 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0101', @payrolltype, 'RE') END AS salida01,
        CASE WHEN 2 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0202', @payrolltype, 'RE') END AS salida02,
        CASE WHEN 3 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0303', @payrolltype, 'RE') END AS salida03,
        CASE WHEN 4 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0404', @payrolltype, 'RE') END AS salida04,
        CASE WHEN 5 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0505', @payrolltype, 'RE') END AS salida05,
        CASE WHEN 6 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0606', @payrolltype, 'RE') END AS salida06,
        CASE WHEN 7 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0707', @payrolltype, 'RE') END AS salida07,
        CASE WHEN 8 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0808', @payrolltype, 'RE') END AS salida08,
        CASE WHEN 9 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0909', @payrolltype, 'RE') END AS salida09,
        CASE WHEN 10 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1010', @payrolltype, 'RE') END AS salida10,
        CASE WHEN 11 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1111', @payrolltype, 'RE') END AS salida11,
        CASE WHEN 12 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1212', @payrolltype, 'RE') END AS salida12,
        CASE WHEN 1 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0101', @payrolltype, 'UT') END AS utilidad01,
        CASE WHEN 2 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0202', @payrolltype, 'UT') END AS utilidad02,
        CASE WHEN 3 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0303', @payrolltype, 'UT') END AS utilidad03,
        CASE WHEN 4 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0404', @payrolltype, 'UT') END AS utilidad04,
        CASE WHEN 5 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0505', @payrolltype, 'UT') END AS utilidad05,
        CASE WHEN 6 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0606', @payrolltype, 'UT') END AS utilidad06,
        CASE WHEN 7 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0707', @payrolltype, 'UT') END AS utilidad07,
        CASE WHEN 8 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0808', @payrolltype, 'UT') END AS utilidad08,
        CASE WHEN 9 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '0909', @payrolltype, 'UT') END AS utilidad09,
        CASE WHEN 10 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1010', @payrolltype, 'UT') END AS utilidad10,
        CASE WHEN 11 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1111', @payrolltype, 'UT') END AS utilidad11,
        CASE WHEN 12 >= CONVERT(INT, SUBSTRING(@period, 5, 2)) THEN 0 ELSE dbo.f_getSuma5ta_web(@company, @person, LEFT(@period, 4) + '1212', @payrolltype, 'UT') END AS utilidad12,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND PRPERIOD = @period
              AND pr_concept.formulacode = 'RET_RENTA_ACUM'
              AND PERSON = pr_employee.person
        ) AS ret_renta_acum,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND PRPERIOD = @period
              AND pr_concept.formulacode = 'DIFERENCIASEMANA'
              AND PERSON = pr_employee.person
        ) AS diferenciasemana,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND PRPERIOD = @period
              AND pr_concept.formulacode = 'NUMEROSEMANA'
              AND PERSON = pr_employee.person
        ) AS numerosemana,
        (
            SELECT SUM(ISNULL(CONCEPTVALUE, 0.00))
            FROM PR_EMPLOYEEPAYROLLCONCEPT, pr_concept
            WHERE PR_EMPLOYEEPAYROLLCONCEPT.COMPANY = @company
              AND pr_concept.COMPANY = @company
              AND pr_employeepayrollconcept.concept = pr_concept.concept
              AND PROCESSTYPE = @process
              AND PAYROLLTYPE = @payrolltype
              AND PRPERIOD = @period
              AND pr_concept.formulacode = 'TOTALDEV5TA'
              AND PERSON = pr_employee.person
        ) AS devolucion_quinta
    FROM pr_employee
        LEFT JOIN pr_employeecategory
            ON pr_employee.EmployeeCategory = pr_employeecategory.EmployeeCategory,
        sy_person
        LEFT JOIN sy_department
            ON sy_person.department = sy_department.department,
        sy_company,
        pr_payrolltype,
        pr_employeepayroll
        LEFT JOIN pr_position
            ON pr_employeepayroll.Position = pr_position.Position,
        PR_ProcessType,
        pr_mapping,
        pr_period,
        ac_costcenter,
        pr_periodtype
    WHERE pr_mapping.company = @company
      AND pr_employeepayroll.costcenter = ac_costcenter.costcenter
      AND pr_employee.company = pr_mapping.company
      AND pr_employee.Person = sy_person.Person
      AND pr_employee.Company = sy_company.Company
      AND pr_employeepayroll.PayRollType = pr_payrolltype.PayRollType
      AND pr_employeepayroll.Company = pr_employee.Company
      AND pr_employeepayroll.Person = pr_employee.Person
      AND pr_employeepayroll.ProcessType = PR_ProcessType.ProcessType
      AND pr_payrolltype.periodtype = pr_periodtype.periodtype
      AND pr_employeepayroll.processtype = @process
      AND pr_employeepayroll.payrolltype = @payrolltype
      AND LEFT(pr_employeepayroll.prperiod, 6) = LEFT(@period, 6)
      AND pr_employeepayroll.person = @person
      AND pr_period.payrolltype = @payrolltype
    ORDER BY 1 ASC;
END
GO



-- ============================================================================
-- [035/282] sp_pr_CambiarPassword_web.sql
-- ============================================================================

/*
    Cambia PasswordWeb de SY_User (login web).
    Usado por: POST /cambiar-password (login).

    Retorna: resultado ('OK'/'KO'), Mensaje
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_CambiarPassword_web]
    @userid      VARCHAR(20),
    @clave_ant   VARCHAR(20),
    @clave_nueva VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @uid VARCHAR(20) = LTRIM(RTRIM(ISNULL(@userid, '')));
    DECLARE @ant VARCHAR(20) = ISNULL(@clave_ant, '');
    DECLARE @nueva VARCHAR(20) = ISNULL(@clave_nueva, '');
    DECLARE @actual VARCHAR(20);

    IF @uid = ''
    BEGIN
        SELECT 'KO' AS resultado, 'Usuario no indicado.' AS Mensaje;
        RETURN;
    END;

    IF @nueva = ''
    BEGIN
        SELECT 'KO' AS resultado, 'Debe indicar la nueva contraseña.' AS Mensaje;
        RETURN;
    END;

    IF @nueva = @ant
    BEGIN
        SELECT 'KO' AS resultado, 'La nueva contraseña debe ser distinta a la anterior.' AS Mensaje;
        RETURN;
    END;

    SELECT @actual = PasswordWeb
    FROM SY_User (NOLOCK)
    WHERE UserID = @uid;

    IF @actual IS NULL
    BEGIN
        SELECT 'KO' AS resultado, 'Usuario no encontrado.' AS Mensaje;
        RETURN;
    END;

    IF ISNULL(@actual, '') <> @ant
    BEGIN
        SELECT 'KO' AS resultado, 'La contraseña anterior no es correcta.' AS Mensaje;
        RETURN;
    END;

    UPDATE SY_User
    SET PasswordWeb = @nueva,
        XLastUser = @uid,
        XLastDate = GETDATE()
    WHERE UserID = @uid;

    IF @@ROWCOUNT = 0
    BEGIN
        SELECT 'KO' AS resultado, 'No se pudo actualizar la contraseña.' AS Mensaje;
        RETURN;
    END;

    SELECT 'OK' AS resultado, 'Contraseña actualizada correctamente.' AS Mensaje;
END
GO



-- ============================================================================
-- [036/282] sp_pr_actualizar_bancario_trabajador_web.sql
-- ============================================================================

/*
    Actualiza datos bancarios y CTS del trabajador.
    Clave: person + company (@cia).
    CCI → PR_Employee.SocialAssistanceNumber (convención HM).
    Forma de pago → PR_Employee.CollectionForm (TE_CollectionForm).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_actualizar_bancario_trabajador_web]
    @cia                VARCHAR(10),
    @person             VARCHAR(20),
    @collectionform     VARCHAR(20),
    @salarybank         VARCHAR(20),
    @salaryaccounttype  VARCHAR(20),
    @salaryaccount      VARCHAR(20),
    @cci                VARCHAR(20),
    @ctsbank            VARCHAR(20),
    @ctsaccount         VARCHAR(20),
    @ctscurrency        VARCHAR(2),
    @xlastuser          VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (
        SELECT 1 FROM pr_employee
        WHERE company = @cia AND person = @person
    )
    BEGIN
        RAISERROR('Trabajador no encontrado para la compañía indicada.', 16, 1);
        RETURN;
    END

    IF RTRIM(ISNULL(@ctscurrency, '')) = '' SET @ctscurrency = 'LO';

    UPDATE pr_employee
    SET
        collectionform = NULLIF(LTRIM(RTRIM(@collectionform)), ''),
        salarybank = NULLIF(LTRIM(RTRIM(@salarybank)), ''),
        salaryaccounttype = NULLIF(LTRIM(RTRIM(@salaryaccounttype)), ''),
        salaryaccount = NULLIF(LTRIM(RTRIM(@salaryaccount)), ''),
        socialassistancenumber = NULLIF(LTRIM(RTRIM(@cci)), ''),
        ctsbank = NULLIF(LTRIM(RTRIM(@ctsbank)), ''),
        ctsaccount = NULLIF(LTRIM(RTRIM(@ctsaccount)), ''),
        ctscurrency = @ctscurrency,
        xlastdate = GETDATE(),
        xlastuser = NULLIF(LTRIM(RTRIM(@xlastuser)), '')
    WHERE company = @cia
      AND person = @person;
END
GO



-- ============================================================================
-- [037/282] sp_pr_actualizar_datos_afp_web.sql
-- ============================================================================

/*
    Control de datos AFP — actualiza PR_EmployeeAFP y PR_EmployeeAFPHeader.

    Usado por: POST /api/declaracion-afp/generar-xlsx (antes de generar el Excel AFPnet).

    Basado en: AUXILIARES/control de datos AFP.txt (PowerBuilder w_pr_afp_calc_list).

    Solo procesa combinaciones planilla/proceso que tengan concepto formulacode = TOTAL_REM_AFP
    en PR_EmployeePayRollConcept para el periodo indicado.

    CUSPP: prioriza PR_Employee.AFPCard (ficha); si falta, usa PR_EmployeePayRoll.AFPCard.

    Parámetros:
      @cia         — compañía
      @period      — periodo YYYYMM (6 dígitos)
      @payroll_all — Y = todas las planillas con TOTAL_REM_AFP, N = filtrar por @payroll
      @payroll     — tipo de planilla
      @xlastuser   — usuario que ejecuta el proceso
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_actualizar_datos_afp_web]
    @cia         VARCHAR(10),
    @period      VARCHAR(20),
    @payroll_all CHAR(1)     = 'Y',
    @payroll     VARCHAR(20) = NULL,
    @xlastuser   VARCHAR(20) = 'WEB'
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @period = LEFT(LTRIM(RTRIM(ISNULL(@period, ''))), 6);
    SET @payroll_all = UPPER(LTRIM(RTRIM(ISNULL(@payroll_all, 'Y'))));
    SET @payroll = LTRIM(RTRIM(ISNULL(@payroll, '')));
    SET @xlastuser = LTRIM(RTRIM(ISNULL(@xlastuser, 'WEB')));
    IF @payroll_all NOT IN ('Y', 'N') SET @payroll_all = 'Y';
    IF @payroll_all = 'Y' SET @payroll = '';

    DECLARE
        @AFPAssureableRemConcept VARCHAR(20),
        @AFPFixedAmountConcept VARCHAR(20),
        @AFPVariableAmountConcept VARCHAR(20),
        @AFPInsuredAmountConcept VARCHAR(20),
        @AFPARComisionAmountConcept VARCHAR(20),
        @AFPEmployerContribution VARCHAR(20),
        @LiquidacionProcess VARCHAR(20),
        @DefaultReplicationUnit VARCHAR(4);

    SELECT
        @AFPAssureableRemConcept = LTRIM(RTRIM(AFPAssureableRemConcept)),
        @AFPFixedAmountConcept = LTRIM(RTRIM(AFPFixedAmountConcept)),
        @AFPVariableAmountConcept = LTRIM(RTRIM(AFPVariableAmountConcept)),
        @AFPInsuredAmountConcept = LTRIM(RTRIM(AFPInsuredAmountConcept)),
        @AFPARComisionAmountConcept = LTRIM(RTRIM(AFPARComisionAmountConcept)),
        @AFPEmployerContribution = LTRIM(RTRIM(AfpEmployerContribution)),
        @LiquidacionProcess = LTRIM(RTRIM(LiquidacionProcess))
    FROM pr_mapping (NOLOCK)
    WHERE Company = @cia;

    IF @AFPAssureableRemConcept IS NULL OR @AFPFixedAmountConcept IS NULL
       OR @AFPVariableAmountConcept IS NULL OR @AFPInsuredAmountConcept IS NULL
       OR @AFPARComisionAmountConcept IS NULL
    BEGIN
        RAISERROR('Debe configurarse los conceptos AFP de la compañía en PR_Mapping.', 16, 1);
        RETURN;
    END

    SELECT TOP 1 @DefaultReplicationUnit = LTRIM(RTRIM(ReplicationUnit))
    FROM sy_replicationunit (NOLOCK)
    ORDER BY ReplicationUnit;

    CREATE TABLE #PlanillasProcesar (
        payrolltype VARCHAR(20) NOT NULL,
        processtype VARCHAR(20) NOT NULL,
        PRIMARY KEY (payrolltype, processtype)
    );

    INSERT INTO #PlanillasProcesar (payrolltype, processtype)
    SELECT DISTINCT
        LTRIM(RTRIM(EPC.PayRollType)),
        LTRIM(RTRIM(EPC.ProcessType))
    FROM PR_EmployeePayRollConcept EPC (NOLOCK)
        INNER JOIN PR_Concept C (NOLOCK)
            ON EPC.Concept = C.Concept
           AND EPC.Company = C.Company
    WHERE EPC.Company = @cia
      AND LEFT(EPC.PRPeriod, 6) = @period
      AND C.FormulaCode = 'TOTAL_REM_AFP'
      AND (@payroll_all = 'Y' OR EPC.PayRollType = @payroll);

    IF NOT EXISTS (SELECT 1 FROM #PlanillasProcesar)
    BEGIN
        SELECT
            0 AS actualizado,
            0 AS filas_afp,
            0 AS filas_header,
            'No hay combinaciones planilla/proceso con concepto TOTAL_REM_AFP para el periodo.' AS mensaje;
        RETURN;
    END

    CREATE TABLE #ConceptosAfp (
        person VARCHAR(20) NOT NULL,
        company VARCHAR(4) NOT NULL,
        payrolltype VARCHAR(20) NOT NULL,
        processtype VARCHAR(20) NOT NULL,
        prperiod VARCHAR(20) NOT NULL,
        concept VARCHAR(20) NOT NULL,
        conceptcurrency CHAR(2) NULL,
        exchangerate NUMERIC(18, 4) NULL,
        conceptvalue NUMERIC(18, 4) NOT NULL,
        conceptvaluelo NUMERIC(18, 4) NOT NULL,
        conceptvalueex NUMERIC(18, 4) NOT NULL,
        afpcard VARCHAR(20) NULL,
        ceasedate DATETIME NULL,
        entrydate DATETIME NULL,
        afp VARCHAR(20) NULL,
        costcenter VARCHAR(20) NULL,
        costcentername VARCHAR(20) NULL,
        replicationunit VARCHAR(4) NULL
    );

    INSERT INTO #ConceptosAfp (
        person, company, payrolltype, processtype, prperiod, concept,
        conceptcurrency, exchangerate, conceptvalue, conceptvaluelo, conceptvalueex,
        afpcard, ceasedate, entrydate, afp, costcenter, costcentername, replicationunit
    )
    SELECT
        LTRIM(RTRIM(EPC.Person)),
        LTRIM(RTRIM(EPC.Company)),
        LTRIM(RTRIM(EPC.PayRollType)),
        LTRIM(RTRIM(EPC.ProcessType)),
        LTRIM(RTRIM(EPC.PRPeriod)),
        LTRIM(RTRIM(EPC.Concept)),
        EPC.ConceptCurrency,
        EPC.ExchangeRate,
        ISNULL(EPC.ConceptValue, 0),
        ISNULL(EPC.ConceptValueLo, 0),
        ISNULL(EPC.ConceptValueEx, 0),
        LTRIM(RTRIM(COALESCE(
            NULLIF(LTRIM(RTRIM(ISNULL(EM.AFPCard, ''))), ''),
            NULLIF(LTRIM(RTRIM(ISNULL(EP.AFPCard, ''))), ''),
            ''
        ))),
        EP.CeaseDate,
        EP.EntryDate,
        LTRIM(RTRIM(EP.AFP)),
        LTRIM(RTRIM(EP.CostCenter)),
        LTRIM(RTRIM(EP.CostCenterName)),
        LTRIM(RTRIM(ISNULL(EP.ReplicationUnit, EPC.ReplicationUnit)))
    FROM PR_EmployeePayRollConcept EPC (NOLOCK)
        INNER JOIN PR_EmployeePayRoll EP (NOLOCK)
            ON EPC.Company = EP.Company
           AND EPC.PayRollType = EP.PayRollType
           AND EPC.PRPeriod = EP.PRPeriod
           AND EPC.Person = EP.Person
           AND EPC.ProcessType = EP.ProcessType
        INNER JOIN PR_Employee EM (NOLOCK)
            ON EPC.Company = EM.Company
           AND EPC.Person = EM.person
        INNER JOIN #PlanillasProcesar PP
            ON EPC.PayRollType = PP.payrolltype
           AND EPC.ProcessType = PP.processtype
    WHERE EPC.Company = @cia
      AND LEFT(EPC.PRPeriod, 6) = @period
      AND ISNULL(LTRIM(RTRIM(EP.AFP)), '') <> ''
      AND (
            EPC.Concept = @AFPAssureableRemConcept
         OR EPC.Concept = @AFPFixedAmountConcept
         OR EPC.Concept = @AFPVariableAmountConcept
         OR EPC.Concept = @AFPInsuredAmountConcept
         OR EPC.Concept = @AFPARComisionAmountConcept
         OR EPC.Concept = @AFPEmployerContribution
      );

    BEGIN TRY
        BEGIN TRANSACTION;

        DELETE H
        FROM PR_EmployeeAFPHeader H
            INNER JOIN (
                SELECT DISTINCT payrolltype FROM #PlanillasProcesar
            ) P ON H.PayRollType = P.payrolltype
        WHERE H.Company = @cia
          AND LEFT(H.PRPeriod, 6) = @period;

        DELETE A
        FROM PR_EmployeeAFP A
            INNER JOIN (
                SELECT DISTINCT payrolltype FROM #PlanillasProcesar
            ) P ON A.PayRollType = P.payrolltype
        WHERE A.Company = @cia
          AND LEFT(A.PRPeriod, 6) = @period;

        INSERT INTO PR_EmployeeAFP (
            Person, Company, PRPeriod, AFP, AFPCurrency, AFPExchangeRate,
            AssureableRemAmount, AssureableRemAmountLo, AssureableRemAmountEx,
            FixedAmount, FixedAmountLo, FixedAmountEx,
            VariableAmount, VariableAmountLo, VariableAmountEx,
            InsuredAmount, InsuredAmountLo, InsuredAmountEx,
            ARComisionAmount, ARComisionAmountLo, ARComisionAmountEx,
            EmployerContribution, EmployerContributionLo, EmployerContributionEx,
            ReplicationUnit, XLastUser, XLastDate,
            Costcenter, Costcentername, payrolltype, ceasedate, afpcard, entrydate
        )
        SELECT
            S.person,
            S.company,
            S.prperiod,
            S.afp,
            S.conceptcurrency,
            S.exchangerate,
            S.AssureableRemAmount,
            S.AssureableRemAmountLo,
            S.AssureableRemAmountEx,
            S.FixedAmount,
            S.FixedAmountLo,
            S.FixedAmountEx,
            S.VariableAmount,
            S.VariableAmountLo,
            S.VariableAmountEx,
            S.InsuredAmount,
            S.InsuredAmountLo,
            S.InsuredAmountEx,
            S.ARComisionAmount,
            S.ARComisionAmountLo,
            S.ARComisionAmountEx,
            S.EmployerContribution,
            S.EmployerContributionLo,
            S.EmployerContributionEx,
            CASE
                WHEN ISNULL(S.replicationunit, '') = '' THEN @DefaultReplicationUnit
                ELSE S.replicationunit
            END,
            @xlastuser,
            GETDATE(),
            S.costcenter,
            S.costcentername,
            S.payrolltype,
            S.ceasedate,
            LTRIM(RTRIM(COALESCE(
                NULLIF(LTRIM(RTRIM(ISNULL(EM.AFPCard, ''))), ''),
                NULLIF(LTRIM(RTRIM(ISNULL(S.afpcard, ''))), ''),
                ''
            ))),
            S.entrydate AS entrydate
        FROM (
            SELECT
                C.person,
                C.company,
                LEFT(C.prperiod, 6) + SUBSTRING(C.prperiod, 5, 2) AS prperiod,
                MAX(C.afp) AS afp,
                MAX(C.conceptcurrency) AS conceptcurrency,
                MAX(C.exchangerate) AS exchangerate,
                SUM(CASE WHEN C.concept = @AFPAssureableRemConcept THEN C.conceptvalue ELSE 0 END) AS AssureableRemAmount,
                SUM(CASE WHEN C.concept = @AFPAssureableRemConcept THEN C.conceptvaluelo ELSE 0 END) AS AssureableRemAmountLo,
                SUM(CASE WHEN C.concept = @AFPAssureableRemConcept THEN C.conceptvalueex ELSE 0 END) AS AssureableRemAmountEx,
                SUM(CASE WHEN C.concept = @AFPFixedAmountConcept THEN C.conceptvalue ELSE 0 END) AS FixedAmount,
                SUM(CASE WHEN C.concept = @AFPFixedAmountConcept THEN C.conceptvaluelo ELSE 0 END) AS FixedAmountLo,
                SUM(CASE WHEN C.concept = @AFPFixedAmountConcept THEN C.conceptvalueex ELSE 0 END) AS FixedAmountEx,
                SUM(CASE WHEN C.concept = @AFPVariableAmountConcept THEN C.conceptvalue ELSE 0 END) AS VariableAmount,
                SUM(CASE WHEN C.concept = @AFPVariableAmountConcept THEN C.conceptvaluelo ELSE 0 END) AS VariableAmountLo,
                SUM(CASE WHEN C.concept = @AFPVariableAmountConcept THEN C.conceptvalueex ELSE 0 END) AS VariableAmountEx,
                SUM(CASE WHEN C.concept = @AFPInsuredAmountConcept THEN C.conceptvalue ELSE 0 END) AS InsuredAmount,
                SUM(CASE WHEN C.concept = @AFPInsuredAmountConcept THEN C.conceptvaluelo ELSE 0 END) AS InsuredAmountLo,
                SUM(CASE WHEN C.concept = @AFPInsuredAmountConcept THEN C.conceptvalueex ELSE 0 END) AS InsuredAmountEx,
                SUM(CASE WHEN C.concept = @AFPARComisionAmountConcept THEN C.conceptvalue ELSE 0 END) AS ARComisionAmount,
                SUM(CASE WHEN C.concept = @AFPARComisionAmountConcept THEN C.conceptvaluelo ELSE 0 END) AS ARComisionAmountLo,
                SUM(CASE WHEN C.concept = @AFPARComisionAmountConcept THEN C.conceptvalueex ELSE 0 END) AS ARComisionAmountEx,
                SUM(CASE WHEN C.concept = @AFPEmployerContribution THEN C.conceptvalue ELSE 0 END) AS EmployerContribution,
                SUM(CASE WHEN C.concept = @AFPEmployerContribution THEN C.conceptvaluelo ELSE 0 END) AS EmployerContributionLo,
                SUM(CASE WHEN C.concept = @AFPEmployerContribution THEN C.conceptvalueex ELSE 0 END) AS EmployerContributionEx,
                MAX(C.replicationunit) AS replicationunit,
                MAX(C.costcenter) AS costcenter,
                MAX(C.costcentername) AS costcentername,
                MAX(C.payrolltype) AS payrolltype,
                MAX(C.afpcard) AS afpcard,
                /* Preferir FIN_DE_MES; si no hay, LIQUIDACION / SEMANAL (obreros). */
                COALESCE(
                    MAX(CASE WHEN LTRIM(RTRIM(PT.ShortName)) = 'FIN_DE_MES' THEN C.ceasedate END),
                    MAX(CASE WHEN LTRIM(RTRIM(PT.ShortName)) = 'LIQUIDACION' THEN C.ceasedate END),
                    MAX(CASE WHEN LTRIM(RTRIM(PT.ShortName)) = 'SEMANAL' THEN C.ceasedate END)
                ) AS ceasedate,
                COALESCE(
                    MAX(CASE WHEN LTRIM(RTRIM(PT.ShortName)) = 'FIN_DE_MES' THEN C.entrydate END),
                    MAX(CASE WHEN LTRIM(RTRIM(PT.ShortName)) = 'LIQUIDACION' THEN C.entrydate END),
                    MAX(CASE WHEN LTRIM(RTRIM(PT.ShortName)) = 'SEMANAL' THEN C.entrydate END)
                ) AS entrydate,
                SUM(CASE
                    WHEN C.concept IN (
                        @AFPFixedAmountConcept, @AFPVariableAmountConcept,
                        @AFPInsuredAmountConcept, @AFPARComisionAmountConcept, @AFPEmployerContribution
                    ) THEN 1 ELSE 0
                END) AS tiene_aportes
            FROM #ConceptosAfp C
                INNER JOIN PR_ProcessType PT (NOLOCK)
                    ON PT.ProcessType = C.processtype
                   AND PT.Company = C.company
            GROUP BY C.person, C.company, C.payrolltype, LEFT(C.prperiod, 6) + SUBSTRING(C.prperiod, 5, 2)
        ) S
            INNER JOIN pr_employee EM (NOLOCK)
                ON EM.person = S.person
               AND EM.company = S.company
        WHERE S.tiene_aportes > 0
          AND ISNULL(LTRIM(RTRIM(S.afp)), '') <> '';

        INSERT INTO PR_EmployeeAFPHeader (
            Company, ReplicationUnit, PRPeriod, PayRollType, AFP, costcenter,
            costcentername, PaymentStatus, XLastUser, XLastDate
        )
        SELECT
            A.Company,
            A.ReplicationUnit,
            A.PRPeriod,
            A.PayRollType,
            A.AFP,
            A.Costcenter,
            MAX(A.Costcentername),
            'P',
            @xlastuser,
            GETDATE()
        FROM PR_EmployeeAFP A (NOLOCK)
        WHERE A.Company = @cia
          AND LEFT(A.PRPeriod, 6) = @period
          AND A.PayRollType IN (SELECT DISTINCT payrolltype FROM #PlanillasProcesar)
          AND ISNULL(A.ReplicationUnit, '') <> ''
        GROUP BY
            A.Company, A.ReplicationUnit, A.PRPeriod, A.PayRollType, A.AFP, A.Costcenter;

        UPDATE PR_EmployeeAFP
        SET AssureableRemAmountLo = AssureableRemAmount
        WHERE Company = @cia
          AND LEFT(PRPeriod, 4) = LEFT(@period, 4);

        COMMIT TRANSACTION;

        SELECT
            1 AS actualizado,
            (SELECT COUNT(*) FROM PR_EmployeeAFP (NOLOCK)
             WHERE Company = @cia AND LEFT(PRPeriod, 6) = @period
               AND PayRollType IN (SELECT DISTINCT payrolltype FROM #PlanillasProcesar)) AS filas_afp,
            (SELECT COUNT(*) FROM PR_EmployeeAFPHeader (NOLOCK)
             WHERE Company = @cia AND LEFT(PRPeriod, 6) = @period
               AND PayRollType IN (SELECT DISTINCT payrolltype FROM #PlanillasProcesar)) AS filas_header,
            'Control de datos AFP ejecutado correctamente.' AS mensaje;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        DECLARE @err VARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR('Error en control de datos AFP: %s', 16, 1, @err);
    END CATCH
END
GO



-- ============================================================================
-- [038/282] sp_pr_actualizar_datoseducacion_trabajador_web.sql
-- ============================================================================

/*
    Actualiza datos de educación en SY_Person para un trabajador web.
    Reutiliza campos del legado:
      InstructionLevel, CostCenter1, CostCenter2, DriverLicenseAntiquity,
      Specialty, ProfesionalStudiesCenterType, IsTrainer, Indicator.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_actualizar_datoseducacion_trabajador_web]
    @cia                            VARCHAR(10),
    @person                         VARCHAR(20),
    @instructionlevel               VARCHAR(20) = NULL,
    @costcenter1                    VARCHAR(20) = NULL,
    @costcenter2                    VARCHAR(20) = NULL,
    @anio_egreso                    VARCHAR(10) = NULL,
    @specialty                      VARCHAR(100) = NULL,
    @profesionalstudiescentertype   CHAR(1) = NULL,
    @istrainer                      CHAR(1) = NULL,
    @indicator                      CHAR(1) = NULL,
    @xlastuser                      VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @anio_int INT;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @person = UPPER(LTRIM(RTRIM(ISNULL(@person, ''))));
    SET @instructionlevel = NULLIF(LTRIM(RTRIM(ISNULL(@instructionlevel, ''))), '');
    SET @costcenter1 = NULLIF(LTRIM(RTRIM(ISNULL(@costcenter1, ''))), '');
    SET @costcenter2 = NULLIF(LTRIM(RTRIM(ISNULL(@costcenter2, ''))), '');
    SET @anio_egreso = NULLIF(LTRIM(RTRIM(ISNULL(@anio_egreso, ''))), '');
    SET @specialty = NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@specialty, '')))), '');
    SET @profesionalstudiescentertype = NULLIF(LTRIM(RTRIM(ISNULL(@profesionalstudiescentertype, ''))), '');
    SET @istrainer = UPPER(NULLIF(LTRIM(RTRIM(ISNULL(@istrainer, ''))), ''));
    SET @indicator = NULLIF(LTRIM(RTRIM(ISNULL(@indicator, ''))), '');
    SET @xlastuser = NULLIF(LTRIM(RTRIM(ISNULL(@xlastuser, ''))), '');

    IF @cia = '' OR @person = ''
    BEGIN
        RAISERROR('Indique compañía y código de trabajador.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1 FROM pr_employee (NOLOCK)
        WHERE company = @cia AND person = @person
    )
    BEGIN
        RAISERROR('Trabajador no encontrado para la compañía indicada.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (SELECT 1 FROM sy_person (NOLOCK) WHERE person = @person)
    BEGIN
        RAISERROR('No se encontró la persona indicada.', 16, 1);
        RETURN;
    END;

    IF @instructionlevel IS NOT NULL
       AND NOT EXISTS (
            SELECT 1 FROM pr_instructionlevel (NOLOCK)
            WHERE instructionlevel = @instructionlevel
       )
    BEGIN
        RAISERROR('Nivel de instrucción no válido.', 16, 1);
        RETURN;
    END;

    IF @costcenter1 IS NOT NULL
       AND NOT EXISTS (
            SELECT 1 FROM pr_institution (NOLOCK)
            WHERE company = @cia AND pdt = @costcenter1
       )
    BEGIN
        RAISERROR('Institución no válida para la compañía.', 16, 1);
        RETURN;
    END;

    IF @costcenter2 IS NOT NULL
    BEGIN
        IF @costcenter1 IS NULL
        BEGIN
            RAISERROR('Seleccione la institución antes de la carrera.', 16, 1);
            RETURN;
        END;

        IF NOT EXISTS (
            SELECT 1
            FROM pr_career c (NOLOCK)
                INNER JOIN pr_institution i (NOLOCK)
                    ON i.institution = c.institution
                   AND i.company = c.company
            WHERE c.company = @cia
              AND i.pdt = @costcenter1
              AND c.pdt = @costcenter2
        )
        BEGIN
            RAISERROR('Carrera no válida para la institución seleccionada.', 16, 1);
            RETURN;
        END;
    END;

    SET @anio_int = NULL;
    IF @anio_egreso IS NOT NULL
    BEGIN
        IF ISNUMERIC(@anio_egreso) = 0
           OR LEN(@anio_egreso) <> 4
           OR CAST(@anio_egreso AS INT) < 1900
           OR CAST(@anio_egreso AS INT) > 2100
        BEGIN
            RAISERROR('Año de egreso no válido. Use formato YYYY (ej. 1997).', 16, 1);
            RETURN;
        END;
        SET @anio_int = CAST(@anio_egreso AS INT);
    END;

    IF @profesionalstudiescentertype IS NOT NULL
       AND @profesionalstudiescentertype NOT IN ('1', '2', '3', '4')
    BEGIN
        RAISERROR('Tipo de centro de formación no válido.', 16, 1);
        RETURN;
    END;

    IF @istrainer IS NULL
        SET @istrainer = 'N';
    IF @istrainer NOT IN ('Y', 'N')
    BEGIN
        RAISERROR('Valor de estudios concluidos no válido.', 16, 1);
        RETURN;
    END;

    IF @indicator IS NOT NULL AND LEN(@indicator) > 1
    BEGIN
        RAISERROR('Indicador no válido.', 16, 1);
        RETURN;
    END;

    UPDATE sy_person
    SET instructionlevel = @instructionlevel,
        costcenter1 = @costcenter1,
        costcenter2 = @costcenter2,
        driverlicenseantiquity = @anio_int,
        specialty = @specialty,
        profesionalstudiescentertype = @profesionalstudiescentertype,
        istrainer = @istrainer,
        indicator = @indicator,
        xlastuser = @xlastuser,
        xlastdate = GETDATE()
    WHERE person = @person;
END
GO



-- ============================================================================
-- [039/282] sp_pr_actualizar_datosgenerales_trabajador_web.sql
-- ============================================================================

/*
    Actualiza datos generales de SY_Person para un trabajador web.
    El código (person) no se modifica. Status siempre Activo (A).
    Name se calcula: ApellidoPaterno + ApellidoMaterno + Nombre1 + Nombre2.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_actualizar_datosgenerales_trabajador_web]
    @cia                    VARCHAR(10),
    @person                 VARCHAR(20),
    @name1                  VARCHAR(40),
    @name2                  VARCHAR(40) = NULL,
    @lastname1              VARCHAR(40),
    @lastname2              VARCHAR(40) = NULL,
    @birthdate              VARCHAR(10) = NULL,
    @sex                    CHAR(1),
    @sectelephone           VARCHAR(15) = NULL,
    @email                  VARCHAR(255) = NULL,
    @address                VARCHAR(255) = NULL,
    @nacionalidad           VARCHAR(100) = NULL,
    @localite               VARCHAR(20) = NULL,
    @employeedocumenttype   VARCHAR(20),
    @documentnumber         VARCHAR(15),
    @replicationunit        VARCHAR(4),
    @userid                 VARCHAR(20) = NULL,
    @xlastuser              VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @nombre_completo VARCHAR(100);
    DECLARE @userid_norm     VARCHAR(20);
    DECLARE @birthdate_dt    DATETIME;
    DECLARE @localite_norm   VARCHAR(20);
    DECLARE @province_id     VARCHAR(20);
    DECLARE @department_id   VARCHAR(20);
    DECLARE @country_id      VARCHAR(20);

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @person = UPPER(LTRIM(RTRIM(ISNULL(@person, ''))));
    SET @name1 = UPPER(LTRIM(RTRIM(ISNULL(@name1, ''))));
    SET @name2 = UPPER(LTRIM(RTRIM(ISNULL(@name2, ''))));
    SET @lastname1 = UPPER(LTRIM(RTRIM(ISNULL(@lastname1, ''))));
    SET @lastname2 = UPPER(LTRIM(RTRIM(ISNULL(@lastname2, ''))));
    SET @birthdate = NULLIF(LTRIM(RTRIM(ISNULL(@birthdate, ''))), '');
    SET @sex = NULLIF(LTRIM(RTRIM(ISNULL(@sex, ''))), '');
    SET @sectelephone = NULLIF(LTRIM(RTRIM(ISNULL(@sectelephone, ''))), '');
    SET @email = NULLIF(LTRIM(RTRIM(ISNULL(@email, ''))), '');
    SET @address = NULLIF(LTRIM(RTRIM(ISNULL(@address, ''))), '');
    SET @nacionalidad = NULLIF(LTRIM(RTRIM(ISNULL(@nacionalidad, ''))), '');
    SET @localite_norm = NULLIF(LTRIM(RTRIM(ISNULL(@localite, ''))), '');
    SET @employeedocumenttype = LTRIM(RTRIM(ISNULL(@employeedocumenttype, '')));
    SET @province_id = NULL;
    SET @department_id = NULL;
    SET @country_id = NULL;
    SET @documentnumber = LTRIM(RTRIM(ISNULL(@documentnumber, '')));
    SET @replicationunit = UPPER(LTRIM(RTRIM(ISNULL(@replicationunit, ''))));
    SET @userid_norm = NULLIF(LOWER(LTRIM(RTRIM(ISNULL(@userid, '')))), '');
    SET @xlastuser = NULLIF(LTRIM(RTRIM(ISNULL(@xlastuser, ''))), '');

    IF @cia = '' OR @person = ''
    BEGIN
        RAISERROR('Indique compañía y código de trabajador.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM pr_employee (NOLOCK)
        WHERE company = @cia
          AND person = @person
    )
    BEGIN
        RAISERROR('Trabajador no encontrado para la compañía indicada.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM sy_person (NOLOCK)
        WHERE person = @person
    )
    BEGIN
        RAISERROR('No se encontró la persona indicada.', 16, 1);
        RETURN;
    END;

    IF @name1 = '' OR @lastname1 = ''
    BEGIN
        RAISERROR('Indique primer nombre y apellido paterno.', 16, 1);
        RETURN;
    END;

    IF @employeedocumenttype = ''
    BEGIN
        RAISERROR('Indique el tipo de documento.', 16, 1);
        RETURN;
    END;

    IF @documentnumber = ''
    BEGIN
        RAISERROR('Indique el número de documento.', 16, 1);
        RETURN;
    END;

    IF @replicationunit = ''
    BEGIN
        RAISERROR('Indique la unidad.', 16, 1);
        RETURN;
    END;

    IF @sex IS NULL OR @sex = ''
    BEGIN
        RAISERROR('Indique el sexo.', 16, 1);
        RETURN;
    END;

    IF @sex NOT IN ('1', '2')
    BEGIN
        RAISERROR('Sexo no válido. Use 1 (Masculino) o 2 (Femenino).', 16, 1);
        RETURN;
    END;

    SET @birthdate_dt = NULL;
    IF @birthdate IS NOT NULL
    BEGIN
        IF ISDATE(@birthdate) = 0
        BEGIN
            RAISERROR('Fecha de nacimiento no válida.', 16, 1);
            RETURN;
        END;
        SET @birthdate_dt = CONVERT(DATETIME, @birthdate, 120);
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM sy_persondocumenttype (NOLOCK)
        WHERE persondocumenttype = @employeedocumenttype
          AND company = @cia
    )
    BEGIN
        RAISERROR('Tipo de documento no válido para la compañía.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM sy_replicationunit (NOLOCK)
        WHERE replicationunit = @replicationunit
    )
    BEGIN
        RAISERROR('Unidad no válida.', 16, 1);
        RETURN;
    END;

    IF @userid_norm IS NOT NULL
    BEGIN
        IF NOT EXISTS (
            SELECT 1
            FROM sy_user (NOLOCK)
            WHERE userid = @userid_norm
        )
        BEGIN
            RAISERROR('El usuario indicado no existe en el sistema.', 16, 1);
            RETURN;
        END;

        IF EXISTS (
            SELECT 1
            FROM sy_person (NOLOCK)
            WHERE userid = @userid_norm
              AND person <> @person
        )
        BEGIN
            RAISERROR('El usuario ya está asignado a otro trabajador.', 16, 1);
            RETURN;
        END;
    END;

    IF @localite_norm IS NOT NULL
    BEGIN
        SELECT
            @province_id = LTRIM(RTRIM(l.Province)),
            @department_id = LTRIM(RTRIM(p.Department)),
            @country_id = LTRIM(RTRIM(d.Country))
        FROM SY_Localite l (NOLOCK)
            INNER JOIN SY_Province p (NOLOCK)
                ON p.Province = l.Province
            INNER JOIN SY_Department d (NOLOCK)
                ON d.Department = p.Department
            INNER JOIN SY_Country c (NOLOCK)
                ON c.Country = d.Country
        WHERE l.Localite = @localite_norm
          AND UPPER(LTRIM(RTRIM(ISNULL(c.Name, '')))) = 'PERU';

        IF @province_id IS NULL
        BEGIN
            RAISERROR('Ubigeo / distrito no válido.', 16, 1);
            RETURN;
        END;
    END;

    SET @nombre_completo = UPPER(LTRIM(RTRIM(
        ISNULL(@lastname1, '') + ' ' +
        ISNULL(@lastname2, '') + ' ' +
        ISNULL(@name1, '') + ' ' +
        ISNULL(@name2, '')
    )));

    IF LEN(@nombre_completo) > 100
        SET @nombre_completo = LEFT(@nombre_completo, 100);

    UPDATE sy_person
    SET name1 = @name1,
        name2 = NULLIF(@name2, ''),
        lastname1 = @lastname1,
        lastname2 = NULLIF(@lastname2, ''),
        birthdate = @birthdate_dt,
        sex = @sex,
        name = @nombre_completo,
        sectelephone = @sectelephone,
        email = @email,
        address = @address,
        nacionalidad = @nacionalidad,
        localite = @localite_norm,
        province = @province_id,
        department = @department_id,
        country = @country_id,
        employeedocumenttype = @employeedocumenttype,
        documenttype = @employeedocumenttype,
        documentnumber = @documentnumber,
        replicationunit = @replicationunit,
        userid = @userid_norm,
        flaguserid = CASE WHEN @userid_norm IS NULL THEN 'N' ELSE 'Y' END,
        status = 'A',
        flagname = 'P',
        isemployee = 'Y',
        xlastuser = @xlastuser,
        xlastdate = GETDATE()
    WHERE person = @person;
END
GO



-- ============================================================================
-- [040/282] sp_pr_actualizar_datoslaborales_trabajador_web.sql
-- ============================================================================

/*
    Actualiza datos laborales del trabajador (PR_Employee) y sincroniza REM_BASICA si existe.
    Fechas: VARCHAR(10) YYYY-MM-DD o vacío → NULL.
    @modo_reingreso = 'Y': limpia cese, Status='N', EntryDate inmutable y valida nueva ReEntryDate.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_actualizar_datoslaborales_trabajador_web]
    @cia                VARCHAR(10),
    @person             VARCHAR(20),
    @employeetype       VARCHAR(20) = NULL,
    @employeecategory   VARCHAR(20) = NULL,
    @entrydate          VARCHAR(10) = '',
    @reentrydate        VARCHAR(10) = '',
    @ceasedate          VARCHAR(10) = '',
    @ceasereason        VARCHAR(30) = NULL,
    @contractmodality   VARCHAR(20) = NULL,
    @ocupation          VARCHAR(20) = NULL,
    @specialstatus      VARCHAR(20) = NULL,
    @position           VARCHAR(20) = NULL,
    @costcenter         VARCHAR(20) = NULL,
    @payrolltype        VARCHAR(20) = NULL,
    @accountprofile     VARCHAR(20) = NULL,
    @sueldo             VARCHAR(20) = NULL,
    @flagasigfamiliar   VARCHAR(1) = 'N',
    @xlastuser          VARCHAR(20) = NULL,
    @modo_reingreso     VARCHAR(1)  = 'N'
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (
        SELECT 1 FROM pr_employee
        WHERE company = @cia AND person = @person
    )
    BEGIN
        RAISERROR('Trabajador no encontrado para la compañía indicada.', 16, 1);
        RETURN;
    END

    IF RTRIM(ISNULL(@flagasigfamiliar, '')) NOT IN ('Y', 'N') SET @flagasigfamiliar = 'N';
    SET @modo_reingreso = UPPER(LTRIM(RTRIM(ISNULL(@modo_reingreso, 'N'))));
    IF @modo_reingreso NOT IN ('Y', 'N') SET @modo_reingreso = 'N';

    DECLARE @fecha_ingreso DATETIME = NULL;
    DECLARE @fecha_reingreso DATETIME = NULL;
    DECLARE @fecha_cese DATETIME = NULL;
    DECLARE @rembasica NUMERIC(18, 4) = NULL;
    DECLARE @costcentername VARCHAR(20) = NULL;
    DECLARE @entry_actual DATETIME = NULL;
    DECLARE @reentry_actual DATETIME = NULL;
    DECLARE @cese_actual DATETIME = NULL;
    DECLARE @fecha_efectiva_anterior DATE = NULL;

    SELECT
        @entry_actual = e.EntryDate,
        @reentry_actual = e.ReEntryDate,
        @cese_actual = e.CeaseDate
    FROM pr_employee e
    WHERE e.Company = @cia
      AND e.Person = @person;

    IF @modo_reingreso = 'Y'
    BEGIN
        IF @cese_actual IS NULL
        BEGIN
            RAISERROR('Solo se puede registrar reingreso de un trabajador cesado.', 16, 1);
            RETURN;
        END

        -- En reingreso la fecha de ingreso original no cambia.
        SET @fecha_ingreso = @entry_actual;
        SET @fecha_cese = NULL;
        SET @ceasereason = NULL;

        IF RTRIM(ISNULL(@reentrydate, '')) = '' OR ISDATE(@reentrydate) = 0
        BEGIN
            RAISERROR('Indique la fecha de reingreso.', 16, 1);
            RETURN;
        END

        SET @fecha_reingreso = CONVERT(DATETIME, @reentrydate, 120);
        SET @fecha_efectiva_anterior = CONVERT(DATE, ISNULL(@reentry_actual, @entry_actual));

        IF @fecha_efectiva_anterior IS NOT NULL
           AND CONVERT(DATE, @fecha_reingreso) <= @fecha_efectiva_anterior
        BEGIN
            RAISERROR('La fecha de reingreso debe ser posterior a la fecha de ingreso/reingreso anterior.', 16, 1);
            RETURN;
        END

        IF CONVERT(DATE, @fecha_reingreso) <= CONVERT(DATE, @cese_actual)
        BEGIN
            RAISERROR('La fecha de reingreso debe ser posterior a la fecha de cese.', 16, 1);
            RETURN;
        END
    END
    ELSE
    BEGIN
        IF RTRIM(ISNULL(@entrydate, '')) <> '' AND ISDATE(@entrydate) = 1
            SET @fecha_ingreso = CONVERT(DATETIME, @entrydate, 120);

        IF RTRIM(ISNULL(@reentrydate, '')) <> '' AND ISDATE(@reentrydate) = 1
            SET @fecha_reingreso = CONVERT(DATETIME, @reentrydate, 120);

        IF RTRIM(ISNULL(@ceasedate, '')) <> '' AND ISDATE(@ceasedate) = 1
            SET @fecha_cese = CONVERT(DATETIME, @ceasedate, 120);

        IF RTRIM(ISNULL(@ceasedate, '')) <> '' AND @fecha_cese IS NULL
        BEGIN
            RAISERROR('La fecha de cese indicada no es válida.', 16, 1);
            RETURN;
        END

        IF @fecha_cese IS NOT NULL AND NULLIF(LTRIM(RTRIM(ISNULL(@ceasereason, ''))), '') IS NULL
        BEGIN
            RAISERROR('Indique el motivo de cese cuando registra una fecha de cese.', 16, 1);
            RETURN;
        END
    END

    IF RTRIM(ISNULL(@sueldo, '')) <> ''
    BEGIN
        BEGIN TRY
            SET @rembasica = CONVERT(NUMERIC(18, 4), REPLACE(@sueldo, ',', ''));
        END TRY
        BEGIN CATCH
            SET @rembasica = NULL;
        END CATCH
        IF @rembasica IS NULL
        BEGIN
            RAISERROR('El sueldo indicado no es un valor numérico válido.', 16, 1);
            RETURN;
        END
    END

    IF NULLIF(LTRIM(RTRIM(ISNULL(@costcenter, ''))), '') IS NOT NULL
    BEGIN
        SELECT TOP 1 @costcentername = LTRIM(RTRIM(ISNULL(cc.Name, '')))
        FROM AC_CostCenter cc (NOLOCK)
        WHERE cc.Company = @cia
          AND cc.CostCenter = LTRIM(RTRIM(@costcenter));
    END

    UPDATE pr_employee
    SET
        employeetype = NULLIF(LTRIM(RTRIM(@employeetype)), ''),
        employeecategory = NULLIF(LTRIM(RTRIM(@employeecategory)), ''),
        entrydate = @fecha_ingreso,
        reentrydate = @fecha_reingreso,
        ceasedate = @fecha_cese,
        ceasereason = CASE
            WHEN @fecha_cese IS NULL THEN NULL
            ELSE NULLIF(LTRIM(RTRIM(@ceasereason)), '')
        END,
        Status = CASE
            WHEN @modo_reingreso = 'Y' THEN 'N'
            ELSE Status
        END,
        contractmodality = NULLIF(LTRIM(RTRIM(@contractmodality)), ''),
        ocupation = NULLIF(LTRIM(RTRIM(@ocupation)), ''),
        specialstatus = NULLIF(LTRIM(RTRIM(@specialstatus)), ''),
        position = NULLIF(LTRIM(RTRIM(@position)), ''),
        costcenter = NULLIF(LTRIM(RTRIM(@costcenter)), ''),
        costcentername = CASE
            WHEN NULLIF(LTRIM(RTRIM(@costcenter)), '') IS NULL THEN NULL
            ELSE NULLIF(@costcentername, '')
        END,
        payrolltype = NULLIF(LTRIM(RTRIM(@payrolltype)), ''),
        accountprofile = NULLIF(LTRIM(RTRIM(@accountprofile)), ''),
        rembasica = CASE WHEN @rembasica IS NULL THEN rembasica ELSE @rembasica END,
        salary = CASE WHEN @rembasica IS NULL THEN salary ELSE @rembasica END,
        flagasigfamiliar = @flagasigfamiliar,
        xlastdate = GETDATE(),
        xlastuser = NULLIF(LTRIM(RTRIM(@xlastuser)), '')
    WHERE company = @cia
      AND person = @person;

    IF @rembasica IS NOT NULL
    BEGIN
        UPDATE ec
        SET
            ec.ConceptValue = @rembasica,
            ec.ConceptValueLo = CASE
                WHEN UPPER(LTRIM(RTRIM(ISNULL(ec.ConceptCurrency, 'LO')))) = 'LO'
                    THEN @rembasica
                ELSE ec.ConceptValueLo
            END,
            ec.XLastDate = GETDATE(),
            ec.XLastUser = NULLIF(LTRIM(RTRIM(@xlastuser)), '')
        FROM PR_EmployeeConcept ec
            INNER JOIN PR_Concept c
                ON c.Concept = ec.Concept
               AND c.Company = ec.Company
        WHERE ec.Company = @cia
          AND ec.Person = @person
          AND c.FormulaCode = 'REM_BASICA'
          AND ec.FlagFrecuencyType = 'P'
          AND ec.PRPeriodEnd IS NULL;
    END
END
GO



-- ============================================================================
-- [041/282] sp_pr_actualizar_pensiones_trabajador_web.sql
-- ============================================================================

/*
    Actualiza datos de pensiones del trabajador (PR_Employee).
    Clave: person + company (@cia).
    Fecha inscripción: VARCHAR(10) YYYY-MM-DD o vacío → NULL.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_actualizar_pensiones_trabajador_web]
    @cia                        VARCHAR(10),
    @person                     VARCHAR(20),
    @pensiontype                VARCHAR(20),
    @pensioninscriptiondate     VARCHAR(10) = '',
    @regimehealth               VARCHAR(20),
    @flagmixta                  VARCHAR(1) = 'N',
    @cuspp                      VARCHAR(20) = NULL,
    @xlastuser                  VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (
        SELECT 1 FROM pr_employee
        WHERE company = @cia AND person = @person
    )
    BEGIN
        RAISERROR('Trabajador no encontrado para la compañía indicada.', 16, 1);
        RETURN;
    END

    IF RTRIM(ISNULL(@flagmixta, '')) NOT IN ('Y', 'N') SET @flagmixta = 'N';

    DECLARE @fecha_inscripcion DATETIME = NULL;
    DECLARE @afp_id VARCHAR(20) = NULL;
    DECLARE @pension_pdt VARCHAR(20) = NULL;
    DECLARE @pensiontype_norm VARCHAR(20) = NULLIF(LTRIM(RTRIM(@pensiontype)), '');

    IF RTRIM(ISNULL(@pensioninscriptiondate, '')) <> ''
       AND ISDATE(@pensioninscriptiondate) = 1
        SET @fecha_inscripcion = CONVERT(DATETIME, @pensioninscriptiondate, 120);

    /* Resolver AFP automáticamente desde el régimen (sin UI). */
    IF @pensiontype_norm IS NOT NULL
    BEGIN
        SELECT @pension_pdt = LTRIM(RTRIM(ISNULL(pt.PDT, '')))
        FROM PR_PensionType pt (NOLOCK)
        WHERE pt.PensionType = @pensiontype_norm;

        IF @pension_pdt IN ('21', '23', '24', '25')
            OR EXISTS (
                SELECT 1
                FROM PR_PensionType pt (NOLOCK)
                WHERE pt.PensionType = @pensiontype_norm
                  AND (
                        UPPER(LTRIM(RTRIM(ISNULL(pt.Description, '')))) LIKE '%SPP%'
                     OR UPPER(LTRIM(RTRIM(ISNULL(pt.Description, '')))) LIKE '%AFP%'
                  )
                  AND UPPER(LTRIM(RTRIM(ISNULL(pt.Description, '')))) NOT LIKE '%ONP%'
            )
        BEGIN
            IF @pension_pdt IN ('21', '23', '24', '25')
                SELECT TOP 1 @afp_id = a.AFP
                FROM PR_AFP a (NOLOCK)
                WHERE a.Company = @cia
                  AND LTRIM(RTRIM(ISNULL(a.PDT, ''))) = @pension_pdt
                ORDER BY
                    CASE WHEN a.AFP LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END,
                    a.AFP;
        END;
    END;

    UPDATE pr_employee
    SET
        pensiontype = @pensiontype_norm,
        pensioninscriptiondate = @fecha_inscripcion,
        regimehealth = NULLIF(LTRIM(RTRIM(@regimehealth)), ''),
        flagmixta = @flagmixta,
        afpcard = NULLIF(LTRIM(RTRIM(@cuspp)), ''),
        afp = @afp_id,
        xlastdate = GETDATE(),
        xlastuser = NULLIF(LTRIM(RTRIM(@xlastuser)), '')
    WHERE company = @cia
      AND person = @person;
END
GO



-- ============================================================================
-- [042/282] sp_pr_alertas_liquidacion_cese_pendiente_web.sql
-- ============================================================================

/*
    Alertas — liquidación de beneficios sociales pendiente para trabajadores cesados.

    Según normativa laboral peruana, la liquidación debe calcularse dentro de las
    48 horas posteriores al cese. Este SP lista trabajadores que:

      - Están activos en ficha (PR_Employee.Status = 'N').
      - Tienen fecha de cese en ficha (PR_Employee.CeaseDate).
      - Han pasado >= @dias_limite días desde el cese (default 2 = 48 horas).
      - La diferencia entre ISNULL(ReEntryDate, EntryDate) y CeaseDate es > 30 días
        (si el vínculo laboral del ciclo actual no supera 30 días, no corresponde liquidar).
      - Aún no tienen cálculo del proceso LIQUIDACION correspondiente a ese cese,
        identificado por PR_EmployeePayRoll.CeaseDate = PR_Employee.CeaseDate
        con concepto FormulaCode = LIQ_NETO en PR_EmployeePayRollConcept.

    Usado por: alertas del dashboard.

    Parámetros:
      @company      — compañía (obligatorio).
      @payrolltype  — tipo de planilla; '0' = todos.
      @fecha_corte  — fecha de corte; NULL = hoy.
      @dias_limite  — días mínimos desde el cese (default 2).

    Exclusiones:
      - No incluye planillas de Construcción Civil (ShortName/Description
        con CONSTRUCCION, p.ej. CONSTRUCCION CIVIL).

    Ejemplo:
      EXEC sp_pr_alertas_liquidacion_cese_pendiente_web
           @company = 'BGT',
           @payrolltype = '0',
           @fecha_corte = NULL,
           @dias_limite = 2;
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_alertas_liquidacion_cese_pendiente_web]
    @company      VARCHAR(4),
    @payrolltype  VARCHAR(20) = '0',
    @fecha_corte  DATETIME = NULL,
    @dias_limite  INT = 2
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    IF @payrolltype = '' SET @payrolltype = '0';
    SET @fecha_corte = CAST(ISNULL(@fecha_corte, GETDATE()) AS DATE);
    SET @dias_limite = ISNULL(@dias_limite, 2);

    IF @company = ''
    BEGIN
        RAISERROR('Indique la compañía.', 16, 1);
        RETURN;
    END;

    IF @dias_limite < 0
    BEGIN
        RAISERROR('El límite de días debe ser mayor o igual a cero.', 16, 1);
        RETURN;
    END;

    ;WITH cesados AS (
        SELECT
            e.Company AS company,
            e.Person AS person,
            e.EmployeeCode AS employee_code,
            e.PayRollType AS payrolltype,
            LTRIM(RTRIM(
                ISNULL(sp.LastName1, '') + ' ' +
                ISNULL(sp.LastName2, '') + ' ' +
                ISNULL(sp.Name1, '') + ' ' +
                ISNULL(sp.Name2, '')
            )) AS nombre,
            sp.DocumentNumber AS documento,
            pt.ShortName AS tipoplanilla,
            pt.Description AS tipoplanilla_desc,
            CONVERT(DATE, e.EntryDate) AS fecha_ingreso_original,
            CONVERT(DATE, e.ReEntryDate) AS fecha_reingreso,
            CONVERT(DATE, ISNULL(e.ReEntryDate, e.EntryDate)) AS fecha_ingreso,
            CONVERT(DATE, e.CeaseDate) AS fecha_cese,
            DATEDIFF(
                DAY,
                CONVERT(DATE, ISNULL(e.ReEntryDate, e.EntryDate)),
                CONVERT(DATE, e.CeaseDate)
            ) AS dias_entre_ingreso_cese,
            e.CeaseReason AS ceasereason_id,
            ISNULL(cr.Description, '') AS motivo_cese,
            e.Status AS status_empleado,
            LEFT(CONVERT(VARCHAR(8), e.CeaseDate, 112), 6) AS periodo_cese_yyyymm,
            DATEDIFF(DAY, CONVERT(DATE, e.CeaseDate), @fecha_corte) AS dias_desde_cese
        FROM PR_Employee e (NOLOCK)
            INNER JOIN SY_Person sp (NOLOCK)
                ON e.Person = sp.Person
            INNER JOIN PR_PayRollType pt (NOLOCK)
                ON e.PayRollType = pt.PayRollType
               AND pt.Company = e.Company
            LEFT JOIN PR_CeaseReason cr (NOLOCK)
                ON e.CeaseReason = cr.CeaseReason
        WHERE e.Company = @company
          AND e.Status = 'N'
          AND e.CeaseDate IS NOT NULL
          AND ISNULL(e.ReEntryDate, e.EntryDate) IS NOT NULL
          AND CONVERT(DATE, e.CeaseDate) <= @fecha_corte
          AND DATEDIFF(DAY, CONVERT(DATE, e.CeaseDate), @fecha_corte) >= @dias_limite
          /* Solo alerta si el ciclo laboral (reingreso/ingreso → cese) supera 30 días. */
          AND DATEDIFF(
                DAY,
                CONVERT(DATE, ISNULL(e.ReEntryDate, e.EntryDate)),
                CONVERT(DATE, e.CeaseDate)
              ) > 30
          AND (@payrolltype = '0' OR e.PayRollType = @payrolltype)
          /* Construcción Civil no aplica a esta alerta. */
          AND UPPER(LTRIM(RTRIM(ISNULL(pt.ShortName, '')))) NOT LIKE '%CONSTRUCCION%'
          AND UPPER(LTRIM(RTRIM(ISNULL(pt.Description, '')))) NOT LIKE '%CONSTRUCCION%'
    )
    SELECT
        c.company,
        c.person,
        c.employee_code,
        c.documento,
        c.nombre,
        c.payrolltype,
        c.tipoplanilla,
        c.tipoplanilla_desc,
        c.fecha_ingreso_original,
        c.fecha_reingreso,
        c.fecha_ingreso,
        c.fecha_cese,
        c.dias_entre_ingreso_cese,
        c.motivo_cese,
        c.status_empleado,
        c.periodo_cese_yyyymm,
        STUFF(c.periodo_cese_yyyymm, 5, 0, '-') AS periodo_cese,
        c.dias_desde_cese,
        CASE
            WHEN c.dias_desde_cese >= 2 THEN 'VENCIDO'
            ELSE 'EN_PLAZO'
        END AS estado_plazo,
        'Liquidar beneficios sociales: sin cálculo LIQUIDACION (LIQ_NETO) del periodo de cese.'
            AS motivo_alerta
    FROM cesados c
    WHERE NOT EXISTS (
        SELECT 1
        FROM PR_EmployeePayRollConcept epc (NOLOCK)
            INNER JOIN PR_Concept con (NOLOCK)
                ON epc.Concept = con.Concept
               AND epc.Company = con.Company
            INNER JOIN PR_ProcessType pt (NOLOCK)
                ON epc.ProcessType = pt.ProcessType
            INNER JOIN PR_EmployeePayRoll ep (NOLOCK)
                ON ep.Company = epc.Company
               AND ep.Person = epc.Person
               AND ep.PayRollType = epc.PayRollType
               AND ep.ProcessType = epc.ProcessType
               AND ep.PRPeriod = epc.PRPeriod
        WHERE epc.Company = c.company
          AND epc.Person = c.person
          AND LTRIM(RTRIM(pt.ShortName)) = 'LIQUIDACION'
          AND UPPER(LTRIM(RTRIM(ISNULL(con.FormulaCode, '')))) = 'LIQ_NETO'
          AND CONVERT(DATE, ep.CeaseDate) = c.fecha_cese
    )
    ORDER BY
        c.dias_desde_cese DESC,
        c.fecha_cese DESC,
        c.nombre,
        c.person;
END
GO



-- ============================================================================
-- [043/282] sp_pr_alertas_vacaciones_pendientes_web.sql
-- ============================================================================

/*
    Alertas — trabajadores con vacaciones pendientes de programar.

    Identifica, por cada periodo vacacional (PR_Vacation / ControlYear), trabajadores
    activos (Status = 'N' y sin cese) que acumulan >= @dias_umbral días
    (2.5 por mes trabajado) y no registran goce de vacaciones en
    PR_VacationDetail (VacationType = 'D').

    Fecha base de acumulación:
      ISNULL(ReEntryDate, EntryDate)
      — si hay reingreso, solo cuentan periodos con DateBeginProvision >= esa fecha
        y la acumulación se calcula desde el reingreso (no desde el ingreso original).

    Validación por periodo:
      - Cada ControlYear se evalúa de forma independiente.
      - Si el trabajador gozó sus 30 días del 2024, el periodo 2025 se valida aparte.

    Cálculo de días acumulados (misma lógica que saldo de vacaciones):
      - Si ya inició el derecho (DateBeginRights <= fecha corte): AcquiredDays.
      - Si aún está en periodo de acumulación: f_getDias360 * 2.5 / 30
        desde MAX(inicio_provision, fecha_base).

    Usado por: alertas del dashboard (fase 1: listado en hm_aci2).

    Parámetros:
      @company      — compañía (obligatorio).
      @payrolltype  — tipo de planilla; '0' = todos.
      @fecha_corte  — fecha de corte; NULL = hoy.
      @dias_umbral  — umbral de alerta (default 28).

    Exclusiones:
      - No incluye planillas de Construcción Civil (ShortName/Description
        con CONSTRUCCION, p.ej. CONSTRUCCION CIVIL).

    Ejemplo:
      EXEC sp_pr_alertas_vacaciones_pendientes_web
           @company = 'BGT',
           @payrolltype = '0',
           @fecha_corte = NULL,
           @dias_umbral = 28;
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_alertas_vacaciones_pendientes_web]
    @company      VARCHAR(4),
    @payrolltype  VARCHAR(20) = '0',
    @fecha_corte  DATETIME = NULL,
    @dias_umbral  DECIMAL(10, 2) = 28
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    IF @payrolltype = '' SET @payrolltype = '0';
    SET @fecha_corte = CAST(ISNULL(@fecha_corte, GETDATE()) AS DATE);
    SET @dias_umbral = ISNULL(@dias_umbral, 28);

    IF @company = ''
    BEGIN
        RAISERROR('Indique la compañía.', 16, 1);
        RETURN;
    END;

    IF @dias_umbral < 0
    BEGIN
        RAISERROR('El umbral de días debe ser mayor o igual a cero.', 16, 1);
        RETURN;
    END;

    ;WITH periodos AS (
        SELECT
            e.Company AS company,
            e.Person AS person,
            e.EmployeeCode AS employee_code,
            e.PayRollType AS payrolltype,
            LTRIM(RTRIM(
                ISNULL(sp.LastName1, '') + ' ' +
                ISNULL(sp.LastName2, '') + ' ' +
                ISNULL(sp.Name1, '') + ' ' +
                ISNULL(sp.Name2, '')
            )) AS nombre,
            sp.DocumentNumber AS documento,
            pt.ShortName AS tipoplanilla,
            pt.Description AS tipoplanilla_desc,
            fb.fecha_base AS fecha_ingreso,
            CONVERT(DATE, e.ReEntryDate) AS fecha_reingreso,
            v.Line AS line,
            v.ControlYear AS control_year,
            CAST(v.ControlYear AS VARCHAR(4)) + '-'
                + CAST(CAST(v.ControlYear AS INT) + 1 AS VARCHAR(4)) AS periodo_vacacional,
            CONVERT(DATE, v.DateBeginProvision) AS inicio_provision,
            CONVERT(DATE, v.DateBeginRights) AS inicio_derecho,
            CONVERT(DATE, v.DateEndRights) AS fin_derecho,
            CONVERT(DATE, v.DateEndNormal) AS limite_sin_indemnizacion,
            ISNULL(v.AcquiredDays, ISNULL(v.Days, 30)) AS dias_adquiridos,
            CASE
                WHEN CONVERT(DATE, v.DateBeginRights) <= @fecha_corte THEN
                    CAST(ISNULL(v.AcquiredDays, ISNULL(v.Days, 30)) AS DECIMAL(10, 2))
                ELSE
                    ROUND(
                        (
                            dbo.f_getDias360(
                                CASE
                                    WHEN CONVERT(DATE, v.DateBeginProvision) > fb.fecha_base
                                    THEN CONVERT(DATE, v.DateBeginProvision)
                                    ELSE fb.fecha_base
                                END,
                                @fecha_corte
                            ) * 2.5
                        ) / 30.0,
                        2
                    )
            END AS dias_acumulados,
            ISNULL(gz.gozados_total, 0) AS dias_gozados,
            ISNULL(gz.gozados_efectivos, 0) AS dias_gozados_efectivos,
            ISNULL(gz.programados_futuro, 0) AS dias_programados_futuro
        FROM PR_Employee e (NOLOCK)
            INNER JOIN SY_Person sp (NOLOCK)
                ON e.Person = sp.Person
            INNER JOIN PR_PayRollType pt (NOLOCK)
                ON e.PayRollType = pt.PayRollType
               AND pt.Company = e.Company
            CROSS APPLY (
                SELECT CONVERT(DATE, ISNULL(e.ReEntryDate, e.EntryDate)) AS fecha_base
            ) fb
            INNER JOIN PR_Vacation v (NOLOCK)
                ON v.Person = e.Person
               AND v.Company = e.Company
               AND ISNULL(v.status, 'A') = 'A'
            OUTER APPLY (
                SELECT
                    SUM(ISNULL(vd.Days, 0)) AS gozados_total,
                    SUM(
                        CASE
                            WHEN CONVERT(DATE, vd.DateBegin) <= @fecha_corte
                            THEN ISNULL(vd.Days, 0)
                            ELSE 0
                        END
                    ) AS gozados_efectivos,
                    SUM(
                        CASE
                            WHEN CONVERT(DATE, vd.DateBegin) > @fecha_corte
                            THEN ISNULL(vd.Days, 0)
                            ELSE 0
                        END
                    ) AS programados_futuro
                FROM PR_VacationDetail vd (NOLOCK)
                WHERE vd.Company = v.Company
                  AND vd.Person = v.Person
                  AND vd.Line = v.Line
                  AND LTRIM(RTRIM(ISNULL(vd.VacationType, ''))) = 'D'
            ) gz
        WHERE e.Company = @company
          AND e.Status = 'N'
          AND e.CeaseDate IS NULL
          AND fb.fecha_base IS NOT NULL
          AND fb.fecha_base <= @fecha_corte
          AND (@payrolltype = '0' OR e.PayRollType = @payrolltype)
          /* Construcción Civil no aplica a esta alerta. */
          AND UPPER(LTRIM(RTRIM(ISNULL(pt.ShortName, '')))) NOT LIKE '%CONSTRUCCION%'
          AND UPPER(LTRIM(RTRIM(ISNULL(pt.Description, '')))) NOT LIKE '%CONSTRUCCION%'
          /* Solo periodos del ciclo laboral actual (desde reingreso/ingreso). */
          AND CONVERT(DATE, v.DateBeginProvision) >= fb.fecha_base
          AND CONVERT(DATE, v.DateBeginProvision) <= @fecha_corte
    )
    SELECT
        p.company,
        p.person,
        p.employee_code,
        p.documento,
        p.nombre,
        p.payrolltype,
        p.tipoplanilla,
        p.tipoplanilla_desc,
        p.fecha_ingreso,
        p.fecha_reingreso,
        p.line,
        p.control_year,
        p.periodo_vacacional,
        p.inicio_provision,
        p.inicio_derecho,
        p.fin_derecho,
        p.limite_sin_indemnizacion,
        p.dias_adquiridos,
        p.dias_acumulados,
        p.dias_gozados,
        p.dias_gozados_efectivos,
        p.dias_programados_futuro,
        CAST(
            CASE
                WHEN p.dias_acumulados > p.dias_gozados
                THEN p.dias_acumulados - p.dias_gozados
                ELSE 0
            END AS DECIMAL(10, 2)
        ) AS dias_pendientes,
        CASE
            WHEN CONVERT(DATE, p.inicio_derecho) <= @fecha_corte THEN 'DERECHO_VENCIDO'
            ELSE 'ACUMULACION_PREVIA'
        END AS estado_periodo,
        'Programar vacaciones: acumulado >= '
            + CAST(@dias_umbral AS VARCHAR(10))
            + ' días sin goce registrado en el periodo.' AS motivo_alerta
    FROM periodos p
    WHERE p.dias_acumulados >= @dias_umbral
      AND ISNULL(p.dias_gozados, 0) = 0
    ORDER BY
        p.dias_acumulados DESC,
        p.inicio_derecho ASC,
        p.nombre,
        p.person,
        p.control_year;
END
GO



-- ============================================================================
-- [044/282] sp_pr_aperturarperiodo_proceso_web.sql
-- ============================================================================

/*
    Apertura de periodo para un tipo de proceso (lógica Useroption1 PowerBuilder).
    Usado por: POST /api/aperturar-periodos/aperturar (una llamada por proceso seleccionado).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_aperturarperiodo_proceso_web]
    @cia         VARCHAR(20),
    @payrolltype VARCHAR(20),
    @processtype VARCHAR(20),
    @period      VARCHAR(20),
    @xlastuser   VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LEFT(LTRIM(RTRIM(ISNULL(@cia, ''))), 4);
    SET @payrolltype = LEFT(LTRIM(RTRIM(ISNULL(@payrolltype, ''))), 20);
    SET @processtype = LEFT(LTRIM(RTRIM(ISNULL(@processtype, ''))), 20);
    SET @period = LEFT(LTRIM(RTRIM(ISNULL(@period, ''))), 10);
    SET @xlastuser = LEFT(LTRIM(RTRIM(ISNULL(@xlastuser, ''))), 20);

    IF @cia = '' OR @payrolltype = '' OR @processtype = '' OR @period = ''
    BEGIN
        RAISERROR('Faltan parámetros para aperturar el periodo.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM PR_Period p WITH (NOLOCK)
        WHERE p.Company = @cia
          AND p.PayRollType = @payrolltype
          AND LTRIM(RTRIM(p.PRPeriod)) = @period
    )
    BEGIN
        RAISERROR('No existe el periodo configurado para el tipo de planilla seleccionado.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM PR_PayRollTypeProcess ptp WITH (NOLOCK)
        WHERE ptp.Company = @cia
          AND ptp.PayRollType = @payrolltype
          AND ptp.ProcessType = @processtype
    )
    BEGIN
        RAISERROR('El tipo de proceso no está configurado para la planilla.', 16, 1);
        RETURN;
    END;

    DECLARE @replicationunit VARCHAR(4) = '';

    SELECT TOP 1
        @replicationunit = LEFT(NULLIF(LTRIM(RTRIM(pc.ReplicationUnit)), ''), 4)
    FROM PR_ProcessControl pc WITH (NOLOCK)
    WHERE pc.Company = @cia
      AND pc.PayRollType = @payrolltype
      AND pc.ProcessType = @processtype;

    IF @replicationunit IS NULL
        SET @replicationunit = '';

    IF NOT EXISTS (
        SELECT 1
        FROM PR_ProcessControl pc WITH (NOLOCK)
        WHERE pc.Company = @cia
          AND pc.PayRollType = @payrolltype
          AND pc.ProcessType = @processtype
    )
    BEGIN
        INSERT INTO PR_ProcessControl (
            PayRollType, ProcessType, PRPeriod, Status,
            PaymentDate, ProcessDate, Company, ReplicationUnit,
            XLastUser, XLastDate
        )
        SELECT
            @payrolltype,
            @processtype,
            LEFT(LTRIM(RTRIM(p.PRPeriod)), 10),
            CASE
                WHEN LTRIM(RTRIM(p.PRPeriod)) < @period THEN 'C'
                WHEN LTRIM(RTRIM(p.PRPeriod)) > @period THEN 'P'
                ELSE 'A'
            END,
            NULL,
            CASE WHEN LTRIM(RTRIM(p.PRPeriod)) = @period THEN GETDATE() ELSE NULL END,
            @cia,
            LEFT(ISNULL(NULLIF(LTRIM(RTRIM(p.ReplicationUnit)), ''), @replicationunit), 4),
            @xlastuser,
            GETDATE()
        FROM PR_Period p WITH (NOLOCK)
        WHERE p.Company = @cia
          AND p.PayRollType = @payrolltype;
        RETURN;
    END;

    UPDATE PR_ProcessControl
    SET Status = 'C',
        XLastUser = @xlastuser,
        XLastDate = GETDATE()
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND ProcessType = @processtype
      AND LTRIM(RTRIM(PRPeriod)) < @period;

    UPDATE PR_ProcessControl
    SET Status = 'P',
        XLastUser = @xlastuser,
        XLastDate = GETDATE()
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND ProcessType = @processtype
      AND LTRIM(RTRIM(PRPeriod)) > @period;

    UPDATE PR_ProcessControl
    SET Status = 'A',
        PRPeriod = @period,
        ProcessDate = GETDATE(),
        XLastUser = @xlastuser,
        XLastDate = GETDATE()
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND ProcessType = @processtype
      AND LTRIM(RTRIM(PRPeriod)) = @period;

    IF @@ROWCOUNT = 0
    BEGIN
        INSERT INTO PR_ProcessControl (
            PayRollType, ProcessType, PRPeriod, Status,
            PaymentDate, ProcessDate, Company, ReplicationUnit,
            XLastUser, XLastDate
        )
        VALUES (
            @payrolltype, @processtype, @period, 'A',
            NULL, GETDATE(), @cia, @replicationunit,
            @xlastuser, GETDATE()
        );
    END;
END
GO



-- ============================================================================
-- [045/282] sp_pr_calcularplanillas_masivo_web.sql
-- ============================================================================

/*
    Trabajadores elegibles para cálculo masivo multi-empresa.
    Resuelve PayRollType y ProcessType por Description en cada empresa.
    @companies: códigos separados por coma.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_calcularplanillas_masivo_web]
    @payroll_desc VARCHAR(200),
    @proceso_desc  VARCHAR(200),
    @period        VARCHAR(10),
    @cesados       CHAR(1),
    @companies     VARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;

    SET @payroll_desc = LTRIM(RTRIM(ISNULL(@payroll_desc, '')));
    SET @proceso_desc = LTRIM(RTRIM(ISNULL(@proceso_desc, '')));
    SET @period = LEFT(LTRIM(RTRIM(ISNULL(@period, ''))), 10);
    SET @companies = LTRIM(RTRIM(ISNULL(@companies, '')));
    IF RTRIM(ISNULL(@cesados, '')) = '' SET @cesados = 'T';

    DECLARE @fecha_inicio_mes DATE;
    DECLARE @fecha_fin_mes DATE;
    DECLARE @period_ym CHAR(6);

    SET @period_ym = LEFT(@period, 6);
    IF LEN(@period_ym) = 6 AND @period_ym NOT LIKE '%[^0-9]%'
    BEGIN
        SET @fecha_inicio_mes = CONVERT(DATE, @period_ym + '01', 112);
        SET @fecha_fin_mes = EOMONTH(@fecha_inicio_mes);
    END

    DECLARE @empresas TABLE (
        company      VARCHAR(10) NOT NULL PRIMARY KEY,
        payrolltype  VARCHAR(20) NULL,
        processtype  VARCHAR(20) NULL
    );

    DECLARE @piece VARCHAR(10);
    DECLARE @pt VARCHAR(20);
    DECLARE @proc VARCHAR(20);

    IF @companies <> ''
    BEGIN
        DECLARE @work VARCHAR(500) = @companies + ',';
        DECLARE @pos INT;

        WHILE LEN(@work) > 0
        BEGIN
            SET @pos = CHARINDEX(',', @work);
            IF @pos = 0 BREAK;
            SET @piece = UPPER(LTRIM(RTRIM(LEFT(@work, @pos - 1))));
            SET @work = SUBSTRING(@work, @pos + 1, LEN(@work));
            SET @pt = NULL;
            SET @proc = NULL;

            IF @piece <> ''
            AND NOT EXISTS (SELECT 1 FROM @empresas e WHERE e.company = @piece)
            BEGIN
                SELECT TOP 1 @pt = PayRollType
                FROM PR_PayRollType (NOLOCK)
                WHERE Company = @piece
                  AND LTRIM(RTRIM(Description)) = @payroll_desc;

                IF @pt IS NOT NULL
                BEGIN
                    SELECT TOP 1 @proc = ptp.ProcessType
                    FROM PR_PayRollTypeProcess ptp (NOLOCK)
                        INNER JOIN PR_ProcessType pt2 (NOLOCK)
                            ON pt2.Company = ptp.Company
                           AND pt2.ProcessType = ptp.ProcessType
                    WHERE ptp.Company = @piece
                      AND ptp.PayRollType = @pt
                      AND LTRIM(RTRIM(pt2.Description)) = @proceso_desc;
                END

                IF @pt IS NOT NULL
               AND @proc IS NOT NULL
               AND EXISTS (
                    SELECT 1
                    FROM SY_Company sc (NOLOCK)
                    WHERE sc.Company = @piece
                      AND UPPER(LTRIM(RTRIM(ISNULL(sc.[status], '')))) = 'A'
               )
               AND EXISTS (
                    SELECT 1
                    FROM PR_ProcessControl PC (NOLOCK)
                    WHERE PC.Company = @piece
                      AND PC.PayRollType = @pt
                      AND PC.ProcessType = @proc
                      AND PC.PRPeriod = @period
                      AND PC.Status IN ('A', 'C', 'G')
               )
                    INSERT INTO @empresas (company, payrolltype, processtype)
                    VALUES (@piece, @pt, @proc);
            END
        END
    END

    SELECT
        e.company,
        ISNULL(sc.description, e.company) AS company_desc,
        e.payrolltype,
        e.processtype,
        LTRIM(RTRIM(
            ISNULL(SY_PERSON.LASTNAME1, '') + ' ' +
            ISNULL(SY_PERSON.LASTNAME2, '') + ' ' +
            ISNULL(SY_PERSON.NAME1, '') + ' ' +
            ISNULL(SY_PERSON.NAME2, '')
        )) AS [name],
        PR_EMPLOYEE.PERSON AS person,
        ISNULL(PR_EMPLOYEE.REENTRYDATE, PR_EMPLOYEE.ENTRYDATE) AS entrydate,
        PR_EMPLOYEE.CEASEDATE AS ceasedate,
        EPR.XLastDate AS calculationdate
    FROM @empresas e
        INNER JOIN SY_Company sc (NOLOCK)
            ON sc.Company = e.company
           AND UPPER(LTRIM(RTRIM(ISNULL(sc.[status], '')))) = 'A'
        INNER JOIN PR_EMPLOYEE (NOLOCK)
            ON PR_EMPLOYEE.COMPANY = e.company
           AND PR_EMPLOYEE.PAYROLLTYPE = e.payrolltype
        INNER JOIN SY_PERSON (NOLOCK)
            ON PR_EMPLOYEE.PERSON = SY_PERSON.PERSON
        LEFT JOIN PR_EmployeePayRoll EPR (NOLOCK)
            ON EPR.Person = PR_EMPLOYEE.Person
           AND EPR.Company = e.company
           AND EPR.PayRollType = e.payrolltype
           AND EPR.ProcessType = e.processtype
           AND LTRIM(RTRIM(EPR.PRPeriod)) = @period
    WHERE PR_EMPLOYEE.STATUS = 'N'
      AND (
            (
                @cesados = 'T'
                AND (
                    PR_EMPLOYEE.CEASEDATE IS NULL
                    OR @fecha_inicio_mes IS NULL
                    OR CONVERT(DATE, PR_EMPLOYEE.CEASEDATE) >= @fecha_inicio_mes
                )
            )
            OR (
                @cesados = 'Y'
                AND @fecha_inicio_mes IS NOT NULL
                AND @fecha_fin_mes IS NOT NULL
                AND PR_EMPLOYEE.CEASEDATE IS NOT NULL
                AND CONVERT(DATE, PR_EMPLOYEE.CEASEDATE) >= @fecha_inicio_mes
                AND CONVERT(DATE, PR_EMPLOYEE.CEASEDATE) <= @fecha_fin_mes
            )
            OR (
                @cesados = 'N'
                AND PR_EMPLOYEE.CEASEDATE IS NULL
            )
      )
      AND (
            @fecha_fin_mes IS NULL
            OR CONVERT(DATE, ISNULL(PR_EMPLOYEE.REENTRYDATE, PR_EMPLOYEE.ENTRYDATE)) <= @fecha_fin_mes
      )
    ORDER BY e.company ASC, [name] ASC, person ASC;
END
GO



-- ============================================================================
-- [046/282] sp_pr_calcularplanillas_web.sql
-- ============================================================================

/*
    Trabajadores elegibles para el cálculo de planilla (módulo Procesar planilla).
    Devuelve nombre, person, fechas de ingreso/reingreso, cese y última fecha de cálculo.

    @cia, @payrolltype, @processtype, @period: obligatorios para fecha de cálculo.
    @cesados: T = activos + cesados del mes del periodo, Y = solo cesados del mes, N = sin fecha de cese.
    @repunit: '0' = todas las unidades; otro valor filtra SY_Person.ReplicationUnit.

    Solo incluye trabajadores con fecha de ingreso/reingreso <= ultimo dia del mes del periodo.
    Los cesados de meses anteriores al periodo no se listan (p. ej. cese en mayo no aparece en junio).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_calcularplanillas_web]
    @cia          VARCHAR(10),
    @payrolltype  VARCHAR(20),
    @processtype  VARCHAR(20),
    @period       VARCHAR(10),
    @cesados      CHAR(1),
    @repunit      VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LEFT(LTRIM(RTRIM(ISNULL(@cia, ''))), 10);
    SET @payrolltype = LEFT(LTRIM(RTRIM(ISNULL(@payrolltype, ''))), 20);
    SET @processtype = LEFT(LTRIM(RTRIM(ISNULL(@processtype, ''))), 20);
    SET @period = LEFT(LTRIM(RTRIM(ISNULL(@period, ''))), 10);

    IF RTRIM(ISNULL(@cesados, '')) = '' SET @cesados = 'T';
    IF RTRIM(ISNULL(@repunit, '')) = '' SET @repunit = '0';

    DECLARE @fecha_inicio_mes DATE;
    DECLARE @fecha_fin_mes DATE;
    DECLARE @period_ym CHAR(6);

    SET @period_ym = LEFT(@period, 6);
    IF LEN(@period_ym) = 6 AND @period_ym NOT LIKE '%[^0-9]%'
    BEGIN
        SET @fecha_inicio_mes = CONVERT(DATE, @period_ym + '01', 112);
        SET @fecha_fin_mes = EOMONTH(@fecha_inicio_mes);
    END;

    SELECT
        LTRIM(RTRIM(
            ISNULL(SY_PERSON.LASTNAME1, '') + ' ' +
            ISNULL(SY_PERSON.LASTNAME2, '') + ' ' +
            ISNULL(SY_PERSON.NAME1, '') + ' ' +
            ISNULL(SY_PERSON.NAME2, '')
        )) AS [name],
        PR_EMPLOYEE.PERSON AS person,
        PR_EMPLOYEE.COMPANY AS company,
        PR_EMPLOYEE.PAYROLLTYPE AS payrolltype,
        ISNULL(PR_EMPLOYEE.REENTRYDATE, PR_EMPLOYEE.ENTRYDATE) AS entrydate,
        PR_EMPLOYEE.CEASEDATE AS ceasedate,
        EPR.XLastDate AS calculationdate
    FROM PR_EMPLOYEE
        INNER JOIN SY_PERSON
            ON PR_EMPLOYEE.PERSON = SY_PERSON.PERSON
        LEFT JOIN PR_EmployeePayRoll EPR
            ON EPR.Person = PR_EMPLOYEE.Person
           AND EPR.Company = @cia
           AND EPR.PayRollType = @payrolltype
           AND EPR.ProcessType = @processtype
           AND LTRIM(RTRIM(EPR.PRPeriod)) = @period
    WHERE PR_EMPLOYEE.COMPANY = @cia
      AND PR_EMPLOYEE.PAYROLLTYPE = @payrolltype
      AND PR_EMPLOYEE.STATUS = 'N'
      AND (
            (
                @cesados = 'T'
                AND (
                    PR_EMPLOYEE.CEASEDATE IS NULL
                    OR @fecha_inicio_mes IS NULL
                    OR CONVERT(DATE, PR_EMPLOYEE.CEASEDATE) >= @fecha_inicio_mes
                )
            )
            OR (
                @cesados = 'Y'
                AND @fecha_inicio_mes IS NOT NULL
                AND @fecha_fin_mes IS NOT NULL
                AND PR_EMPLOYEE.CEASEDATE IS NOT NULL
                AND CONVERT(DATE, PR_EMPLOYEE.CEASEDATE) >= @fecha_inicio_mes
                AND CONVERT(DATE, PR_EMPLOYEE.CEASEDATE) <= @fecha_fin_mes
            )
            OR (
                @cesados = 'N'
                AND PR_EMPLOYEE.CEASEDATE IS NULL
            )
      )
      AND (@repunit = '0' OR SY_PERSON.REPLICATIONUNIT = @repunit)
      AND (
            @fecha_fin_mes IS NULL
            OR CONVERT(DATE, ISNULL(PR_EMPLOYEE.REENTRYDATE, PR_EMPLOYEE.ENTRYDATE)) <= @fecha_fin_mes
      )
    ORDER BY [name], person;
END
GO



-- ============================================================================
-- [047/282] sp_pr_cerrarperiodo_proceso_web.sql
-- ============================================================================

/*
    Cierra el periodo activo de un tipo de proceso (Status A/G → C).
    Usado por: POST /api/aperturar-periodos/cerrar
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_cerrarperiodo_proceso_web]
    @cia         VARCHAR(20),
    @payrolltype VARCHAR(20),
    @processtype VARCHAR(20),
    @xlastuser   VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LEFT(LTRIM(RTRIM(ISNULL(@cia, ''))), 4);
    SET @payrolltype = LEFT(LTRIM(RTRIM(ISNULL(@payrolltype, ''))), 20);
    SET @processtype = LEFT(LTRIM(RTRIM(ISNULL(@processtype, ''))), 20);
    SET @xlastuser = LEFT(LTRIM(RTRIM(ISNULL(@xlastuser, ''))), 20);

    IF @cia = '' OR @payrolltype = '' OR @processtype = ''
    BEGIN
        RAISERROR('Faltan parámetros para cerrar el periodo.', 16, 1);
        RETURN;
    END;

    UPDATE PR_ProcessControl
    SET Status = 'C',
        XLastUser = @xlastuser,
        XLastDate = GETDATE()
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND ProcessType = @processtype
      AND Status IN ('A', 'G');
END
GO



-- ============================================================================
-- [048/282] sp_pr_certificadoquinta_web.sql
-- ============================================================================

/*
    Certificado quinta — datos para PDF. Usado por preview_certificado_quinta.

    Parámetros:
      @cia              — compañía
      @payrolltype      — tipo de planilla
      @payrolltype_all  — 'Y' = todos los tipos de planilla
      @anio             — año calendario (ej. 2026)
      @person           — código persona
      @employee_all     — 'Y' = todos los empleados
      @activo           — 'Y' = solo empleados activos (filtro PB)
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_certificadoquinta_web]
    @cia              VARCHAR(4),
    @payrolltype      VARCHAR(20),
    @payrolltype_all  CHAR(1) = 'N',
    @anio             VARCHAR(4),
    @person           VARCHAR(20),
    @employee_all     CHAR(1) = 'N',
    @activo           CHAR(1) = 'N'
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        P.Person AS person,
        P.Name AS nombre_persona,
        P.DocumentNumber AS docno_persona,
        P.Sex AS sexo,
        P.Address AS direccion_persona,
        ISNULL(O.Description, '') AS ocupacion,
        E.ceasedate AS fecha_cese,
        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.taxrentconcept = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS monto_retenido,
        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.remtaxrentconcept = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS remuneracion_bruta,
        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.taxrentconcept = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS retencion_5ta_cat,

               ISNULL((
        SELECT
        SUM(EC.ConceptValue)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND (select top 1 Concept from PR_Concept where  FormulaCode = 'SUB_IMPUESTO') = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio and
                 ( right(PRPeriod,4) = '1212' or right(PRPeriod,4) = '1252'))
        ,0) AS sub_impuesto,

              ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
         M.utilitiesconcept = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS utilidades,

        ISNULL((
            SELECT SUM(EC.ConceptValueLo)
            FROM PR_EmployeePayRollConcept EC (NOLOCK)
                INNER JOIN PR_Concept C (NOLOCK)
                    ON C.Company = EC.Company AND C.Concept = EC.Concept
                INNER JOIN PR_ProcessType PT (NOLOCK)
                    ON PT.ProcessType = EC.ProcessType
            WHERE EC.Company = @cia
              AND EC.Person = P.Person
              AND EC.PayRollType = @payrolltype
              AND LEFT(LTRIM(RTRIM(EC.PRPeriod)), 4) = @anio
              AND ISNULL(C.flagafecto5ta, 'N') = 'Y'
              AND ISNULL(PT.ShortName, '') <> 'UTILIDADES'
        ), 0) AS importe_sueldos_asignaciones,

        ISNULL((
            SELECT SUM(EC.ConceptValueLo)
            FROM PR_EmployeePayRollConcept EC (NOLOCK)
                INNER JOIN PR_Concept C (NOLOCK)
                    ON C.Company = EC.Company AND C.Concept = EC.Concept
                INNER JOIN PR_ProcessType PT (NOLOCK)
                    ON PT.ProcessType = EC.ProcessType
            WHERE EC.Company = @cia
              AND EC.Person = P.Person
              AND EC.PayRollType = @payrolltype
              AND LEFT(LTRIM(RTRIM(EC.PRPeriod)), 4) = @anio
              AND ISNULL(C.flagafecto5ta, 'N') = 'Y'
              AND ISNULL(PT.ShortName, '') = 'UTILIDADES'
        ), 0) AS importe_participacion_utilidades,

        ISNULL((
            SELECT SUM(ISNULL(EC.ConceptValueLo, EC.ConceptValue))
            FROM PR_EmployeeConcept EC (NOLOCK)
                INNER JOIN PR_Concept C (NOLOCK)
                    ON C.Company = EC.Company AND C.Concept = EC.Concept
            WHERE EC.Company = @cia
              AND EC.Person = P.Person
              AND EC.PayRollType = @payrolltype
              AND C.FormulaCode = 'REM_ACUM_OTRA_EM'
              AND EC.FlagFrecuencyType = 'P'
              AND LEFT(LTRIM(RTRIM(EC.PRPeriodStart)), 4) = @anio
        ), 0) AS importe_remuneracion_otras_empresas,

        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.irembascomconcept = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS rem_bas,

        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.icomisionconcept = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS comision,

        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.irefund = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS reintegro,

        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.ibonifconcept = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS bonificacion,

        dbo.F_PR_GetImportFormat(@cia, 'R', '1', P.Person, @anio) AS importe1,
        dbo.F_PR_GetImportFormat(@cia, 'R', '2', P.Person, @anio) AS importe2,
        dbo.F_PR_GetImportFormat(@cia, 'R', '3', P.Person, @anio) AS importe3,
        dbo.F_PR_GetImportFormat(@cia, 'R', '4', P.Person, @anio) AS importe4,
        dbo.F_PR_GetImportFormat(@cia, 'R', '14', P.Person, @anio) AS importe14,
        dbo.F_PR_GetImportFormat(@cia, 'R', '15', P.Person, @anio) AS importe15,
        dbo.F_PR_GetImportFormat(@cia, 'R', '16', P.Person, @anio) AS importe16,
        dbo.F_PR_GetImportFormat(@cia, 'R', '20', P.Person, @anio) AS importe20,

        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.ihe100concept = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS extras100,

        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.ibonifprod = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS bonifproduc,
        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.irefund = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS reintegro_sueldo,

        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
        )
        AND M.ivacacconcept = EC.Concept
        AND LEFT(EC.PRPeriod,4) = @anio
        )
        ,0) AS vacaciones,
        ISNULL((
        SELECT
        SUM(EC.ConceptValueLo)
        FROM
        PR_EmployeePayRollConcept EC (NOLOCK),
        PR_Mapping M (NOLOCK),
        PR_ProcessType PT (NOLOCK)
        WHERE
        EC.Company = @cia
        AND	M.Company = EC.Company
        AND EC.Person = P.Person
        AND PT.ProcessType = EC.ProcessType and
        (
         (PT.ShortName IN ('SEMANAL','VACACIONES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)= 'OBREROS'	)
         or  (PT.ShortName IN ('FIN_DE_MES') and (select ShortName from pr_payrolltype where payrolltype = EC.payrolltype)<> 'OBREROS')
