        DAY(GETDATE()) AS day_print,
        CASE MONTH(GETDATE())
            WHEN 1 THEN 'Enero' WHEN 2 THEN 'Febrero' WHEN 3 THEN 'Marzo'
            WHEN 4 THEN 'Abril' WHEN 5 THEN 'Mayo' WHEN 6 THEN 'Junio'
            WHEN 7 THEN 'Julio' WHEN 8 THEN 'Agosto' WHEN 9 THEN 'Septiembre'
            WHEN 10 THEN 'Octubre' WHEN 11 THEN 'Noviembre' WHEN 12 THEN 'Diciembre'
        END AS month_print,
        YEAR(GETDATE()) AS year_print,
        DAY(pe.CeaseDate) AS ceasedate_day,
        CASE MONTH(pe.CeaseDate)
            WHEN 1 THEN 'Enero' WHEN 2 THEN 'Febrero' WHEN 3 THEN 'Marzo'
            WHEN 4 THEN 'Abril' WHEN 5 THEN 'Mayo' WHEN 6 THEN 'Junio'
            WHEN 7 THEN 'Julio' WHEN 8 THEN 'Agosto' WHEN 9 THEN 'Septiembre'
            WHEN 10 THEN 'Octubre' WHEN 11 THEN 'Noviembre' WHEN 12 THEN 'Diciembre'
        END AS ceasedate_month,
        YEAR(pe.CeaseDate) AS ceasedate_year,
        DAY(ISNULL(pe.ReEntryDate, pe.EntryDate)) AS fecha_entry_day,
        CASE MONTH(ISNULL(pe.ReEntryDate, pe.EntryDate))
            WHEN 1 THEN 'Enero' WHEN 2 THEN 'Febrero' WHEN 3 THEN 'Marzo'
            WHEN 4 THEN 'Abril' WHEN 5 THEN 'Mayo' WHEN 6 THEN 'Junio'
            WHEN 7 THEN 'Julio' WHEN 8 THEN 'Agosto' WHEN 9 THEN 'Septiembre'
            WHEN 10 THEN 'Octubre' WHEN 11 THEN 'Noviembre' WHEN 12 THEN 'Diciembre'
        END AS fecha_entry_month,
        YEAR(ISNULL(pe.ReEntryDate, pe.EntryDate)) AS fecha_entry_year,
        sp.LastName1 AS lastname1,
        sp.Sex AS sex,
        cc.Description AS centrocosto
    FROM PR_Employee pe
        INNER JOIN SY_Person sp ON pe.Person = sp.Person
        LEFT JOIN PR_Position pp ON pe.Position = pp.Position
        INNER JOIN SY_Company sc ON pe.Company = sc.Company
        LEFT JOIN PR_PersonContract pc
            ON pe.Company = pc.Company
           AND pe.Person = pc.Person
           AND pc.Status = 'A'
        INNER JOIN PR_EmployeePayRoll epc ON pe.Person = epc.Person
        INNER JOIN PR_ProcessType pt_liq (NOLOCK)
            ON epc.ProcessType = pt_liq.ProcessType
           AND epc.Company = pt_liq.Company
        LEFT JOIN SY_PersonDocumentType dt ON sp.DocumentType = dt.PersonDocumentType
        LEFT JOIN SY_PersonDocumentType dt2 ON sc.Rep_DocType = dt2.PersonDocumentType
        LEFT JOIN AC_CostCenter cc ON pe.CostCenter = cc.CostCenter
    WHERE pe.Company = @cia
      AND epc.Company = @cia
      AND epc.PayRollType = @payrolltype
      AND pt_liq.ShortName = 'LIQUIDACION'
      AND epc.PRPeriod = @period
      AND epc.Person = @person;
END
GO



-- ============================================================================
-- [051/282] sp_pr_control_pagos_afp_web.sql
-- ============================================================================

/*
    Control de Pagos AFP — resumen por tipo de planilla y AFP.
    Legacy PowerBuilder: PAGOS AFP (RPR001).

    Usado por: GET /afp/control-pagos, POST /reporte_control_pagos_afp

    Parámetros:
      @company    — código de compañía
      @payrolltype — tipo de planilla; vacío / NULL / TODOS = todas
      @period     — periodo YYYYMM (6 dígitos)
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_control_pagos_afp_web]
    @company     VARCHAR(4),
    @payrolltype VARCHAR(20),
    @period      VARCHAR(6)
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    SET @period = LTRIM(RTRIM(ISNULL(@period, '')));

    IF UPPER(@payrolltype) IN ('TODOS', 'TODAS', 'T', '0')
        SET @payrolltype = '';

    /*
        Cuando se consultan todas las planillas, la descripción queda vacía y
        el GROUP BY consolida EMPLEADOS + CONSTRUCCIÓN (u otras) por AFP.
    */
    SELECT
        CASE WHEN @payrolltype = '' THEN '' ELSE MAX(P.description) END AS tipoplanilla,
        A.description AS afpname,
        COUNT(*) AS cantidad,
        SUM(ROUND(F.fixedamountlo, 2)) AS fixedamountlo,
        SUM(ROUND(F.insuredamountlo, 2)) AS insuredamountlo,
        SUM(ROUND(F.employercontributionlo, 2)) AS employercontributionlo,
        SUM(ROUND(F.variableamountlo, 2)) AS variableamountlo,
        SUM(ROUND(F.arcomisionamountlo, 2)) AS arcomisionamountlo
    FROM PR_EmployeeAFPHeader H (NOLOCK)
        INNER JOIN PR_EmployeeAFP F (NOLOCK)
            ON H.company = F.company
           AND H.replicationunit = F.replicationunit
           AND H.costcenter = F.costcenter
           AND H.prperiod = F.prperiod
           AND H.afp = F.afp
           AND H.payrolltype = F.payrolltype
        INNER JOIN PR_Employee E (NOLOCK)
            ON F.company = E.company
           AND F.person = E.person
        INNER JOIN PR_AFP A (NOLOCK)
            ON F.afp = A.afp
        INNER JOIN PR_PayRollType P (NOLOCK)
            ON E.payrolltype = P.payrolltype
    WHERE H.company = @company
      AND (@payrolltype = '' OR H.payrolltype = @payrolltype)
      AND LEFT(H.prperiod, 6) = @period
    GROUP BY
        CASE WHEN @payrolltype = '' THEN '' ELSE P.description END,
        A.description
    ORDER BY
        CASE WHEN @payrolltype = '' THEN '' ELSE P.description END,
        A.description;
END
GO



-- ============================================================================
-- [052/282] sp_pr_datosusuario_web.sql
-- ============================================================================

/*
    Datos del usuario / trabajador para perfil web.

    Usado por: get_datos_usuario_web (database.py).

    Parámetros:
      @userid — SY_User.UserID (código de acceso)
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_datosusuario_web]
    @userid VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @userid = LTRIM(RTRIM(ISNULL(@userid, '')));

    SELECT
        ISNULL(p.LastName1, '') AS primerapellido,
        ISNULL(p.LastName2, '') AS segundoapellido,
        ISNULL(p.Name1, '') + ' ' + ISNULL(p.Name2, '') AS nombres,
        ISNULL(SY_PersonDocumentType.Description, '') AS TipoDocumento,
        ISNULL(p.documentnumber, '') AS NroDocumento,
        ISNULL(PR_Nacionalidad.Description, '') AS LugarNacimiento,
        p.BirthDate AS FechaNacimiento,
        ISNULL(p.Telephone, '') AS TelefonoFijo,
        ISNULL(p.SecTelephone, '') AS Movil,
        ISNULL(p.EMail, '') AS email,
        ISNULL(p.Address, '') AS Direccion,
        ISNULL(SY_Localite.Name, '') AS distrito,
        ISNULL(SY_Province.Name, '') AS provincia,
        ISNULL(SY_Department.Name, '') AS departamento,
        '' AS Fotografia,
        E.Company AS company,
        E.Person AS person,
        p.Sex AS sexo,
        PP.Description AS cargo,
        B1.Name AS BancoSalario,
        E.SalaryAccount AS CuentaSalario,
        B2.Name AS BancoCTS,
        E.CTSAccount AS CuentaCTS,
        I.Description AS NivelInstruccion,
        PR_Institution.description AS Institucion,
        PR_Career.Description AS carrera,
        PR_EmployeeType.Description AS tipoempleado,
        ISNULL(E.ReEntryDate, E.EntryDate) AS FechaIngreso,
        HR_CONTRACTMODALITY.Description AS tipocontrato,
        PR_PensionType.Description AS Regimenenpension,
        ISNULL(E.AFPCard, '') AS cussp,
        'Si' AS AsignacionFamiliar,
        'Si' AS Afpmixta
    FROM SY_User u (NOLOCK)
        INNER JOIN SY_Person p (NOLOCK) ON p.UserID = u.UserID
        INNER JOIN PR_Employee E (NOLOCK) ON p.Person = E.Person AND E.Status = 'N'
        INNER JOIN PR_Position PP (NOLOCK) ON E.Position = PP.Position
        INNER JOIN SY_Company c (NOLOCK) ON E.Company = c.Company
        INNER JOIN SY_UserProfile up (NOLOCK) ON up.UserID = u.UserID
        INNER JOIN PR_mapping2 M (NOLOCK) ON c.Company = M.company
        LEFT JOIN SY_Localite (NOLOCK) ON p.Localite = SY_Localite.Localite
        LEFT JOIN SY_Province (NOLOCK)
            ON p.Province = SY_Province.Province
           AND SY_Province.Province = SY_Localite.Province
        LEFT JOIN SY_Department (NOLOCK)
            ON p.Department = SY_Department.Department
           AND SY_Province.Department = SY_Department.Department
        LEFT JOIN PR_Nacionalidad (NOLOCK) ON P.Nationality = PR_Nacionalidad.Nacionalidad
        INNER JOIN SY_PersonDocumentType (NOLOCK)
            ON P.EmployeeDocumentType = SY_PersonDocumentType.PersonDocumentType
        LEFT JOIN ERP_Bank B1 (NOLOCK) ON E.SalaryBank = B1.Bank
        LEFT JOIN ERP_Bank B2 (NOLOCK) ON E.CTSBank = B2.Bank
        LEFT JOIN PR_InstructionLevel I ON p.InstructionLevel = I.InstructionLevel
        LEFT JOIN PR_Institution
            ON p.costcenter1 = PR_Institution.pdt
           AND PR_Institution.Company = E.Company
        LEFT JOIN PR_Career
            ON PR_Institution.Institution = PR_Career.Institution
           AND PR_Career.pdt = p.costcenter2
        LEFT JOIN PR_EmployeeType ON E.employeetype = PR_EmployeeType.employeetype
        LEFT JOIN HR_CONTRACTMODALITY ON E.ContractModality = HR_CONTRACTMODALITY.ContractModality
        LEFT JOIN PR_PensionType ON E.PensionType = PR_PensionType.PensionType
    WHERE u.UserID = @userid;
END
GO



-- ============================================================================
-- [053/282] sp_pr_deletepersoncompany_web.sql
-- ============================================================================

/*

    Elimina un trabajador solo de la compañía indicada (@cia + @person).



    - Borra dependencias de planillas / contratos / vacaciones / etc. filtradas por Company.

    - Si el trabajador NO existe en otra compañía (PR_Employee), también elimina

      SY_Person y tablas personales sin Company (p.ej. PR_CapitalHumano).

    - Si existe en otra compañía, conserva SY_Person y datos generales.



    Basado en sp_pr_deleteperson (hm_aci2), adaptado a filtro por compañía.

    Usado por: POST /api/trabajadores/eliminar

*/

CREATE OR ALTER PROCEDURE [dbo].[sp_pr_deletepersoncompany_web]

    @cia    VARCHAR(10),

    @person VARCHAR(20)

AS

BEGIN

    SET NOCOUNT ON;

    SET XACT_ABORT ON;



    DECLARE @cia_n VARCHAR(10) = LTRIM(RTRIM(ISNULL(@cia, '')));

    DECLARE @person_n VARCHAR(20) = LTRIM(RTRIM(ISNULL(@person, '')));

    DECLARE @otras_cias INT = 0;

    DECLARE @borro_sy_person CHAR(1) = 'N';

    DECLARE @nombre VARCHAR(200) = '';



    IF @cia_n = '' OR @person_n = ''

    BEGIN

        RAISERROR('Debe indicar compañía y trabajador.', 16, 1);

        RETURN;

    END;



    IF NOT EXISTS (

        SELECT 1

        FROM PR_Employee (NOLOCK)

        WHERE Company = @cia_n

          AND Person = @person_n

    )

    BEGIN

        RAISERROR('El trabajador no existe en la compañía indicada.', 16, 1);

        RETURN;

    END;



    SELECT TOP 1

        @nombre = LTRIM(RTRIM(ISNULL(p.Name, '')))

    FROM SY_Person p (NOLOCK)

    WHERE p.Person = @person_n;



    SELECT @otras_cias = COUNT(DISTINCT e.Company)

    FROM PR_Employee e (NOLOCK)

    WHERE e.Person = @person_n

      AND e.Company <> @cia_n;



    BEGIN TRY

        BEGIN TRAN;



        DELETE FROM PR_EmployeeCTS

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_EmployeeAFP

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_EmployeeConcept

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_EmployeePayRollConcept

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_EmployeePayRoll

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_VacationProvisionedDays

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_VacationProvisionTxn

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_VacationProvision

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_VacationPay

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_VacationDetail

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_Vacation

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_TaxRentEmployee

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_PersonContract

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_EmployeeMedicalRest

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_EmployeeLoanAmortization

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_EmployeeLoan

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_EmployeeCurrentAccount

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM AR_PersonProfile

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM CA_Photocheck

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_EmployeeLocal

        WHERE Company = @cia_n

          AND (Employee = @person_n OR Person = @person_n);



        DELETE FROM SY_Dependant

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM CA_Resumenmarcas

        WHERE person = @person_n AND company = @cia_n;



        DELETE FROM ca_papeleta

        WHERE person = @person_n AND company = @cia_n;



        DELETE FROM CA_Check

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM CA_CheckSummary

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM CA_CheckApprove

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PR_EmployeeSchedule

        WHERE Person = @person_n AND Company = @cia_n;



        DELETE FROM PeriodsIndicators

        WHERE person = @person_n AND company = @cia_n;



        DELETE FROM PR_Employee

        WHERE Person = @person_n AND Company = @cia_n;



        IF @otras_cias = 0

        BEGIN

            DELETE FROM PR_CapitalHumano

            WHERE Person = @person_n;



            DELETE FROM SY_Person

            WHERE Person = @person_n;



            SET @borro_sy_person = 'Y';

        END;



        COMMIT TRAN;



        SELECT

            CAST(1 AS INT) AS ok,

            @cia_n AS cia,

            @person_n AS person,

            @nombre AS nombre,

            @borro_sy_person AS borro_sy_person,

            CASE

                WHEN @borro_sy_person = 'Y'

                    THEN 'Trabajador eliminado completamente del sistema.'

                ELSE 'Trabajador eliminado de la compania. Se conservaron sus datos generales porque existe en otra empresa.'

            END AS mensaje;

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0

            ROLLBACK TRAN;



        DECLARE @err NVARCHAR(4000) = ERROR_MESSAGE();

        RAISERROR(@err, 16, 1);

    END CATCH

END

GO



-- ============================================================================
-- [054/282] sp_pr_depurar_conceptos_auxiliares_web.sql
-- ============================================================================

/*
    Depuración de conceptos AUXILIARES no utilizados por compañía.

    Grupos de uso:
      G1 — Fórmulas (cabecera, condición, detalle, ConceptList)
      G2 — PR_EmployeeConcept (asignación)
      G3 — PR_EmployeePayRollConcept (calculados)
      G4 — Nemónicos literales en SP de cálculo (fin de mes, liquidación,
           gratificación, provisiones CTS / grati / vacaciones)

    Resultado depurable: Maestro AUX - (G1 ∪ G2 ∪ G3 ∪ G4)

    @modo:
      RESUMEN         — conteos por grupo
      NO_USADOS       — lista final depurable (default)
      NO_USADOS_G123  — sin cruzar SP
      G1 | G2 | G3 | G4 — conceptos usados en cada grupo
      DETALLE         — maestro AUX con flags por grupo

    Ejemplo:
      EXEC sp_pr_depurar_conceptos_auxiliares_web @company = 'BGT', @modo = 'RESUMEN';
      EXEC sp_pr_depurar_conceptos_auxiliares_web @company = 'SB01', @modo = 'NO_USADOS';
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_depurar_conceptos_auxiliares_web]
    @company VARCHAR(4),
    @modo    VARCHAR(20) = 'NO_USADOS'
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @modo = UPPER(LTRIM(RTRIM(ISNULL(@modo, 'NO_USADOS'))));

    IF @company = ''
    BEGIN
        RAISERROR('Indique la compañía (@company).', 16, 1);
        RETURN;
    END;

    CREATE TABLE #maestro (
        concept_id      VARCHAR(20) NOT NULL PRIMARY KEY,
        formulacode     VARCHAR(50) NULL,
        nombre_concepto VARCHAR(200) NULL,
        status          VARCHAR(10) NULL
    );

    CREATE TABLE #usado (
        concept_id VARCHAR(20) NOT NULL,
        grupo      CHAR(2) NOT NULL,
        PRIMARY KEY (concept_id, grupo)
    );

    CREATE TABLE #g4_nemonicos (
        formulacode VARCHAR(50) NOT NULL PRIMARY KEY
    );

    CREATE TABLE #tmp_nemo (
        formulacode VARCHAR(50) NOT NULL,
        origen      VARCHAR(30) NOT NULL
    );

    /* Maestro AUX */
    INSERT INTO #maestro (concept_id, formulacode, nombre_concepto, status)
    SELECT
        c.Concept,
        NULLIF(LTRIM(RTRIM(c.FormulaCode)), ''),
        NULLIF(LTRIM(RTRIM(c.Description)), ''),
        NULLIF(LTRIM(RTRIM(c.Status)), '')
    FROM PR_Concept c (NOLOCK)
        INNER JOIN PR_ConceptType ct (NOLOCK)
            ON ct.ConceptType = c.ConceptType
           AND ct.Company = c.Company
    WHERE c.Company = @company
      AND LTRIM(RTRIM(ct.ShortName)) = 'X';

    /* G1 — fórmulas */
    INSERT INTO #usado (concept_id, grupo)
    SELECT DISTINCT u.concept_id, 'G1'
    FROM (
        SELECT fh.Concept AS concept_id
        FROM PR_FormulaHeader fh (NOLOCK)
        WHERE fh.Company = @company
          AND fh.Concept IS NOT NULL
          AND LTRIM(RTRIM(fh.Concept)) <> ''

        UNION

        SELECT fh.ConceptCond
        FROM PR_FormulaHeader fh (NOLOCK)
        WHERE fh.Company = @company
          AND fh.ConceptCond IS NOT NULL
          AND LTRIM(RTRIM(fh.ConceptCond)) <> ''

        UNION

        SELECT fd.Concept
        FROM PR_FormulaHeader fh (NOLOCK)
            INNER JOIN PR_FormulaDetail fd (NOLOCK)
                ON fd.FormulaHeader = fh.FormulaHeader
        WHERE fh.Company = @company
          AND fd.Concept IS NOT NULL
          AND LTRIM(RTRIM(fd.Concept)) <> ''

        UNION

        SELECT s.concept_id
        FROM PR_FormulaHeader fh (NOLOCK)
            INNER JOIN PR_FormulaDetail fd (NOLOCK)
                ON fd.FormulaHeader = fh.FormulaHeader
        CROSS APPLY (
            SELECT LTRIM(RTRIM(
                SUBSTRING(
                    fd.ConceptList,
                    n.number,
                    CHARINDEX('|', fd.ConceptList + '|', n.number) - n.number
                )
            )) AS concept_id
            FROM master..spt_values n
            WHERE n.type = 'P'
              AND n.number BETWEEN 1 AND LEN(ISNULL(fd.ConceptList, ''))
              AND SUBSTRING('|' + fd.ConceptList, n.number, 1) = '|'
        ) s
        WHERE fh.Company = @company
          AND fd.ConceptList IS NOT NULL
          AND LTRIM(RTRIM(fd.ConceptList)) <> ''
          AND LTRIM(RTRIM(s.concept_id)) <> ''
    ) u
        INNER JOIN #maestro m ON m.concept_id = u.concept_id;

    /* G2 — asignación */
    INSERT INTO #usado (concept_id, grupo)
    SELECT DISTINCT ec.Concept, 'G2'
    FROM PR_EmployeeConcept ec (NOLOCK)
        INNER JOIN #maestro m ON m.concept_id = ec.Concept
    WHERE ec.Company = @company
      AND NOT EXISTS (
          SELECT 1 FROM #usado u
          WHERE u.concept_id = ec.Concept AND u.grupo = 'G2'
      );

    /* G3 — calculados */
    INSERT INTO #usado (concept_id, grupo)
    SELECT DISTINCT epc.Concept, 'G3'
    FROM PR_EmployeePayRollConcept epc (NOLOCK)
        INNER JOIN #maestro m ON m.concept_id = epc.Concept
    WHERE epc.Company = @company
      AND NOT EXISTS (
          SELECT 1 FROM #usado u
          WHERE u.concept_id = epc.Concept AND u.grupo = 'G3'
      );

    /* G4 — SP de cálculo (nemónicos literales) */
    DECLARE @calc_sp VARCHAR(128);
    DECLARE @calc_sps TABLE (sp_name VARCHAR(128) NOT NULL PRIMARY KEY);

    INSERT INTO @calc_sps (sp_name) VALUES
        ('sp_pr_calcular_finmes_persona'),
        ('sp_pr_calcular_liquidacion_persona'),
        ('sp_pr_calcular_gratificacion_persona'),
        ('sp_pr_calcular_provcts_persona'),
        ('sp_pr_calcular_provgrati_persona'),
        ('sp_pr_calcular_provvac_persona');

    DECLARE cur_sp CURSOR LOCAL FAST_FORWARD FOR
        SELECT sp_name FROM @calc_sps;

    OPEN cur_sp;
    FETCH NEXT FROM cur_sp INTO @calc_sp;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        DELETE FROM #tmp_nemo;

        INSERT INTO #tmp_nemo (formulacode, origen)
        EXEC dbo.sp_pr_extraer_nemonicos_literal_sp_web @procedure_name = @calc_sp;

        INSERT INTO #g4_nemonicos (formulacode)
        SELECT DISTINCT t.formulacode
        FROM #tmp_nemo t
        WHERE NOT EXISTS (
            SELECT 1 FROM #g4_nemonicos g WHERE g.formulacode = t.formulacode
        );

        FETCH NEXT FROM cur_sp INTO @calc_sp;
    END;

    CLOSE cur_sp;
    DEALLOCATE cur_sp;

    INSERT INTO #usado (concept_id, grupo)
    SELECT m.concept_id, 'G4'
    FROM #maestro m
        INNER JOIN #g4_nemonicos g
            ON g.formulacode = UPPER(LTRIM(RTRIM(ISNULL(m.formulacode, ''))))
    WHERE LTRIM(RTRIM(ISNULL(m.formulacode, ''))) <> ''
      AND NOT EXISTS (
          SELECT 1 FROM #usado u
          WHERE u.concept_id = m.concept_id AND u.grupo = 'G4'
      );

    IF @modo = 'RESUMEN'
    BEGIN
        SELECT
            @company AS company,
            (SELECT COUNT(*) FROM #maestro) AS maestro_aux,
            (SELECT COUNT(DISTINCT concept_id) FROM #usado WHERE grupo = 'G1') AS g1_formulas,
            (SELECT COUNT(DISTINCT concept_id) FROM #usado WHERE grupo = 'G2') AS g2_asignacion,
            (SELECT COUNT(DISTINCT concept_id) FROM #usado WHERE grupo = 'G3') AS g3_calculados,
            (SELECT COUNT(DISTINCT concept_id) FROM #usado WHERE grupo = 'G4') AS g4_sp_calculo,
            (SELECT COUNT(DISTINCT concept_id) FROM #usado WHERE grupo IN ('G1', 'G2', 'G3')) AS usados_g123,
            (SELECT COUNT(DISTINCT concept_id) FROM #usado) AS usados_g1234,
            (SELECT COUNT(*)
             FROM #maestro m
             WHERE NOT EXISTS (SELECT 1 FROM #usado u WHERE u.concept_id = m.concept_id AND u.grupo IN ('G1', 'G2', 'G3'))
            ) AS no_usados_g123,
            (SELECT COUNT(*)
             FROM #maestro m
             WHERE NOT EXISTS (SELECT 1 FROM #usado u WHERE u.concept_id = m.concept_id)
            ) AS no_usados_definitivos;
        RETURN;
    END;

    IF @modo IN ('G1', 'G2', 'G3', 'G4')
    BEGIN
        SELECT
            @company AS company,
            m.formulacode,
            m.nombre_concepto,
            m.concept_id,
            m.status
        FROM #usado u
            INNER JOIN #maestro m ON m.concept_id = u.concept_id
        WHERE u.grupo = @modo
        ORDER BY m.formulacode, m.nombre_concepto;
        RETURN;
    END;

    IF @modo = 'DETALLE'
    BEGIN
        SELECT
            @company AS company,
            m.formulacode,
            m.nombre_concepto,
            m.concept_id,
            m.status,
            CASE WHEN EXISTS (SELECT 1 FROM #usado u WHERE u.concept_id = m.concept_id AND u.grupo = 'G1') THEN 'S' ELSE 'N' END AS en_g1,
            CASE WHEN EXISTS (SELECT 1 FROM #usado u WHERE u.concept_id = m.concept_id AND u.grupo = 'G2') THEN 'S' ELSE 'N' END AS en_g2,
            CASE WHEN EXISTS (SELECT 1 FROM #usado u WHERE u.concept_id = m.concept_id AND u.grupo = 'G3') THEN 'S' ELSE 'N' END AS en_g3,
            CASE WHEN EXISTS (SELECT 1 FROM #usado u WHERE u.concept_id = m.concept_id AND u.grupo = 'G4') THEN 'S' ELSE 'N' END AS en_g4,
            CASE WHEN EXISTS (SELECT 1 FROM #usado u WHERE u.concept_id = m.concept_id) THEN 'N' ELSE 'S' END AS depurable
        FROM #maestro m
        ORDER BY depurable DESC, m.formulacode, m.nombre_concepto;
        RETURN;
    END;

    IF @modo = 'NO_USADOS_G123'
    BEGIN
        SELECT
            @company AS company,
            m.formulacode,
            m.nombre_concepto,
            m.concept_id,
            m.status
        FROM #maestro m
        WHERE NOT EXISTS (
            SELECT 1 FROM #usado u
            WHERE u.concept_id = m.concept_id
              AND u.grupo IN ('G1', 'G2', 'G3')
        )
        ORDER BY m.formulacode, m.nombre_concepto;
        RETURN;
    END;

    /* NO_USADOS (default) */
    SELECT
        @company AS company,
        m.formulacode,
        m.nombre_concepto,
        m.concept_id,
        m.status
    FROM #maestro m
    WHERE NOT EXISTS (SELECT 1 FROM #usado u WHERE u.concept_id = m.concept_id)
    ORDER BY m.formulacode, m.nombre_concepto;
END
GO



-- ============================================================================
-- [055/282] sp_pr_depurar_permanentes_duplicados_web.sql
-- ============================================================================

/*
    Depura asignaciones permanentes duplicadas en PR_EmployeeConcept.

    Regla:
      - Por Company + Person + PayRollType + Concept con más de un FlagFrecuencyType='P':
      - Queda PERMANENTE el de mayor PRPeriodStart (empate: mayor CostCenter).
      - Los anteriores pasan a TEMPORAL (FlagFrecuencyType='T') con
        PRPeriodEnd = periodo inmediato anterior al inicio del siguiente registro
        (vía PR_Period.PeriodOrder-1; si no hay periodo, fallback YYYYMMDD mes-1).

    Ejemplo (VIDA LEY):
      20210101 P + 20211010 P
      → 20211010 permanece P
      → 20210101 pasa a T con PRPeriodEnd = 20210909

    Uso (NO aplica cambios si @ejecutar = 'N'):
      -- Preview hm_divisa / BGT / planilla empleados:
      EXEC sp_pr_depurar_permanentes_duplicados_web
           @cia='BGT', @payrolltype='BGT 000000000004', @ejecutar='N';

      -- Aplicar:
      EXEC sp_pr_depurar_permanentes_duplicados_web
           @cia='BGT', @payrolltype='BGT 000000000004', @ejecutar='Y';

      -- Toda la compañía (todas las planillas):
      EXEC sp_pr_depurar_permanentes_duplicados_web @cia='BGT', @payrolltype=NULL, @ejecutar='N';

    Resultsets:
      1) Filas a corregir (antes → después)
      2) Resumen (grupos, filas, actualizadas)
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_depurar_permanentes_duplicados_web]
    @cia         VARCHAR(10),
    @payrolltype VARCHAR(20) = NULL,
    @ejecutar    CHAR(1) = 'N'   -- 'N' preview, 'Y' aplica UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @payrolltype = NULLIF(LTRIM(RTRIM(ISNULL(@payrolltype, ''))), '');
    SET @ejecutar = UPPER(LEFT(LTRIM(RTRIM(ISNULL(@ejecutar, 'N'))), 1));
    IF @ejecutar NOT IN ('Y', 'N')
        SET @ejecutar = 'N';

    IF @cia = ''
    BEGIN
        RAISERROR('Debe indicar @cia.', 16, 1);
        RETURN;
    END

    ;WITH base AS (
        SELECT
            EC.Person,
            EC.Company,
            EC.Concept,
            EC.PayRollType,
            EC.PRPeriodStart,
            EC.CostCenter,
            EC.FlagFrecuencyType,
            EC.PRPeriodEnd,
            EC.ConceptValue,
            C.FormulaCode,
            C.Description AS ConceptDescription,
            COUNT(*) OVER (
                PARTITION BY EC.Company, EC.Person, EC.PayRollType, EC.Concept
            ) AS cnt_grupo,
            ROW_NUMBER() OVER (
                PARTITION BY EC.Company, EC.Person, EC.PayRollType, EC.Concept
                ORDER BY EC.PRPeriodStart DESC, EC.CostCenter DESC
            ) AS rn_keep,
            LEAD(EC.PRPeriodStart) OVER (
                PARTITION BY EC.Company, EC.Person, EC.PayRollType, EC.Concept
                ORDER BY EC.PRPeriodStart ASC, EC.CostCenter ASC
            ) AS next_start
        FROM PR_EmployeeConcept EC WITH (NOLOCK)
            INNER JOIN PR_Concept C WITH (NOLOCK)
                ON C.Concept = EC.Concept
               AND C.Company = EC.Company
        WHERE EC.Company = @cia
          AND EC.FlagFrecuencyType = 'P'
          AND (@payrolltype IS NULL OR EC.PayRollType = @payrolltype)
    ),
    candidatas AS (
        SELECT
            b.*,
            CASE
                WHEN b.rn_keep = 1 THEN 'P'
                ELSE 'T'
            END AS nuevo_flag,
            CASE
                WHEN b.rn_keep = 1 THEN NULL
                ELSE COALESCE(
                    (
                        SELECT TOP 1 p2.PRPeriod
                        FROM PR_Period p1 WITH (NOLOCK)
                            INNER JOIN PR_Period p2 WITH (NOLOCK)
                                ON p2.Company = p1.Company
                               AND p2.PayRollType = p1.PayRollType
                               AND p2.PeriodOrder = p1.PeriodOrder - 1
                        WHERE p1.Company = b.Company
                          AND p1.PayRollType = b.PayRollType
                          AND p1.PRPeriod = b.next_start
                    ),
                    /* Fallback: periodo tipo YYYY + MM + MM (mes anterior). */
                    CASE
                        WHEN LEN(ISNULL(b.next_start, '')) = 8
                             AND b.next_start NOT LIKE '%[^0-9]%'
                        THEN
                            CASE
                                WHEN CONVERT(INT, SUBSTRING(b.next_start, 5, 2)) = 1
                                THEN CONVERT(CHAR(4), CONVERT(INT, LEFT(b.next_start, 4)) - 1)
                                     + '1212'
                                ELSE LEFT(b.next_start, 4)
                                     + RIGHT('0' + CONVERT(VARCHAR(2), CONVERT(INT, SUBSTRING(b.next_start, 5, 2)) - 1), 2)
                                     + RIGHT('0' + CONVERT(VARCHAR(2), CONVERT(INT, SUBSTRING(b.next_start, 5, 2)) - 1), 2)
                            END
                        ELSE NULL
                    END
                )
            END AS nuevo_period_end
        FROM base b
        WHERE b.cnt_grupo > 1
    )
    SELECT
        Person,
        Company,
        PayRollType,
        Concept,
        FormulaCode,
        ConceptDescription,
        CostCenter,
        ConceptValue,
        PRPeriodStart,
        FlagFrecuencyType AS flag_actual,
        NULLIF(LTRIM(RTRIM(ISNULL(PRPeriodEnd, ''))), '') AS period_end_actual,
        nuevo_flag,
        nuevo_period_end,
        CASE WHEN rn_keep = 1 THEN 'MANTIENE permanente' ELSE 'Convierte a temporal' END AS accion,
        next_start AS inicio_siguiente
    INTO #cambios
    FROM candidatas;

    /* Preview detalle */
    SELECT
        Person,
        FormulaCode,
        ConceptDescription,
        CostCenter,
        ConceptValue,
        PRPeriodStart,
        flag_actual,
        period_end_actual,
        nuevo_flag,
        nuevo_period_end,
        accion,
        inicio_siguiente
    FROM #cambios
    ORDER BY Person, FormulaCode, PRPeriodStart, CostCenter;

    DECLARE @grupos INT = (
        SELECT COUNT(*) FROM (
            SELECT Person, PayRollType, Concept
            FROM #cambios
            GROUP BY Person, PayRollType, Concept
        ) g
    );
    DECLARE @filas INT = (SELECT COUNT(*) FROM #cambios);
    DECLARE @a_temporal INT = (SELECT COUNT(*) FROM #cambios WHERE nuevo_flag = 'T');
    DECLARE @actualizadas INT = 0;

    IF @ejecutar = 'Y'
    BEGIN
        BEGIN TRAN;

        UPDATE EC
        SET
            EC.FlagFrecuencyType = C.nuevo_flag,
            EC.PRPeriodEnd = C.nuevo_period_end,
            EC.XLastUser = 'DEPURAR_PERM',
            EC.XLastDate = GETDATE()
        FROM PR_EmployeeConcept EC
            INNER JOIN #cambios C
                ON EC.Company = C.Company
               AND EC.Person = C.Person
               AND EC.Concept = C.Concept
               AND EC.PayRollType = C.PayRollType
               AND EC.PRPeriodStart = C.PRPeriodStart
               AND (
                    (EC.CostCenter = C.CostCenter)
                    OR (EC.CostCenter IS NULL AND C.CostCenter IS NULL)
               )
        WHERE EC.FlagFrecuencyType = 'P'
          AND (
                C.nuevo_flag = 'T'
                OR (
                    C.nuevo_flag = 'P'
                    AND NULLIF(LTRIM(RTRIM(ISNULL(EC.PRPeriodEnd, ''))), '') IS NOT NULL
                )
            );

        SET @actualizadas = @@ROWCOUNT;

        COMMIT TRAN;
    END

    SELECT
        @cia AS cia,
        ISNULL(@payrolltype, '(TODAS)') AS payrolltype,
        @ejecutar AS ejecutar,
        @grupos AS grupos_duplicados,
        @filas AS filas_en_grupos,
        @a_temporal AS filas_a_temporal,
        @actualizadas AS filas_actualizadas,
        CASE
            WHEN @ejecutar = 'Y' THEN 'APLICADO'
            ELSE 'PREVIEW (sin cambios). Ejecutar con @ejecutar=''Y'' para aplicar.'
        END AS estado;
END
GO



-- ============================================================================
-- [056/282] sp_pr_descansos_eliminar_web.sql
-- ============================================================================

/*
    Elimina un registro de PR_EmployeeMedicalRest por clave (Company, Person, line).
    Usado por: POST /descansos/eliminar (registro_descansos_medicos.html).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_descansos_eliminar_web]
    @company   VARCHAR(4),
    @person    VARCHAR(20),
    @line      INT,
    @xlastuser VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @adjunto VARCHAR(255);

    IF @line IS NULL OR @line <= 0
    BEGIN
        RAISERROR('Indique el registro de descanso a eliminar.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM PR_EmployeeMedicalRest
        WHERE Company = @company
          AND Person = @person
          AND line = @line
    )
    BEGIN
        RAISERROR('No se encontró el registro de descanso médico.', 16, 1);
        RETURN;
    END;

    SELECT @adjunto = adjunto
    FROM PR_EmployeeMedicalRest
    WHERE Company = @company
      AND Person = @person
      AND line = @line;

    DELETE FROM PR_EmployeeMedicalRest
    WHERE Company = @company
      AND Person = @person
      AND line = @line;

    SELECT 1 AS ok, @adjunto AS adjunto;
END
GO



-- ============================================================================
-- [057/282] sp_pr_descansos_guardar_web.sql
-- ============================================================================

/*
    Alta / edición de descanso médico en PR_EmployeeMedicalRest.
    Usado por: POST /descansos/guardar (registro_descansos_medicos.html).

    @line NULL o <= 0 → alta (INSERT).
    @line > 0 → actualización del registro existente.

    @medicalresttype — código de PR_MedicalRestType (filtrado por compañía).
    Si el tipo tiene PDT 20 y los días empleador acumulados del año + días nuevos
    (excluyendo el propio @line en edición) superan 20, fuerza cobertura EsSalud
    (PayReponsableFlag = S, PDT 21) y exige CITT.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_descansos_guardar_web]
    @company          VARCHAR(4),
    @person           VARCHAR(20),
    @datebegin        DATETIME,
    @dateend          DATETIME,
    @medicalresttype  VARCHAR(20),
    @prperiod         VARCHAR(10) = NULL,
    @citt             VARCHAR(20) = NULL,
    @cmp_medico       VARCHAR(255) = NULL,
    @adjunto          VARCHAR(255) = NULL,
    @days             INT = NULL,
    @line             INT = NULL,
    @xlastuser        VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @dias_nuevos       INT;
    DECLARE @anio              INT;
    DECLARE @dias_empleador    INT;
    DECLARE @pay_flag          CHAR(1);
    DECLARE @pdt               VARCHAR(2);
    DECLARE @replicationunit   VARCHAR(4);
    DECLARE @yyyymm            VARCHAR(6);
    DECLARE @cobertura_forzada BIT = 0;
    DECLARE @es_edicion        BIT = 0;

    IF @datebegin IS NULL OR @dateend IS NULL
    BEGIN
        RAISERROR('Indique fecha de inicio y término.', 16, 1);
        RETURN;
    END;

    IF @dateend < @datebegin
    BEGIN
        RAISERROR('La fecha de término no puede ser anterior a la de inicio.', 16, 1);
        RETURN;
    END;

    SET @medicalresttype = LTRIM(RTRIM(ISNULL(@medicalresttype, '')));
    IF @medicalresttype = ''
    BEGIN
        RAISERROR('Seleccione el tipo de descanso.', 16, 1);
        RETURN;
    END;

    IF ISNULL(@line, 0) > 0
    BEGIN
        SET @es_edicion = 1;
        IF NOT EXISTS (
            SELECT 1
            FROM PR_EmployeeMedicalRest
            WHERE Company = @company
              AND Person = @person
              AND line = @line
        )
        BEGIN
            RAISERROR('No se encontró el registro de descanso médico a editar.', 16, 1);
            RETURN;
        END;
    END;

    SELECT @pdt = LTRIM(RTRIM(mrt.PDT))
    FROM PR_MedicalRestType mrt
    WHERE mrt.Company = @company
      AND mrt.MedicalRestType = @medicalresttype;

    IF RTRIM(ISNULL(@pdt, '')) = ''
    BEGIN
        RAISERROR('Tipo de descanso no válido para la compañía.', 16, 1);
        RETURN;
    END;

    SET @dias_nuevos = ISNULL(@days, DATEDIFF(DAY, @datebegin, @dateend) + 1);
    IF @dias_nuevos <= 0
    BEGIN
        RAISERROR('El rango de fechas debe generar al menos 1 día.', 16, 1);
        RETURN;
    END;

    SET @anio = YEAR(@datebegin);

    SELECT @dias_empleador = ISNULL(SUM(emr.Days), 0)
    FROM PR_EmployeeMedicalRest emr
        INNER JOIN PR_MedicalRestType mrt
            ON mrt.MedicalRestType = emr.MedicalRestType
           AND mrt.Company = emr.Company
    WHERE emr.Company = @company
      AND emr.Person = @person
      AND emr.PayReponsableFlag = 'E'
      AND LTRIM(RTRIM(ISNULL(mrt.PDT, ''))) = '20'
      AND YEAR(emr.DateBegin) = @anio
      AND (@es_edicion = 0 OR emr.line <> @line);

    IF @pdt = '20' AND (@dias_empleador + @dias_nuevos) > 20
    BEGIN
        SET @pay_flag = 'S';
        SET @cobertura_forzada = 1;

        IF RTRIM(ISNULL(@citt, '')) = ''
        BEGIN
            RAISERROR('Al superar los 20 días a cargo del empleador se requiere el número de CITT para el subsidio EsSalud.', 16, 1);
            RETURN;
        END;

        SELECT TOP 1 @medicalresttype = mrt.MedicalRestType
        FROM PR_MedicalRestType mrt
        WHERE mrt.Company = @company
          AND LTRIM(RTRIM(mrt.PDT)) = '21'
        ORDER BY mrt.MedicalRestType;

        IF RTRIM(ISNULL(@medicalresttype, '')) = ''
        BEGIN
            RAISERROR('No se encontró el tipo de descanso médico (PDT 21) para el subsidio EsSalud.', 16, 1);
            RETURN;
        END;

        SET @pdt = '21';
    END
    ELSE IF @pdt IN ('21', '22')
    BEGIN
        SET @pay_flag = 'S';
    END
    ELSE
    BEGIN
        SET @pay_flag = 'E';
    END;

    SET @prperiod = LTRIM(RTRIM(ISNULL(@prperiod, '')));

    IF @prperiod = ''
    BEGIN
        SET @yyyymm = CONVERT(VARCHAR(6), @datebegin, 112);

        SELECT TOP 1 @prperiod = p.PRPeriod
        FROM PR_Period p
            INNER JOIN PR_Employee e
                ON e.Company = @company
               AND e.Person = @person
        WHERE p.Company = @company
          AND p.PayRollType = e.PayRollType
          AND LEFT(p.PRPeriod, 6) = @yyyymm
        ORDER BY p.PRPeriod DESC;

        IF RTRIM(ISNULL(@prperiod, '')) = ''
        BEGIN
            SELECT TOP 1 @prperiod = p.PRPeriod
            FROM PR_Period p
            WHERE p.Company = @company
              AND LEFT(p.PRPeriod, 6) = @yyyymm
            ORDER BY p.PRPeriod DESC;
        END;

        IF RTRIM(ISNULL(@prperiod, '')) = ''
            SET @prperiod = CONVERT(VARCHAR(8), @datebegin, 112);
    END;

    IF @es_edicion = 1
    BEGIN
        UPDATE PR_EmployeeMedicalRest
        SET MedicalRestType = @medicalresttype,
            DateBegin = @datebegin,
            DateEnd = @dateend,
            Days = @dias_nuevos,
            PRPeriod = @prperiod,
            PayReponsableFlag = @pay_flag,
            XLastUser = @xlastuser,
            XLastDate = GETDATE(),
            citt = NULLIF(LTRIM(RTRIM(@citt)), ''),
            pdt = @pdt,
            medico = NULLIF(LTRIM(RTRIM(@cmp_medico)), ''),
            adjunto = CASE
                WHEN @adjunto IS NULL THEN adjunto
                WHEN LTRIM(RTRIM(@adjunto)) = '' THEN NULL
                ELSE @adjunto
            END
        WHERE Company = @company
          AND Person = @person
          AND line = @line;
    END
    ELSE
    BEGIN
        SELECT @line = ISNULL(MAX(line), 0) + 1
        FROM PR_EmployeeMedicalRest
        WHERE Company = @company
          AND Person = @person;

        SELECT @replicationunit = ISNULL(ReplicationUnit, @company)
        FROM PR_Employee
        WHERE Company = @company
          AND Person = @person;

        INSERT INTO PR_EmployeeMedicalRest (
            Person, Company, line,
            MedicalRestType, DateBegin, DateEnd, Days,
            PRPeriod, PayReponsableFlag, Status,
            CostCenter, CostCenterCode,
            ReplicationUnit, XLastUser, XLastDate,
            citt, pdt, medico, adjunto
        )
        VALUES (
            @person, @company, @line,
            @medicalresttype, @datebegin, @dateend, @dias_nuevos,
            @prperiod, @pay_flag, 'P',
            NULL, NULL,
            @replicationunit, @xlastuser, GETDATE(),
            NULLIF(LTRIM(RTRIM(@citt)), ''),
            @pdt,
            NULLIF(LTRIM(RTRIM(@cmp_medico)), ''),
            NULLIF(LTRIM(RTRIM(@adjunto)), '')
        );
    END;

    SELECT
        @line AS line,
        @dias_nuevos AS dias,
        @pay_flag AS payreponsableflag,
        @pdt AS pdt,
        @medicalresttype AS medicalresttype,
        @cobertura_forzada AS cobertura_forzada,
        @es_edicion AS es_edicion,
        CASE @pay_flag
            WHEN 'E' THEN 'Empleador'
            WHEN 'S' THEN 'Subsidio EsSalud'
            ELSE @pay_flag
        END AS cobertura_texto;
END
GO



-- ============================================================================
-- [058/282] sp_pr_descansos_obtener_trabajador_web.sql
-- ============================================================================

/*
    Detalle de descansos médicos de un trabajador para Registro de Descansos Médicos.
    Usado por: GET /descansos/trabajador/<id> (registro_descansos_medicos.html).

    Result sets:
      1 — Datos del empleado.
      2 — KPIs del año (@anio; por defecto año actual).
      3 — Historial completo de descansos (sin filtro de año).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_descansos_obtener_trabajador_web]
    @company VARCHAR(4),
    @person  VARCHAR(20),
    @anio    INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @anio IS NULL OR @anio < 1900
        SET @anio = YEAR(GETDATE());

    SELECT
        PR_Employee.Person AS person,
        PR_Employee.EmployeeCode AS codigo,
        LTRIM(RTRIM(
            ISNULL(SY_Person.LastName1, '') + ' ' +
            ISNULL(SY_Person.LastName2, '') + ' ' +
            ISNULL(SY_Person.Name1, '') + ' ' +
            ISNULL(SY_Person.Name2, '')
        )) AS nombre,
        SY_Person.DocumentNumber AS documento,
        ISNULL(PR_Employee.ReentryDate, PR_Employee.EntryDate) AS fechaingreso,
        PR_Employee.PayRollType AS payrolltype
    FROM PR_Employee
        INNER JOIN SY_Person
            ON PR_Employee.Person = SY_Person.Person
    WHERE PR_Employee.Company = @company
      AND PR_Employee.Person = @person;

    SELECT
        ISNULL(SUM(
            CASE
                WHEN emr.PayReponsableFlag = 'E'
                 AND LTRIM(RTRIM(ISNULL(mrt.PDT, ''))) = '20'
                THEN emr.Days
                ELSE 0
            END
        ), 0) AS dias_empleador,
        ISNULL(SUM(
            CASE
                WHEN emr.PayReponsableFlag = 'S'
                 AND LTRIM(RTRIM(ISNULL(mrt.PDT, ''))) IN ('21', '22')
                THEN emr.Days
                ELSE 0
            END
        ), 0) AS dias_essalud,
        ISNULL(SUM(emr.Days), 0) AS total_anio,
        20 AS limite_empleador
    FROM PR_EmployeeMedicalRest emr
        INNER JOIN PR_MedicalRestType mrt
            ON mrt.MedicalRestType = emr.MedicalRestType
           AND mrt.Company = emr.Company
    WHERE emr.Company = @company
      AND emr.Person = @person
      AND YEAR(emr.DateBegin) = @anio;

    SELECT
        emr.line AS line,
        emr.DateBegin AS datebegin,
        emr.DateEnd AS dateend,
        emr.Days AS days,
        emr.PRPeriod AS prperiod,
        emr.PayReponsableFlag AS payreponsableflag,
        CASE emr.PayReponsableFlag
            WHEN 'E' THEN 'Empleador'
            WHEN 'S' THEN 'Subsidio EsSalud'
            ELSE emr.PayReponsableFlag
        END AS cobertura_texto,
        emr.MedicalRestType AS medicalresttype,
        PR_MedicalRestType.Description AS tipo_descanso,
        PR_MedicalRestType.PDT AS pdt,
        emr.citt AS citt,
        emr.medico AS cmp_medico,
        emr.adjunto AS adjunto,
        emr.Status AS status,
        emr.XLastDate AS fecha_modificacion
    FROM PR_EmployeeMedicalRest emr
        INNER JOIN PR_MedicalRestType
            ON PR_MedicalRestType.MedicalRestType = emr.MedicalRestType
           AND PR_MedicalRestType.Company = emr.Company
    WHERE emr.Company = @company
      AND emr.Person = @person
    ORDER BY emr.DateBegin DESC, emr.line DESC;
END
GO



-- ============================================================================
-- [059/282] sp_pr_detalleboletaaportes_web.sql
-- ============================================================================

/*
    Generar boletas — detalle de aportes para el PDF.

    Usado por: generar_pdf_en_memoria (app.py).

    Parámetros:
      @cia, @process, @payrolltype, @period, @person
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_detalleboletaaportes_web]
    @cia         VARCHAR(4),
    @process     VARCHAR(20),
    @payrolltype VARCHAR(20),
    @period      VARCHAR(20),
    @person      VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        C.person,
        pr_concepttype.shortname,
        pr_concept.printtext,
        C.conceptvalue,
        pr_concept.conceptorder
    FROM pr_concept (NOLOCK),
         pr_concepttype (NOLOCK),
         pr_employeepayrollconcept C (NOLOCK)
    WHERE C.concept = pr_concept.concept
      AND pr_concept.concepttype = pr_concepttype.concepttype
      AND C.company = @cia
      AND C.processtype = @process
      AND C.payrolltype = @payrolltype
      AND C.prperiod = @period
      AND C.person = @person
      AND ISNULL(pr_concept.flagpayrollticket, 'N') = 'Y'
      AND pr_concepttype.shortname = 'A'
    ORDER BY 5;
END
GO



-- ============================================================================
-- [060/282] sp_pr_detalleboletadescuentos_web.sql
-- ============================================================================

/*
    Generar boletas — detalle de descuentos para el PDF.

    Usado por: generar_pdf_en_memoria (app.py).

    Parámetros:
      @cia, @process, @payrolltype, @period, @person
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_detalleboletadescuentos_web]
    @cia         VARCHAR(4),
    @process     VARCHAR(20),
    @payrolltype VARCHAR(20),
    @period      VARCHAR(20),
    @person      VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        C.person,
        pr_concepttype.shortname,
        pr_concept.printtext,
        C.conceptvalue,
        pr_concept.conceptorder
    FROM pr_concept (NOLOCK),
         pr_concepttype (NOLOCK),
         pr_employeepayrollconcept C (NOLOCK)
    WHERE C.concept = pr_concept.concept
      AND pr_concept.concepttype = pr_concepttype.concepttype
      AND C.company = @cia
      AND C.processtype = @process
      AND C.payrolltype = @payrolltype
      AND C.prperiod = @period
      AND C.person = @person
      AND ISNULL(pr_concept.flagpayrollticket, 'N') = 'Y'
      AND pr_concepttype.shortname = 'D'
    ORDER BY 5;
END
GO



-- ============================================================================
-- [061/282] sp_pr_detalleboletaingresos_web.sql
-- ============================================================================

/*
    Generar boletas — detalle de ingresos para el PDF.

    Usado por: generar_pdf_en_memoria (app.py).

    Parámetros:
      @cia, @process, @payrolltype, @period, @person
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_detalleboletaingresos_web]
    @cia         VARCHAR(4),
    @process     VARCHAR(20),
    @payrolltype VARCHAR(20),
    @period      VARCHAR(20),
    @person      VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        C.person,
        pr_concepttype.shortname,
        pr_concept.printtext,
        C.conceptvalue,
        pr_concept.conceptorder
    FROM pr_concept (NOLOCK),
         pr_concepttype (NOLOCK),
         pr_employeepayrollconcept C (NOLOCK)
    WHERE C.concept = pr_concept.concept
      AND pr_concept.concepttype = pr_concepttype.concepttype
      AND C.company = @cia
      AND C.processtype = @process
      AND C.payrolltype = @payrolltype
      AND C.prperiod = @period
      AND C.person = @person
      AND ISNULL(pr_concept.flagpayrollticket, 'N') = 'Y'
      AND pr_concepttype.shortname = 'I'
    ORDER BY 5;
END
GO



-- ============================================================================
-- [062/282] sp_pr_detallecalculocertificadoquinta_web.sql
-- ============================================================================

/*
    Detalle de cálculo — sueldos/asignaciones y utilidades (certificado quinta).
    Usado por: POST /get_detalle_calculo_certificado_quinta

    Lista conceptos con flagafecto5ta = 'Y' de todos los procesos del año,
    incluyendo UTILIDADES (excluido del importe de sueldos pero visible en detalle).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_detallecalculocertificadoquinta_web]
    @cia         VARCHAR(4),
    @payrolltype VARCHAR(20),
    @anio        VARCHAR(4),
    @person      VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    SET @anio = LTRIM(RTRIM(ISNULL(@anio, '')));
    SET @person = LTRIM(RTRIM(ISNULL(@person, '')));

    SELECT
        ISNULL(PT.ShortName, '') AS proceso,
        ISNULL(PT.Description, '') AS proceso_descripcion,
        LTRIM(RTRIM(EC.PRPeriod)) AS periodo,
        ISNULL(NULLIF(LTRIM(RTRIM(C.PrintText)), ''), C.Description) AS concepto,
        C.FormulaCode AS formulacode,
        ISNULL(EC.ConceptValueLo, 0) AS importe,
        CASE
            WHEN ISNULL(PT.ShortName, '') = 'UTILIDADES' THEN 'UTILIDADES'
            ELSE 'SUELDOS'
        END AS tipo_linea
    FROM PR_EmployeePayRollConcept EC (NOLOCK)
        INNER JOIN PR_Concept C (NOLOCK)
            ON C.Company = EC.Company AND C.Concept = EC.Concept
        INNER JOIN PR_ProcessType PT (NOLOCK)
            ON PT.ProcessType = EC.ProcessType
    WHERE EC.Company = @cia
      AND EC.Person = @person
      AND EC.PayRollType = @payrolltype
      AND LEFT(LTRIM(RTRIM(EC.PRPeriod)), 4) = @anio
      AND ISNULL(C.flagafecto5ta, 'N') = 'Y'
    ORDER BY
        CASE WHEN ISNULL(PT.ShortName, '') = 'UTILIDADES' THEN 2 ELSE 1 END,
        PT.ShortName,
        EC.PRPeriod,
        concepto;
END
GO



-- ============================================================================
-- [063/282] sp_pr_detallecalculoutilidades_web.sql
-- ============================================================================

/*
    Detalle de cálculo — constancia de utilidades.
    Usado por: POST /get_detalle_calculo_formato_utilidades

    Lista conceptos con flagafectoUtilidad = 'Y' del año de ejercicio indicado.
    El ejercicio es el año calendario anterior al periodo de utilidades:
      utilidad calculada en marzo 2026 → @ejercicio = '2025'
      (planillas con PRPeriod que inicia en 2025: 20250101, 20251212, etc.)

    Parámetros:
      @cia, @payrolltype, @ejercicio (4 dígitos), @person
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_detallecalculoutilidades_web]
    @cia         VARCHAR(4),
    @payrolltype VARCHAR(20),
    @ejercicio   VARCHAR(4),
    @person      VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    SET @ejercicio = LTRIM(RTRIM(ISNULL(@ejercicio, '')));
    SET @person = LTRIM(RTRIM(ISNULL(@person, '')));

    SELECT
        ISNULL(PT.ShortName, '') AS proceso,
        ISNULL(PT.Description, '') AS proceso_descripcion,
        LTRIM(RTRIM(EC.PRPeriod)) AS periodo,
        ISNULL(NULLIF(LTRIM(RTRIM(C.PrintText)), ''), C.Description) AS concepto,
        C.FormulaCode AS formulacode,
        ISNULL(EC.ConceptValueLo, EC.ConceptValue) AS importe
    FROM PR_EmployeePayRollConcept EC (NOLOCK)
        INNER JOIN PR_Concept C (NOLOCK)
            ON C.Company = EC.Company
           AND C.Concept = EC.Concept
        INNER JOIN PR_ProcessType PT (NOLOCK)
            ON PT.ProcessType = EC.ProcessType
           AND PT.Company = EC.Company
    WHERE EC.Company = @cia
      AND EC.Person = @person
      AND EC.PayRollType = @payrolltype
      AND @ejercicio <> ''
      AND LEFT(LTRIM(RTRIM(EC.PRPeriod)), 4) = @ejercicio
      AND ISNULL(C.flagafectoUtilidad, 'N') = 'Y'
    ORDER BY
        PT.ShortName,
        EC.PRPeriod,
        concepto;
END
GO



-- ============================================================================
-- [064/282] sp_pr_eliminar_accountprofiledetail_web.sql
-- ============================================================================

/*
    Elimina una configuración de concepto en PR_AccountProfileDetail.
    Clave: Detail + AccountProfile (+ Company).
    Usado por: POST /api/asientos/configurar-conceptos/eliminar
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_eliminar_accountprofiledetail_web]
    @company         VARCHAR(4),
    @detail          VARCHAR(20),
    @accountprofile  VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @detail = LTRIM(RTRIM(ISNULL(@detail, '')));
    SET @accountprofile = LTRIM(RTRIM(ISNULL(@accountprofile, '')));

    IF @company = '' OR @detail = '' OR @accountprofile = ''
    BEGIN
        RAISERROR('Indique compañía, detalle y perfil contable.', 16, 1);
