-- ============================================================================
-- [065/282] sp_pr_eliminar_calculo_planilla_web.sql
-- ============================================================================

/*
    Elimina el cálculo de planilla de un trabajador para compañía, tipo, proceso y periodo.
    Equivalente web al proceso legacy de PowerBuilder (eliminar cálculo).
    Usado por: POST /api/procesar-planilla/eliminar-calculo (procesar_planilla.html).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_eliminar_calculo_planilla_web]
    @company     VARCHAR(10),
    @payrolltype VARCHAR(20),
    @processtype VARCHAR(20),
    @period      VARCHAR(10),
    @person      VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    SET @processtype = LTRIM(RTRIM(ISNULL(@processtype, '')));
    SET @period = LTRIM(RTRIM(ISNULL(@period, '')));
    SET @person = LTRIM(RTRIM(ISNULL(@person, '')));

    IF @company = '' OR @payrolltype = '' OR @processtype = '' OR @period = ''
    BEGIN
        RAISERROR('Faltan compañía, tipo de planilla, proceso o periodo.', 16, 1);
        RETURN;
    END;

    IF @person = ''
    BEGIN
        RAISERROR('Debe seleccionar un trabajador.', 16, 1);
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        DELETE FROM PR_IntegralProcessLog
        WHERE Company = @company
          AND PRPeriod = @period
          AND Person = @person;

        DELETE FROM PR_EMPLOYEEAFP
        WHERE Company = @company
          AND PayRollType = @payrolltype
          AND PRPeriod = @period
          AND Person = @person;

        DELETE FROM PR_EmployeePayRollConcept
        WHERE Company = @company
          AND PayRollType = @payrolltype
          AND ProcessType = @processtype
          AND PRPeriod = @period
          AND Person = @person;

        DELETE FROM PR_EmployeePayRoll
        WHERE Company = @company
          AND PayRollType = @payrolltype
          AND ProcessType = @processtype
          AND PRPeriod = @period
          AND Person = @person;

        DELETE FROM PR_LOG_CALCULO_PLANILLAS
        WHERE Company = @company
          AND PayRollType = @payrolltype
          AND Process = @processtype
          AND Period = @period
          AND Person = @person;

        DELETE FROM PR_PayrollLog
        WHERE Company = @company
          AND PayRollType = @payrolltype
          AND ProcessType = @processtype
          AND PRPeriod = @period
          AND Person = @person;

        COMMIT TRANSACTION;

        SELECT 1 AS ok, @person AS person;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @msg NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR(@msg, 16, 1);
    END CATCH;
END
GO



-- ============================================================================
-- [066/282] sp_pr_eliminar_distribucion_voucher_web.sql
-- ============================================================================

/*
    Maestro Distribución Porcentual — eliminación de PR_DistribucionVoucher.
    Usado por: POST /api/asientos/distribucion-porcentual/eliminar
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_eliminar_distribucion_voucher_web]
    @company VARCHAR(4),
    @period  VARCHAR(20),
    @fila    INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @period = LTRIM(RTRIM(ISNULL(@period, '')));

    IF @fila IS NULL OR @company = '' OR @period = ''
    BEGIN
        RAISERROR('Indique compañía, periodo y registro a eliminar.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM PR_DistribucionVoucher (NOLOCK)
        WHERE Fila = @fila
          AND company = @company
          AND period = @period
    )
    BEGIN
        RAISERROR('No se encontró el registro de distribución.', 16, 1);
        RETURN;
    END;

    DELETE FROM PR_DistribucionVoucher
    WHERE Fila = @fila
      AND company = @company
      AND period = @period;

    SELECT
        @fila AS fila,
        'Distribución eliminada correctamente.' AS mensaje;
END
GO



-- ============================================================================
-- [067/282] sp_pr_eliminaraf_web.sql
-- ============================================================================

/*
    Elimina una AFP de PR_AFP si no está en uso.
    Usado por: POST /api/afps/eliminar
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_eliminaraf_web]
    @company VARCHAR(4),
    @afp     VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @afp = LTRIM(RTRIM(ISNULL(@afp, '')));

    IF @company = '' OR @afp = ''
    BEGIN
        RAISERROR('Indique compañía y AFP a eliminar.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM PR_AFP (NOLOCK)
        WHERE Company = @company
          AND AFP = @afp
    )
    BEGIN
        RAISERROR('La AFP no existe o no pertenece a la compañía indicada.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM PR_Employee (NOLOCK)
        WHERE Company = @company
          AND AFP = @afp
    )
    BEGIN
        RAISERROR('No se puede eliminar: la AFP está asignada a trabajadores.', 16, 1);
        RETURN;
    END;

    IF OBJECT_ID('dbo.PR_EmployeeAFP', 'U') IS NOT NULL
       AND EXISTS (
            SELECT 1
            FROM PR_EmployeeAFP (NOLOCK)
            WHERE Company = @company
              AND AFP = @afp
       )
    BEGIN
        RAISERROR('No se puede eliminar: la AFP tiene historial en trabajadores.', 16, 1);
        RETURN;
    END;

    DELETE FROM PR_AFP
    WHERE Company = @company
      AND AFP = @afp;

    IF @@ROWCOUNT = 0
    BEGIN
        RAISERROR('No se pudo eliminar la AFP.', 16, 1);
        RETURN;
    END;

    SELECT
        @afp AS afp,
        'AFP eliminada correctamente.' AS mensaje;
END
GO



-- ============================================================================
-- [068/282] sp_pr_eliminarasignacionconcepto_web.sql
-- ============================================================================

/*
    Elimina una asignación de concepto (PR_EmployeeConcept).
    Clave: person, company, concept, payrolltype, prperiodstart, costcenter.
    Usado por: POST /api/asignacion-conceptos/eliminar
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_eliminarasignacionconcepto_web]
    @par_company       VARCHAR(10),
    @par_person        VARCHAR(20),
    @par_concept       VARCHAR(20),
    @par_payrolltype   VARCHAR(20),
    @par_prperiodstart VARCHAR(10),
    @par_costcenter    VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @par_company = LTRIM(RTRIM(ISNULL(@par_company, '')));
    SET @par_person = LTRIM(RTRIM(ISNULL(@par_person, '')));
    SET @par_concept = LTRIM(RTRIM(ISNULL(@par_concept, '')));
    SET @par_payrolltype = LTRIM(RTRIM(ISNULL(@par_payrolltype, '')));
    SET @par_prperiodstart = LTRIM(RTRIM(ISNULL(@par_prperiodstart, '')));
    SET @par_costcenter = LTRIM(RTRIM(ISNULL(@par_costcenter, '')));

    IF @par_company = '' OR @par_person = '' OR @par_concept = '' OR @par_payrolltype = '' OR @par_prperiodstart = ''
    BEGIN
