-- ============================================================================
-- [128/282] sp_pr_listarconceptos_web.sql
-- ============================================================================

/*
    Listado de conceptos de planilla por compañía (maestro Conceptos).
    Usado por: POST /api/conceptos/listado

    Filtros: @company (obligatorio), @descripcion (opcional, parcial).

    Optimización: puede_eliminar con LEFT JOIN agregados (evita EXISTS correlacionados
    por fila). La comprobación AFP vía EPC es redundante si ya existe en EPC.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_listarconceptos_web]
    @company     VARCHAR(4),
    @descripcion VARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @descripcion = NULLIF(LTRIM(RTRIM(ISNULL(@descripcion, ''))), '');

    SELECT
        C.Concept AS concept,
        C.Description AS description,
        ISNULL(C.pdt, '') AS pdt,
        ISNULL(T.ShortName, '') AS tiposhortname,
        ISNULL(T.Description, '') AS tipodescription,
        C.FormulaCode AS formulacode,
        ISNULL(C.reporden, 0) AS reporden,
        C.XLastDate AS xlastdate,
        CASE
            WHEN EC.Concept IS NOT NULL OR EPC.Concept IS NOT NULL THEN 'N'
            ELSE 'Y'
        END AS puede_eliminar
    FROM PR_Concept C (NOLOCK)
        LEFT JOIN PR_ConceptType T (NOLOCK)
            ON C.ConceptType = T.ConceptType
           AND T.Company = C.Company
        LEFT JOIN (
            SELECT DISTINCT Company, Concept
            FROM PR_EmployeeConcept (NOLOCK)
            WHERE Company = @company
        ) EC
            ON EC.Company = C.Company
           AND EC.Concept = C.Concept
        LEFT JOIN (
            SELECT DISTINCT Company, Concept
            FROM PR_EmployeePayRollConcept (NOLOCK)
            WHERE Company = @company
        ) EPC
            ON EPC.Company = C.Company
           AND EPC.Concept = C.Concept
    WHERE C.Company = @company
      AND (
            @descripcion IS NULL
         OR C.Description LIKE '%' + @descripcion + '%'
         OR C.FormulaCode LIKE '%' + @descripcion + '%'
         OR C.PrintText LIKE '%' + @descripcion + '%'
      )
    ORDER BY
        C.Description ASC,
        C.FormulaCode ASC;
END
GO



-- ============================================================================
-- [129/282] sp_pr_listarformulas_web.sql
-- ============================================================================

/*
    Listado maestro de fórmulas por compañía, tipo de planilla y proceso.
    Usado por: POST /api/formulas/listado
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_listarformulas_web]
    @company     VARCHAR(4),
    @payrolltype VARCHAR(20),
    @processtype VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    SET @processtype = LTRIM(RTRIM(ISNULL(@processtype, '')));

    IF @company = '' OR @payrolltype = '' OR @processtype = ''
    BEGIN
        RAISERROR('Indique compañía, tipo de planilla y proceso.', 16, 1);
        RETURN;
    END;

    SELECT
        fh.FormulaHeader AS formulaheader,
        fh.Company AS company,
        fh.Payrolltype AS payrolltype,
        fh.Proccestype AS proccestype,
        fh.Concept AS concept,
        fh.Description AS description,
        fh.orden,
        c.Description AS concepto,
        ct.Description AS tipo,
        cc.Description AS condicion,
        gf.name AS grupo,
        LTRIM(RTRIM(ISNULL(c.FormulaCode, fh.formulacode))) AS formulacode,
        'N' AS flag,
        (
            SELECT MAX(fd.XLastDate)
            FROM PR_FormulaDetail fd (NOLOCK)
            WHERE fd.FormulaHeader = fh.FormulaHeader
        ) AS ultimafecha
    FROM PR_FormulaHeader fh (NOLOCK)
        INNER JOIN PR_Concept c (NOLOCK)
            ON fh.Concept = c.Concept
           AND fh.Company = c.Company
        INNER JOIN PR_ConceptType ct (NOLOCK)
            ON c.ConceptType = ct.ConceptType
        LEFT JOIN PR_GrupoFormula gf (NOLOCK)
            ON fh.GrupoFormula = gf.GrupoFormula
        LEFT JOIN PR_Concept cc (NOLOCK)
            ON fh.ConceptCond = cc.Concept
           AND fh.Company = cc.Company
    WHERE fh.Company = @company
      AND fh.Payrolltype = @payrolltype
      AND fh.Proccestype = @processtype
    ORDER BY fh.orden ASC, fh.FormulaHeader ASC;
END
GO



-- ============================================================================
-- [130/282] sp_pr_listarimportconcept_web.sql
-- ============================================================================

/*
    Listado de plantillas de importación de conceptos (PR_ImportConcept).
    Usado por: POST /api/plantillas-importacion/listado

    Nota: en datos legacy PR_ImportConceptDetail.Company puede ser NULL;
    el conteo de líneas incluye esas filas.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_listarimportconcept_web]
    @company  VARCHAR(4),
    @busqueda VARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @busqueda = NULLIF(LTRIM(RTRIM(ISNULL(@busqueda, ''))), '');

    SELECT
        ic.ImportConcept AS importconcept,
        LTRIM(RTRIM(ISNULL(ic.Name, ''))) AS name,
        ic.Company AS company,
        ic.XlastUser AS xlastuser,
        ic.XlastDate AS xlastdate,
        ISNULL((
            SELECT COUNT(*)
            FROM PR_ImportConceptDetail d (NOLOCK)
            WHERE d.ImportConcept = ic.ImportConcept
              AND (
                    ISNULL(LTRIM(RTRIM(d.Company)), '') = ''
                 OR d.Company = ic.Company
              )
        ), 0) AS lineas
    FROM PR_ImportConcept ic (NOLOCK)
    WHERE ic.Company = @company
      AND (
            @busqueda IS NULL
         OR ic.Name LIKE '%' + @busqueda + '%'
         OR ic.ImportConcept LIKE '%' + @busqueda + '%'
      )
    ORDER BY ic.Name ASC, ic.ImportConcept ASC;
END
GO



