-- ============================================================================
-- [199/282] sp_pr_selectorconceptoneto_web.sql
-- ============================================================================

/*
    Concepto por defecto para Pago de haberes: Neto a recibir (FormulaCode = NETO).
    Usado por: GET /api/selectores/concepto-neto

    Parámetros:
      @cia — compañía (obligatorio).

    Retorna una fila con concept y description, o vacío si no existe.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorconceptoneto_web]
    @cia VARCHAR(10)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1
        LTRIM(RTRIM(PR_CONCEPT.CONCEPT)) AS concept,
        LTRIM(RTRIM(PR_CONCEPT.DESCRIPTION)) AS description
    FROM PR_CONCEPT
    WHERE PR_CONCEPT.STATUS = 'A'
      AND PR_CONCEPT.COMPANY = @cia
      AND UPPER(LTRIM(RTRIM(PR_CONCEPT.FormulaCode))) = 'NETO'
    ORDER BY PR_CONCEPT.CONCEPT;
END
GO



-- ============================================================================
-- [200/282] sp_pr_selectorconceptos_contables_web.sql
-- ============================================================================

/*
    Selector de conceptos monetarios por compañía (para configuración contable).
    Usado por: POST /api/asientos/configurar-conceptos/conceptos
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorconceptos_contables_web]
    @company   VARCHAR(4),
    @busqueda  VARCHAR(80) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @busqueda = NULLIF(LTRIM(RTRIM(ISNULL(@busqueda, ''))), '');

    IF @company = ''
    BEGIN
        RAISERROR('Indique la compañía.', 16, 1);
        RETURN;
    END;

    SELECT
        LTRIM(RTRIM(c.Concept)) AS id,
        LTRIM(RTRIM(ISNULL(c.Description, c.Concept))) AS text,
        LTRIM(RTRIM(ISNULL(c.FormulaCode, ''))) AS formulacode
    FROM PR_Concept c (NOLOCK)
    WHERE c.Company = @company
      AND ISNULL(c.Status, 'A') = 'A'
      AND ISNULL(c.FlagIsMonetary, 'Y') = 'Y'
      AND (
            @busqueda IS NULL
         OR ISNULL(c.Description, '') LIKE '%' + @busqueda + '%'
         OR ISNULL(c.FormulaCode, '') LIKE '%' + @busqueda + '%'
      )
    ORDER BY c.Description ASC, c.FormulaCode ASC;
END
GO



