-- ============================================================================
-- [215/282] sp_pr_selectorperiodoactivo_planilla_web.sql
-- ============================================================================

/*
    Ultimo periodo abierto del proceso Mensual / Fin de mes de una planilla.
    Usado por: GET /api/aperturar-periodos/periodo-sugerido
               (carga masiva, aperturar periodos, asignacion de conceptos)
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorperiodoactivo_planilla_web]
    @cia         VARCHAR(20),
    @payrolltype VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1
        LTRIM(RTRIM(pc.PRPeriod)) AS prperiod
    FROM PR_ProcessControl pc WITH (NOLOCK)
    INNER JOIN PR_ProcessType pt WITH (NOLOCK)
        ON pt.ProcessType = pc.ProcessType
       AND pt.Company = pc.Company
    WHERE pc.Company = @cia
      AND pc.PayRollType = @payrolltype
      AND pc.Status IN ('A', 'G')
      AND (
            UPPER(LTRIM(RTRIM(ISNULL(pt.ShortName, '')))) IN ('FIN_DE_MES', 'MENSUAL')
         OR UPPER(LTRIM(RTRIM(ISNULL(pt.ShortName, '')))) LIKE '%FIN%MES%'
         OR UPPER(LTRIM(RTRIM(ISNULL(pt.ShortName, '')))) LIKE '%MENSUAL%'
      )
    ORDER BY pc.PRPeriod DESC;
END
GO



-- ============================================================================
-- [216/282] sp_pr_selectorperiodoactivo_web.sql
-- ============================================================================

/*
    Periodo activo del proceso (PR_ProcessControl, Status = 'A').
    Usado por: GET /api/selectores/periodo-activo (reporte resumen total y similares).

    Parámetros:
      @cia, @payrolltype, @processtype — obligatorios.

    Retorna una fila con prperiod o vacío si no hay periodo activo.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorperiodoactivo_web]
    @cia         VARCHAR(10),
    @payrolltype VARCHAR(20),
    @processtype VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1
        LTRIM(RTRIM(PRPeriod)) AS prperiod
    FROM PR_ProcessControl
    WHERE Company = @cia
      AND PayRollType = @payrolltype
      AND ProcessType = @processtype
      AND Status = 'A'
    ORDER BY PRPeriod DESC;
END
GO



-- ============================================================================
-- [217/282] sp_pr_selectorperiodocalculo_web.sql
-- ============================================================================

/*
    Selector de periodos de cálculo por compañía, planilla y proceso.
    Periodos abiertos o cerrados en PR_ProcessControl (status A, C, G)
    de la planilla indicada (no mezcla otras planillas).
    Usado por: GET /api/procesar-planilla/periodos-calculo (procesar_planilla.html).

    processtype, prperiod, description, company, status
    Orden: abiertos (A/G) primero, luego PRPeriod DESC.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorperiodocalculo_web]
    @cia         VARCHAR(4),
    @processtype VARCHAR(20),
    @payrolltype VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @processtype = LTRIM(RTRIM(ISNULL(@processtype, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));

    SELECT
        PC.ProcessType AS processtype,
        PC.PRPeriod AS prperiod,
        SUBSTRING(PC.PRPeriod, 1, 4) + '-'
            + SUBSTRING(PC.PRPeriod, 5, 2) + '-'
            + SUBSTRING(PC.PRPeriod, 7, 2) AS description,
        PC.Company AS company,
        LTRIM(RTRIM(ISNULL(PC.Status, ''))) AS status
    FROM PR_ProcessControl PC (NOLOCK)
    WHERE PC.Status IN ('A', 'C', 'G')
      AND PC.Company = @cia
      AND PC.ProcessType = @processtype
      AND (@payrolltype = '' OR PC.PayRollType = @payrolltype)
    ORDER BY
        CASE LTRIM(RTRIM(ISNULL(PC.Status, '')))
            WHEN 'A' THEN 0
            WHEN 'G' THEN 0
            ELSE 1
        END,
        PC.PRPeriod DESC;
END
GO



-- ============================================================================
-- [218/282] sp_pr_selectorperiodos_apertura_web.sql
-- ============================================================================

/*
    Periodos configurados para apertura (PR_Period).
    Usado por: GET /api/aperturar-periodos/periodos
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorperiodos_apertura_web]
    @cia         VARCHAR(20),
    @payrolltype VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));

    SELECT
        LTRIM(RTRIM(p.PRPeriod)) AS prperiod,
        CASE
            WHEN LEN(LTRIM(RTRIM(p.PRPeriod))) >= 8
                THEN STUFF(STUFF(LTRIM(RTRIM(p.PRPeriod)), 5, 0, '-'), 8, 0, '-')
            WHEN LEN(LTRIM(RTRIM(p.PRPeriod))) >= 6
                THEN STUFF(LTRIM(RTRIM(p.PRPeriod)), 5, 0, '-')
            ELSE LTRIM(RTRIM(p.PRPeriod))
        END AS description
    FROM PR_Period p WITH (NOLOCK)
    WHERE p.Company = @cia
      AND p.PayRollType = @payrolltype
    ORDER BY p.PRPeriod DESC;
END
GO



-- ============================================================================
-- [219/282] sp_pr_selectorperiodos_asientos_web.sql
-- ============================================================================

/*
    Selector de periodos contables con vouchers de planilla (Application = PR).
    Usado por: GET /api/asientos/interfaz/periodos
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorperiodos_asientos_web]
    @company VARCHAR(4)
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));

    SELECT DISTINCT
        LTRIM(RTRIM(v.Period)) AS id,
        CASE
            WHEN LEN(LTRIM(RTRIM(v.Period))) = 6
                THEN LEFT(LTRIM(RTRIM(v.Period)), 4) + '-' + RIGHT(LTRIM(RTRIM(v.Period)), 2)
            ELSE LTRIM(RTRIM(v.Period))
        END AS text
    FROM AC_Voucher v (NOLOCK)
    WHERE v.Company = @company
      AND v.Application = 'PR'
      AND NULLIF(LTRIM(RTRIM(ISNULL(v.Period, ''))), '') IS NOT NULL
    ORDER BY id DESC;
END
GO



-- ============================================================================
-- [220/282] sp_pr_selectorperiodos_asig_web.sql
-- ============================================================================

/*
    Selector de periodos para asignación / descansos médicos.
    Usado por: GET /api/selectores/periodos-asig
               registro_descansos_medicos.html

    @payrolltype: código PayRollType, o Description/ShortName de la misma compañía.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorperiodos_asig_web]
    @cia         VARCHAR(4),
    @payrolltype VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));

    SELECT
        p.PayRollType,
        SUBSTRING(p.PRPeriod, 1, 4) + '-'
            + SUBSTRING(p.PRPeriod, 5, 2) + '-'
            + SUBSTRING(p.PRPeriod, 7, 2) AS description,
        p.PRPeriod,
        p.GLPeriod,
        p.Company,
        p.ReplicationUnit,
        p.XLastUser,
        p.XLastDate
    FROM PR_Period p (NOLOCK)
    WHERE p.Company = @cia
      AND (
            p.PayRollType = @payrolltype
         OR p.PayRollType IN (
                SELECT PT.PayRollType
                FROM PR_PayRollType PT (NOLOCK)
                WHERE PT.Company = @cia
                  AND (
                        PT.Description = @payrolltype
                     OR PT.ShortName = @payrolltype
                  )
            )
          )
    ORDER BY p.PRPeriod DESC;
END
GO



-- ============================================================================
-- [221/282] sp_pr_selectorperiodos_cia_web.sql
-- ============================================================================

/*
    Selector de periodos distintos por compañía (PR_ProcessControl).
    Usado por: GET /api/selectores/periodos-cia (reporte planilla por conceptos).

    id: period (PRPERIOD, YYYYMMDD)
    text: periodo (YYYY-MM-DD)
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorperiodos_cia_web]
    @cia VARCHAR(4)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));

    SELECT DISTINCT
        PC.PRPeriod AS period,
        SUBSTRING(PC.PRPeriod, 1, 4) + '-'
            + SUBSTRING(PC.PRPeriod, 5, 2) + '-'
            + SUBSTRING(PC.PRPeriod, 7, 2) AS periodo
    FROM PR_ProcessControl PC (NOLOCK)
    WHERE PC.Status IN ('A', 'C', 'G')
      AND PC.Company = @cia
      AND LEN(LTRIM(RTRIM(ISNULL(PC.PRPeriod, '')))) = 8
    ORDER BY PC.PRPeriod DESC;
