-- ============================================================================
-- [222/282] sp_pr_selectorperiodos_consolidada_web.sql
-- ============================================================================

/*
    Periodos distintos para planilla + proceso (por Description) en todas las compañías.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorperiodos_consolidada_web]
    @payroll_desc VARCHAR(200),
    @proceso_desc  VARCHAR(200)
AS
BEGIN
    SET NOCOUNT ON;

    SET @payroll_desc = LTRIM(RTRIM(ISNULL(@payroll_desc, '')));
    SET @proceso_desc = LTRIM(RTRIM(ISNULL(@proceso_desc, '')));

    SELECT DISTINCT
        PC.PRPeriod AS period,
        SUBSTRING(PC.PRPeriod, 1, 4) + '-'
            + SUBSTRING(PC.PRPeriod, 5, 2) + '-'
            + SUBSTRING(PC.PRPeriod, 7, 2) AS periodo
    FROM PR_ProcessControl PC (NOLOCK)
        INNER JOIN PR_PayRollType PRT (NOLOCK)
            ON PRT.Company = PC.Company
           AND PRT.PayRollType = PC.PayRollType
        INNER JOIN PR_ProcessType PT (NOLOCK)
            ON PT.Company = PC.Company
           AND PT.ProcessType = PC.ProcessType
        INNER JOIN SY_Company SC (NOLOCK)
            ON SC.Company = PC.Company
           AND SC.status = 'A'
    WHERE PC.Status IN ('A', 'C', 'G')
      AND LTRIM(RTRIM(PRT.Description)) = @payroll_desc
      AND LTRIM(RTRIM(PT.Description)) = @proceso_desc
    ORDER BY PC.PRPeriod DESC;
END
GO



-- ============================================================================
-- [223/282] sp_pr_selectorperiodos_generar_voucher_web.sql
-- ============================================================================

/*
    Periodos de planilla para Generar Voucher (agrupados por mes).
    id   = PRPeriod (YYYYMMDD) representativo del mes
    text = YYYY-MM
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorperiodos_generar_voucher_web]
    @cia         VARCHAR(4),
    @payrolltype VARCHAR(20),
    @processtype VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    SET @processtype = LTRIM(RTRIM(ISNULL(@processtype, '')));

    ;WITH base AS (
        SELECT
            PC.PRPeriod AS period,
            LEFT(LTRIM(RTRIM(PC.PRPeriod)), 6) AS yyyymm,
            ROW_NUMBER() OVER (
                PARTITION BY LEFT(LTRIM(RTRIM(PC.PRPeriod)), 6)
                ORDER BY PC.PRPeriod DESC
            ) AS rn
        FROM PR_ProcessControl PC (NOLOCK)
        WHERE PC.Company = @cia
          AND PC.PayRollType = @payrolltype
          AND PC.ProcessType = @processtype
          AND PC.Status IN ('A', 'C', 'G')
          AND LEN(LTRIM(RTRIM(ISNULL(PC.PRPeriod, '')))) >= 6
    )
    SELECT
        period AS id,
        LEFT(yyyymm, 4) + '-' + RIGHT(yyyymm, 2) AS text
    FROM base
    WHERE rn = 1
    ORDER BY yyyymm DESC;
END
GO



-- ============================================================================
-- [224/282] sp_pr_selectorperiodos_plame_web.sql
-- ============================================================================

/*
    Periodos tributarios PLAME por compañía (YYYY-MM).
    Usado por: GET /api/selectores/periodos-plame (plame_archivo14.html y otros).

    id (prperiod): YYYYMM — se envía al listado/generación PLAME.
    text (description): YYYY-MM — etiqueta en el selector.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_selectorperiodos_plame_web]
    @cia VARCHAR(10)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT DISTINCT
        SUBSTRING(pr_period.prperiod, 1, 4) + '-' + SUBSTRING(pr_period.prperiod, 5, 2) AS description,
        SUBSTRING(pr_period.prperiod, 1, 4) + SUBSTRING(pr_period.prperiod, 5, 2) AS prperiod,
        pr_period.company AS company
    FROM PR_Period pr_period (NOLOCK)
    WHERE SUBSTRING(pr_period.prperiod, 1, 4) <= CONVERT(VARCHAR(4), DATEADD(YEAR, 1, GETDATE()), 112)
      AND pr_period.company = @cia
    ORDER BY description DESC;
END
GO



