-- ============================================================================
-- [245/282] sp_pr_trabajadores_sin_regimen_pension_afp_web.sql
-- ============================================================================

/*
    Trabajadores de la planilla del periodo sin régimen de pensión (ONP/AFP).
    Usado por validaciones del reporte Declaración AFP / AFPnet.

    Sin régimen: PensionType vacío o PR_PensionType.PDT = '99' (sin régimen pensionario).
    Alcance: trabajadores con conceptos de planilla en el periodo (@period YYYYMM).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_trabajadores_sin_regimen_pension_afp_web]
    @cia         VARCHAR(10),
    @period      VARCHAR(20),
    @payroll_all CHAR(1)     = 'Y',
    @payroll     VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @period = LEFT(LTRIM(RTRIM(ISNULL(@period, ''))), 6);
    SET @payroll_all = UPPER(LTRIM(RTRIM(ISNULL(@payroll_all, 'Y'))));
    SET @payroll = LTRIM(RTRIM(ISNULL(@payroll, '')));

    IF @payroll_all NOT IN ('Y', 'N') SET @payroll_all = 'Y';

    SELECT DISTINCT
        LTRIM(RTRIM(E.person)) AS person,
        LTRIM(RTRIM(ISNULL(P.documentnumber, ''))) AS documentnumber,
        LTRIM(RTRIM(
            ISNULL(P.lastname1, '') + ' ' +
            ISNULL(P.lastname2, '') + ' ' +
            ISNULL(P.name1, '') + ' ' +
            ISNULL(P.name2, '')
        )) AS nombre,
        LTRIM(RTRIM(ISNULL(E.pensiontype, ''))) AS pensiontype,
        LTRIM(RTRIM(ISNULL(PT.description, ''))) AS pensiontype_desc,
        LTRIM(RTRIM(ISNULL(PT.pdt, ''))) AS pension_pdt
    FROM PR_Employee E (NOLOCK)
        INNER JOIN SY_Person P (NOLOCK)
            ON P.person = E.person
        LEFT JOIN PR_PensionType PT (NOLOCK)
            ON PT.PensionType = E.PensionType
           AND (
                LTRIM(RTRIM(ISNULL(PT.Company, ''))) = ''
                OR LTRIM(RTRIM(PT.Company)) = E.Company
           )
    WHERE E.Company = @cia
      AND EXISTS (
            SELECT 1
            FROM PR_EmployeePayRollConcept EPC (NOLOCK)
            WHERE EPC.Company = @cia
              AND EPC.Person = E.person
              AND LEFT(EPC.PRPeriod, 6) = @period
              AND (@payroll_all = 'Y' OR EPC.PayRollType = @payroll)
      )
      AND (
            LTRIM(RTRIM(ISNULL(E.PensionType, ''))) = ''
            OR LTRIM(RTRIM(ISNULL(PT.PDT, ''))) = '99'
      )
    ORDER BY nombre, person;
END
GO



-- ============================================================================
-- [246/282] sp_pr_tregistro_actualizar_campos_nuevos_web.sql
-- ============================================================================

/*

    Actualiza solo campos post T-Registro que no vienen del ZIP:

      Position, CostCenter (+CostCenterName), AccountProfile,

      FlagAsigFamiliar, FlagMixta.



    Usado por: POST /api/tregistro-importacion/campos-nuevos/guardar

*/

CREATE OR ALTER PROCEDURE [dbo].[sp_pr_tregistro_actualizar_campos_nuevos_web]

    @cia              VARCHAR(10),

    @person           VARCHAR(20),

    @position         VARCHAR(20) = NULL,

    @costcenter       VARCHAR(20) = NULL,

    @accountprofile   VARCHAR(20) = NULL,

    @flagasigfamiliar VARCHAR(1) = 'N',

    @flagmixta        VARCHAR(1) = 'N',

    @xlastuser        VARCHAR(20) = NULL

AS

BEGIN

    SET NOCOUNT ON;



    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));

    SET @person = LTRIM(RTRIM(ISNULL(@person, '')));



    IF @cia = '' OR @person = ''

    BEGIN

        RAISERROR('Debe indicar compania y trabajador.', 16, 1);

        RETURN;

    END;



    IF NOT EXISTS (

        SELECT 1

        FROM PR_Employee (NOLOCK)

        WHERE Company = @cia

          AND Person = @person

    )

    BEGIN

        RAISERROR('Trabajador no encontrado para la compania indicada.', 16, 1);

        RETURN;

    END;



    IF RTRIM(ISNULL(@flagasigfamiliar, '')) NOT IN ('Y', 'N') SET @flagasigfamiliar = 'N';

    IF RTRIM(ISNULL(@flagmixta, '')) NOT IN ('Y', 'N') SET @flagmixta = 'N';



    DECLARE @costcentername VARCHAR(100) = NULL;

    IF NULLIF(LTRIM(RTRIM(ISNULL(@costcenter, ''))), '') IS NOT NULL

    BEGIN

        SELECT TOP 1 @costcentername = LTRIM(RTRIM(ISNULL(cc.Name, '')))

        FROM AC_CostCenter cc (NOLOCK)

        WHERE cc.Company = @cia

          AND cc.CostCenter = LTRIM(RTRIM(@costcenter));

    END;



    UPDATE PR_Employee

    SET

        Position = NULLIF(LTRIM(RTRIM(@position)), ''),

        CostCenter = NULLIF(LTRIM(RTRIM(@costcenter)), ''),

        CostCenterName = CASE

            WHEN NULLIF(LTRIM(RTRIM(@costcenter)), '') IS NULL THEN NULL

            ELSE NULLIF(@costcentername, '')

        END,

        AccountProfile = NULLIF(LTRIM(RTRIM(@accountprofile)), ''),

        FlagAsigFamiliar = @flagasigfamiliar,

        FlagMixta = @flagmixta,

        xlastdate = GETDATE(),

        xlastuser = NULLIF(LTRIM(RTRIM(@xlastuser)), '')

    WHERE Company = @cia

      AND Person = @person;



    SELECT

        CAST(1 AS INT) AS ok,

        @cia AS cia,

        @person AS person,

        'Campos actualizados correctamente.' AS mensaje;

END

GO



-- ============================================================================
-- [247/282] sp_pr_tregistro_cuentas_web.sql
-- ============================================================================

/*
    T-REGISTRO Estructura 30 — Cuentas de abono de remuneraciones (TXT RP_RUC.cta).

    Usado por: POST /api/plame/t-registro/generar-txt (archivo 30)

    @personas — lista separada por comas de códigos SY_Person.Person
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_tregistro_cuentas_web]
    @cia       VARCHAR(10),
    @personas  VARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @personas = LTRIM(RTRIM(ISNULL(@personas, '')));

    IF @cia = '' OR @personas = ''
        RETURN;

    CREATE TABLE #Personas (
        person VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL PRIMARY KEY
    );

    INSERT INTO #Personas (person)
    SELECT DISTINCT LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)')))
    FROM (
        SELECT CAST('<x>' + REPLACE(@personas, ',', '</x><x>') + '</x>' AS XML) AS x
    ) t
    CROSS APPLY x.nodes('/x') Split(a)
    WHERE LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)'))) <> '';

    SELECT
        LTRIM(RTRIM(ISNULL(p.Person, ''))) AS person,
        LTRIM(RTRIM(ISNULL(pdt.Pdt, ''))) AS documenttype,
        LTRIM(RTRIM(ISNULL(p.DocumentNumber, ''))) AS documentnumber,
        LTRIM(RTRIM(ISNULL(cid.Pdt, ''))) AS docissuingcountry,
        LTRIM(RTRIM(ISNULL(
            (SELECT CASE
                WHEN LEN(LTRIM(RTRIM(ISNULL(b.PDT, '')))) = 2
                    THEN '0' + LTRIM(RTRIM(b.PDT))
                ELSE LTRIM(RTRIM(ISNULL(b.PDT, '')))
             END
             FROM erp_bank b (NOLOCK)
             WHERE b.bank = e.SalaryBank),
            ''
        ))) AS salarybank,
        LTRIM(RTRIM(ISNULL(e.SalaryAccount, ''))) AS salaryaccount,
        LTRIM(RTRIM(ISNULL(ec.PDT, ''))) AS employeecategory
    FROM PR_Employee e (NOLOCK)
        INNER JOIN #Personas sel ON sel.person = e.Person
        INNER JOIN SY_Person p (NOLOCK) ON p.Person = e.Person
        LEFT JOIN SY_PersonDocumentType pdt (NOLOCK)
            ON p.EmployeeDocumentType = pdt.PersonDocumentType
        LEFT JOIN PR_EmployeeCategory ec (NOLOCK)
            ON e.EmployeeCategory = ec.EmployeeCategory
        LEFT JOIN PR_CountryIssuingDocument cid (NOLOCK)
            ON p.CountryIssuing = cid.CountryIssuing
    WHERE e.Company = @cia
      AND ISNULL(ec.PDT, '') <> '3'
    ORDER BY documentnumber;
END
GO



-- ============================================================================
-- [248/282] sp_pr_tregistro_datos_personales_web.sql
-- ============================================================================

/*
    T-REGISTRO Estructura 04 — Datos personales (generación TXT RP_RUC.ide).

    Usado por: POST /api/plame/t-registro/generar-txt (archivo 04)

    @personas — lista separada por comas de códigos SY_Person.Person
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_tregistro_datos_personales_web]
    @cia       VARCHAR(10),
    @personas  VARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @personas = LTRIM(RTRIM(ISNULL(@personas, '')));

    IF @cia = '' OR @personas = ''
        RETURN;

    CREATE TABLE #Personas (
        person VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL PRIMARY KEY
    );

    INSERT INTO #Personas (person)
    SELECT DISTINCT LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)')))
    FROM (
        SELECT CAST('<x>' + REPLACE(@personas, ',', '</x><x>') + '</x>' AS XML) AS x
    ) t
    CROSS APPLY x.nodes('/x') Split(a)
    WHERE LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)'))) <> '';

    SELECT
        LTRIM(RTRIM(ISNULL(PDT_DOC.Pdt, ''))) AS documenttype,
        LTRIM(RTRIM(ISNULL(P.DocumentNumber, ''))) AS documentnumber,
        LTRIM(RTRIM(ISNULL(CID.Pdt, ''))) AS docissuingcountry,
        P.BirthDate AS birthdate,
        LTRIM(RTRIM(ISNULL(P.LastName1, ''))) AS lastname1,
        LTRIM(RTRIM(ISNULL(P.LastName2, ''))) AS lastname2,
        LTRIM(RTRIM(
            ISNULL(P.Name1, '') +
            CASE WHEN ISNULL(P.Name2, '') = '' THEN '' ELSE ' ' + P.Name2 END
        )) AS employeename,
        LTRIM(RTRIM(ISNULL(CAST(P.Sex AS VARCHAR(10)), ''))) AS sex,
        LTRIM(RTRIM(ISNULL(NAC.Nro, ''))) AS nationality,
        LTRIM(RTRIM(ISNULL(P.CodeLDN, ''))) AS codeldn,
        LTRIM(RTRIM(ISNULL(P.SecTelephone, ''))) AS telephone,
        LTRIM(RTRIM(ISNULL(P.Email, ''))) AS email,
        LTRIM(RTRIM(ISNULL(ST1.Pdt, ''))) AS streettype,
        LTRIM(RTRIM(ISNULL(P.StreetName, ''))) AS streetname,
        LTRIM(RTRIM(ISNULL(P.AddressNumber, ''))) AS addressnumber,
        LTRIM(RTRIM(ISNULL(P.Room, ''))) AS room,
        LTRIM(RTRIM(ISNULL(P.Inside, ''))) AS inside,
        LTRIM(RTRIM(ISNULL(P.Apple, ''))) AS apple,
        LTRIM(RTRIM(ISNULL(P.Lot, ''))) AS lot,
        LTRIM(RTRIM(ISNULL(P.Kilometer, ''))) AS kilometer,
        LTRIM(RTRIM(ISNULL(P.Block, ''))) AS block,
        LTRIM(RTRIM(ISNULL(P.Stage, ''))) AS stage,
        LTRIM(RTRIM(ISNULL(Z1.Pdt, ''))) AS zone,
        LTRIM(RTRIM(ISNULL(P.ZoneName, ''))) AS zonename,
        LTRIM(RTRIM(ISNULL(P.Reference, ''))) AS reference,
        LTRIM(RTRIM(ISNULL(LOC1.Pdt, ''))) AS localite,
        LTRIM(RTRIM(ISNULL(ST2.Pdt, ''))) AS streettype2,
        LTRIM(RTRIM(ISNULL(P.StreetName2, ''))) AS streetname2,
        LTRIM(RTRIM(ISNULL(P.AddressNumber2, ''))) AS addressnumber2,
        LTRIM(RTRIM(ISNULL(P.Room2, ''))) AS room2,
        LTRIM(RTRIM(ISNULL(P.Inside2, ''))) AS inside2,
        LTRIM(RTRIM(ISNULL(P.Apple2, ''))) AS apple2,
        LTRIM(RTRIM(ISNULL(P.Lot2, ''))) AS lot2,
        LTRIM(RTRIM(ISNULL(P.Kilometer2, ''))) AS kilometer2,
        LTRIM(RTRIM(ISNULL(P.Block2, ''))) AS block2,
        LTRIM(RTRIM(ISNULL(P.Stage2, ''))) AS stage2,
        LTRIM(RTRIM(ISNULL(Z2.Pdt, ''))) AS zone2,
        LTRIM(RTRIM(ISNULL(P.ZoneName2, ''))) AS zonename2,
        LTRIM(RTRIM(ISNULL(P.Reference2, ''))) AS reference2,
        LTRIM(RTRIM(ISNULL(LOC2.Pdt, ''))) AS localite2,
        '1' AS indicator,
        LTRIM(RTRIM(ISNULL(P.Person, ''))) AS person
    FROM PR_Employee E (NOLOCK)
        INNER JOIN #Personas SEL ON SEL.person = E.Person
        INNER JOIN SY_Person P (NOLOCK) ON P.Person = E.Person
        LEFT JOIN SY_PersonDocumentType PDT_DOC (NOLOCK)
            ON P.EmployeeDocumentType = PDT_DOC.PersonDocumentType
        LEFT JOIN PR_Nacionalidad NAC (NOLOCK)
            ON P.Nationality = NAC.Nacionalidad
        LEFT JOIN SY_StreetType ST1 (NOLOCK)
            ON P.StreetType = ST1.StreetType
        LEFT JOIN SY_Zone Z1 (NOLOCK)
            ON P.Zone = Z1.Zone
        LEFT JOIN SY_Localite LOC1 (NOLOCK)
            ON P.Localite = LOC1.Localite
        LEFT JOIN SY_StreetType ST2 (NOLOCK)
            ON P.StreetType2 = ST2.StreetType
        LEFT JOIN SY_Zone Z2 (NOLOCK)
            ON P.Zone2 = Z2.Zone
        LEFT JOIN SY_Localite LOC2 (NOLOCK)
            ON P.Localite2 = LOC2.Localite
        LEFT JOIN PR_EmployeeCategory EC (NOLOCK)
            ON E.EmployeeCategory = EC.EmployeeCategory
        LEFT JOIN PR_CountryIssuingDocument CID (NOLOCK)
            ON P.CountryIssuing = CID.CountryIssuing
    WHERE E.Company = @cia
      AND ISNULL(EC.PDT, '') <> '3'
    ORDER BY employeename, documentnumber;
END
GO



-- ============================================================================
-- [249/282] sp_pr_tregistro_establecimiento_web.sql
-- ============================================================================

/*
    T-REGISTRO Estructura 17 — Establecimientos donde labora el trabajador (TXT RP_RUC.est).

    Usado por: POST /api/plame/t-registro/generar-txt (archivo 17)

    @personas     — lista separada por comas de códigos SY_Person.Person
    @fecha_desde  — YYYYMMDD (filtro de período, se usa YYYYMM)
    @fecha_hasta  — YYYYMMDD (filtro de período, se usa YYYYMM)
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_tregistro_establecimiento_web]
    @cia          VARCHAR(10),
    @personas     VARCHAR(MAX),
    @fecha_desde  VARCHAR(20),
    @fecha_hasta  VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @personas = LTRIM(RTRIM(ISNULL(@personas, '')));
    SET @fecha_desde = LTRIM(RTRIM(ISNULL(@fecha_desde, '')));
    SET @fecha_hasta = LTRIM(RTRIM(ISNULL(@fecha_hasta, '')));

    IF @cia = '' OR @personas = ''
        RETURN;

    DECLARE @pd CHAR(6);
    DECLARE @ph CHAR(6);

    IF LEN(@fecha_desde) >= 6
        SET @pd = LEFT(@fecha_desde, 6);
    IF LEN(@fecha_hasta) >= 6
        SET @ph = LEFT(@fecha_hasta, 6);
    IF @pd IS NULL OR @ph IS NULL
        RETURN;

    CREATE TABLE #Personas (
        person VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL PRIMARY KEY
    );

    INSERT INTO #Personas (person)
    SELECT DISTINCT LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)')))
    FROM (
        SELECT CAST('<x>' + REPLACE(@personas, ',', '</x><x>') + '</x>' AS XML) AS x
    ) t
    CROSS APPLY x.nodes('/x') Split(a)
    WHERE LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)'))) <> '';

    SELECT
        LTRIM(RTRIM(ISNULL(el.Employee, ''))) AS person,
        LTRIM(RTRIM(ISNULL(pdt.pdt, ''))) AS documenttype,
        LTRIM(RTRIM(ISNULL(p.DocumentNumber, ''))) AS documentnumber,
        LTRIM(RTRIM(ISNULL(cid.Pdt, ''))) AS docissuingcountry,
        LTRIM(RTRIM(COALESCE(
            NULLIF(LTRIM(RTRIM(po.Ruc)), ''),
            NULLIF(LTRIM(RTRIM(cl.RUC)), ''),
            NULLIF(LTRIM(RTRIM(c.RUC)), ''),
            NULLIF(LTRIM(RTRIM(c.Ruc)), '')
        ))) AS ruc,
        LTRIM(RTRIM(COALESCE(
            NULLIF(LTRIM(RTRIM(po.LocalCode)), ''),
            NULLIF(LTRIM(RTRIM(cl.NROLOCALTYPE)), ''),
            '0000'
        ))) AS localcode
    FROM PR_EmployeeLocal el (NOLOCK)
        INNER JOIN #Personas sel ON sel.person = el.Employee
        INNER JOIN PR_Employee e (NOLOCK)
            ON e.Person = el.Employee AND e.Company = el.Company
        INNER JOIN pr_employeecategory ec (NOLOCK)
            ON e.employeecategory = ec.employeecategory
        INNER JOIN SY_Person p (NOLOCK)
            ON p.Person = el.Employee
        LEFT JOIN sy_persondocumenttype pdt (NOLOCK)
            ON p.employeedocumenttype = pdt.persondocumenttype
        LEFT JOIN PR_CountryIssuingDocument cid (NOLOCK)
            ON p.CountryIssuing = cid.CountryIssuing
        LEFT JOIN SY_PersonOffice po (NOLOCK)
            ON po.PersonOffice = el.PersonOffice
        LEFT JOIN PR_COMPANYLOCAL cl (NOLOCK)
            ON cl.COMPANYLOCAL = po.LocalType AND cl.COMPANY = el.Company
        LEFT JOIN SY_Company c (NOLOCK)
            ON c.Company = el.Company
    WHERE el.Company = @cia
      AND ec.PDT = '1'
      AND LEN(LTRIM(RTRIM(ISNULL(el.startperiod, '')))) >= 6
      AND LEFT(el.startperiod, 6) <= @ph
      AND (
            el.endperiod IS NULL
            OR LTRIM(RTRIM(el.endperiod)) = ''
            OR LEN(LTRIM(RTRIM(el.endperiod))) < 6
            OR LEFT(el.endperiod, 6) >= @pd
          )
    ORDER BY documentnumber, localcode, ruc;
END
GO



-- ============================================================================
-- [250/282] sp_pr_tregistro_estudios_web.sql
-- ============================================================================

/*
    T-REGISTRO Estructura 29 — Estudios concluidos (generación TXT RP_RUC.edu).

    Usado por: POST /api/plame/t-registro/generar-txt (archivo 29)

    @personas — lista separada por comas de códigos SY_Person.Person
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_tregistro_estudios_web]
    @cia       VARCHAR(10),
    @personas  VARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @personas = LTRIM(RTRIM(ISNULL(@personas, '')));

    IF @cia = '' OR @personas = ''
        RETURN;

    CREATE TABLE #Personas (
        person VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL PRIMARY KEY
    );

    INSERT INTO #Personas (person)
    SELECT DISTINCT LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)')))
    FROM (
        SELECT CAST('<x>' + REPLACE(@personas, ',', '</x><x>') + '</x>' AS XML) AS x
    ) t
    CROSS APPLY x.nodes('/x') Split(a)
    WHERE LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)'))) <> '';

    SELECT DISTINCT
        LTRIM(RTRIM(ISNULL(p.Person, ''))) AS person,
        LTRIM(RTRIM(ISNULL(pdt.pdt, ''))) AS documenttype,
        LTRIM(RTRIM(ISNULL(p.DocumentNumber, ''))) AS documentnumber,
        LTRIM(RTRIM(ISNULL(cid.Pdt, ''))) AS docissuingcountry,
        CASE
            WHEN il.pdt = '13' OR il.pdt = '11' THEN il.pdt
            WHEN il.pdt >= '14' AND il.pdt <= '21' THEN '13'
            ELSE ''
        END AS instructionlevel,
        LTRIM(RTRIM(ISNULL(il.pdt, ''))) AS nivelinstruccion,
        LTRIM(RTRIM(ISNULL(CAST(p.IsTrainer AS VARCHAR(10)), ''))) AS istrainer,
        LTRIM(RTRIM(ISNULL(p.CostCenter1, ''))) AS costcenter1,
        LTRIM(RTRIM(ISNULL(p.CostCenter2, ''))) AS costcenter2,
        LTRIM(RTRIM(ISNULL(CAST(p.DriverLicenseAntiquity AS VARCHAR(20)), ''))) AS driverlicenseantiquity
    FROM pr_employee e (NOLOCK)
        INNER JOIN #Personas sel ON sel.person = e.Person
        INNER JOIN sy_person p (NOLOCK) ON p.Person = e.Person
        LEFT JOIN sy_persondocumenttype pdt (NOLOCK)
            ON p.employeedocumenttype = pdt.persondocumenttype
        LEFT JOIN pr_instructionlevel il (NOLOCK)
            ON p.instructionlevel = il.instructionlevel
        LEFT JOIN pr_employeecategory ec (NOLOCK)
            ON e.employeecategory = ec.employeecategory
        LEFT JOIN PR_CountryIssuingDocument cid (NOLOCK)
            ON p.CountryIssuing = cid.CountryIssuing
    WHERE e.Company = @cia
      AND ISNULL(ec.PDT, '') <> '3'
    ORDER BY documentnumber;
END
GO



-- ============================================================================
-- [251/282] sp_pr_tregistro_periodos_web.sql
-- ============================================================================

/*
    T-REGISTRO Estructura 11 — Datos de períodos (generación TXT RP_RUC.per).

    Usado por: POST /api/plame/t-registro/generar-txt (archivo 11)

    @personas — lista separada por comas de códigos SY_Person.Person
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_tregistro_periodos_web]
    @cia       VARCHAR(10),
    @personas  VARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @personas = LTRIM(RTRIM(ISNULL(@personas, '')));

    IF @cia = '' OR @personas = ''
        RETURN;

    CREATE TABLE #Personas (
        person VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL PRIMARY KEY
    );

    INSERT INTO #Personas (person)
    SELECT DISTINCT LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)')))
    FROM (
        SELECT CAST('<x>' + REPLACE(@personas, ',', '</x><x>') + '</x>' AS XML) AS x
    ) t
    CROSS APPLY x.nodes('/x') Split(a)
    WHERE LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)'))) <> '';

    SELECT DISTINCT
        LTRIM(RTRIM(
            ISNULL(sy_person.LastName1, '') + ' ' +
            ISNULL(sy_person.LastName2, '') + ' ' +
            ISNULL(sy_person.Name1, '') + ' ' +
            ISNULL(sy_person.Name2, '')
        )) AS name,
        LTRIM(RTRIM(ISNULL(sy_persondocumenttype.pdt, ''))) AS documenttype,
        LTRIM(RTRIM(ISNULL(sy_person.DocumentNumber, ''))) AS documentnumber,
        LTRIM(RTRIM(ISNULL(PR_CountryIssuingDocument.Pdt, ''))) AS countryissuingdocument,
        LTRIM(RTRIM(ISNULL(pr_employeecategory.PDT, ''))) AS employeecategory,
        CASE
            WHEN ISNULL(pr_employee.ReEntryDate, '') = '' THEN pr_employee.EntryDate
            ELSE pr_employee.ReEntryDate
        END AS entrydate,
        pr_employee.CeaseDate AS ceasedate,
        LTRIM(RTRIM(ISNULL(pr_ceasereason.pdt, ''))) AS ceasereason,
        (SELECT TOP 1 PeriodsIndicators.StartDate
           FROM PeriodsIndicators (NOLOCK)
          WHERE PeriodsIndicators.RecordType = '2'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS startdate2,
        (SELECT TOP 1 PeriodsIndicators.EndDate
           FROM PeriodsIndicators (NOLOCK)
          WHERE PeriodsIndicators.RecordType = '2'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS enddate2,
        (SELECT TOP 1 pr_employeetype.PDT
           FROM PeriodsIndicators (NOLOCK)
                LEFT JOIN pr_employeetype (NOLOCK)
                    ON PeriodsIndicators.Indicator = pr_employeetype.employeetype
          WHERE PeriodsIndicators.RecordType = '2'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS indicator2,
        (SELECT TOP 1 PeriodsIndicators.StartDate
           FROM PeriodsIndicators (NOLOCK)
          WHERE PeriodsIndicators.RecordType = '3'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS startdate3,
        (SELECT TOP 1 PeriodsIndicators.EndDate
           FROM PeriodsIndicators (NOLOCK)
          WHERE PeriodsIndicators.RecordType = '3'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS enddate3,
        (SELECT TOP 1 PR_REGIMEHEALTH.Pdt
           FROM PeriodsIndicators (NOLOCK)
                LEFT JOIN PR_REGIMEHEALTH (NOLOCK)
                    ON PeriodsIndicators.Indicator = PR_REGIMEHEALTH.RegimeHealth
          WHERE PeriodsIndicators.RecordType = '3'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS indicator3,
        (SELECT TOP 1 PeriodsIndicators.StartDate
           FROM PeriodsIndicators (NOLOCK)
          WHERE PeriodsIndicators.RecordType = '4'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS startdate4,
        (SELECT TOP 1 PeriodsIndicators.EndDate
           FROM PeriodsIndicators (NOLOCK)
          WHERE PeriodsIndicators.RecordType = '4'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS enddate4,
        CASE
            WHEN (
                SELECT TOP 1 b.Pdt
                  FROM pr_employee a (NOLOCK)
                       INNER JOIN PR_PENSIONTYPE b (NOLOCK)
                           ON a.PensionType = b.PensionType
                          AND a.Company = b.Company
                 WHERE b.Company = @cia
                   AND a.Person = pr_employee.Person
            ) = '02' THEN '02'
            ELSE (
                SELECT TOP 1 b.Pdt
                  FROM pr_employee a (NOLOCK)
                       INNER JOIN PR_PENSIONTYPE b (NOLOCK)
                           ON a.PensionType = b.PensionType
                          AND a.Company = b.Company
                 WHERE b.Company = @cia
                   AND a.Person = pr_employee.Person
            )
        END AS indicator4,
        (SELECT TOP 1 PeriodsIndicators.StartDate
           FROM PeriodsIndicators (NOLOCK)
          WHERE PeriodsIndicators.RecordType = '5'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS startdate5,
        (SELECT TOP 1 PeriodsIndicators.EndDate
           FROM PeriodsIndicators (NOLOCK)
          WHERE PeriodsIndicators.RecordType = '5'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS enddate5,
        (SELECT TOP 1 PR_SCTR.PDT
           FROM PeriodsIndicators (NOLOCK), PR_SCTR (NOLOCK)
          WHERE PeriodsIndicators.Indicator = PR_SCTR.SCTR
            AND PR_SCTR.SCTRType = 'H'
            AND PeriodsIndicators.RecordType = '5'
            AND PeriodsIndicators.Status = 'A'
            AND PeriodsIndicators.Company = pr_employee.Company
            AND PeriodsIndicators.Person = pr_employee.Person) AS indicator5,
        LTRIM(RTRIM(ISNULL(PR_REGIMEHEALTH.Pdt, ''))) AS regimehealth,
        LTRIM(RTRIM(ISNULL(pr_healthentity.pdt, ''))) AS healthentity,
        LTRIM(RTRIM(ISNULL(sy_person.Person, ''))) AS person
    FROM pr_employee (NOLOCK)
        INNER JOIN #Personas SEL ON SEL.person = pr_employee.person
        INNER JOIN sy_person (NOLOCK)
            ON sy_person.person = pr_employee.person
        LEFT JOIN sy_persondocumenttype (NOLOCK)
            ON sy_person.employeedocumenttype = sy_persondocumenttype.persondocumenttype
        LEFT JOIN pr_healthentity (NOLOCK)
            ON pr_employee.ownserviceruc = pr_healthentity.healthentity
        LEFT JOIN pr_employeecategory (NOLOCK)
            ON pr_employee.employeecategory = pr_employeecategory.employeecategory
        LEFT JOIN PR_CountryIssuingDocument (NOLOCK)
            ON SY_Person.CountryIssuing = PR_CountryIssuingDocument.CountryIssuing
        LEFT JOIN pr_ceasereason (NOLOCK)
            ON PR_Employee.CeaseReason = pr_ceasereason.CeaseReason
        LEFT JOIN PR_REGIMEHEALTH (NOLOCK)
            ON pr_employee.regimehealth = PR_REGIMEHEALTH.RegimeHealth
    WHERE pr_employee.company = @cia
    ORDER BY name ASC;
END
GO



-- ============================================================================
-- [252/282] sp_pr_tregistro_registrar_nuevos_web.sql
-- ============================================================================

/*
    Registra en lote trabajadores NUEVOS del T-Registro.
    Recibe JSON (array de objetos) y delega en sp_pr_tregistro_registrar_trabajador_nuevo_web.

    NOTA: requiere SQL Server 2016+ (OPENJSON). En servidores anteriores la API web
    invoca sp_pr_tregistro_registrar_trabajador_nuevo_web en bucle desde Python.

    Usado por: POST /api/tregistro-importacion/registrar (fallback opcional)
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_tregistro_registrar_nuevos_web]
    @cia            VARCHAR(10),
    @trabajadores   NVARCHAR(MAX),
    @replicationunit VARCHAR(20) = 'LIMA',
    @xlastuser      VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @replicationunit = UPPER(LTRIM(RTRIM(ISNULL(@replicationunit, 'LIMA'))));
    SET @xlastuser = NULLIF(LTRIM(RTRIM(ISNULL(@xlastuser, ''))), '');

    IF @cia = ''
    BEGIN
        RAISERROR('Indique la compañía.', 16, 1);
        RETURN;
    END;

    IF @trabajadores IS NULL OR LTRIM(RTRIM(@trabajadores)) = ''
    BEGIN
        RAISERROR('No se recibieron trabajadores para registrar.', 16, 1);
        RETURN;
    END;

    IF ISJSON(@trabajadores) <> 1
    BEGIN
        RAISERROR('El formato de trabajadores no es JSON válido.', 16, 1);
        RETURN;
    END;

    CREATE TABLE #Resultado (
        num_doc         VARCHAR(15) NULL,
        nombre          VARCHAR(120) NULL,
        estado          VARCHAR(20) NOT NULL,
        person          VARCHAR(20) NULL,
        mensaje         VARCHAR(500) NULL
    );

    DECLARE @num_doc                VARCHAR(15);
    DECLARE @tipo_doc               VARCHAR(50);
    DECLARE @apellido_paterno       VARCHAR(40);
    DECLARE @apellido_materno       VARCHAR(40);
    DECLARE @nombres                VARCHAR(80);
    DECLARE @fecha_nac              VARCHAR(10);
    DECLARE @nacionalidad           VARCHAR(100);
    DECLARE @sexo                   VARCHAR(20);
    DECLARE @telefono               VARCHAR(15);
    DECLARE @email                  VARCHAR(255);
    DECLARE @direccion              VARCHAR(255);
    DECLARE @fecha_ingreso          VARCHAR(10);
    DECLARE @tipo_trabajador        VARCHAR(80);
    DECLARE @regimen_laboral        VARCHAR(80);
    DECLARE @cat_ocupacional        VARCHAR(80);
    DECLARE @ocupacion              VARCHAR(120);
    DECLARE @nivel_educativo        VARCHAR(80);
    DECLARE @formacion_superior_completa VARCHAR(120);
    DECLARE @tipo_inst_educ         VARCHAR(80);
    DECLARE @nombre_inst_educ       VARCHAR(120);
    DECLARE @carrera                VARCHAR(120);
    DECLARE @anio_egreso            VARCHAR(10);
    DECLARE @indicador_educ         VARCHAR(5);
    DECLARE @tipo_contrato          VARCHAR(80);
    DECLARE @tipo_pago              VARCHAR(80);
    DECLARE @entidad_financiera     VARCHAR(120);
    DECLARE @nro_cuenta             VARCHAR(30);
    DECLARE @remun_bas              VARCHAR(20);
    DECLARE @regimen_pension        VARCHAR(80);
    DECLARE @regimen_pension_fec    VARCHAR(10);
    DECLARE @cuspp                  VARCHAR(20);
    DECLARE @regimen_salud          VARCHAR(80);
    DECLARE @regimen_salud_fec      VARCHAR(10);
    DECLARE @situacion_especial     VARCHAR(80);
    DECLARE @sindicalizado          VARCHAR(5);
    DECLARE @nombre_completo        VARCHAR(120);
    DECLARE @person_out             VARCHAR(20);
    DECLARE @mensaje_out            VARCHAR(500);
    DECLARE @err                    VARCHAR(500);

    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            JSON_VALUE(j.value, '$.tipo_doc'),
            JSON_VALUE(j.value, '$.num_doc'),
            JSON_VALUE(j.value, '$.apellido_paterno'),
            JSON_VALUE(j.value, '$.apellido_materno'),
            JSON_VALUE(j.value, '$.nombres'),
            JSON_VALUE(j.value, '$.fecha_nac'),
            JSON_VALUE(j.value, '$.nacionalidad'),
            JSON_VALUE(j.value, '$.sexo'),
            JSON_VALUE(j.value, '$.telefono'),
            JSON_VALUE(j.value, '$.email'),
            JSON_VALUE(j.value, '$.direccion'),
            JSON_VALUE(j.value, '$.fecha_ingreso'),
            JSON_VALUE(j.value, '$.tipo_trabajador'),
            JSON_VALUE(j.value, '$.regimen_laboral'),
            JSON_VALUE(j.value, '$.cat_ocupacional'),
            JSON_VALUE(j.value, '$.ocupacion'),
            JSON_VALUE(j.value, '$.nivel_educativo'),
            JSON_VALUE(j.value, '$.formacion_superior_completa'),
            JSON_VALUE(j.value, '$.tipo_inst_educ'),
            JSON_VALUE(j.value, '$.nombre_inst_educ'),
            JSON_VALUE(j.value, '$.carrera'),
            JSON_VALUE(j.value, '$.anio_egreso'),
            JSON_VALUE(j.value, '$.indicador'),
            JSON_VALUE(j.value, '$.tipo_contrato'),
            JSON_VALUE(j.value, '$.tipo_pago'),
            JSON_VALUE(j.value, '$.entidad_financiera'),
            JSON_VALUE(j.value, '$.nro_cuenta'),
            JSON_VALUE(j.value, '$.remun_bas'),
            JSON_VALUE(j.value, '$.regimen_pension'),
            JSON_VALUE(j.value, '$.regimen_pension_fec'),
            JSON_VALUE(j.value, '$.cuspp'),
            JSON_VALUE(j.value, '$.regimen_salud'),
            JSON_VALUE(j.value, '$.regimen_salud_fec'),
            JSON_VALUE(j.value, '$.situacion_especial'),
            JSON_VALUE(j.value, '$.sindicalizado'),
            JSON_VALUE(j.value, '$.nombre_completo')
        FROM OPENJSON(@trabajadores) j;

    OPEN cur;
    FETCH NEXT FROM cur INTO
        @tipo_doc, @num_doc, @apellido_paterno, @apellido_materno, @nombres,
        @fecha_nac, @nacionalidad, @sexo, @telefono, @email, @direccion,
        @fecha_ingreso, @tipo_trabajador, @regimen_laboral, @cat_ocupacional,
        @ocupacion, @nivel_educativo, @formacion_superior_completa, @tipo_inst_educ,
        @nombre_inst_educ, @carrera, @anio_egreso, @indicador_educ,
        @tipo_contrato, @tipo_pago,
        @entidad_financiera, @nro_cuenta, @remun_bas, @regimen_pension,
        @regimen_pension_fec, @cuspp, @regimen_salud, @regimen_salud_fec,
        @situacion_especial, @sindicalizado, @nombre_completo;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @person_out = NULL;
        SET @mensaje_out = NULL;
        SET @err = NULL;

        BEGIN TRY
            EXEC sp_pr_tregistro_registrar_trabajador_nuevo_web
                @cia = @cia,
                @tipo_doc = @tipo_doc,
                @num_doc = @num_doc,
                @apellido_paterno = @apellido_paterno,
                @apellido_materno = @apellido_materno,
                @nombres = @nombres,
                @fecha_nac = @fecha_nac,
                @nacionalidad = @nacionalidad,
                @sexo = @sexo,
                @telefono = @telefono,
                @email = @email,
                @direccion = @direccion,
                @fecha_ingreso = @fecha_ingreso,
                @tipo_trabajador = @tipo_trabajador,
                @regimen_laboral = @regimen_laboral,
                @cat_ocupacional = @cat_ocupacional,
                @ocupacion = @ocupacion,
                @nivel_educativo = @nivel_educativo,
                @formacion_superior_completa = @formacion_superior_completa,
                @tipo_inst_educ = @tipo_inst_educ,
                @nombre_inst_educ = @nombre_inst_educ,
                @carrera = @carrera,
                @anio_egreso = @anio_egreso,
                @indicador_educ = @indicador_educ,
                @tipo_contrato = @tipo_contrato,
                @tipo_pago = @tipo_pago,
                @entidad_financiera = @entidad_financiera,
                @nro_cuenta = @nro_cuenta,
                @remun_bas = @remun_bas,
                @regimen_pension = @regimen_pension,
                @regimen_pension_fec = @regimen_pension_fec,
                @cuspp = @cuspp,
                @regimen_salud = @regimen_salud,
                @regimen_salud_fec = @regimen_salud_fec,
                @situacion_especial = @situacion_especial,
                @sindicalizado = @sindicalizado,
                @replicationunit = @replicationunit,
                @xlastuser = @xlastuser,
                @person_out = @person_out OUTPUT,
                @mensaje_out = @mensaje_out OUTPUT;

            INSERT INTO #Resultado (num_doc, nombre, estado, person, mensaje)
            VALUES (@num_doc, @nombre_completo, 'OK', @person_out, @mensaje_out);
        END TRY
        BEGIN CATCH
            SET @err = LEFT(ERROR_MESSAGE(), 500);
            INSERT INTO #Resultado (num_doc, nombre, estado, person, mensaje)
            VALUES (@num_doc, @nombre_completo, 'ERROR', NULL, @err);
        END CATCH;

        FETCH NEXT FROM cur INTO
            @tipo_doc, @num_doc, @apellido_paterno, @apellido_materno, @nombres,
            @fecha_nac, @nacionalidad, @sexo, @telefono, @email, @direccion,
            @fecha_ingreso, @tipo_trabajador, @regimen_laboral, @cat_ocupacional,
            @ocupacion, @nivel_educativo, @formacion_superior_completa, @tipo_inst_educ,
            @nombre_inst_educ, @carrera, @anio_egreso, @indicador_educ,
            @tipo_contrato, @tipo_pago,
            @entidad_financiera, @nro_cuenta, @remun_bas, @regimen_pension,
            @regimen_pension_fec, @cuspp, @regimen_salud, @regimen_salud_fec,
            @situacion_especial, @sindicalizado, @nombre_completo;
    END;

    CLOSE cur;
    DEALLOCATE cur;

    SELECT
        num_doc,
        nombre,
        estado,
        person,
        mensaje
    FROM #Resultado
    ORDER BY nombre, num_doc;

    SELECT
        COUNT(*) AS total,
        SUM(CASE WHEN estado = 'OK' THEN 1 ELSE 0 END) AS registrados,
        SUM(CASE WHEN estado = 'ERROR' THEN 1 ELSE 0 END) AS errores
    FROM #Resultado;
END
GO



-- ============================================================================
-- [253/282] sp_pr_tregistro_registrar_trabajador_nuevo_web.sql
-- ============================================================================

/*
    Registra un trabajador NUEVO a partir de datos consolidados del T-Registro (reportes SUNAT).
    Solo inserta si el DNI/documento no existe en la ficha de la compañía.

    Tablas principales: SY_Person + PR_Employee.
    Address: solo texto libre. Nacionalidad: solo texto (columna Nacionalidad).
    No registra ubigeo ni dirección estructurada.

    Usado por: POST /api/tregistro-importacion/registrar
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_tregistro_registrar_trabajador_nuevo_web]
    @cia                    VARCHAR(10),
    @tipo_doc               VARCHAR(50),
    @num_doc                VARCHAR(15),
    @apellido_paterno       VARCHAR(40),
    @apellido_materno       VARCHAR(40) = NULL,
    @nombres                VARCHAR(80),
    @fecha_nac              VARCHAR(10) = NULL,
    @nacionalidad           VARCHAR(100) = NULL,
    @sexo                   VARCHAR(20),
    @telefono               VARCHAR(15) = NULL,
    @email                  VARCHAR(255) = NULL,
    @direccion              VARCHAR(255) = NULL,
    @fecha_ingreso          VARCHAR(10) = NULL,
    @tipo_trabajador        VARCHAR(80) = NULL,
    @regimen_laboral        VARCHAR(80) = NULL,
    @cat_ocupacional        VARCHAR(80) = NULL,
    @ocupacion              VARCHAR(120) = NULL,
    @nivel_educativo        VARCHAR(80) = NULL,
    @formacion_superior_completa VARCHAR(120) = NULL,
    @tipo_inst_educ         VARCHAR(80) = NULL,
    @nombre_inst_educ       VARCHAR(120) = NULL,
    @carrera                VARCHAR(120) = NULL,
    @anio_egreso            VARCHAR(10) = NULL,
    @indicador_educ         VARCHAR(5) = NULL,
    @tipo_contrato          VARCHAR(80) = NULL,
    @tipo_pago              VARCHAR(80) = NULL,
    @entidad_financiera     VARCHAR(120) = NULL,
    @nro_cuenta             VARCHAR(30) = NULL,
    @remun_bas              VARCHAR(20) = NULL,
    @regimen_pension        VARCHAR(80) = NULL,
    @regimen_pension_fec    VARCHAR(10) = NULL,
    @cuspp                  VARCHAR(20) = NULL,
    @regimen_salud          VARCHAR(80) = NULL,
    @regimen_salud_fec      VARCHAR(10) = NULL,
    @situacion_especial     VARCHAR(80) = NULL,
    @sindicalizado          VARCHAR(5) = NULL,
    @replicationunit        VARCHAR(20) = 'LIMA',
    @xlastuser              VARCHAR(20) = NULL,
    @person_out             VARCHAR(20) = NULL OUTPUT,
    @mensaje_out            VARCHAR(500) = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @person                 VARCHAR(20);
    DECLARE @num_doc_norm           VARCHAR(15);
    DECLARE @name1                  VARCHAR(40);
    DECLARE @name2                  VARCHAR(40);
    DECLARE @nombre_completo        VARCHAR(100);
    DECLARE @sex_code               CHAR(1);
    DECLARE @birthdate_dt           DATETIME;
    DECLARE @entrydate_dt           DATETIME;
    DECLARE @pensiondate_dt         DATETIME;
    DECLARE @healthdate_dt          DATETIME;
    DECLARE @rembasica              NUMERIC(18, 4);
    DECLARE @doc_type_id            VARCHAR(20);
    DECLARE @employee_type_id       VARCHAR(20);
    DECLARE @regimen_labour_id      VARCHAR(20);
    DECLARE @prof_category_id       VARCHAR(20);
    DECLARE @contract_modality_id   VARCHAR(20);
    DECLARE @ocupation_id           VARCHAR(20);
    DECLARE @instruction_level_id   VARCHAR(20);
    DECLARE @institution_pdt        VARCHAR(20);
    DECLARE @career_pdt             VARCHAR(20);
    DECLARE @anio_egreso_int        INT;
    DECLARE @center_type            CHAR(1);
    DECLARE @istrainer_educ         CHAR(1);
    DECLARE @indicator_educ         CHAR(1);
    DECLARE @specialty_educ         VARCHAR(100);
    DECLARE @pension_type_id        VARCHAR(20);
    DECLARE @regime_health_id       VARCHAR(20);
    DECLARE @collection_form_id     VARCHAR(20);
    DECLARE @salary_bank_id         VARCHAR(20);
    DECLARE @special_status_id      VARCHAR(20);
    DECLARE @employee_category_id   VARCHAR(20);
    DECLARE @employee_status_id     VARCHAR(20);
    DECLARE @payroll_type_id        VARCHAR(20);
    DECLARE @position_id            VARCHAR(20);
    DECLARE @costcenter_id          VARCHAR(20);
    DECLARE @accountprofile_id      VARCHAR(20);
    DECLARE @salaryaccounttype_id   VARCHAR(20);
    DECLARE @sctr_health_id         VARCHAR(20);
    DECLARE @sctr_pension_id        VARCHAR(20);
    DECLARE @costcentername         VARCHAR(20);
    DECLARE @is_unionized           CHAR(1);
    DECLARE @flag_mixta             CHAR(1);
    DECLARE @tiene_afp              CHAR(1);
    DECLARE @afp_id                 VARCHAR(20);
    DECLARE @pension_pdt            VARCHAR(20);
    DECLARE @es_construccion        CHAR(1);
    DECLARE @concept_rembasica      VARCHAR(20);
    DECLARE @concept_afp_flujo      VARCHAR(20);
    DECLARE @period_start           VARCHAR(10);
    DECLARE @cc_asignacion          VARCHAR(20);
    DECLARE @cc_code_asignacion     VARCHAR(20);
    DECLARE @txt                    VARCHAR(200);
    DECLARE @tipo_contrato_raw      VARCHAR(80);
    DECLARE @pos_space              INT;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @tipo_doc = LTRIM(RTRIM(ISNULL(@tipo_doc, '')));
    SET @num_doc = LTRIM(RTRIM(ISNULL(@num_doc, '')));
    SET @apellido_paterno = UPPER(LTRIM(RTRIM(ISNULL(@apellido_paterno, ''))));
    SET @apellido_materno = UPPER(LTRIM(RTRIM(ISNULL(@apellido_materno, ''))));
    SET @nombres = UPPER(LTRIM(RTRIM(ISNULL(@nombres, ''))));
    SET @nacionalidad = NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@nacionalidad, '')))), '');
    SET @telefono = NULLIF(LTRIM(RTRIM(ISNULL(@telefono, ''))), '');
    SET @email = NULLIF(LOWER(LTRIM(RTRIM(ISNULL(@email, '')))), '');
    SET @direccion = NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@direccion, '')))), '');
    SET @replicationunit = UPPER(LTRIM(RTRIM(ISNULL(@replicationunit, 'LIMA'))));
    SET @xlastuser = NULLIF(LTRIM(RTRIM(ISNULL(@xlastuser, ''))), '');
    SET @person_out = NULL;
    SET @mensaje_out = NULL;

    IF @cia = '' OR @num_doc = '' OR @apellido_paterno = '' OR @nombres = ''
    BEGIN
        RAISERROR('Indique compañía, documento, apellido paterno y nombres.', 16, 1);
        RETURN;
    END;

    /* Normalizar documento (sin ceros a la izquierda si es numérico). */
    SET @num_doc_norm = @num_doc;
    IF @num_doc_norm NOT LIKE '%[^0-9]%'
    BEGIN
        WHILE LEN(@num_doc_norm) > 1 AND LEFT(@num_doc_norm, 1) = '0'
            SET @num_doc_norm = SUBSTRING(@num_doc_norm, 2, 15);
    END;

    IF EXISTS (
        SELECT 1
        FROM pr_employee e (NOLOCK)
            INNER JOIN sy_person sp (NOLOCK) ON sp.person = e.person
        WHERE e.company = @cia
          AND (
                LTRIM(RTRIM(ISNULL(sp.documentnumber, ''))) = @num_doc
             OR LTRIM(RTRIM(ISNULL(sp.documentnumber, ''))) = @num_doc_norm
             OR (
                    ISNUMERIC(sp.documentnumber) = 1
                AND ISNUMERIC(@num_doc_norm) = 1
                AND CAST(sp.documentnumber AS BIGINT) = CAST(@num_doc_norm AS BIGINT)
             )
          )
    )
    BEGIN
        RAISERROR('El documento %s ya está registrado en la ficha de la compañía.', 16, 1, @num_doc_norm);
        RETURN;
    END;

    IF EXISTS (SELECT 1 FROM sy_person (NOLOCK) WHERE person = @num_doc_norm)
    BEGIN
        RAISERROR('El código de persona %s ya existe en SY_Person.', 16, 1, @num_doc_norm);
        RETURN;
    END;

    SET @person = @num_doc_norm;

    SET @pos_space = CHARINDEX(' ', @nombres + ' ');
    SET @name1 = LEFT(@nombres, @pos_space - 1);
    SET @name2 = NULLIF(LTRIM(SUBSTRING(@nombres, @pos_space + 1, 80)), '');

    SET @nombre_completo = UPPER(LTRIM(RTRIM(
        ISNULL(@apellido_paterno, '') + ' ' +
        ISNULL(@apellido_materno, '') + ' ' +
        ISNULL(@name1, '') + ' ' +
        ISNULL(@name2, '')
    )));
    IF LEN(@nombre_completo) > 100
        SET @nombre_completo = LEFT(@nombre_completo, 100);

    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@sexo, ''))));
    IF @txt LIKE '%FEMENIN%' OR @txt IN ('2', 'F')
        SET @sex_code = '2';
    ELSE IF @txt LIKE '%MASCULIN%' OR @txt IN ('1', 'M')
        SET @sex_code = '1';
    ELSE
    BEGIN
        RAISERROR('Sexo no reconocido: %s', 16, 1, @sexo);
        RETURN;
    END;

    SET @birthdate_dt = NULL;
    IF NULLIF(LTRIM(RTRIM(ISNULL(@fecha_nac, ''))), '') IS NOT NULL
    BEGIN
        BEGIN TRY
            IF CHARINDEX('/', @fecha_nac) > 0
                SET @birthdate_dt = CONVERT(DATETIME, @fecha_nac, 103);
            ELSE IF ISDATE(@fecha_nac) = 1
                SET @birthdate_dt = CONVERT(DATETIME, @fecha_nac, 120);
        END TRY
        BEGIN CATCH
            SET @birthdate_dt = NULL;
        END CATCH;

        IF @birthdate_dt IS NULL
        BEGIN
            RAISERROR('Fecha de nacimiento no válida: %s', 16, 1, @fecha_nac);
            RETURN;
        END;
    END;

    SET @entrydate_dt = NULL;
    IF NULLIF(LTRIM(RTRIM(ISNULL(@fecha_ingreso, ''))), '') IS NOT NULL
    BEGIN
        BEGIN TRY
            IF CHARINDEX('/', @fecha_ingreso) > 0
                SET @entrydate_dt = CONVERT(DATETIME, @fecha_ingreso, 103);
            ELSE IF ISDATE(@fecha_ingreso) = 1
                SET @entrydate_dt = CONVERT(DATETIME, @fecha_ingreso, 120);
        END TRY
        BEGIN CATCH
            SET @entrydate_dt = NULL;
        END CATCH;

        IF @entrydate_dt IS NULL
        BEGIN
            RAISERROR('Fecha de ingreso no válida: %s', 16, 1, @fecha_ingreso);
            RETURN;
        END;
    END;

    SET @pensiondate_dt = NULL;
    IF NULLIF(LTRIM(RTRIM(ISNULL(@regimen_pension_fec, ''))), '') IS NOT NULL
    BEGIN
        BEGIN TRY
            IF CHARINDEX('/', @regimen_pension_fec) > 0
                SET @pensiondate_dt = CONVERT(DATETIME, @regimen_pension_fec, 103);
            ELSE IF ISDATE(@regimen_pension_fec) = 1
                SET @pensiondate_dt = CONVERT(DATETIME, @regimen_pension_fec, 120);
        END TRY
        BEGIN CATCH
            SET @pensiondate_dt = NULL;
        END CATCH;
    END;
    IF @pensiondate_dt IS NULL
        SET @pensiondate_dt = @entrydate_dt;

    SET @healthdate_dt = NULL;
    IF NULLIF(LTRIM(RTRIM(ISNULL(@regimen_salud_fec, ''))), '') IS NOT NULL
    BEGIN
        BEGIN TRY
            IF CHARINDEX('/', @regimen_salud_fec) > 0
                SET @healthdate_dt = CONVERT(DATETIME, @regimen_salud_fec, 103);
            ELSE IF ISDATE(@regimen_salud_fec) = 1
                SET @healthdate_dt = CONVERT(DATETIME, @regimen_salud_fec, 120);
        END TRY
        BEGIN CATCH
            SET @healthdate_dt = NULL;
        END CATCH;
    END;

    SET @rembasica = NULL;
    IF NULLIF(LTRIM(RTRIM(ISNULL(@remun_bas, ''))), '') IS NOT NULL
       AND ISNUMERIC(REPLACE(@remun_bas, ',', '')) = 1
        SET @rembasica = CONVERT(NUMERIC(18, 4), REPLACE(@remun_bas, ',', ''));

    SET @is_unionized = CASE
        WHEN UPPER(LTRIM(RTRIM(ISNULL(@sindicalizado, '')))) IN ('SI', 'S', '1', 'X') THEN '1'
        ELSE '0'
    END;

    /* --- Tipo de documento --- */
    SET @txt = UPPER(@tipo_doc);
    SELECT TOP 1 @doc_type_id = dt.persondocumenttype
    FROM sy_persondocumenttype dt (NOLOCK)
    WHERE dt.company = @cia
      AND (
            (@txt LIKE '%DNI%' AND dt.pdt = '01')
         OR (@txt LIKE '%CARN%' AND @txt LIKE '%EXT%' AND dt.pdt = '04')
         OR (@txt LIKE '%PASAPORTE%' AND dt.pdt = '07')
         OR (@txt LIKE '%PTP%' AND dt.pdt = '26')
         OR dt.description = @txt
      )
    ORDER BY CASE WHEN dt.persondocumenttype LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END;

    IF @doc_type_id IS NULL
    BEGIN
        RAISERROR('No se encontró tipo de documento para: %s', 16, 1, @tipo_doc);
        RETURN;
    END;

    /* --- Tipo trabajador --- */
    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@tipo_trabajador, ''))));
    SELECT TOP 1 @employee_type_id = et.employeetype
    FROM pr_employeetype et (NOLOCK)
    WHERE et.company = @cia
      AND UPPER(LTRIM(RTRIM(ISNULL(et.description, '')))) = @txt
    ORDER BY et.employeetype;

    IF @employee_type_id IS NULL AND @txt <> ''
    BEGIN
        SELECT TOP 1 @employee_type_id = et.employeetype
        FROM pr_employeetype et (NOLOCK)
        WHERE et.company = @cia
          AND UPPER(LTRIM(RTRIM(ISNULL(et.description, '')))) LIKE '%' + @txt + '%'
        ORDER BY et.employeetype;
    END;

    /* --- Régimen laboral (728 -> PRIVADO) --- */
    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@regimen_laboral, ''))));
    IF @txt LIKE '%728%' OR @txt LIKE '%PRIVAD%'
        SET @txt = 'PRIVADO';
    ELSE IF @txt LIKE '%PUBLIC%'
        SET @txt = 'PUBLICO';

    SELECT TOP 1 @regimen_labour_id = rl.regimenlabour
    FROM pr_regimenlabour rl (NOLOCK)
    WHERE (rl.company = @cia OR rl.regimenlabour LIKE 'LIMA' + @cia + '%')
      AND UPPER(LTRIM(RTRIM(ISNULL(rl.description, '')))) = @txt
    ORDER BY CASE WHEN rl.regimenlabour LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END;

    /* --- Categoría ocupacional --- */
    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@cat_ocupacional, ''))));
    SELECT TOP 1 @prof_category_id = pc.professionalcategory
    FROM pr_professionalcategory pc (NOLOCK)
    WHERE (pc.company = @cia OR pc.professionalcategory LIKE 'LIMA' + @cia + '%')
      AND UPPER(LTRIM(RTRIM(ISNULL(pc.description, '')))) = @txt
    ORDER BY CASE WHEN pc.professionalcategory LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END;

    /* --- Ocupación --- */
    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@ocupacion, ''))));
    IF @txt <> ''
    BEGIN
        SELECT TOP 1 @ocupation_id = o.ocupation
        FROM pr_ocupation o (NOLOCK)
        WHERE UPPER(LTRIM(RTRIM(ISNULL(o.description, '')))) = @txt
           OR UPPER(LTRIM(RTRIM(ISNULL(o.description, '')))) LIKE '%' + @txt + '%'
        ORDER BY CASE WHEN o.ocupation LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END, o.ocupation;
    END;

    /* --- Nivel educativo --- */
    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@nivel_educativo, ''))));
    IF @txt <> ''
    BEGIN
        SELECT TOP 1 @instruction_level_id = il.instructionlevel
        FROM pr_instructionlevel il (NOLOCK)
        WHERE UPPER(LTRIM(RTRIM(ISNULL(il.description, '')))) = @txt
           OR UPPER(LTRIM(RTRIM(ISNULL(il.description, '')))) LIKE '%' + @txt + '%'
        ORDER BY CASE WHEN il.instructionlevel LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END, il.instructionlevel;
    END;

    /* --- Educación detalle (SET TR1 → campos SY_Person reutilizados) --- */
    SET @institution_pdt = NULL;
    SET @career_pdt = NULL;
    SET @anio_egreso_int = NULL;
    SET @center_type = NULL;
    SET @istrainer_educ = 'N';
    SET @indicator_educ = NULL;
    SET @specialty_educ = NULL;

    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@nombre_inst_educ, ''))));
    IF @txt <> ''
    BEGIN
        SELECT TOP 1 @institution_pdt = i.pdt
        FROM pr_institution i (NOLOCK)
        WHERE i.company = @cia
          AND (
                UPPER(LTRIM(RTRIM(ISNULL(i.description, '')))) = @txt
             OR UPPER(LTRIM(RTRIM(ISNULL(i.description, '')))) LIKE '%' + @txt + '%'
             OR @txt LIKE '%' + UPPER(LTRIM(RTRIM(ISNULL(i.description, '')))) + '%'
          )
        ORDER BY
            CASE WHEN UPPER(LTRIM(RTRIM(ISNULL(i.description, '')))) = @txt THEN 0 ELSE 1 END,
            i.institution;
    END;

    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@carrera, ''))));
    IF @txt <> ''
    BEGIN
        SET @specialty_educ = LEFT(@txt, 100);

        IF @institution_pdt IS NOT NULL
        BEGIN
            SELECT TOP 1 @career_pdt = c.pdt
            FROM pr_career c (NOLOCK)
                INNER JOIN pr_institution i (NOLOCK)
                    ON i.institution = c.institution
                   AND i.company = c.company
            WHERE c.company = @cia
              AND i.pdt = @institution_pdt
              AND (
                    UPPER(LTRIM(RTRIM(ISNULL(c.description, '')))) = @txt
                 OR UPPER(LTRIM(RTRIM(ISNULL(c.description, '')))) LIKE '%' + @txt + '%'
                 OR @txt LIKE '%' + UPPER(LTRIM(RTRIM(ISNULL(c.description, '')))) + '%'
              )
            ORDER BY
                CASE WHEN UPPER(LTRIM(RTRIM(ISNULL(c.description, '')))) = @txt THEN 0 ELSE 1 END,
                c.line;
        END;
    END;

    SET @txt = LTRIM(RTRIM(ISNULL(@anio_egreso, '')));
    IF @txt <> '' AND ISNUMERIC(@txt) = 1 AND LEN(@txt) = 4
       AND CAST(@txt AS INT) BETWEEN 1900 AND 2100
        SET @anio_egreso_int = CAST(@txt AS INT);

    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@tipo_inst_educ, ''))));
    IF @txt LIKE '%UNIVERSIDAD%'
        SET @center_type = '2';
    ELSE IF @txt LIKE '%INSTITUTO%'
        SET @center_type = '3';
    ELSE IF @txt LIKE '%CENTRO%' OR @txt LIKE '%COLEGIO%' OR @txt LIKE '%EDUCATIV%'
        SET @center_type = '1';
    ELSE IF @txt <> ''
        SET @center_type = '4';

    SET @txt = LTRIM(RTRIM(ISNULL(@indicador_educ, '')));
    IF @txt <> ''
        SET @indicator_educ = LEFT(@txt, 1);
    ELSE
        SET @indicator_educ = NULL;

    IF NULLIF(LTRIM(RTRIM(ISNULL(@formacion_superior_completa, ''))), '') IS NOT NULL
        SET @istrainer_educ = 'Y';
    ELSE IF @indicator_educ IN ('1', '2') AND (
            @institution_pdt IS NOT NULL
         OR @career_pdt IS NOT NULL
         OR @anio_egreso_int IS NOT NULL
    )
        SET @istrainer_educ = 'Y';

    /* --- Modalidad de contrato (TRA → HR_ContractModality de la compañía) --- */
    SET @tipo_contrato_raw = UPPER(LTRIM(RTRIM(ISNULL(@tipo_contrato, ''))));
    SET @txt = @tipo_contrato_raw;

    IF @txt <> ''
    BEGIN
        SELECT TOP 1 @contract_modality_id = cm.contractmodality
        FROM hr_contractmodality cm (NOLOCK)
        WHERE (cm.company = @cia OR cm.contractmodality LIKE 'LIMA' + @cia + '%')
          AND (
                UPPER(LTRIM(RTRIM(ISNULL(cm.description, '')))) = @txt
             OR UPPER(LTRIM(RTRIM(ISNULL(cm.description, '')))) LIKE '%' + @txt + '%'
             OR @txt LIKE '%' + UPPER(LTRIM(RTRIM(ISNULL(cm.description, '')))) + '%'
             OR (@txt LIKE '%OBRA%' AND @txt LIKE '%DETERM%' AND cm.pdt = '09')
             OR (@txt LIKE '%OBRA%' AND @txt LIKE '%DETERM%' AND UPPER(cm.description) LIKE '%OBRA DETERMIN%')
             OR (@txt LIKE '%SERV%ESPEC%' AND cm.pdt = '09')
             /* T-Registro envía "A PLAZO INDET - D.LEG. 728" (abreviatura de INDETERMINADO) */
             OR (@txt LIKE '%INDET%' AND cm.pdt = '01')
             OR (@txt LIKE '%INDET%' AND UPPER(cm.description) LIKE '%INDETERMIN%')
             OR (@txt LIKE '%PLAZO FIJO%' AND cm.pdt = '02')
             OR (@txt LIKE '%TEMPORAL%' AND cm.pdt IN ('03', '04'))
          )
        ORDER BY
            CASE WHEN cm.company = @cia THEN 0 ELSE 1 END,
            CASE WHEN cm.contractmodality LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END,
            cm.contractmodality;
    END;

    /* --- Pensión --- */
    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@regimen_pension, ''))));
    SELECT TOP 1 @pension_type_id = pt.pensiontype
    FROM pr_pensiontype pt (NOLOCK)
    WHERE (pt.company = @cia OR pt.pensiontype LIKE 'LIMA' + @cia + '%' OR pt.pensiontype LIKE @cia + '%')
      AND (
            UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) = @txt
         OR UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) LIKE '%' + @txt + '%'
         OR @txt LIKE '%' + UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) + '%'
         OR (
                (
                    @txt LIKE '%ONP%'
                 OR @txt LIKE '%19990%'
                 OR @txt LIKE '%DECRETO LEY 19990%'
                 OR @txt LIKE '%SISTEMA NACIONAL DE PENS%'
                 OR @txt LIKE '%S.N.P.%'
                 OR @txt LIKE '%SNP%'
                )
            AND pt.pdt IN ('02', '2')
            )
         OR (@txt LIKE '%INTEGRA%' AND pt.pdt = '21')
         OR (@txt LIKE '%PROFUTURO%' AND pt.pdt = '23')
         OR (@txt LIKE '%PRIMA%' AND @txt NOT LIKE '%ONP%' AND @txt NOT LIKE '%19990%' AND pt.pdt = '24')
         OR ((@txt LIKE '%HABITAT%' OR @txt LIKE '%HORIZONTE%') AND pt.pdt = '25')
      )
    ORDER BY
        CASE
            WHEN (
                    @txt LIKE '%ONP%'
                 OR @txt LIKE '%19990%'
                 OR @txt LIKE '%SISTEMA NACIONAL DE PENS%'
                 OR @txt LIKE '%DECRETO LEY 19990%'
                )
             AND pt.pdt IN ('02', '2')
                THEN 0
            WHEN UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) = @txt THEN 1
            ELSE 2
        END,
        CASE WHEN pt.pensiontype LIKE 'LIMA' + @cia + '%' THEN 0 WHEN pt.pensiontype LIKE @cia + '%' THEN 1 ELSE 2 END,
        pt.pensiontype;

    /* Respaldo ONP: texto T-Registro DL 19990 sin coincidencia literal en catálogo */
    IF @pension_type_id IS NULL
       AND (
            @txt LIKE '%ONP%'
         OR @txt LIKE '%19990%'
         OR @txt LIKE '%DECRETO LEY 19990%'
         OR @txt LIKE '%SISTEMA NACIONAL DE PENS%'
         OR @txt LIKE '%S.N.P.%'
         OR @txt LIKE '%SNP%'
       )
    BEGIN
        SELECT TOP 1 @pension_type_id = pt.pensiontype
        FROM pr_pensiontype pt (NOLOCK)
        WHERE (pt.company = @cia OR pt.pensiontype LIKE @cia + '%')
          AND pt.pdt IN ('02', '2')
          AND UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) LIKE '%19990%'
        ORDER BY
            CASE WHEN pt.company = @cia AND pt.pensiontype NOT LIKE 'LIMA%' THEN 0 ELSE 1 END,
            pt.pensiontype;
    END;

    /* AFP en T-Registro (SPP / CUSPP) → marcar flag AFP mixta por defecto */
    SET @flag_mixta = 'N';
    IF @pension_type_id IS NOT NULL
    BEGIN
        IF EXISTS (
            SELECT 1
            FROM pr_pensiontype pt (NOLOCK)
            WHERE pt.pensiontype = @pension_type_id
              AND (
                    pt.pdt IN ('21', '23', '24', '25')
                 OR (
                        (
                            UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) LIKE '%SPP%'
                         OR UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) LIKE '%AFP%'
                        )
                    AND UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) NOT LIKE '%ONP%'
                 )
              )
        )
            SET @flag_mixta = 'Y';
    END;
    IF @flag_mixta = 'N'
    BEGIN
        SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@regimen_pension, ''))));
        IF @txt LIKE '%SPP%'
           OR @txt LIKE '%INTEGRA%'
           OR @txt LIKE '%PRIMA%'
           OR @txt LIKE '%PROFUTURO%'
           OR @txt LIKE '%HABITAT%'
           OR @txt LIKE '%AFP%'
            SET @flag_mixta = 'Y';
        IF @txt LIKE '%ONP%' OR @txt LIKE '%19990%'
            SET @flag_mixta = 'N';
        IF NULLIF(LTRIM(RTRIM(ISNULL(@cuspp, ''))), '') IS NOT NULL
           AND @txt NOT LIKE '%ONP%'
            SET @flag_mixta = 'Y';
    END;

    /* Trabajador con régimen AFP (no ONP) → asignar concepto AFP_FLUJO */
    SET @tiene_afp = 'N';
    IF @pension_type_id IS NOT NULL
    BEGIN
        IF EXISTS (
            SELECT 1
            FROM pr_pensiontype pt (NOLOCK)
            WHERE pt.pensiontype = @pension_type_id
              AND (
                    pt.pdt IN ('21', '23', '24', '25')
                 OR (
                        (
                            UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) LIKE '%SPP%'
                         OR UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) LIKE '%AFP%'
                        )
                    AND UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) NOT LIKE '%ONP%'
                 )
              )
        )
            SET @tiene_afp = 'Y';
    END;
    IF @tiene_afp = 'N'
    BEGIN
        SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@regimen_pension, ''))));
        IF (
               @txt LIKE '%SPP%'
            OR @txt LIKE '%INTEGRA%'
            OR @txt LIKE '%PRIMA%'
            OR @txt LIKE '%PROFUTURO%'
            OR @txt LIKE '%HABITAT%'
            OR @txt LIKE '%AFP%'
           )
           AND @txt NOT LIKE '%ONP%'
           AND @txt NOT LIKE '%19990%'
            SET @tiene_afp = 'Y';
        IF NULLIF(LTRIM(RTRIM(ISNULL(@cuspp, ''))), '') IS NOT NULL
           AND @txt NOT LIKE '%ONP%'
           AND @txt NOT LIKE '%19990%'
            SET @tiene_afp = 'Y';
    END;

    /*
        Campo PR_Employee.AFP: se resuelve desde PR_AFP (mismo pdt del régimen).
        ONP / sin AFP → NULL. No inventar AFP si el régimen no es SPP.
    */
    SET @afp_id = NULL;
    SET @pension_pdt = NULL;
    IF @tiene_afp = 'Y'
    BEGIN
        IF @pension_type_id IS NOT NULL
            SELECT @pension_pdt = LTRIM(RTRIM(ISNULL(pt.pdt, '')))
            FROM pr_pensiontype pt (NOLOCK)
            WHERE pt.pensiontype = @pension_type_id;

        IF @pension_pdt IN ('21', '23', '24', '25')
        BEGIN
            SELECT TOP 1 @afp_id = a.afp
            FROM pr_afp a (NOLOCK)
            WHERE a.company = @cia
              AND LTRIM(RTRIM(ISNULL(a.pdt, ''))) = @pension_pdt
            ORDER BY
                CASE WHEN a.afp LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END,
                a.afp;
        END;

        /* Respaldo por nombre si el pdt del régimen no matcheó (catálogo incompleto) */
        IF @afp_id IS NULL
        BEGIN
            SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@regimen_pension, ''))));
            SELECT TOP 1 @afp_id = a.afp
            FROM pr_afp a (NOLOCK)
            WHERE a.company = @cia
              AND (
                    (@txt LIKE '%INTEGRA%' AND (a.pdt = '21' OR UPPER(a.description) LIKE '%INTEGRA%'))
                 OR (@txt LIKE '%PROFUTURO%' AND (a.pdt = '23' OR UPPER(a.description) LIKE '%PROFUTURO%'))
                 OR (@txt LIKE '%PRIMA%' AND @txt NOT LIKE '%ONP%' AND (a.pdt = '24' OR UPPER(a.description) LIKE '%PRIMA%'))
                 OR (
                        (@txt LIKE '%HABITAT%' OR @txt LIKE '%HORIZONTE%')
                    AND (a.pdt = '25' OR UPPER(a.description) LIKE '%HABITAT%' OR UPPER(a.description) LIKE '%HORIZONTE%')
                    )
              )
            ORDER BY
                CASE WHEN a.afp LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END,
                a.afp;
        END;
    END;

    /* --- Salud --- */
    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@regimen_salud, ''))));
    IF @txt LIKE '%ESSALUD%REGULAR%'
        SET @txt = 'ESSALUD REGULAR (Exclusivamente)';

    SELECT TOP 1 @regime_health_id = rh.regimehealth
    FROM pr_regimehealth rh (NOLOCK)
    WHERE UPPER(LTRIM(RTRIM(ISNULL(rh.description, '')))) = @txt
       OR UPPER(LTRIM(RTRIM(ISNULL(rh.description, '')))) LIKE '%ESSALUD REGULAR%'
    ORDER BY CASE WHEN rh.regimehealth LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END, rh.regimehealth;

    /* --- Forma de pago --- */
    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@tipo_pago, ''))));
    IF @txt LIKE '%DEPOS%' OR @txt LIKE '%DEPÓS%'
        SET @txt = 'DEPOSITO';
    ELSE IF @txt LIKE '%EFECTIV%'
        SET @txt = 'EFECTIVO';

    SELECT TOP 1 @collection_form_id = cf.collectionform
    FROM te_collectionform cf (NOLOCK)
    WHERE UPPER(LTRIM(RTRIM(ISNULL(cf.description, '')))) = @txt
       OR UPPER(LTRIM(RTRIM(ISNULL(cf.description, '')))) LIKE '%' + @txt + '%'
    ORDER BY CASE WHEN cf.collectionform LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END;

    /* --- Banco salario --- */
    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@entidad_financiera, ''))));
    IF @txt <> ''
    BEGIN
        SELECT TOP 1 @salary_bank_id = b.bank
        FROM erp_bank b (NOLOCK)
        WHERE (b.company = @cia OR b.bank LIKE 'LIMA' + @cia + '%')
          AND (
                UPPER(LTRIM(RTRIM(ISNULL(b.name, '')))) = @txt
             OR UPPER(LTRIM(RTRIM(ISNULL(b.name, '')))) LIKE '%' + @txt + '%'
             OR (@txt LIKE '%BBVA%' AND UPPER(b.name) LIKE '%CONTINENTAL%')
             OR (@txt LIKE '%CONTINENTAL%' AND UPPER(b.name) LIKE '%CONTINENTAL%')
             OR (@txt LIKE '%BCP%' AND UPPER(b.name) LIKE '%CREDITO%')
             OR (@txt LIKE '%INTERBANK%' AND UPPER(b.name) LIKE '%INTERBANK%')
          )
        ORDER BY CASE WHEN b.bank LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END, b.bank;
    END;

    /* --- Situación especial --- */
    SET @txt = UPPER(LTRIM(RTRIM(ISNULL(@situacion_especial, ''))));
    IF @txt IN ('', 'NINGUNA', 'NINGUNO', '0')
        SET @txt = 'NINGUNA';

    SELECT TOP 1 @special_status_id = ss.specialstatus
    FROM pr_specialstatus ss (NOLOCK)
    WHERE ss.specialstatus LIKE 'LIMA' + @cia + '%'
      AND (
            UPPER(LTRIM(RTRIM(ISNULL(ss.description, '')))) = @txt
         OR UPPER(LTRIM(RTRIM(ISNULL(ss.description, '')))) LIKE '%' + @txt + '%'
      )
    ORDER BY CASE WHEN ss.specialstatus LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END;

    /* --- Categoría y estado empleado (defaults compañía) --- */
    SELECT TOP 1 @employee_category_id = ec.employeecategory
    FROM pr_employeecategory ec (NOLOCK)
    WHERE ec.company = @cia OR ec.employeecategory LIKE 'LIMA' + @cia + '%'
    ORDER BY CASE WHEN ec.pdt = '1' THEN 0 ELSE 1 END,
             CASE WHEN ec.employeecategory LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END,
             ec.employeecategory;

    SELECT TOP 1 @employee_status_id = es.employeestatus
    FROM pr_employeestatus es (NOLOCK)
    WHERE (es.company = @cia OR es.employeestatus LIKE 'LIMA' + @cia + '%')
      AND (es.pdt IN ('11', '10') OR UPPER(es.description) LIKE '%ACTIVO%')
    ORDER BY CASE WHEN es.pdt = '11' THEN 0 WHEN es.pdt = '10' THEN 1 ELSE 2 END,
             CASE WHEN es.employeestatus LIKE 'LIMA' + @cia + '%' THEN 0 ELSE 1 END;

    /* --- Defaults laborales (sin cargo ni centro de costo; vienen vacíos) --- */
    SET @position_id = NULL;
    SET @costcenter_id = NULL;
    SET @costcentername = NULL;

    SELECT TOP 1
        @payroll_type_id = e.payrolltype,
        @accountprofile_id = e.accountprofile,
        @salaryaccounttype_id = e.salaryaccounttype,
        @sctr_health_id = e.sctrhealth,
        @sctr_pension_id = e.sctrpension
    FROM pr_employee e (NOLOCK)
    WHERE e.company = @cia
      AND (
            (@employee_type_id IS NOT NULL AND e.employeetype = @employee_type_id)
         OR (@employee_type_id IS NULL)
      )
    ORDER BY
        CASE WHEN @employee_type_id IS NOT NULL AND e.employeetype = @employee_type_id THEN 0 ELSE 1 END,
        e.xlastdate DESC;

    IF @payroll_type_id IS NULL
    BEGIN
        SELECT TOP 1 @payroll_type_id = pt.payrolltype
        FROM pr_payrolltype pt (NOLOCK)
        WHERE pt.company = @cia
        ORDER BY pt.payrolltype;
    END;

    IF @salaryaccounttype_id IS NULL
        SELECT TOP 1 @salaryaccounttype_id = e.salaryaccounttype
        FROM pr_employee e (NOLOCK)
        WHERE e.company = @cia AND e.salaryaccounttype IS NOT NULL
        ORDER BY e.xlastdate DESC;

    IF NOT EXISTS (
        SELECT 1
        FROM sy_replicationunit (NOLOCK)
        WHERE replicationunit = @replicationunit
           OR UPPER(LTRIM(RTRIM(ISNULL(description, '')))) = @replicationunit
           OR UPPER(LTRIM(RTRIM(ISNULL(name, '')))) = @replicationunit
    )
    BEGIN
        RAISERROR('Unidad de replicación no válida: %s', 16, 1, @replicationunit);
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO sy_person (
            person, flaguserid, persontype, name, address,
            documenttype, documentnumber, email, status, flagrucpersontype,
            isvendor, iscustomer, xlastuser, xlastdate, company,
            replicationunit, isemployee, sectelephone, name2, lastname1,
            name1, lastname2, birthdate, instructionlevel, sex,
            employeedocumenttype, flagkeep, flagname, flagoutsourcingin,
            flagoutsourcingout, isdomiciled, nacionalidad, flagperceptionagent,
            flagsunat5, istrainer, isrecruiter, issupervisor, indicator,
            flaglockca, licensecondition,
            costcenter1, costcenter2, driverlicenseantiquity, specialty,
            profesionalstudiescentertype
        )
        VALUES (
            @person, 'N', 'NN', @nombre_completo, @direccion,
            @doc_type_id, @num_doc_norm, @email, 'A', 'XX',
            'Y', 'N', @xlastuser, GETDATE(), @cia,
            @replicationunit, 'Y', @telefono, @name2, @apellido_paterno,
            @name1, NULLIF(@apellido_materno, ''), @birthdate_dt, @instruction_level_id, @sex_code,
            @doc_type_id, 'N', 'P', 'N',
            'N', '1', @nacionalidad, 'N',
            'N', @istrainer_educ, 'N', 'N', @indicator_educ,
            'N', 'L',
            @institution_pdt, @career_pdt, @anio_egreso_int, @specialty_educ,
            @center_type
        );

        INSERT INTO pr_employee (
            person, company, employeecode, employeetype, employeecategory,
            entrydate, reentrydate, pensiontype, pensioninscriptiondate,
            salarybank, salaryaccounttype, salarycurrency, salaryaccount,
            costcenter, position, accountprofile, payrolltype, employeestatus,
            flagessaludvida, status, xlastdate, xlastuser, replicationunit,
            costcentername, flagdistribution, contractmodality, considerincalc,
            flagparticipar, regimenlabour, sctrhealth, sctrpension,
            flagalternativeregimen, flagmaxworkinghours, flagnightschedule,
            otherincomerenttax, isunionized, affiliatedowneps, relievedrenttax,
            specialstatus, collectionform, workingdaystype, professionalcategory,
            pensionmembership, ocupation, regimehealth, accidentinsurance,
            confirmcessation, rembasica, salary, afpcard, flagmixta, afp
        )
        VALUES (
            @person, @cia, @person, @employee_type_id, @employee_category_id,
            @entrydate_dt, @entrydate_dt, @pension_type_id, @pensiondate_dt,
            @salary_bank_id, @salaryaccounttype_id, 'LO', NULLIF(@nro_cuenta, ''),
            @costcenter_id, @position_id, @accountprofile_id, @payroll_type_id, @employee_status_id,
            'N', 'N', GETDATE(), @xlastuser, @replicationunit,
            @costcentername, 'H', @contract_modality_id, 'Y',
            'Y', @regimen_labour_id, @sctr_health_id, @sctr_pension_id,
            '0', '0', '0',
            '0', @is_unionized, '0', '0',
            @special_status_id, @collection_form_id, 'S', @prof_category_id,
            '0', @ocupation_id, @regime_health_id, '0',
            'N', @rembasica, @rembasica, NULLIF(LTRIM(RTRIM(ISNULL(@cuspp, ''))), ''), @flag_mixta, @afp_id
        );

        /*
            Asignación permanente REM_BASICA desde el periodo de ingreso.
            No aplica a Construcción Civil (planilla/tipo CONSTRUCCION): usan jornal diario.
        */
        SET @es_construccion = 'N';
        IF EXISTS (
            SELECT 1
            FROM pr_employeetype et (NOLOCK)
            WHERE et.employeetype = @employee_type_id
              AND (
                    et.pdt = '27'
                 OR UPPER(LTRIM(RTRIM(ISNULL(et.description, '')))) LIKE '%CONSTRUCCION%'
              )
        )
            SET @es_construccion = 'Y';

        IF @es_construccion = 'N' AND EXISTS (
            SELECT 1
            FROM pr_payrolltype pt (NOLOCK)
            WHERE pt.payrolltype = @payroll_type_id
              AND (
                    UPPER(LTRIM(RTRIM(ISNULL(pt.description, '')))) LIKE '%CONSTRUCCION%'
                 OR UPPER(LTRIM(RTRIM(ISNULL(pt.shortname, '')))) LIKE '%CONSTRUCCION%'
              )
        )
            SET @es_construccion = 'Y';

        IF @es_construccion = 'N'
           AND @rembasica IS NOT NULL
           AND @rembasica > 0
           AND @payroll_type_id IS NOT NULL
           AND @entrydate_dt IS NOT NULL
        BEGIN
            SET @concept_rembasica = NULL;
            SELECT TOP 1 @concept_rembasica = c.concept
            FROM pr_concept c (NOLOCK)
            WHERE c.company = @cia
              AND c.formulacode = 'REM_BASICA'
              AND c.status = 'A'
            ORDER BY c.concept;

            SET @period_start = NULL;
            SELECT TOP 1 @period_start = p.prperiod
            FROM pr_period p (NOLOCK)
            WHERE p.company = @cia
              AND p.payrolltype = @payroll_type_id
              AND @entrydate_dt BETWEEN p.datebegin AND p.dateend
            ORDER BY p.prperiod;

            IF @period_start IS NULL
            BEGIN
                /* Si aún no hay periodo que contenga la fecha, usar el más cercano posterior o el último anterior. */
                SELECT TOP 1 @period_start = p.prperiod
                FROM pr_period p (NOLOCK)
                WHERE p.company = @cia
                  AND p.payrolltype = @payroll_type_id
                  AND p.datebegin >= @entrydate_dt
                ORDER BY p.datebegin ASC, p.prperiod ASC;

                IF @period_start IS NULL
                    SELECT TOP 1 @period_start = p.prperiod
                    FROM pr_period p (NOLOCK)
                    WHERE p.company = @cia
                      AND p.payrolltype = @payroll_type_id
                      AND p.datebegin <= @entrydate_dt
                    ORDER BY p.datebegin DESC, p.prperiod DESC;
            END;

            SET @cc_asignacion = ISNULL(NULLIF(LTRIM(RTRIM(ISNULL(@costcenter_id, ''))), ''), '');
            SET @cc_code_asignacion = ISNULL(NULLIF(LTRIM(RTRIM(ISNULL(@costcentername, ''))), ''), @cc_asignacion);

            IF @concept_rembasica IS NOT NULL
               AND @period_start IS NOT NULL
               AND NOT EXISTS (
                    SELECT 1
                    FROM pr_employeeconcept ec (NOLOCK)
                    WHERE ec.person = @person
                      AND ec.company = @cia
                      AND ec.concept = @concept_rembasica
                      AND ec.payrolltype = @payroll_type_id
                      AND ec.prperiodstart = @period_start
                      AND ec.costcenter = @cc_asignacion
               )
            BEGIN
                INSERT INTO pr_employeeconcept (
                    person, company, concept, payrolltype, prperiodstart, costcenter,
                    prperiodend, conceptvalue, application, conceptcurrency, comments,
                    flagapplyformula, flagfrecuencytype, replicationunit,
                    xlastuser, xlastdate, conceptvaluelo, conceptvalueex, exchangerate,
                    costcentercode, project, projectcode, percentagedistribution, flagcopy
                )
                VALUES (
                    @person, @cia, @concept_rembasica, @payroll_type_id, @period_start, @cc_asignacion,
                    NULL, @rembasica, NULL, 'LO', NULL,
                    'N', 'P', @replicationunit,
                    @xlastuser, GETDATE(), @rembasica, 0, 0,
                    @cc_code_asignacion, '', '', 'A', NULL
                );
            END;
        END;

        /*
            Asignación permanente AFP_FLUJO (=1) desde el periodo de ingreso.
            Aplica a todo trabajador con AFP, sin excepción por tipo de planilla.
        */
        IF @tiene_afp = 'Y'
           AND @payroll_type_id IS NOT NULL
           AND @entrydate_dt IS NOT NULL
        BEGIN
            SET @concept_afp_flujo = NULL;
            SELECT TOP 1 @concept_afp_flujo = c.concept
            FROM pr_concept c (NOLOCK)
            WHERE c.company = @cia
              AND c.formulacode = 'AFP_FLUJO'
              AND c.status = 'A'
            ORDER BY c.concept;

            IF @period_start IS NULL
            BEGIN
                SELECT TOP 1 @period_start = p.prperiod
                FROM pr_period p (NOLOCK)
                WHERE p.company = @cia
                  AND p.payrolltype = @payroll_type_id
                  AND @entrydate_dt BETWEEN p.datebegin AND p.dateend
                ORDER BY p.prperiod;

                IF @period_start IS NULL
                BEGIN
                    SELECT TOP 1 @period_start = p.prperiod
                    FROM pr_period p (NOLOCK)
                    WHERE p.company = @cia
                      AND p.payrolltype = @payroll_type_id
                      AND p.datebegin >= @entrydate_dt
                    ORDER BY p.datebegin ASC, p.prperiod ASC;

                    IF @period_start IS NULL
                        SELECT TOP 1 @period_start = p.prperiod
                        FROM pr_period p (NOLOCK)
                        WHERE p.company = @cia
                          AND p.payrolltype = @payroll_type_id
                          AND p.datebegin <= @entrydate_dt
                        ORDER BY p.datebegin DESC, p.prperiod DESC;
                END;
            END;

            SET @cc_asignacion = ISNULL(NULLIF(LTRIM(RTRIM(ISNULL(@costcenter_id, ''))), ''), '');
            SET @cc_code_asignacion = ISNULL(NULLIF(LTRIM(RTRIM(ISNULL(@costcentername, ''))), ''), @cc_asignacion);

            IF @concept_afp_flujo IS NOT NULL
               AND @period_start IS NOT NULL
               AND NOT EXISTS (
                    SELECT 1
                    FROM pr_employeeconcept ec (NOLOCK)
                    WHERE ec.person = @person
                      AND ec.company = @cia
                      AND ec.concept = @concept_afp_flujo
                      AND ec.payrolltype = @payroll_type_id
                      AND ec.prperiodstart = @period_start
                      AND ec.costcenter = @cc_asignacion
               )
            BEGIN
                INSERT INTO pr_employeeconcept (
                    person, company, concept, payrolltype, prperiodstart, costcenter,
                    prperiodend, conceptvalue, application, conceptcurrency, comments,
                    flagapplyformula, flagfrecuencytype, replicationunit,
                    xlastuser, xlastdate, conceptvaluelo, conceptvalueex, exchangerate,
                    costcentercode, project, projectcode, percentagedistribution, flagcopy
                )
                VALUES (
                    @person, @cia, @concept_afp_flujo, @payroll_type_id, @period_start, @cc_asignacion,
                    NULL, 1, NULL, 'LO', NULL,
                    'N', 'P', @replicationunit,
                    @xlastuser, GETDATE(), 1, 0, 0,
                    @cc_code_asignacion, '', '', 'A', NULL
                );
            END;
        END;

        COMMIT TRANSACTION;

        SET @person_out = @person;
        SET @mensaje_out = 'Trabajador registrado correctamente.';
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @err VARCHAR(500) = LEFT(ERROR_MESSAGE(), 500);
        RAISERROR('%s', 16, 1, @err);
        RETURN;
    END CATCH;
END
GO



-- ============================================================================
-- [254/282] sp_pr_tregistro_trabajador_web.sql
-- ============================================================================

/*
    T-REGISTRO Estructura 05 — Datos del trabajador (generación TXT RP_RUC.tra).

    Usado por: POST /api/plame/t-registro/generar-txt (archivo 05)

    @personas — lista separada por comas de códigos SY_Person.Person
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_tregistro_trabajador_web]
    @cia       VARCHAR(10),
    @personas  VARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @personas = LTRIM(RTRIM(ISNULL(@personas, '')));

    IF @cia = '' OR @personas = ''
        RETURN;

    CREATE TABLE #Personas (
        person VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL PRIMARY KEY
    );

    INSERT INTO #Personas (person)
    SELECT DISTINCT LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)')))
    FROM (
        SELECT CAST('<x>' + REPLACE(@personas, ',', '</x><x>') + '</x>' AS XML) AS x
    ) t
    CROSS APPLY x.nodes('/x') Split(a)
    WHERE LTRIM(RTRIM(Split.a.value('.', 'VARCHAR(20)'))) <> '';

    SELECT DISTINCT
        LTRIM(RTRIM(
            ISNULL(sy_person.LastName1, '') + ' ' +
            ISNULL(sy_person.LastName2, '') + ' ' +
            ISNULL(sy_person.Name1, '') + ' ' +
            ISNULL(sy_person.Name2, '')
        )) AS name,
        LTRIM(RTRIM(ISNULL(sy_persondocumenttype.pdt, ''))) AS documenttype,
        LTRIM(RTRIM(ISNULL(sy_person.DocumentNumber, ''))) AS documentnumber,
        LTRIM(RTRIM(ISNULL(pr_employeetype.pdt, ''))) AS employeetype,
        LTRIM(RTRIM(ISNULL(pr_regimenlabour.pdt, ''))) AS regimenlabour,
        LTRIM(RTRIM(ISNULL(pr_instructionlevel.pdt, ''))) AS instructionlevel,
        LTRIM(RTRIM(ISNULL(pr_ocupation.pdt, ''))) AS ocupation,
        LTRIM(RTRIM(ISNULL(CAST(sy_person.Discapacity AS VARCHAR(10)), ''))) AS discapacity,
        LTRIM(RTRIM(ISNULL(pr_pensiontype.pdt, ''))) AS pensiontype,
        pr_employee.PensionInscriptionDate AS pensioninscriptiondate,
        LTRIM(RTRIM(ISNULL(pr_employee.AfpCard, ''))) AS afpcard,
        LTRIM(RTRIM(ISNULL(pr_sctr_a.pdt, ''))) AS sctrhealth,
        LTRIM(RTRIM(ISNULL(pr_sctr_b.pdt, ''))) AS sctrpension,
        LTRIM(RTRIM(ISNULL(hr_contractmodality.pdt, ''))) AS contractmodality,
        LTRIM(RTRIM(ISNULL(CAST(pr_employee.FlagAlternativeRegimen AS VARCHAR(10)), '0'))) AS flagalternativeregimen,
        LTRIM(RTRIM(ISNULL(CAST(pr_employee.FlagMaxWorkingHours AS VARCHAR(10)), '0'))) AS flagmaxworkinghours,
        LTRIM(RTRIM(ISNULL(CAST(pr_employee.FlagNightSchedule AS VARCHAR(10)), '0'))) AS flagnightschedule,
        LTRIM(RTRIM(ISNULL(CAST(pr_employee.OtherIncomeRentTax AS VARCHAR(10)), '0'))) AS otherincomerenttax,
        LTRIM(RTRIM(ISNULL(CAST(pr_employee.IsUnionized AS VARCHAR(10)), '0'))) AS isunionized,
        LTRIM(RTRIM(ISNULL(pr_periodtype.pdt, ''))) AS periodtype,
        LTRIM(RTRIM(ISNULL(CAST(pr_employee.AffiliatedOwnEps AS VARCHAR(10)), '0'))) AS affiliatedowneps,
        LTRIM(RTRIM(ISNULL(pr_healthentity.pdt, ''))) AS ownserviceruc,
        LTRIM(RTRIM(ISNULL(pr_employeestatus.pdt, ''))) AS employeestatus,
        LTRIM(RTRIM(ISNULL(CAST(pr_employee.RelievedRentTax AS VARCHAR(10)), '0'))) AS relievedrenttax,
        LTRIM(RTRIM(ISNULL(pr_specialstatus.pdt, ''))) AS specialstatus,
        LTRIM(RTRIM(ISNULL(te_collectionform.pdt, ''))) AS collectionform,
        LTRIM(RTRIM(ISNULL(CAST(pr_employee.PensionMembership AS VARCHAR(10)), ''))) AS pensionmembership,
        LTRIM(RTRIM(ISNULL(pr_taxagreement.pdt, ''))) AS taxagreement,
        LTRIM(RTRIM(ISNULL(pr_professionalcategory.pdt, ''))) AS professionalcategory,
        (SELECT TOP 1 PR_EmployeeConcept.ConceptValue
           FROM PR_EmployeeConcept (nolock), PR_Concept (nolock)
          WHERE PR_EmployeeConcept.Concept = PR_Concept.Concept
            AND PR_EmployeeConcept.Company = pr_employee.company
            AND PR_EmployeeConcept.Person = pr_employee.person
            AND PR_Concept.FormulaCode = 'REM_BASICA'
            AND PR_EmployeeConcept.FlagFrecuencyType = 'P'
            AND PR_EmployeeConcept.PRPeriodEnd IS NULL) AS salarybasic,
        (SELECT TOP 1 (PR_EmployeeConcept.ConceptValue * 30)
           FROM PR_EmployeeConcept (nolock), PR_Concept (nolock)
          WHERE PR_EmployeeConcept.Concept = PR_Concept.Concept
            AND PR_EmployeeConcept.Company = pr_employee.company
            AND PR_EmployeeConcept.Person = pr_employee.person
            AND PR_Concept.FormulaCode = 'JOR_DIARIO'
            AND PR_EmployeeConcept.FlagFrecuencyType = 'P'
            AND PR_EmployeeConcept.PRPeriodEnd IS NULL) AS jornalbasic,
        LTRIM(RTRIM(ISNULL(pr_payrolltype.ShortName, ''))) AS planilla,
        '' AS ruccas,
        LTRIM(RTRIM(ISNULL(PR_CountryIssuingDocument.Pdt, ''))) AS docissuingcountry,
        LTRIM(RTRIM(ISNULL(sy_person.Person, ''))) AS person
    FROM pr_employee (nolock)
        INNER JOIN #Personas SEL ON SEL.person = pr_employee.person
        INNER JOIN sy_person (nolock)
            ON sy_person.person = pr_employee.person
        LEFT JOIN pr_pensiontype (nolock)
            ON pr_employee.pensiontype = pr_pensiontype.pensiontype
        LEFT JOIN pr_sctr pr_sctr_a (nolock)
            ON pr_employee.sctrhealth = pr_sctr_a.sctr
        LEFT JOIN pr_sctr pr_sctr_b (nolock)
            ON pr_employee.sctrpension = pr_sctr_b.sctr
        LEFT JOIN hr_contractmodality (nolock)
            ON pr_employee.contractmodality = hr_contractmodality.contractmodality
        INNER JOIN pr_payrolltype (nolock)
            ON pr_employee.payrolltype = pr_payrolltype.payrolltype
        LEFT JOIN pr_periodtype (nolock)
            ON pr_payrolltype.periodtype = pr_periodtype.periodtype
        LEFT JOIN pr_healthentity (nolock)
            ON pr_employee.ownserviceruc = pr_healthentity.healthentity
        LEFT JOIN pr_employeestatus (nolock)
            ON pr_employee.employeestatus = pr_employeestatus.employeestatus
        LEFT JOIN pr_specialstatus (nolock)
            ON pr_employee.specialstatus = pr_specialstatus.specialstatus
        LEFT JOIN te_collectionform (nolock)
            ON pr_employee.collectionform = te_collectionform.collectionform
        LEFT JOIN sy_persondocumenttype (nolock)
            ON sy_person.employeedocumenttype = sy_persondocumenttype.persondocumenttype
        LEFT JOIN pr_employeetype (nolock)
            ON pr_employee.employeetype = pr_employeetype.employeetype
        LEFT JOIN pr_regimenlabour (nolock)
            ON pr_employee.regimenlabour = pr_regimenlabour.regimenlabour
        LEFT JOIN pr_instructionlevel (nolock)
            ON sy_person.instructionlevel = pr_instructionlevel.instructionlevel
        LEFT JOIN pr_ocupation (nolock)
            ON pr_employee.ocupation = pr_ocupation.ocupation
        LEFT JOIN pr_employeecategory (nolock)
            ON pr_employee.employeecategory = pr_employeecategory.employeecategory
        LEFT JOIN pr_taxagreement (nolock)
            ON pr_employee.taxagreement = pr_taxagreement.taxagreement
        LEFT JOIN pr_professionalcategory (nolock)
            ON pr_employee.professionalcategory = pr_professionalcategory.professionalcategory
        LEFT JOIN PR_CountryIssuingDocument (nolock)
            ON SY_Person.CountryIssuing = PR_CountryIssuingDocument.CountryIssuing
    WHERE pr_employeecategory.PDT = '1'
      AND pr_employee.company = @cia
    ORDER BY name ASC;
END
GO



-- ============================================================================
-- [255/282] sp_pr_vacaciones_eliminar_detalle_web.sql
-- ============================================================================

/*
    Elimina un registro de PR_VacationDetail y PR_VacationPay;
    recalcula consumeddays en PR_Vacation.
    Usado por: POST /api/vacaciones/eliminar-detalle (registro_vacaciones.html).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_vacaciones_eliminar_detalle_web]
    @company   VARCHAR(4),
    @person    VARCHAR(20),
    @line      INT,
    @secuence  INT,
    @xlastuser VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (
        SELECT 1
        FROM PR_VacationDetail
        WHERE company = @company
          AND person = @person
          AND line = @line
          AND Secuence = @secuence
    )
    BEGIN
        RAISERROR('No se encontró el registro de utilización.', 16, 1);
        RETURN;
    END;

    DELETE FROM PR_VacationPay
    WHERE company = @company
      AND person = @person
      AND line = @line
      AND Secuence = @secuence;

    DELETE FROM PR_VacationDetail
    WHERE company = @company
      AND person = @person
      AND line = @line
      AND Secuence = @secuence;

    UPDATE PR_Vacation
    SET consumeddays = (
            SELECT ISNULL(SUM(Days), 0)
            FROM PR_VacationDetail
            WHERE Person = @person
              AND Company = @company
              AND line = @line
        ),
        XLastUser = @xlastuser,
        XLastDate = GETDATE()
    WHERE company = @company
      AND person = @person
      AND line = @line;

    SELECT 1 AS ok;
END
GO



-- ============================================================================
-- [256/282] sp_pr_vacaciones_guardar_detalle_web.sql
-- ============================================================================

/*
    Alta de registro en PR_VacationDetail y PR_VacationPay;
    actualización de consumeddays en PR_Vacation.
    Usado por: POST /api/vacaciones/guardar-detalle (registro_vacaciones.html).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_vacaciones_guardar_detalle_web]
    @company       VARCHAR(4),
    @person        VARCHAR(20),
    @line          INT,
    @prperiod      VARCHAR(10),
    @datebegin     DATETIME,
    @dateend       DATETIME,
    @days          INT = NULL,
    @vacationtype  CHAR(1) = 'D',
    @xlastuser     VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @secuence        INT;
    DECLARE @acquireddays    INT;
    DECLARE @consumeddays    INT;
    DECLARE @pendientes      INT;
    DECLARE @dias_nuevos     INT;
    DECLARE @replicationunit VARCHAR(4);

    IF @datebegin IS NULL OR @dateend IS NULL
    BEGIN
        RAISERROR('Indique fecha de inicio y término.', 16, 1);
        RETURN;
    END;

    IF @dateend < @datebegin
    BEGIN
        RAISERROR('La fecha de término no puede ser anterior a la de inicio.', 16, 1);
        RETURN;
    END;

    IF RTRIM(ISNULL(@prperiod, '')) = ''
    BEGIN
        RAISERROR('Seleccione el periodo de consumo efectivo.', 16, 1);
        RETURN;
    END;

    /* Normalizar y resolver periodo completo (YYYYMMDD) desde PR_Period. */
    DECLARE @prperiod_digits VARCHAR(10);
    DECLARE @prperiod_full   VARCHAR(10);

    SET @prperiod_digits = REPLACE(REPLACE(LTRIM(RTRIM(@prperiod)), '-', ''), '/', '');
    SET @prperiod_full = @prperiod_digits;

    IF LEN(@prperiod_digits) = 6 AND @prperiod_digits NOT LIKE '%[^0-9]%'
    BEGIN
        SELECT TOP 1 @prperiod_full = p.prperiod
        FROM PR_Period p
            INNER JOIN PR_Employee e
                ON e.company = @company
               AND e.person = @person
        WHERE p.company = @company
          AND p.payrolltype = e.payrolltype
          AND LEFT(p.prperiod, 6) = @prperiod_digits
        ORDER BY p.prperiod DESC;

        IF RTRIM(ISNULL(@prperiod_full, '')) = ''
        BEGIN
            SELECT TOP 1 @prperiod_full = prperiod
            FROM PR_Period
            WHERE company = @company
              AND LEFT(prperiod, 6) = @prperiod_digits
            ORDER BY prperiod DESC;
        END
    END
    ELSE IF LEN(@prperiod_digits) >= 8 AND @prperiod_digits NOT LIKE '%[^0-9]%'
    BEGIN
        SET @prperiod_full = LEFT(@prperiod_digits, 8);
    END;

    IF RTRIM(ISNULL(@prperiod_full, '')) = ''
       OR LEN(@prperiod_full) < 8
       OR @prperiod_full LIKE '%[^0-9]%'
    BEGIN
        RAISERROR('No se encontró el periodo de consumo efectivo en PR_Period.', 16, 1);
        RETURN;
    END;

    SET @prperiod = @prperiod_full;

    SET @vacationtype = UPPER(LTRIM(RTRIM(ISNULL(@vacationtype, 'D'))));
    IF @vacationtype NOT IN ('D', 'V', 'X') SET @vacationtype = 'D';

    SET @dias_nuevos = ISNULL(@days, DATEDIFF(DAY, @datebegin, @dateend) + 1);
    IF @dias_nuevos <= 0
    BEGIN
        RAISERROR('El rango de fechas debe generar al menos 1 día.', 16, 1);
        RETURN;
    END;

    SELECT
        @acquireddays = ISNULL(AcquiredDays, 0),
        @consumeddays = ISNULL(consumeddays, 0)
    FROM PR_Vacation
    WHERE company = @company
      AND person = @person
      AND line = @line;

    IF @acquireddays IS NULL
    BEGIN
        RAISERROR('No se encontró el periodo vacacional seleccionado.', 16, 1);
        RETURN;
    END;

    SET @pendientes = ABS(@consumeddays - @acquireddays);
    IF (@consumeddays + @dias_nuevos) > @acquireddays
    BEGIN
        RAISERROR('Los días solicitados superan el saldo pendiente del periodo (%d día(s)).', 16, 1, @pendientes);
        RETURN;
    END;

    SELECT @secuence = ISNULL(MAX(Secuence), 0) + 1
    FROM PR_VacationDetail
    WHERE company = @company
      AND person = @person
      AND line = @line;

    SELECT @replicationunit = ISNULL(ReplicationUnit, @company)
    FROM PR_Employee
    WHERE company = @company
      AND person = @person;

    INSERT INTO PR_VacationDetail (
        Person, Company, line, Secuence,
        prperiod, Datebegin, Dateend, Days,
        VacationType, ReplicationUnit, XLastUser, XLastDate
    )
    VALUES (
        @person, @company, @line, @secuence,
        @prperiod, @datebegin, @dateend, @dias_nuevos,
        @vacationtype, @replicationunit, @xlastuser, GETDATE()
    );

    INSERT INTO PR_VacationPay (
        Person, Company, line, Secuence,
        Datebegin, Dateend, Days, PRPeriod,
        VacationType, Status, ReplicationUnit,
        XLastUser, XLastDate
    )
    VALUES (
        @person, @company, @line, @secuence,
        @datebegin, @dateend, @dias_nuevos, @prperiod,
        @vacationtype, 'A', @replicationunit,
        @xlastuser, GETDATE()
    );

    UPDATE PR_Vacation
    SET consumeddays = (
            SELECT ISNULL(SUM(Days), 0)
            FROM PR_VacationDetail
            WHERE Person = @person
              AND Company = @company
              AND line = @line
        ),
        XLastUser = @xlastuser,
        XLastDate = GETDATE()
    WHERE company = @company
      AND person = @person
      AND line = @line;

    SELECT
        @secuence AS secuence,
        @dias_nuevos AS dias,
        @pendientes - @dias_nuevos AS pendientes_restantes;
END
GO



-- ============================================================================
-- [257/282] sp_pr_vacaciones_listar_trabajadores_web.sql
-- ============================================================================

/*
    Listado de trabajadores para Registro de Vacaciones / Descansos Médicos.
    Usado por: POST /api/vacaciones/trabajadores
               (registro_vacaciones.html, registro_descansos_medicos.html).

    Parámetros:
      @company     — obligatorio.
      @payrolltype — '0' = todos los tipos de planilla.
      @busqueda    — filtro opcional por nombre, documento o código.
      @cesados     — T = Todos, Y = solo con fecha de cese, N = sin fecha de cese (default).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_vacaciones_listar_trabajadores_web]
    @company     VARCHAR(4),
    @payrolltype VARCHAR(20) = '0',
    @busqueda    VARCHAR(100) = '',
    @cesados     CHAR(1) = 'N'
AS
BEGIN
    SET NOCOUNT ON;

    IF RTRIM(ISNULL(@payrolltype, '')) = '' SET @payrolltype = '0';
    SET @busqueda = LTRIM(RTRIM(ISNULL(@busqueda, '')));
    SET @cesados = UPPER(LTRIM(RTRIM(ISNULL(@cesados, 'N'))));
    IF @cesados NOT IN ('T', 'Y', 'N') SET @cesados = 'N';

    SELECT
        PR_EMPLOYEE.PERSON AS person,
        PR_EMPLOYEE.EMPLOYEECODE AS codigo,
        LTRIM(RTRIM(
            ISNULL(SY_PERSON.LASTNAME1, '') + ' ' +
            ISNULL(SY_PERSON.LASTNAME2, '') + ' ' +
            ISNULL(SY_PERSON.NAME1, '') + ' ' +
            ISNULL(SY_PERSON.NAME2, '')
        )) AS nombre,
        SY_PERSON.DOCUMENTNUMBER AS documento,
        ISNULL(PR_EMPLOYEE.REENTRYDATE, PR_EMPLOYEE.ENTRYDATE) AS fechaingreso,
        PR_EMPLOYEE.CEASEDATE AS fechacese,
        PR_EMPLOYEE.PAYROLLTYPE AS payrolltype,
        PR_PAYROLLTYPE.DESCRIPTION AS tipoplanilla
    FROM PR_EMPLOYEE
        INNER JOIN SY_PERSON
            ON PR_EMPLOYEE.PERSON = SY_PERSON.PERSON
        LEFT JOIN PR_PAYROLLTYPE
            ON PR_EMPLOYEE.PAYROLLTYPE = PR_PAYROLLTYPE.PAYROLLTYPE
           AND PR_EMPLOYEE.COMPANY = PR_PAYROLLTYPE.COMPANY
    WHERE PR_EMPLOYEE.COMPANY = @company
      AND PR_EMPLOYEE.STATUS = 'N'
      AND (
            @cesados = 'T'
         OR (@cesados = 'Y' AND PR_EMPLOYEE.CEASEDATE IS NOT NULL)
         OR (@cesados = 'N' AND PR_EMPLOYEE.CEASEDATE IS NULL)
      )
      AND (
            @payrolltype = '0'
         OR PR_EMPLOYEE.PAYROLLTYPE = @payrolltype
         OR PR_EMPLOYEE.PAYROLLTYPE IN (
                SELECT PT.PayRollType
                FROM PR_PAYROLLTYPE PT (NOLOCK)
                WHERE PT.Company = @company
                  AND (
                        PT.Description = @payrolltype
                     OR PT.ShortName = @payrolltype
                  )
            )
          )
      AND (
            @busqueda = ''
         OR SY_PERSON.DOCUMENTNUMBER LIKE '%' + @busqueda + '%'
         OR LTRIM(RTRIM(
                ISNULL(SY_PERSON.LASTNAME1, '') + ' ' +
                ISNULL(SY_PERSON.LASTNAME2, '') + ' ' +
                ISNULL(SY_PERSON.NAME1, '') + ' ' +
                ISNULL(SY_PERSON.NAME2, '')
            )) LIKE '%' + @busqueda + '%'
         OR PR_EMPLOYEE.EMPLOYEECODE LIKE '%' + @busqueda + '%'
      )
    ORDER BY nombre;
END
GO



-- ============================================================================
-- [258/282] sp_pr_vacaciones_obtener_trabajador_web.sql
-- ============================================================================

/*
    Datos de vacaciones de un trabajador para Registro de Vacaciones.
    Usado por: POST /api/vacaciones/obtener (registro_vacaciones.html).

    Devuelve 4 resultsets:
      1) Datos del empleado
      2) Resumen de saldo (acumulados, gozados, pendientes)
      3) Periodos vacacionales (PR_Vacation)
      4) Detalle de utilización (PR_VacationDetail)
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_vacaciones_obtener_trabajador_web]
    @company VARCHAR(4),
    @person  VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    /* 1) Empleado */
    SELECT
        PR_EMPLOYEE.PERSON AS person,
        PR_EMPLOYEE.EMPLOYEECODE AS codigo,
        LTRIM(RTRIM(
            ISNULL(SY_PERSON.LASTNAME1, '') + ' ' +
            ISNULL(SY_PERSON.LASTNAME2, '') + ' ' +
            ISNULL(SY_PERSON.NAME1, '') + ' ' +
            ISNULL(SY_PERSON.NAME2, '')
        )) AS nombre,
        SY_PERSON.DOCUMENTNUMBER AS documento,
        ISNULL(PR_EMPLOYEE.REENTRYDATE, PR_EMPLOYEE.ENTRYDATE) AS fechaingreso,
        PR_EMPLOYEE.PAYROLLTYPE AS payrolltype,
        PR_PAYROLLTYPE.DESCRIPTION AS tipoplanilla
    FROM PR_EMPLOYEE
        INNER JOIN SY_PERSON
            ON PR_EMPLOYEE.PERSON = SY_PERSON.PERSON
        LEFT JOIN PR_PAYROLLTYPE
            ON PR_EMPLOYEE.PAYROLLTYPE = PR_PAYROLLTYPE.PAYROLLTYPE
    WHERE PR_EMPLOYEE.COMPANY = @company
      AND PR_EMPLOYEE.PERSON = @person;

    /* 2) Resumen */
    SELECT
        ISNULL(SUM(CASE WHEN v.status = 'A' THEN ISNULL(v.AcquiredDays, 0) ELSE 0 END), 0) AS dias_acumulados,
        ISNULL(SUM(CASE WHEN v.status = 'A' THEN ISNULL(v.consumeddays, 0) ELSE 0 END), 0) AS dias_gozados,
        ISNULL(SUM(
            CASE
                WHEN v.status = 'A' THEN ABS(ISNULL(v.consumeddays, 0) - ISNULL(v.AcquiredDays, 0))
                ELSE 0
            END
        ), 0) AS dias_pendientes
    FROM PR_Vacation v
    WHERE v.company = @company
      AND v.person = @person;

    /* 3) Periodos vacacionales */
    SELECT
        v.line,
        v.controlyear,
        CAST(v.controlyear AS VARCHAR(4)) + '-' + CAST(CAST(v.controlyear AS INT) + 1 AS VARCHAR(4)) AS periodo,
        ISNULL(v.days, 0) AS dias,
        ISNULL(v.AcquiredDays, 0) AS dias_adquiridos,
        ISNULL(v.consumeddays, 0) AS consumidos,
        ABS(ISNULL(v.consumeddays, 0) - ISNULL(v.AcquiredDays, 0)) AS pendientes,
        ISNULL(v.payeddays, 0) AS pagados,
        ISNULL(v.AcquiredDays, 0) - ISNULL(v.payeddays, 0) AS por_pagar,
        v.DateBeginProvision AS inicio_provision,
        v.DateBeginRights AS inicio_derecho,
        v.DateEndRights AS fin_derecho,
        v.DateEndNormal AS limite_sin_indemnizacion,
        v.status,
        CASE v.status WHEN 'A' THEN 'Activo' WHEN 'I' THEN 'Inactivo' ELSE v.status END AS estado_texto,
        v.XLastUser AS usuario,
        v.XLastDate AS fecha_modificacion
    FROM PR_Vacation v
    WHERE v.company = @company
      AND v.person = @person
    ORDER BY v.controlyear DESC;

    /* 4) Detalle de utilización */
    SELECT
        d.line,
        d.secuence,
        d.prperiod,
        CASE
            WHEN LEN(LTRIM(RTRIM(ISNULL(d.prperiod, '')))) >= 6
                 AND SUBSTRING(d.prperiod, 1, 6) NOT LIKE '%[^0-9]%'
            THEN SUBSTRING(d.prperiod, 1, 4) + '-' + SUBSTRING(d.prperiod, 5, 2)
            ELSE d.prperiod
        END AS consumo_efectivo,
        d.datebegin AS fecha_inicio,
        d.dateend AS fecha_fin,
        ISNULL(d.days, 0) AS dias,
        d.vacationtype,
        CASE d.vacationtype
            WHEN 'D' THEN 'Descanso'
            WHEN 'V' THEN 'Venta'
            WHEN 'X' THEN 'No Remunerada'
            ELSE d.vacationtype
        END AS tipo_texto,
        d.XLastUser AS usuario,
        d.XLastDate AS fecha_modificacion
    FROM PR_VacationDetail d
    WHERE d.company = @company
      AND d.person = @person
    ORDER BY d.datebegin ASC;
END
GO



-- ============================================================================
-- [259/282] sp_pr_validar_alta_trabajador_web.sql
-- ============================================================================

/*
    Validaciones previas al alta manual de trabajador (módulo Trabajadores / Nuevo).

    Result sets:
      1) cabecera: codigo_existe, documento_existe_cia, codigo_distinto_documento, hay_similares
      2) similares (solo si hay): person, name, documentnumber, company

    Usado por: POST /api/trabajadores/validar-alta
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_validar_alta_trabajador_web]
    @cia             VARCHAR(10),
    @person          VARCHAR(20),
    @documentnumber  VARCHAR(15),
    @name1           VARCHAR(40) = NULL,
    @name2           VARCHAR(40) = NULL,
    @lastname1       VARCHAR(40) = NULL,
    @lastname2       VARCHAR(40) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @person = UPPER(LTRIM(RTRIM(ISNULL(@person, ''))));
    SET @documentnumber = LTRIM(RTRIM(ISNULL(@documentnumber, '')));
    SET @name1 = UPPER(LTRIM(RTRIM(ISNULL(@name1, ''))));
    SET @name2 = UPPER(LTRIM(RTRIM(ISNULL(@name2, ''))));
    SET @lastname1 = UPPER(LTRIM(RTRIM(ISNULL(@lastname1, ''))));
    SET @lastname2 = UPPER(LTRIM(RTRIM(ISNULL(@lastname2, ''))));

    DECLARE @nombre_completo VARCHAR(100);
    DECLARE @codigo_existe BIT = 0;
    DECLARE @documento_existe_cia BIT = 0;
    DECLARE @codigo_distinto_documento BIT = 0;
    DECLARE @hay_similares BIT = 0;
    DECLARE @doc_norm VARCHAR(15) = @documentnumber;

    IF @doc_norm <> '' AND @doc_norm NOT LIKE '%[^0-9]%'
    BEGIN
        WHILE LEN(@doc_norm) > 1 AND LEFT(@doc_norm, 1) = '0'
            SET @doc_norm = SUBSTRING(@doc_norm, 2, 15);
    END;

    SET @nombre_completo = UPPER(LTRIM(RTRIM(
        ISNULL(@lastname1, '') + ' ' +
        ISNULL(@lastname2, '') + ' ' +
        ISNULL(@name1, '') + ' ' +
        ISNULL(@name2, '')
    )));
    WHILE CHARINDEX('  ', @nombre_completo) > 0
        SET @nombre_completo = REPLACE(@nombre_completo, '  ', ' ');
    IF LEN(@nombre_completo) > 100
        SET @nombre_completo = LEFT(@nombre_completo, 100);

    IF @person <> '' AND EXISTS (SELECT 1 FROM SY_Person (NOLOCK) WHERE Person = @person)
        SET @codigo_existe = 1;

    IF @cia <> '' AND @documentnumber <> ''
       AND EXISTS (
            SELECT 1
            FROM PR_Employee e (NOLOCK)
                INNER JOIN SY_Person p (NOLOCK) ON p.Person = e.Person
            WHERE e.Company = @cia
              AND (
                    LTRIM(RTRIM(ISNULL(p.DocumentNumber, ''))) = @documentnumber
                 OR LTRIM(RTRIM(ISNULL(p.DocumentNumber, ''))) = @doc_norm
                 OR (
                        ISNUMERIC(p.DocumentNumber) = 1
                    AND ISNUMERIC(@doc_norm) = 1
                    AND CAST(p.DocumentNumber AS BIGINT) = CAST(@doc_norm AS BIGINT)
                 )
              )
       )
        SET @documento_existe_cia = 1;

    IF @person <> '' AND @documentnumber <> ''
       AND UPPER(@person) <> UPPER(@documentnumber)
       AND UPPER(@person) <> UPPER(@doc_norm)
        SET @codigo_distinto_documento = 1;

    CREATE TABLE #similares (
        person          VARCHAR(20) NOT NULL,
        name            VARCHAR(100) NULL,
        documentnumber  VARCHAR(15) NULL,
        company         VARCHAR(10) NULL
    );

    IF @lastname1 <> '' AND @name1 <> ''
    BEGIN
        INSERT INTO #similares (person, name, documentnumber, company)
        SELECT TOP 25
            LTRIM(RTRIM(p.Person)),
            LTRIM(RTRIM(ISNULL(p.Name, ''))),
            LTRIM(RTRIM(ISNULL(p.DocumentNumber, ''))),
            LTRIM(RTRIM(ISNULL(p.Company, '')))
        FROM SY_Person p (NOLOCK)
        WHERE (
                UPPER(LTRIM(RTRIM(ISNULL(p.LastName1, '')))) = @lastname1
            AND UPPER(LTRIM(RTRIM(ISNULL(p.Name1, '')))) = @name1
          )
           OR (
                @nombre_completo <> ''
            AND UPPER(LTRIM(RTRIM(ISNULL(p.Name, '')))) = @nombre_completo
           )
        ORDER BY p.Name, p.Person;

        IF EXISTS (SELECT 1 FROM #similares)
            SET @hay_similares = 1;
    END;

    SELECT
        @codigo_existe AS codigo_existe,
        @documento_existe_cia AS documento_existe_cia,
        @codigo_distinto_documento AS codigo_distinto_documento,
        @hay_similares AS hay_similares,
        @nombre_completo AS nombre_completo;

    SELECT
        person,
        name,
        documentnumber,
        company
    FROM #similares
    ORDER BY name, person;
END
GO



-- ============================================================================
-- [260/282] sp_pr_validar_calculo_web.sql
-- ============================================================================

/*
    Validaciones post-cálculo de planilla (módulo Procesar planilla).

    Usado por: POST /api/procesar-planilla/validar-calculo
    y al finalizar /ejecutar_calculo_streaming.

    Basado en: sp_pr_validar_calculo (legacy).

    Parámetros:
      @cia         — compañía
      @payrolltype — tipo de planilla
      @processtype — proceso
      @period      — periodo PRPeriod (ej. 20260505)

    Solo valida trabajadores con ingreso/reingreso <= ultimo dia del mes del periodo.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_validar_calculo_web]
    @cia         VARCHAR(10),
    @payrolltype VARCHAR(20),
    @processtype VARCHAR(20),
    @period      VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    SET @processtype = LTRIM(RTRIM(ISNULL(@processtype, '')));
    SET @period = LTRIM(RTRIM(ISNULL(@period, '')));

    DECLARE @fecha_fin_mes DATE;
    DECLARE @period_ym CHAR(6);
    DECLARE @proceso_shortname VARCHAR(50);

    SET @period_ym = LEFT(@period, 6);
    IF LEN(@period_ym) = 6 AND @period_ym NOT LIKE '%[^0-9]%'
        SET @fecha_fin_mes = EOMONTH(CONVERT(DATE, @period_ym + '01', 112));

    SELECT @proceso_shortname = LTRIM(RTRIM(ISNULL(PT.ShortName, '')))
    FROM PR_ProcessType PT (NOLOCK)
    WHERE PT.Company = @cia
      AND PT.ProcessType = @processtype;

    CREATE TABLE #errores (
        person      VARCHAR(20) NULL,
        name        VARCHAR(200) NULL,
        observacion VARCHAR(500) NOT NULL
    );

    CREATE TABLE #lista_rem_basica (
        person VARCHAR(20) NOT NULL PRIMARY KEY
    );

    CREATE TABLE #empleados_periodo (
        person VARCHAR(20) NOT NULL PRIMARY KEY
    );

    INSERT INTO #empleados_periodo (person)
    SELECT E.Person
    FROM PR_Employee E (NOLOCK)
    WHERE E.Company = @cia
      AND E.PayRollType = @payrolltype
      AND E.Status = 'N'
      AND (
            @fecha_fin_mes IS NULL
            OR CONVERT(DATE, ISNULL(E.ReEntryDate, E.EntryDate)) <= @fecha_fin_mes
          );

    INSERT INTO #lista_rem_basica (person)
    SELECT EC.Person
    FROM PR_EmployeeConcept EC (NOLOCK)
        INNER JOIN #empleados_periodo EP ON EC.Person = EP.person
        INNER JOIN PR_Concept C (NOLOCK)
            ON EC.Concept = C.Concept
           AND C.Company = @cia
    WHERE EC.Company = @cia
      AND EC.PayRollType = @payrolltype
      AND C.FormulaCode = 'REM_BASICA'
      AND EC.FlagFrecuencyType IN ('P', 'T')
      AND (
            (EC.FlagFrecuencyType = 'P' AND EC.PRPeriodStart <= @period)
            OR (EC.FlagFrecuencyType = 'T' AND @period BETWEEN EC.PRPeriodStart AND ISNULL(EC.PRPeriodEnd, EC.PRPeriodStart))
          )
      AND (
            EC.FlagFrecuencyType = 'T'
            OR (
                EC.FlagFrecuencyType = 'P'
                AND EC.PRPeriodStart = (
                    SELECT MAX(T.PRPeriodStart)
                    FROM PR_EmployeeConcept T (NOLOCK)
                    WHERE T.Company = EC.Company
                      AND T.Person = EC.Person
                      AND T.Concept = EC.Concept
                      AND T.PayRollType = EC.PayRollType
                )
            )
          )
    GROUP BY EC.Person;

    INSERT INTO #errores (person, name, observacion)
    SELECT
        E.Person,
        LTRIM(RTRIM(
            ISNULL(P.LastName1, '') + ' ' +
            ISNULL(P.LastName2, '') + ' ' +
            ISNULL(P.Name1, '') + ' ' +
            ISNULL(P.Name2, '')
        )),
        'No registra Remuneración Básica'
    FROM PR_Employee E (NOLOCK)
        INNER JOIN SY_Person P (NOLOCK) ON E.Person = P.Person
        INNER JOIN #empleados_periodo EP ON E.Person = EP.person
    WHERE E.Company = @cia
      AND E.PayRollType = @payrolltype
      AND E.Status = 'N'
      AND NOT EXISTS (
            SELECT 1 FROM #lista_rem_basica L WHERE L.person = E.Person
      );

    IF @proceso_shortname = 'FIN_DE_MES'
    BEGIN
        ;WITH Totales AS (
            SELECT
                EPC.Person,
                SUM(CASE WHEN C.FormulaCode = 'TOTALINGRESO' THEN ISNULL(EPC.ConceptValueLo, 0) ELSE 0 END) AS total_ingresos,
                SUM(CASE WHEN C.FormulaCode = 'TOTALEGRESOS' THEN ISNULL(EPC.ConceptValueLo, 0) ELSE 0 END) AS total_egresos,
                SUM(CASE WHEN C.FormulaCode = 'NETO' THEN ISNULL(EPC.ConceptValueLo, 0) ELSE 0 END) AS neto
            FROM PR_EmployeePayRollConcept EPC (NOLOCK)
                INNER JOIN PR_Concept C (NOLOCK)
                    ON EPC.Concept = C.Concept
                   AND C.Company = @cia
            WHERE EPC.Company = @cia
              AND EPC.PayRollType = @payrolltype
              AND EPC.ProcessType = @processtype
              AND EPC.PRPeriod = @period
            GROUP BY EPC.Person
        )
        INSERT INTO #errores (person, name, observacion)
        SELECT
            E.Person,
            LTRIM(RTRIM(
                ISNULL(P.LastName1, '') + ' ' +
                ISNULL(P.LastName2, '') + ' ' +
                ISNULL(P.Name1, '') + ' ' +
                ISNULL(P.Name2, '')
            )),
            'Neto no coincide con Ingresos - Egresos'
        FROM Totales T
            INNER JOIN PR_Employee E (NOLOCK)
                ON T.Person = E.Person
               AND E.Company = @cia
               AND E.PayRollType = @payrolltype
               AND E.Status = 'N'
            INNER JOIN #empleados_periodo EP ON E.Person = EP.person
            INNER JOIN SY_Person P (NOLOCK) ON E.Person = P.Person
        WHERE ROUND(T.total_ingresos, 2) - ROUND(T.total_egresos, 2) <> ROUND(T.neto, 2);
    END

    /* Código PDT: solo conceptos de Ingresos (I) y Descuentos (D) con movimiento en el periodo. */
    INSERT INTO #errores (person, name, observacion)
    SELECT NULL, NULL, T.Description + ' no tiene código PDT'
    FROM (
        SELECT DISTINCT C.Description
        FROM PR_EmployeePayRollConcept EPC (NOLOCK)
            INNER JOIN PR_Concept C (NOLOCK) ON EPC.Concept = C.Concept
            INNER JOIN PR_ConceptType CT (NOLOCK)
                ON C.ConceptType = CT.ConceptType
        WHERE EPC.Company = @cia
          AND EPC.PayRollType = @payrolltype
          AND EPC.ProcessType = @processtype
          AND EPC.PRPeriod = @period
          AND ISNULL(C.pdt, '') = ''
          AND (
                LTRIM(RTRIM(CT.ShortName)) = 'I'
                OR (
                    LTRIM(RTRIM(CT.ShortName)) = 'D'
                    AND ISNULL(C.FormulaCode, '') <> 'ONP'
                )
              )
    ) T;

    /* Régimen de pensión: ficha (PR_Employee). Sin régimen = vacío o PDT 99 (SIN REGIMEN PENSIONARIO). */
    INSERT INTO #errores (person, name, observacion)
    SELECT
        E.Person,
        LTRIM(RTRIM(
            ISNULL(P.LastName1, '') + ' ' +
            ISNULL(P.LastName2, '') + ' ' +
            ISNULL(P.Name1, '') + ' ' +
            ISNULL(P.Name2, '')
        )),
        'Trabajador no tiene régimen de pensión'
    FROM PR_Employee E (NOLOCK)
        INNER JOIN SY_Person P (NOLOCK) ON E.Person = P.Person
        INNER JOIN #empleados_periodo EP ON E.Person = EP.person
        INNER JOIN PR_EmployeeCategory ECAT (NOLOCK)
            ON E.EmployeeCategory = ECAT.EmployeeCategory
           AND ECAT.PDT = '1'
        LEFT JOIN PR_PensionType PT (NOLOCK)
            ON PT.PensionType = E.PensionType
           AND (
                LTRIM(RTRIM(ISNULL(PT.Company, ''))) = ''
                OR LTRIM(RTRIM(PT.Company)) = E.Company
           )
    WHERE E.Company = @cia
      AND E.PayRollType = @payrolltype
      AND E.Status = 'N'
      AND (
            LTRIM(RTRIM(ISNULL(E.PensionType, ''))) = ''
            OR LTRIM(RTRIM(ISNULL(PT.PDT, ''))) = '99'
          );

    INSERT INTO #errores (person, name, observacion)
    SELECT T.Person, T.Name, 'Trabajador no tiene cargo'
    FROM (
        SELECT
            E.Person,
            LTRIM(RTRIM(
                ISNULL(P.LastName1, '') + ' ' +
                ISNULL(P.LastName2, '') + ' ' +
                ISNULL(P.Name1, '') + ' ' +
                ISNULL(P.Name2, '')
            )) AS Name,
            E.Position
        FROM PR_Employee E (NOLOCK)
            INNER JOIN SY_Person P (NOLOCK) ON E.Person = P.Person
            INNER JOIN #empleados_periodo EP ON E.Person = EP.person
        WHERE E.Company = @cia
          AND E.PayRollType = @payrolltype
          AND E.Status = 'N'
    ) T
    WHERE ISNULL(T.Position, '') = '';

    INSERT INTO #errores (person, name, observacion)
    SELECT T.Person, T.Name, 'Trabajador no tiene cuenta bancaria'
    FROM (
        SELECT
            E.Person,
            LTRIM(RTRIM(
                ISNULL(P.LastName1, '') + ' ' +
                ISNULL(P.LastName2, '') + ' ' +
                ISNULL(P.Name1, '') + ' ' +
                ISNULL(P.Name2, '')
            )) AS Name,
            E.SalaryAccount
        FROM PR_Employee E (NOLOCK)
            INNER JOIN SY_Person P (NOLOCK) ON E.Person = P.Person
            INNER JOIN #empleados_periodo EP ON E.Person = EP.person
        WHERE E.Company = @cia
          AND E.PayRollType = @payrolltype
          AND E.Status = 'N'
    ) T
    WHERE ISNULL(T.SalaryAccount, '') = '';

    INSERT INTO #errores (person, name, observacion)
    SELECT T.Person, T.Name, 'Trabajador no tiene banco de haberes'
    FROM (
        SELECT
            E.Person,
            LTRIM(RTRIM(
                ISNULL(P.LastName1, '') + ' ' +
                ISNULL(P.LastName2, '') + ' ' +
                ISNULL(P.Name1, '') + ' ' +
                ISNULL(P.Name2, '')
            )) AS Name,
            E.SalaryBank
        FROM PR_Employee E (NOLOCK)
            INNER JOIN SY_Person P (NOLOCK) ON E.Person = P.Person
            INNER JOIN #empleados_periodo EP ON E.Person = EP.person
        WHERE E.Company = @cia
          AND E.PayRollType = @payrolltype
          AND E.Status = 'N'
    ) T
    WHERE ISNULL(T.SalaryBank, '') = '';

    INSERT INTO #errores (person, name, observacion)
    SELECT T.Person, T.Name, 'Trabajador no tiene tipo cuenta de haberes'
    FROM (
        SELECT
            E.Person,
            LTRIM(RTRIM(
                ISNULL(P.LastName1, '') + ' ' +
                ISNULL(P.LastName2, '') + ' ' +
                ISNULL(P.Name1, '') + ' ' +
                ISNULL(P.Name2, '')
            )) AS Name,
            E.SalaryAccountType
        FROM PR_Employee E (NOLOCK)
            INNER JOIN SY_Person P (NOLOCK) ON E.Person = P.Person
            INNER JOIN #empleados_periodo EP ON E.Person = EP.person
        WHERE E.Company = @cia
          AND E.PayRollType = @payrolltype
          AND E.Status = 'N'
    ) T
    WHERE ISNULL(T.SalaryAccountType, '') = '';

    INSERT INTO #errores (person, name, observacion)
    SELECT T.Person, T.Name, 'Trabajador no tiene perfil contable'
    FROM (
        SELECT
            E.Person,
            LTRIM(RTRIM(
                ISNULL(P.LastName1, '') + ' ' +
                ISNULL(P.LastName2, '') + ' ' +
                ISNULL(P.Name1, '') + ' ' +
                ISNULL(P.Name2, '')
            )) AS Name,
            E.AccountProfile
        FROM PR_Employee E (NOLOCK)
            INNER JOIN SY_Person P (NOLOCK) ON E.Person = P.Person
            INNER JOIN #empleados_periodo EP ON E.Person = EP.person
        WHERE E.Company = @cia
          AND E.PayRollType = @payrolltype
          AND E.Status = 'N'
    ) T
    WHERE ISNULL(T.AccountProfile, '') = '';

    SELECT
        LTRIM(RTRIM(ISNULL(person, ''))) AS person,
        LTRIM(RTRIM(ISNULL(name, ''))) AS name,
        LTRIM(RTRIM(observacion)) AS observacion
    FROM #errores
    ORDER BY name, observacion;
END
GO



-- ============================================================================
-- [261/282] sp_pr_validar_periodo_masivo_web.sql
-- ============================================================================

/*
    Valida que las empresas indicadas tengan el periodo abierto (Status A/C/G)
    para la planilla y proceso identificados por Description.
    @companies: códigos separados por coma, ej. BGT,SB01,SB02
    Una fila por empresa (sin duplicados por joins).
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_validar_periodo_masivo_web]
    @payroll_desc VARCHAR(200),
    @proceso_desc  VARCHAR(200),
    @period        VARCHAR(10),
    @companies     VARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;

    SET @payroll_desc = LTRIM(RTRIM(ISNULL(@payroll_desc, '')));
    SET @proceso_desc = LTRIM(RTRIM(ISNULL(@proceso_desc, '')));
    SET @period = LEFT(LTRIM(RTRIM(ISNULL(@period, ''))), 10);
    SET @companies = LTRIM(RTRIM(ISNULL(@companies, '')));

    DECLARE @empresas TABLE (company VARCHAR(10) NOT NULL PRIMARY KEY);

    IF @companies <> ''
    BEGIN
        DECLARE @work VARCHAR(500) = @companies + ',';
        DECLARE @pos INT;
        DECLARE @piece VARCHAR(10);

        WHILE LEN(@work) > 0
        BEGIN
            SET @pos = CHARINDEX(',', @work);
            IF @pos = 0 BREAK;
            SET @piece = UPPER(LTRIM(RTRIM(LEFT(@work, @pos - 1))));
            SET @work = SUBSTRING(@work, @pos + 1, LEN(@work));
            IF @piece <> ''
            AND NOT EXISTS (SELECT 1 FROM @empresas e WHERE e.company = @piece)
                INSERT INTO @empresas (company) VALUES (@piece);
        END
    END

    SELECT
        sc.Company AS company,
        ISNULL(sc.description, sc.Company) AS company_desc,
        pt_id.PayRollType AS payrolltype,
        pr_id.ProcessType AS processtype,
        CASE
            WHEN pt_id.PayRollType IS NULL THEN 'SIN_PLANILLA'
            WHEN pr_id.ProcessType IS NULL THEN 'SIN_PROCESO'
            WHEN pc_ok.PRPeriod IS NULL THEN 'SIN_PERIODO'
            ELSE 'OK'
        END AS estado,
        CASE
            WHEN pt_id.PayRollType IS NULL THEN 'No existe el tipo de planilla en la empresa.'
            WHEN pr_id.ProcessType IS NULL THEN 'No existe el proceso en la empresa.'
            WHEN pc_ok.PRPeriod IS NULL THEN 'El periodo no está abierto para esta empresa.'
            ELSE ''
        END AS mensaje
    FROM @empresas e
        INNER JOIN SY_Company sc (NOLOCK)
            ON sc.Company = e.company
           AND UPPER(LTRIM(RTRIM(ISNULL(sc.[status], '')))) = 'A'
        OUTER APPLY (
            SELECT TOP 1 PayRollType
            FROM PR_PayRollType (NOLOCK)
            WHERE Company = sc.Company
              AND LTRIM(RTRIM(Description)) = @payroll_desc
        ) pt_id
        OUTER APPLY (
            SELECT TOP 1 ptp.ProcessType
            FROM PR_PayRollTypeProcess ptp (NOLOCK)
                INNER JOIN PR_ProcessType pt (NOLOCK)
                    ON pt.Company = ptp.Company
                   AND pt.ProcessType = ptp.ProcessType
            WHERE ptp.Company = sc.Company
              AND ptp.PayRollType = pt_id.PayRollType
              AND LTRIM(RTRIM(pt.Description)) = @proceso_desc
        ) pr_id
        OUTER APPLY (
            SELECT TOP 1 PC.PRPeriod
            FROM PR_ProcessControl PC (NOLOCK)
            WHERE PC.Company = sc.Company
              AND PC.PayRollType = pt_id.PayRollType
              AND PC.ProcessType = pr_id.ProcessType
              AND PC.PRPeriod = @period
              AND PC.Status IN ('A', 'C', 'G')
        ) pc_ok
    ORDER BY sc.Company ASC;
END
GO



-- ============================================================================
-- [262/282] sp_pr_validar_pre_calculo_web.sql
-- ============================================================================

/*
    Validaciones previas al cálculo de planilla (módulo Procesar planilla).

    1) Asignaciones permanentes duplicadas (cualquier proceso):
       Un trabajador no puede tener el mismo concepto más de una vez
       con FlagFrecuencyType = 'P' en la planilla.

    2) Conceptos en más de una vía (solo MENSUAL / FIN_DE_MES):
      M — Maestro de conceptos: Insertar en = Mensual (flaginsertar = 'M')
      S — Procedimiento de cálculo: llamadas literales a sp_pr_registrar_concepto
      F — Fórmulas del proceso (PR_FormulaHeader)
      Solo una vía debe estar activa por concepto.

    Excepción hm_aci / hm_aci2 + MENSUAL/FIN_DE_MES:
      No se incluye F (formulador) en la comparación. Se valida solo M vs S.
      Las fórmulas pueden permanecer configuradas; el cálculo mensual se rige por el SP.
      En esas BDs con otros procesos (p. ej. provisiones), si aplica validación de vías,
      el formulador sí se considera. En el resto de bases de datos F siempre se compara.

    Usado por: POST /api/procesar-planilla/validar-pre-calculo
    (también al buscar trabajadores) y antes de /ejecutar_calculo_streaming
    y /ejecutar_calculo_planilla.

    El procedimiento de cálculo (p. ej. sp_pr_calcular_finmes_persona) se obtiene de
    PR_ProcessType.ProcedureName en la BD del cliente; no se versiona en sql/ porque
    puede variar por empresa.

    Parámetros:
      @cia         — compañía
      @payrolltype — tipo de planilla
      @processtype — proceso
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_validar_pre_calculo_web]
    @cia         VARCHAR(10),
    @payrolltype VARCHAR(20),
    @processtype VARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;

    SET @cia = LTRIM(RTRIM(ISNULL(@cia, '')));
    SET @payrolltype = LTRIM(RTRIM(ISNULL(@payrolltype, '')));
    SET @processtype = LTRIM(RTRIM(ISNULL(@processtype, '')));

    DECLARE @proceso_shortname VARCHAR(50);
    DECLARE @proceso_desc VARCHAR(200);
    DECLARE @procedure_name VARCHAR(128);
    DECLARE @sp_def NVARCHAR(MAX);
    DECLARE @es_mensual BIT = 0;
    DECLARE @omitir_formulas BIT = 0;

    SELECT
        @proceso_shortname = UPPER(LTRIM(RTRIM(ISNULL(PT.ShortName, '')))),
        @proceso_desc = UPPER(LTRIM(RTRIM(ISNULL(PT.Description, '')))),
        @procedure_name = LTRIM(RTRIM(ISNULL(PT.ProcedureName, '')))
    FROM PR_ProcessType PT (NOLOCK)
    WHERE PT.Company = @cia
      AND PT.ProcessType = @processtype;

    IF @proceso_shortname IN ('FIN_DE_MES', 'MENSUAL')
       OR @proceso_desc = 'MENSUAL'
       OR CHARINDEX('FIN DE MES', @proceso_desc) > 0
        SET @es_mensual = 1;

    /* hm_aci / hm_aci2 mensual: no confrontar fórmulas; el SP es la vía de cálculo vigente. */
    IF LOWER(DB_NAME()) IN ('hm_aci', 'hm_aci2') AND @es_mensual = 1
        SET @omitir_formulas = 1;

    CREATE TABLE #errores (
        person      VARCHAR(20) NULL,
        name        VARCHAR(200) NULL,
        observacion VARCHAR(500) NOT NULL
    );

    CREATE TABLE #vias (
        formulacode VARCHAR(50) NOT NULL,
        via         CHAR(1) NOT NULL,
        PRIMARY KEY (formulacode, via)
    );

    CREATE TABLE #sp_nemonicos (
        formulacode VARCHAR(50) NOT NULL PRIMARY KEY
    );

    /* Permanentes duplicados: mismo concepto FlagFrecuencyType='P' más de una vez. */
    INSERT INTO #errores (person, name, observacion)
    SELECT
        D.Person,
        LTRIM(RTRIM(
            ISNULL(P.LastName1, '') + ' ' +
            ISNULL(P.LastName2, '') + ' ' +
            ISNULL(P.Name1, '') + ' ' +
            ISNULL(P.Name2, '')
        )),
        'tiene ' + CONVERT(VARCHAR(10), D.cnt)
            + ' asignaciones permanentes del concepto '
            + CASE
                WHEN LTRIM(RTRIM(ISNULL(C.FormulaCode, ''))) <> ''
                THEN LTRIM(RTRIM(C.FormulaCode))
                ELSE LTRIM(RTRIM(ISNULL(C.Description, D.Concept)))
              END
            + CASE
                WHEN LTRIM(RTRIM(ISNULL(C.Description, ''))) <> ''
                     AND LTRIM(RTRIM(ISNULL(C.FormulaCode, ''))) <> ''
                THEN ' (' + LTRIM(RTRIM(C.Description)) + ')'
                ELSE ''
              END
            + '. Solo debe tener una.'
    FROM (
        SELECT
            EC.Person,
            EC.Concept,
            COUNT(*) AS cnt
        FROM PR_EmployeeConcept EC (NOLOCK)
        WHERE EC.Company = @cia
          AND EC.PayRollType = @payrolltype
          AND EC.FlagFrecuencyType = 'P'
        GROUP BY EC.Person, EC.Concept
        HAVING COUNT(*) > 1
    ) D
        INNER JOIN PR_Concept C (NOLOCK)
            ON C.Concept = D.Concept
           AND C.Company = @cia
        LEFT JOIN SY_Person P (NOLOCK)
            ON P.Person = D.Person
           AND P.Company = @cia;

    /* Vías M/S/F: solo proceso mensual (FIN_DE_MES / MENSUAL). */
    IF @es_mensual = 0
    BEGIN
        SELECT
            LTRIM(RTRIM(ISNULL(person, ''))) AS person,
            LTRIM(RTRIM(ISNULL(name, ''))) AS name,
            LTRIM(RTRIM(observacion)) AS observacion
        FROM #errores
        ORDER BY observacion, person;
        RETURN;
    END

    /* M — Insertar en mensual */
    INSERT INTO #vias (formulacode, via)
    SELECT DISTINCT
        UPPER(LTRIM(RTRIM(C.FormulaCode))),
        'M'
    FROM PR_Concept C (NOLOCK)
    WHERE C.Company = @cia
      AND ISNULL(C.flaginsertar, 'N') = 'M'
      AND LTRIM(RTRIM(ISNULL(C.FormulaCode, ''))) <> '';

    /* F — Fórmulas del proceso (omitido en hm_aci/hm_aci2 + mensual) */
    IF @omitir_formulas = 0
    BEGIN
        INSERT INTO #vias (formulacode, via)
        SELECT DISTINCT
            UPPER(LTRIM(RTRIM(C.FormulaCode))),
            'F'
        FROM PR_FormulaHeader FH (NOLOCK)
            INNER JOIN PR_Concept C (NOLOCK)
                ON FH.Concept = C.Concept
               AND C.Company = @cia
        WHERE FH.Company = @cia
          AND FH.Payrolltype = @payrolltype
          AND FH.Proccestype = @processtype
          AND LTRIM(RTRIM(ISNULL(C.FormulaCode, ''))) <> '';
    END

    /* S — Llamadas literales a sp_pr_registrar_concepto en el SP de cálculo */
    IF @procedure_name <> ''
       AND OBJECT_ID(@procedure_name) IS NOT NULL
    BEGIN
        SELECT @sp_def = OBJECT_DEFINITION(OBJECT_ID(@procedure_name));

        IF @sp_def IS NOT NULL AND LEN(@sp_def) > 0
        BEGIN
            DECLARE @pos INT = 1;
            DECLARE @def_len INT = LEN(@sp_def);
            DECLARE @line_start INT = 1;
            DECLARE @line NVARCHAR(MAX);
            DECLARE @ch NCHAR(1);
            DECLARE @tc_pos INT;
            DECLARE @q1 INT;
            DECLARE @q2 INT;
            DECLARE @code VARCHAR(50);

            WHILE @pos <= @def_len
            BEGIN
                SET @ch = SUBSTRING(@sp_def, @pos, 1);

                IF @ch IN (CHAR(10), CHAR(13))
                BEGIN
                    SET @line = SUBSTRING(@sp_def, @line_start, @pos - @line_start);
                    SET @line = LTRIM(RTRIM(@line));

                    IF CHARINDEX('--', @line) > 0
                        SET @line = LTRIM(RTRIM(LEFT(@line, CHARINDEX('--', @line) - 1)));

                    IF @line <> ''
                       AND @line LIKE '%sp_pr_registrar_concepto%'
                       AND @line NOT LIKE '%@nemonico%'
                    BEGIN
                        SET @tc_pos = CHARINDEX('@tc', @line);
                        IF @tc_pos > 0
                        BEGIN
                            SET @q1 = CHARINDEX('''', @line, @tc_pos);
                            IF @q1 > 0
                            BEGIN
                                SET @q2 = CHARINDEX('''', @line, @q1 + 1);
                                IF @q2 > @q1 + 1
                                BEGIN
                                    SET @code = UPPER(LTRIM(RTRIM(SUBSTRING(@line, @q1 + 1, @q2 - @q1 - 1))));
                                    IF @code <> ''
                                       AND @code NOT LIKE '%@%'
                                       AND NOT EXISTS (SELECT 1 FROM #sp_nemonicos S WHERE S.formulacode = @code)
                                    BEGIN
                                        INSERT INTO #sp_nemonicos (formulacode) VALUES (@code);
                                    END
                                END
                            END
                        END
                    END

                    IF @ch = CHAR(13) AND @pos < @def_len AND SUBSTRING(@sp_def, @pos + 1, 1) = CHAR(10)
                    BEGIN
                        SET @line_start = @pos + 2;
                        SET @pos = @pos + 1;
                    END
                    ELSE
                    BEGIN
                        SET @line_start = @pos + 1;
                    END
                END

                SET @pos = @pos + 1;
            END

            /* Última línea si el texto no termina en salto */
            IF @line_start <= @def_len
            BEGIN
                SET @line = LTRIM(RTRIM(SUBSTRING(@sp_def, @line_start, @def_len - @line_start + 1)));

                IF CHARINDEX('--', @line) > 0
                    SET @line = LTRIM(RTRIM(LEFT(@line, CHARINDEX('--', @line) - 1)));

                IF @line <> ''
                   AND @line LIKE '%sp_pr_registrar_concepto%'
                   AND @line NOT LIKE '%@nemonico%'
                BEGIN
                    SET @tc_pos = CHARINDEX('@tc', @line);
                    IF @tc_pos > 0
                    BEGIN
                        SET @q1 = CHARINDEX('''', @line, @tc_pos);
                        IF @q1 > 0
                        BEGIN
                            SET @q2 = CHARINDEX('''', @line, @q1 + 1);
                            IF @q2 > @q1 + 1
                            BEGIN
                                SET @code = UPPER(LTRIM(RTRIM(SUBSTRING(@line, @q1 + 1, @q2 - @q1 - 1))));
                                IF @code <> ''
                                   AND @code NOT LIKE '%@%'
                                   AND NOT EXISTS (SELECT 1 FROM #sp_nemonicos S WHERE S.formulacode = @code)
                                BEGIN
                                    INSERT INTO #sp_nemonicos (formulacode) VALUES (@code);
                                END
                            END
                        END
                    END
                END
            END
        END

        INSERT INTO #vias (formulacode, via)
        SELECT formulacode, 'S'
        FROM #sp_nemonicos;
    END

    INSERT INTO #errores (person, name, observacion)
    SELECT
        NULL,
        NULL,
        D.formulacode
            + CASE WHEN ISNULL(C.Description, '') <> '' THEN ' (' + LTRIM(RTRIM(C.Description)) + ')' ELSE '' END
            + ': configurado en más de una vía ('
            + STUFF((
                SELECT ', ' + CASE V2.via
                    WHEN 'M' THEN 'Insertar en mensual'
                    WHEN 'S' THEN 'Procedimiento de cálculo'
                    WHEN 'F' THEN 'Fórmulas del proceso'
                END
                FROM #vias V2
                WHERE V2.formulacode = D.formulacode
                ORDER BY V2.via
                FOR XML PATH(''), TYPE
            ).value('.', 'NVARCHAR(MAX)'), 1, 2, '')
            + '). Solo debe estar en una.'
    FROM (
        SELECT formulacode
        FROM #vias
        GROUP BY formulacode
        HAVING COUNT(DISTINCT via) > 1
    ) D
        LEFT JOIN PR_Concept C (NOLOCK)
            ON C.Company = @cia
           AND UPPER(LTRIM(RTRIM(C.FormulaCode))) = D.formulacode;

    SELECT
        LTRIM(RTRIM(ISNULL(person, ''))) AS person,
        LTRIM(RTRIM(ISNULL(name, ''))) AS name,
        LTRIM(RTRIM(observacion)) AS observacion
    FROM #errores
    ORDER BY observacion;
END
GO



-- ============================================================================
-- [263/282] sp_pr_validarconceptos_cias_web.sql
-- ============================================================================

/*
    Valida conceptos filtrados de una compañía frente a las demás empresas activas:
      - FALTANTE: no existe el nemónico (FormulaCode) en destino
      - DIFERENCIA: existe pero PDT, Insertar en, Afecto 5ta o Afecto AFP no coinciden

    Filtros (mismos criterios que el listado web):
      @company, @descripcion, @tipos (códigos cortos separados por coma)

    Resultados:
      1) total_origen
      2) resumen por empresa destino (faltantes, diferencias)
      3) detalle de incidencias
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_pr_validarconceptos_cias_web]
    @company     VARCHAR(4),
    @descripcion VARCHAR(50) = NULL,
    @tipos       VARCHAR(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @company = LTRIM(RTRIM(ISNULL(@company, '')));
    SET @descripcion = NULLIF(LTRIM(RTRIM(ISNULL(@descripcion, ''))), '');
    SET @tipos = NULLIF(LTRIM(RTRIM(ISNULL(@tipos, ''))), '');

    IF @company = ''
    BEGIN
        RAISERROR('Indique la compañía origen.', 16, 1);
        RETURN;
    END

    DECLARE @tipos_filtro TABLE (shortname VARCHAR(10) NOT NULL PRIMARY KEY);

    IF @tipos IS NOT NULL
    BEGIN
        DECLARE @tipos_work VARCHAR(200) = @tipos + ',';
        DECLARE @pos INT;
        DECLARE @piece VARCHAR(10);

        WHILE LEN(@tipos_work) > 0
        BEGIN
            SET @pos = CHARINDEX(',', @tipos_work);
            IF @pos = 0
                BREAK;

            SET @piece = UPPER(LTRIM(RTRIM(LEFT(@tipos_work, @pos - 1))));
            SET @tipos_work = SUBSTRING(@tipos_work, @pos + 1, LEN(@tipos_work));

            IF @piece <> ''
            AND NOT EXISTS (SELECT 1 FROM @tipos_filtro tf WHERE tf.shortname = @piece)
                INSERT INTO @tipos_filtro (shortname) VALUES (@piece);
        END
    END

    SELECT
        LTRIM(RTRIM(C.FormulaCode)) AS formulacode,
        ISNULL(C.Description, '') AS description,
        ISNULL(T.ShortName, '') AS tiposhortname,
        ISNULL(LTRIM(RTRIM(C.pdt)), '') AS pdt,
        ISNULL(UPPER(LTRIM(RTRIM(C.flaginsertar))), 'N') AS flaginsertar,
        ISNULL(UPPER(LTRIM(RTRIM(C.flagafecto5ta))), 'N') AS flagafecto5ta,
        ISNULL(UPPER(LTRIM(RTRIM(C.flagafectoAFP))), 'N') AS flagafectoafp
    INTO #origen
    FROM PR_Concept C (NOLOCK)
        LEFT JOIN PR_ConceptType T (NOLOCK)
            ON C.ConceptType = T.ConceptType
    WHERE C.Company = @company
      AND C.FormulaCode IS NOT NULL
      AND LTRIM(RTRIM(C.FormulaCode)) <> ''
      AND (
            @descripcion IS NULL
         OR C.Description LIKE '%' + @descripcion + '%'
         OR C.FormulaCode LIKE '%' + @descripcion + '%'
         OR C.PrintText LIKE '%' + @descripcion + '%'
      )
      AND (
            @tipos IS NULL
         OR EXISTS (
                SELECT 1
                FROM @tipos_filtro tf
                WHERE tf.shortname = UPPER(LTRIM(RTRIM(ISNULL(T.ShortName, ''))))
            )
      );

    CREATE TABLE #incidencias (
        tipo_validacion VARCHAR(12) NOT NULL,
        company_destino VARCHAR(10) NOT NULL,
        company_desc    VARCHAR(100) NULL,
        formulacode     VARCHAR(20) NOT NULL,
        description     VARCHAR(50) NULL,
        tiposhortname   VARCHAR(10) NULL,
        campo           VARCHAR(40) NULL,
        valor_origen    VARCHAR(100) NULL,
        valor_destino   VARCHAR(100) NULL
    );

    INSERT INTO #incidencias (
        tipo_validacion, company_destino, company_desc, formulacode,
        description, tiposhortname, campo, valor_origen, valor_destino
    )
    SELECT
        'FALTANTE',
        sc.Company,
        ISNULL(sc.description, sc.Company),
        o.formulacode,
        o.description,
        o.tiposhortname,
        NULL,
        NULL,
        NULL
    FROM SY_Company sc (NOLOCK)
        CROSS JOIN #origen o
    WHERE sc.status = 'A'
      AND sc.Company <> @company
      AND NOT EXISTS (
            SELECT 1
            FROM PR_Concept c2 (NOLOCK)
            WHERE c2.Company = sc.Company
              AND LTRIM(RTRIM(c2.FormulaCode)) = o.formulacode
        );

    SELECT
        sc.Company AS company_destino,
        ISNULL(sc.description, sc.Company) AS company_desc,
        o.formulacode,
        o.description,
        o.tiposhortname,
        o.pdt AS o_pdt,
        ISNULL(LTRIM(RTRIM(C.pdt)), '') AS d_pdt,
        o.flaginsertar AS o_flaginsertar,
        ISNULL(UPPER(LTRIM(RTRIM(C.flaginsertar))), 'N') AS d_flaginsertar,
        o.flagafecto5ta AS o_flagafecto5ta,
        ISNULL(UPPER(LTRIM(RTRIM(C.flagafecto5ta))), 'N') AS d_flagafecto5ta,
        o.flagafectoafp AS o_flagafectoafp,
        ISNULL(UPPER(LTRIM(RTRIM(C.flagafectoAFP))), 'N') AS d_flagafectoafp
    INTO #pares
    FROM SY_Company sc (NOLOCK)
        CROSS JOIN #origen o
        INNER JOIN PR_Concept C (NOLOCK)
            ON C.Company = sc.Company
           AND LTRIM(RTRIM(C.FormulaCode)) = o.formulacode
    WHERE sc.status = 'A'
      AND sc.Company <> @company;

    INSERT INTO #incidencias (
        tipo_validacion, company_destino, company_desc, formulacode,
        description, tiposhortname, campo, valor_origen, valor_destino
    )
    SELECT 'DIFERENCIA', company_destino, company_desc, formulacode, description, tiposhortname, 'PDT', o_pdt, d_pdt FROM #pares WHERE o_pdt <> d_pdt
    UNION ALL
    SELECT 'DIFERENCIA', company_destino, company_desc, formulacode, description, tiposhortname, 'Insertar en', o_flaginsertar, d_flaginsertar FROM #pares WHERE o_flaginsertar <> d_flaginsertar
    UNION ALL
    SELECT 'DIFERENCIA', company_destino, company_desc, formulacode, description, tiposhortname, 'Afecto 5ta', o_flagafecto5ta, d_flagafecto5ta FROM #pares WHERE o_flagafecto5ta <> d_flagafecto5ta
    UNION ALL
    SELECT 'DIFERENCIA', company_destino, company_desc, formulacode, description, tiposhortname, 'Afecto AFP', o_flagafectoafp, d_flagafectoafp FROM #pares WHERE o_flagafectoafp <> d_flagafectoafp;

    SELECT COUNT(*) AS total_origen FROM #origen;

    SELECT
        company_destino,
        company_desc,
        SUM(CASE WHEN tipo_validacion = 'FALTANTE' THEN 1 ELSE 0 END) AS faltantes,
        SUM(CASE WHEN tipo_validacion = 'DIFERENCIA' THEN 1 ELSE 0 END) AS diferencias,
        COUNT(*) AS total_incidencias
    FROM #incidencias
    GROUP BY company_destino, company_desc
    ORDER BY company_destino ASC;

    SELECT
        tipo_validacion,
        company_destino,
        company_desc,
        formulacode,
        description,
        tiposhortname,
        campo,
        valor_origen,
        valor_destino
    FROM #incidencias
    ORDER BY
        company_destino ASC,
        tipo_validacion ASC,
        formulacode ASC,
        campo ASC;

    DROP TABLE #incidencias;
    DROP TABLE #pares;
    DROP TABLE #origen;
END
GO



-- ============================================================================
-- [264/282] sp_web_asignar_user_access_profile_web.sql
-- ============================================================================

CREATE OR ALTER PROCEDURE [dbo].[sp_web_asignar_user_access_profile_web]
    @userid      VARCHAR(20),
    @profilecode VARCHAR(30) = NULL,
    @xlastuser   VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @userid = LTRIM(RTRIM(ISNULL(@userid, '')));
    SET @profilecode = NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@profilecode, '')))), '');
    SET @xlastuser = NULLIF(LTRIM(RTRIM(ISNULL(@xlastuser, ''))), '');

    IF @userid = ''
    BEGIN
        RAISERROR('Indique el usuario.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (SELECT 1 FROM SY_User (NOLOCK) WHERE UserID = @userid)
    BEGIN
        RAISERROR('El usuario no existe.', 16, 1);
        RETURN;
    END;

    /* profilecode NULL o vacio = quitar asignacion (vuelve a unrestricted) */
    IF @profilecode IS NULL
    BEGIN
        DELETE FROM WEB_UserAccessProfile WHERE UserID = @userid;
        SELECT
            @userid AS userid,
            CAST(NULL AS VARCHAR(30)) AS profilecode,
            'Asignacion de perfil eliminada. El usuario vera todo el menu.' AS mensaje;
        RETURN;
    END;

    IF NOT EXISTS (
        SELECT 1 FROM WEB_AccessProfile (NOLOCK)
        WHERE ProfileCode = @profilecode AND Status = 'A'
    )
    BEGIN
        RAISERROR('El perfil indicado no existe.', 16, 1);
        RETURN;
    END;

    IF EXISTS (SELECT 1 FROM WEB_UserAccessProfile (NOLOCK) WHERE UserID = @userid)
    BEGIN
        UPDATE WEB_UserAccessProfile
        SET ProfileCode = @profilecode,
            XLastUser = @xlastuser,
            XLastDate = GETDATE()
        WHERE UserID = @userid;
    END
    ELSE
    BEGIN
        INSERT INTO WEB_UserAccessProfile (UserID, ProfileCode, XLastUser, XLastDate)
        VALUES (@userid, @profilecode, @xlastuser, GETDATE());
    END;

    SELECT
        @userid AS userid,
        @profilecode AS profilecode,
        'Perfil asignado correctamente.' AS mensaje;
END
GO



-- ============================================================================
-- [265/282] sp_web_eliminar_access_profile_web.sql
-- ============================================================================

CREATE OR ALTER PROCEDURE [dbo].[sp_web_eliminar_access_profile_web]
    @profilecode VARCHAR(30)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @profilecode = UPPER(LTRIM(RTRIM(ISNULL(@profilecode, ''))));

    IF @profilecode = ''
    BEGIN
        RAISERROR('Indique el perfil a eliminar.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1 FROM WEB_AccessProfile (NOLOCK)
        WHERE ProfileCode = @profilecode AND FlagAdmin = 'Y'
    )
    BEGIN
        RAISERROR('No se puede eliminar el perfil administrador.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1 FROM WEB_UserAccessProfile (NOLOCK)
        WHERE ProfileCode = @profilecode
    )
    BEGIN
        RAISERROR('No se puede eliminar: el perfil esta asignado a usuarios.', 16, 1);
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;
        DELETE FROM WEB_AccessProfileMenu WHERE ProfileCode = @profilecode;
        DELETE FROM WEB_AccessProfile WHERE ProfileCode = @profilecode;
        COMMIT TRANSACTION;

        SELECT @profilecode AS profilecode, 'Perfil eliminado correctamente.' AS mensaje;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO



-- ============================================================================
-- [266/282] sp_web_guardar_access_profile_web.sql
-- ============================================================================

/*
    Alta / edicion de perfil web + reemplazo de menus.
    @menus: lista separada por comas de MenuCode.
*/
CREATE OR ALTER PROCEDURE [dbo].[sp_web_guardar_access_profile_web]
    @modo        CHAR(1),
    @profilecode VARCHAR(30),
    @name        VARCHAR(120),
    @menus       VARCHAR(MAX) = NULL,
    @xlastuser   VARCHAR(20) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @flagadmin CHAR(1) = 'N';
    DECLARE @xmlMenus XML;

    SET @modo = UPPER(LTRIM(RTRIM(ISNULL(@modo, ''))));
    SET @profilecode = UPPER(LTRIM(RTRIM(ISNULL(@profilecode, ''))));
    SET @name = LTRIM(RTRIM(ISNULL(@name, '')));
    SET @menus = LTRIM(RTRIM(ISNULL(@menus, '')));
    SET @xlastuser = NULLIF(LTRIM(RTRIM(ISNULL(@xlastuser, ''))), '');

    IF @modo NOT IN ('I', 'U')
    BEGIN
        RAISERROR('Modo de operacion invalido.', 16, 1);
        RETURN;
    END;

    IF @profilecode = '' OR @name = ''
    BEGIN
        RAISERROR('Indique codigo y nombre del perfil.', 16, 1);
        RETURN;
    END;

    IF @modo = 'I' AND EXISTS (
        SELECT 1 FROM WEB_AccessProfile (NOLOCK) WHERE ProfileCode = @profilecode
    )
    BEGIN
        RAISERROR('Ya existe un perfil con ese codigo.', 16, 1);
        RETURN;
    END;

    IF @modo = 'U' AND NOT EXISTS (
        SELECT 1 FROM WEB_AccessProfile (NOLOCK) WHERE ProfileCode = @profilecode
    )
    BEGIN
        RAISERROR('No se encontro el perfil a actualizar.', 16, 1);
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @modo = 'I'
        BEGIN
            INSERT INTO WEB_AccessProfile (
                ProfileCode, Name, FlagAdmin, Status, XLastUser, XLastDate
            )
            VALUES (
                @profilecode, @name, 'N', 'A', @xlastuser, GETDATE()
            );
        END
        ELSE
        BEGIN
            SELECT @flagadmin = FlagAdmin
            FROM WEB_AccessProfile (NOLOCK)
            WHERE ProfileCode = @profilecode;

            UPDATE WEB_AccessProfile
            SET Name = @name,
                XLastUser = @xlastuser,
                XLastDate = GETDATE()
            WHERE ProfileCode = @profilecode;
        END;

        DELETE FROM WEB_AccessProfileMenu WHERE ProfileCode = @profilecode;

        IF @menus <> ''
        BEGIN
            /* Compatible con SQL Server < 2016 / compatibility < 130 (sin STRING_SPLIT) */
            SET @xmlMenus = CAST(
                '<root><l>' + REPLACE(@menus, ',', '</l><l>') + '</l></root>' AS XML
            );

            INSERT INTO WEB_AccessProfileMenu (ProfileCode, MenuCode)
            SELECT DISTINCT
                @profilecode,
                LTRIM(RTRIM(x.value('.', 'VARCHAR(50)')))
            FROM @xmlMenus.nodes('/root/l') AS T(x)
            WHERE NULLIF(LTRIM(RTRIM(x.value('.', 'VARCHAR(50)'))), '') IS NOT NULL
              AND EXISTS (
                    SELECT 1
                    FROM WEB_MenuOption m (NOLOCK)
                    WHERE m.MenuCode = LTRIM(RTRIM(x.value('.', 'VARCHAR(50)')))
                      AND m.Status = 'A'
              );
        END;

        /* ADMIN siempre conserva FlagAdmin y opciones de administración de perfiles */
        IF EXISTS (
            SELECT 1 FROM WEB_AccessProfile (NOLOCK)
            WHERE ProfileCode = @profilecode AND FlagAdmin = 'Y'
        )
        BEGIN
            IF NOT EXISTS (
                SELECT 1 FROM WEB_AccessProfileMenu (NOLOCK)
                WHERE ProfileCode = @profilecode AND MenuCode = 'perfiles_acceso'
            )
            AND EXISTS (SELECT 1 FROM WEB_MenuOption WHERE MenuCode = 'perfiles_acceso')
            BEGIN
                INSERT INTO WEB_AccessProfileMenu (ProfileCode, MenuCode)
                VALUES (@profilecode, 'perfiles_acceso');
            END;

            IF NOT EXISTS (
                SELECT 1 FROM WEB_AccessProfileMenu (NOLOCK)
                WHERE ProfileCode = @profilecode AND MenuCode = 'asignar_perfiles'
            )
            AND EXISTS (SELECT 1 FROM WEB_MenuOption WHERE MenuCode = 'asignar_perfiles')
            BEGIN
                INSERT INTO WEB_AccessProfileMenu (ProfileCode, MenuCode)
                VALUES (@profilecode, 'asignar_perfiles');
            END;
        END;

        COMMIT TRANSACTION;

        SELECT
            @profilecode AS profilecode,
            'Perfil guardado correctamente.' AS mensaje;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO



-- ============================================================================
-- [267/282] sp_web_listar_access_profiles_web.sql
-- ============================================================================

CREATE OR ALTER PROCEDURE [dbo].[sp_web_listar_access_profiles_web]
    @busqueda VARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @busqueda = NULLIF(LTRIM(RTRIM(ISNULL(@busqueda, ''))), '');

    SELECT
        p.ProfileCode AS profilecode,
        p.Name AS name,
        p.FlagAdmin AS flagadmin,
        p.Status AS status,
        ISNULL((
            SELECT COUNT(*)
            FROM WEB_AccessProfileMenu pm (NOLOCK)
            WHERE pm.ProfileCode = p.ProfileCode
        ), 0) AS menus,
        ISNULL((
            SELECT COUNT(*)
            FROM WEB_UserAccessProfile u (NOLOCK)
            WHERE u.ProfileCode = p.ProfileCode
        ), 0) AS usuarios
    FROM WEB_AccessProfile p (NOLOCK)
    WHERE p.Status = 'A'
      AND (
            @busqueda IS NULL
         OR p.ProfileCode LIKE '%' + @busqueda + '%'
         OR p.Name LIKE '%' + @busqueda + '%'
      )
    ORDER BY CASE WHEN p.FlagAdmin = 'Y' THEN 0 ELSE 1 END, p.ProfileCode;
END
GO



-- ============================================================================
-- [268/282] sp_web_listar_menu_options_web.sql
-- ============================================================================

CREATE OR ALTER PROCEDURE [dbo].[sp_web_listar_menu_options_web]
AS
